// ====== PDF + TS RENDER HELPERS ======
import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';

// MM→points for A4 placement
const MM_TO_PT = 72 / 25.4;
const mmToPt = (mm) => mm * MM_TO_PT;

// UK time formatting helpers
const UK_TZ = 'Europe/London';
const fmtUKDate = (d) => {
  // accepts ISO string or YYYY-MM-DD
  if (!d) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
    const [y, m, dd] = d.split('-').map(Number);
    // dd/mm/yy
    return `${String(dd).padStart(2,'0')}/${String(m).padStart(2,'0')}/${String(y % 100).padStart(2,'0')}`;
  }
  const dt = new Date(d);
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: UK_TZ, day: '2-digit', month: '2-digit', year: '2-digit' }).formatToParts(dt);
  const day = parts.find(p => p.type === 'day')?.value ?? '01';
  const mon = parts.find(p => p.type === 'month')?.value ?? '01';
  const yr2 = parts.find(p => p.type === 'year')?.value ?? '00';
  return `${day}/${mon}/${yr2}`;
};
const fmtUKTime = (d) => {
  if (!d) return '';
  const dt = new Date(d);
  return new Intl.DateTimeFormat('en-GB', { timeZone: UK_TZ, hour: '2-digit', minute: '2-digit', hour12: false }).format(dt);
};
// Monday=0 … Sunday=6 based on UK-local start time
const ukWeekdayIndexMon0 = (iso) => {
  if (!iso) return 0;
  const name = new Intl.DateTimeFormat('en-GB', { timeZone: UK_TZ, weekday: 'short' }).format(new Date(iso));
  const map = { Mon: 0, Tue: 1, Wed: 2, Thu: 3, Fri: 4, Sat: 5, Sun: 6 };
  return map[name] ?? 0;
};

// === R2 JSON convenience ===
const TS_LAYOUT_R2_KEY = 'Assets/Stationery/Timesheet/layout.json';

async function r2Put(env, key, bytesOrString, opts = {}) {
  const bucket = env.R2_BUCKET || env.R2;
  const cleanKey = normalizeKey(key);
  const body =
    bytesOrString instanceof Uint8Array ? bytesOrString
    : bytesOrString instanceof ArrayBuffer ? new Uint8Array(bytesOrString)
    : typeof bytesOrString === 'string' ? bytesOrString
    : new Uint8Array(); // fallback to empty

  return bucket.put(cleanKey, body, opts);
}
// ---------- Shared helpers (local to this patch block) ----------
const DOW_MAP = { mon:1, tue:2, wed:3, thu:4, fri:5, sat:6, sun:0 }; // JS: 0=Sun..6=Sat

function parseHHMM(s) {
  if (!s || typeof s !== 'string') return null;
  const m = s.trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return null;
  const h = +m[1], mi = +m[2];
  if (h<0||h>23||mi<0||mi>59) return null;
  return h*60 + mi;
}
function addDays(ymd, d) { const dt = new Date(ymd+'T00:00:00Z'); dt.setUTCDate(dt.getUTCDate()+d); return dt.toISOString().slice(0,10); }
function dow(ymd) { return (new Date(ymd+'T00:00:00Z')).getUTCDay(); } // 0=Sun..6=Sat
function minutesDiff(startMin, endMin, overnight=false) {
  if (startMin==null || endMin==null) return 0;
  if (overnight || endMin <= startMin) return (24*60 - startMin) + endMin;
  return endMin - startMin;
}
function isBH(ymd, bhSet) { return bhSet && bhSet.has(ymd); }

// Derive per-day total hours (decimal) from std_schedule_json {mon..sun:{start,end,break_minutes}}

// Build planned_schedule_json (7 dated entries) from template (mon..sun) for a given week ending

function buildPlannedScheduleFromTemplate(stdSched, weekEndingYmd) {
  const days = [];
  if (!stdSched || typeof stdSched!=='object') return days;
  const weekDates = Array.from({length:7}, (_,i)=> addDays(weekEndingYmd, - (6-i)));
  const mapDateByDow = Object.fromEntries(weekDates.map(d => [dow(d), d]));
  for (const [k, jsDow] of Object.entries(DOW_MAP)) {
    const dCfg = stdSched[k];
    const date = mapDateByDow[jsDow];
    if (!date) continue;
    // Skip non-templated weekdays completely (no placeholder rows)
    if (!dCfg) continue;
    const s = parseHHMM(dCfg.start), e = parseHHMM(dCfg.end);
    if (s==null || e==null) throw new Error(`Invalid HH:MM in std_schedule_json.${k}`);
    const br = Math.max(0, Number(dCfg.break_minutes||0));
    const overnight = (e<=s);
    const mins = Math.max(0, minutesDiff(s, e, overnight) - br);
    days.push({
      date, start: dCfg.start, end: dCfg.end,
      breaks: Array.isArray(dCfg.breaks)? dCfg.breaks : [],
      break_minutes: br, overnight, expected_minutes: mins
    });
  }
  return days;
}


function deriveStdHoursFromSchedule(stdSched) {
  if (!stdSched || typeof stdSched !== 'object') return null;
  const out = {};
  for (const k of Object.keys(DOW_MAP)) {
    const d = stdSched[k];
    if (!d) { out[k] = 0; continue; }
    const s = parseHHMM(d.start), e = parseHHMM(d.end);
    if (s==null || e==null) throw new Error(`Invalid HH:MM in std_schedule_json.${k}`);
    const br = Math.max(0, Number(d.break_minutes||0));
    const mins = Math.max(0, minutesDiff(s, e, e<=s) - br);   // ← infer overnight
    out[k] = +(mins/60).toFixed(2);
  }
  return out;
}


// ============================================================================
// SETTINGS DEFAULTS (UPDATED):
// - Adds TSFIN knobs from import_config_json.tsfin
// - Caches in-memory with TTL to reduce subrequests across requests
// - Normalises import_config_json whether stored as object OR JSON-string-in-jsonb
// ============================================================================

// Module-scope cache (persists across requests in the same Worker isolate)
const __SETTINGS_DEFAULTS_TTL_MS = 30_000; // 30s (tune as you like)
let __SETTINGS_DEFAULTS_CACHE = { ts: 0, value: null };

function _safeJsonParseMaybe(v, fallback = null) {
  if (v == null) return fallback;
  if (typeof v === 'object') return v;             // already parsed JSON / jsonb object
  if (typeof v !== 'string') return fallback;

  const s = v.trim();
  if (!s) return fallback;
  try { return JSON.parse(s); } catch { return fallback; }
}

function _asBool(v, def) {
  if (typeof v === 'boolean') return v;
  if (v == null) return def;
  const s = String(v).trim().toLowerCase();
  if (['true','1','yes','y','on'].includes(s)) return true;
  if (['false','0','no','n','off'].includes(s)) return false;
  return def;
}

function _asNum(v, def) {
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
}

function _asPosInt(v, def) {
  const n = Math.floor(Number(v));
  return Number.isFinite(n) && n > 0 ? n : def;
}

async function loadSettingsDefaults(env) {
  const LOG = (typeof wranglerimportlog !== 'undefined' && wranglerimportlog === true);

  // TTL cache hit
  try {
    const now = Date.now();
    if (__SETTINGS_DEFAULTS_CACHE.value && (now - __SETTINGS_DEFAULTS_CACHE.ts) < __SETTINGS_DEFAULTS_TTL_MS) {
      if (LOG) console.log('[SETTINGS_DEFAULTS]', JSON.stringify({ stage: 'cache_hit' }));
      return __SETTINGS_DEFAULTS_CACHE.value;
    }
  } catch {}

  try {
    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/settings_defaults` +
        `?select=timezone_id,import_config_json,finance_email,finance_email_settings,max_attachments_per_email,system_email,system_emails,comms_adaptors_json` +
        `&id=eq.1` +
        `&limit=1`
    );

    const row = rows?.[0] || {};

    // import_config_json can be:
    // - proper jsonb object  (preferred)
    // - jsonb string holding JSON (your current DB has this pattern)
    const cfgRaw = row.import_config_json;
    const cfg = (typeof cfgRaw === 'object' && cfgRaw !== null)
      ? cfgRaw
      : (_safeJsonParseMaybe(cfgRaw, {}) || {});

    const timezoneId = row.timezone_id || 'Europe/London';

    // Existing knobs
    const importConfig = {
      useBatchedClassification: _asBool(cfg.use_batched_classification, true),
      maxPreviewSubrequests: _asPosInt(cfg.max_preview_subrequests, 40),
      maxHrRowsForFullPreview: _asPosInt(cfg.max_hr_rows_for_full_preview, 500),
    };

    // New TSFIN knobs (nested under cfg.tsfin)
    const tsfinCfgRaw = cfg.tsfin;
    const tsfinCfg = (typeof tsfinCfgRaw === 'object' && tsfinCfgRaw !== null)
      ? tsfinCfgRaw
      : (_safeJsonParseMaybe(tsfinCfgRaw, {}) || {});

    importConfig.tsfin = {
      maxInlineItems: _asPosInt(tsfinCfg.max_inline_items, 3),
      maxInlineRelatedItems: _asPosInt(tsfinCfg.max_inline_related_items, 10),
      maxCronBatchItems: _asPosInt(tsfinCfg.max_cron_batch_items, 50),
      useContextRpc: _asBool(tsfinCfg.use_context_rpc, true),
      useWriteBatchRpc: _asBool(tsfinCfg.use_write_batch_rpc, true),
      useRatesBatchRpc: _asBool(tsfinCfg.use_rates_batch_rpc, true),
    };

    // --- invpdf knobs (existing in your file) ---
    const invpdfCfgRaw = cfg.invpdf;
    const invpdfCfg0 = (typeof invpdfCfgRaw === 'object' && invpdfCfgRaw !== null)
      ? invpdfCfgRaw
      : (_safeJsonParseMaybe(invpdfCfgRaw, {}) || {});

    const invpdfModeRaw = String(invpdfCfg0.mode || '').trim().toLowerCase();
    const invpdfMode = (invpdfModeRaw === 'paid') ? 'paid' : 'free';

    const invpdfEffective = {
      mode: invpdfMode,

      queue_on_issue: _asBool(invpdfCfg0.queue_on_issue, true),
      queue_on_batch_issue: _asBool(invpdfCfg0.queue_on_batch_issue, true),
      queue_on_render: _asBool(invpdfCfg0.queue_on_render, true),
      queue_on_email: _asBool(invpdfCfg0.queue_on_email, true),

      max_enqueue_per_call: _asPosInt(invpdfCfg0.max_enqueue_per_call, 500),

      // NEW shape supports dequeue_limit + enqueue_sweep_limit
      dequeue_limit: _asPosInt(invpdfCfg0.dequeue_limit, (invpdfMode === 'paid' ? 5 : 1)),
      enqueue_sweep_limit: _asPosInt(invpdfCfg0.enqueue_sweep_limit, 500),

      allow_inline_render: _asBool(invpdfCfg0.allow_inline_render, false),
      email_worker_can_render: _asBool(invpdfCfg0.email_worker_can_render, false),

      cooldown_ms: _asPosInt(invpdfCfg0.cooldown_ms, 4000),
      retry_backoff_ms: Array.isArray(invpdfCfg0.retry_backoff_ms) ? invpdfCfg0.retry_backoff_ms : [2000, 5000, 15000]
    };

    importConfig.invpdf = invpdfCfg0;
    importConfig.invpdf_effective = invpdfEffective;

    // --- inv knobs (existing in your file) ---
    const invCfgRaw = cfg.inv;
    const invCfg0 = (typeof invCfgRaw === 'object' && invCfgRaw !== null)
      ? invCfgRaw
      : (_safeJsonParseMaybe(invCfgRaw, {}) || {});

    const invModeRaw = String(invCfg0.mode || '').trim().toLowerCase();
    const invMode = (invModeRaw === 'paid') ? 'paid' : 'free';

    const invEffective = {
      mode: invMode,
      autoinvoice: {
        enqueue_group_limit: _asPosInt(invCfg0?.autoinvoice?.enqueue_group_limit, 10),
      },
      worker: {
        max_batches: _asPosInt(invCfg0?.worker?.max_batches, 1),
        dequeue_limit: _asPosInt(invCfg0?.worker?.dequeue_limit, 10),
      }
    };

    importConfig.inv = invCfg0;
    importConfig.inv_effective = invEffective;

    // --- tspdf knobs (existing in your file) ---
    const tspdfCfgRaw = cfg.tspdf;
    const tspdfCfg0 = (typeof tspdfCfgRaw === 'object' && tspdfCfgRaw !== null)
      ? tspdfCfgRaw
      : (_safeJsonParseMaybe(tspdfCfgRaw, {}) || {});

    const tspdfModeRaw = String(tspdfCfg0.mode || '').trim().toLowerCase();
    const tspdfMode = (tspdfModeRaw === 'paid') ? 'paid' : 'free';

    const tspdfEffective = {
      mode: tspdfMode,
      enqueue_limit: _asPosInt(tspdfCfg0.enqueue_limit, 200),
      max_batches: _asPosInt(tspdfCfg0.max_batches, 1),
      dequeue_limit: _asPosInt(tspdfCfg0.dequeue_limit, 5),
      regen_on_ref_change: (() => {
        const topVal = tspdfCfg0.regen_on_ref_change;
        const tierVal = (tspdfMode === 'paid') ? tspdfCfg0.regen_on_ref_change_paid : tspdfCfg0.regen_on_ref_change_free;
        const chosen = (tierVal !== undefined) ? tierVal : topVal;
        return _asBool(chosen, true);
      })()
    };

    importConfig.tspdf = tspdfCfg0;
    importConfig.tspdf_effective = tspdfEffective;

    // ✅ NEW: auth policy settings (db-driven; stored under import_config_json.auth)
    const authCfgRaw = cfg.auth;
    const authCfg0 = (typeof authCfgRaw === 'object' && authCfgRaw !== null)
      ? authCfgRaw
      : (_safeJsonParseMaybe(authCfgRaw, {}) || {});

    const tfaEnabled = _asBool(authCfg0.tfa_enabled, true);
    const tfaCodeTtl = _asPosInt(authCfg0.tfa_code_ttl_seconds, 300);
    const tfaTrustWin = _asPosInt(authCfg0.tfa_trust_window_seconds, 8 * 60 * 60);
    const tfaMaxAttempts = _asPosInt(authCfg0.tfa_max_attempts, 10);
    const tfaResendCooldown = _asPosInt(authCfg0.tfa_resend_cooldown_seconds, 30);
    const tfaMaxResends = _asPosInt(authCfg0.tfa_max_resends, 5);

    const idleLogout = _asPosInt(authCfg0.idle_logout_seconds, 2 * 60 * 60);
    let idleWarn = _asPosInt(authCfg0.idle_warning_seconds, 5 * 60);
    if (idleWarn >= idleLogout) idleWarn = Math.max(1, Math.min(300, idleLogout - 1));

    importConfig.auth = authCfg0;
    importConfig.auth_effective = {
      tfa_enabled: tfaEnabled,
      tfa_code_ttl_seconds: tfaCodeTtl,
      tfa_trust_window_seconds: tfaTrustWin,
      tfa_max_attempts: tfaMaxAttempts,
      tfa_resend_cooldown_seconds: tfaResendCooldown,
      tfa_max_resends: tfaMaxResends,
      idle_logout_seconds: idleLogout,
      idle_warning_seconds: idleWarn
    };

    // ✅ NEW: finance email settings (db-driven)
    const financeEmail = row.finance_email ? String(row.finance_email).trim() : null;

    const fesRaw = row.finance_email_settings;
    const financeEmailSettings = (typeof fesRaw === 'object' && fesRaw !== null)
      ? fesRaw
      : (_safeJsonParseMaybe(fesRaw, {}) || {});

    // ✅ NEW: system email settings (db-driven)
    const systemEmail = row.system_email ? String(row.system_email).trim() : null;

    const sesRaw = row.system_emails;
    const systemEmailSettings = (typeof sesRaw === 'object' && sesRaw !== null)
      ? sesRaw
      : (_safeJsonParseMaybe(sesRaw, {}) || {});

    // ✅ NEW: comms adaptors config (db-driven)
    const cadRaw = row.comms_adaptors_json;
    const commsAdaptorsJson0 = (typeof cadRaw === 'object' && cadRaw !== null)
      ? cadRaw
      : (_safeJsonParseMaybe(cadRaw, {}) || {});
    const commsAdaptorsJson = (commsAdaptorsJson0 && typeof commsAdaptorsJson0 === 'object' && !Array.isArray(commsAdaptorsJson0))
      ? commsAdaptorsJson0
      : {};

    const maxAttachments = (() => {
      const n = Number(row.max_attachments_per_email);
      const v = Number.isFinite(n) ? Math.trunc(n) : 30;
      return (v >= 1 && v <= 100) ? v : 30;
    })();

    const out = {
      timezone_id: timezoneId,
      importConfig,

      // ✅ NEW (cached)
      finance_email: financeEmail,
      finance_email_settings: financeEmailSettings,
      system_email: systemEmail,
      system_emails: systemEmailSettings,
      max_attachments_per_email: maxAttachments,

      // ✅ NEW: comms adaptors config for WATI/ClickSend + limits
      comms_adaptors_json: commsAdaptorsJson
    };

    // Store TTL cache
    __SETTINGS_DEFAULTS_CACHE = { ts: Date.now(), value: out };

    if (LOG) {
      console.log('[SETTINGS_DEFAULTS]', JSON.stringify({
        stage: 'loaded',
        timezone_id: timezoneId,
        importConfig,
        finance_email: financeEmail,
        system_email: systemEmail,
        max_attachments_per_email: maxAttachments,
        comms_adaptors_json_present: !!(commsAdaptorsJson && typeof commsAdaptorsJson === 'object' && !Array.isArray(commsAdaptorsJson))
      }));
    }

    return out;
  } catch (e) {
    if (LOG) {
      console.warn('[SETTINGS_DEFAULTS]', JSON.stringify({
        stage: 'load_failed',
        err: e?.message || String(e)
      }));
    }

    // Safe fallbacks
    const out = {
      timezone_id: 'Europe/London',
      importConfig: {
        useBatchedClassification: true,
        maxPreviewSubrequests: 40,
        maxHrRowsForFullPreview: 500,
        tsfin: {
          maxInlineItems: 3,
          maxInlineRelatedItems: 10,
          maxCronBatchItems: 50,
          useContextRpc: true,
          useWriteBatchRpc: true,
          useRatesBatchRpc: true,
        },
        invpdf: {},
        invpdf_effective: {
          mode: 'free',
          queue_on_issue: true,
          queue_on_batch_issue: true,
          queue_on_render: true,
          queue_on_email: true,
          max_enqueue_per_call: 500,
          dequeue_limit: 1,
          enqueue_sweep_limit: 500,
          allow_inline_render: false,
          email_worker_can_render: false,
          cooldown_ms: 4000,
          retry_backoff_ms: [2000, 5000, 15000]
        },

        // ✅ NEW fallbacks
        inv: {},
        inv_effective: {
          mode: 'free',
          autoinvoice: { enqueue_group_limit: 10 },
          worker: { max_batches: 1, dequeue_limit: 10 }
        },
        tspdf: {},
        tspdf_effective: {
          mode: 'free',
          enqueue_limit: 200,
          max_batches: 1,
          dequeue_limit: 5,
          regen_on_ref_change: true
        },
        auth: {},
        auth_effective: {
          tfa_enabled: true,
          tfa_code_ttl_seconds: 300,
          tfa_trust_window_seconds: 28800,
          tfa_max_attempts: 10,
          tfa_resend_cooldown_seconds: 30,
          tfa_max_resends: 5,
          idle_logout_seconds: 7200,
          idle_warning_seconds: 300
        }
      },

      // ✅ NEW fallbacks
      finance_email: null,
      finance_email_settings: {},
      system_email: null,
      system_emails: {},
      max_attachments_per_email: 30,

      // ✅ NEW fallbacks
      comms_adaptors_json: {}
    };

    __SETTINGS_DEFAULTS_CACHE = { ts: Date.now(), value: out };
    return out;
  }
}

async function postToPowerAutomate(env, payload, channel = 'finance') {
  const isPlainObject = (x) => !!(x && typeof x === 'object' && !Array.isArray(x));
  const parseSettingsObject = (raw) => {
    if (isPlainObject(raw)) return raw;
    if (typeof raw === 'string' && raw.trim()) {
      try {
        const parsed = JSON.parse(raw);
        return isPlainObject(parsed) ? parsed : {};
      } catch {}
    }
    return {};
  };

  let ch = 'finance';
  let senderUserId = null;
  let explicitCfg = null;

  if (isPlainObject(channel)) {
    const rawKind = String(channel.kind || channel.channel || channel.route || 'finance').trim().toLowerCase();
    ch = (rawKind === 'system') ? 'system' : (rawKind === 'mailshot' ? 'mailshot' : 'finance');
    senderUserId = channel.user_id ?? channel.userId ?? channel.created_by ?? channel.createdBy ?? null;
    explicitCfg = parseSettingsObject(channel.email_settings ?? channel.emailSettings ?? null);
  } else {
    const rawChannel = String(channel || 'finance').trim().toLowerCase();
    ch = (rawChannel === 'system') ? 'system' : (rawChannel === 'mailshot' ? 'mailshot' : 'finance');
  }

  let url = null;
  let extraHeaders = null;

  if (ch === 'mailshot') {
    let cfg = explicitCfg && Object.keys(explicitCfg).length ? explicitCfg : null;

    if (!cfg) {
      const senderUserIdText = (senderUserId == null) ? '' : String(senderUserId).trim();
      if (senderUserIdText) {
        try {
          const { rows } = await sbFetch(
            env,
            `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}` +
              `?id=eq.${encodeURIComponent(senderUserIdText)}` +
              `&select=id,email_settings` +
              `&limit=1`,
            false
          );

          const userRow = Array.isArray(rows) && rows[0] ? rows[0] : null;
          cfg = parseSettingsObject(userRow && userRow.email_settings);
        } catch {}
      }
    }

    if (cfg && typeof cfg === 'object') {
      const u = (typeof cfg.webhook_url === 'string') ? cfg.webhook_url.trim() : '';
      if (u) url = u;
      if (cfg.headers && typeof cfg.headers === 'object' && !Array.isArray(cfg.headers)) extraHeaders = cfg.headers;
    }
  } else {
    try {
      const s = await loadSettingsDefaults(env);

      const cfg = (ch === 'system') ? s?.system_emails : s?.finance_email_settings;
      if (cfg && typeof cfg === 'object') {
        const u = (typeof cfg.webhook_url === 'string') ? cfg.webhook_url.trim() : '';
        if (u) url = u;

        if (cfg.headers && typeof cfg.headers === 'object') extraHeaders = cfg.headers;
      }
    } catch {}
  }

  if (!url && ch !== 'mailshot') {
    if (ch === 'system' && isNonEmptyString(env.POWER_AUTOMATE_SYSTEM_EMAIL_WEBHOOK_URL)) {
      url = env.POWER_AUTOMATE_SYSTEM_EMAIL_WEBHOOK_URL;
    } else {
      url = env.POWER_AUTOMATE_EMAIL_WEBHOOK_URL;
    }
  }

  if (!isNonEmptyString(url)) {
    const which =
      (ch === 'system')
        ? 'settings_defaults.system_emails.webhook_url or env.POWER_AUTOMATE_SYSTEM_EMAIL_WEBHOOK_URL'
        : (ch === 'mailshot')
            ? 'tms_users.email_settings.webhook_url for the mailshot created_by user'
            : 'settings_defaults.finance_email_settings.webhook_url or env.POWER_AUTOMATE_EMAIL_WEBHOOK_URL';

    return {
      ok: false,
      status: 0,
      body: `Power Automate webhook URL not configured (${which})`,
      provider_message_id: undefined,
      resolved_channel: ch,
      sender_user_id: senderUserId == null ? null : String(senderUserId).trim()
    };
  }

  const headers = { 'Content-Type': 'application/json' };
  if (extraHeaders && typeof extraHeaders === 'object') {
    for (const [k, v] of Object.entries(extraHeaders)) {
      if (typeof k === 'string' && k.trim() && v != null) headers[k] = String(v);
    }
  }

  const outgoing = (payload && typeof payload === 'object' && Array.isArray(payload.items))
    ? payload
    : { items: [payload] };

  const res = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(outgoing),
  });

  let body;
  try { body = await res.text(); } catch { body = ''; }

  const ok = res.ok;

  let provider_message_id = undefined;
  try {
    const j = JSON.parse(body);
    provider_message_id =
      j.provider_message_id ||
      j.correlationId ||
      j.correlation_id ||
      j.id ||
      j.messageId ||
      undefined;
  } catch {}

  return {
    ok,
    status: res.status,
    body,
    provider_message_id,
    resolved_channel: ch,
    sender_user_id: senderUserId == null ? null : String(senderUserId).trim()
  };
}


async function handleAuthLogin(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;
  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const email = String((body.email||'')).trim().toLowerCase();
  const pw    = String(body.password||'');
  if (!email || !pw) return badRequest('email_and_password_required');

  const user = await sbGetUserByEmail(env, email);
  if (!user || user.is_active !== true) return unauthorized('Invalid credentials');

  const okPw = await pbkdf2Verify(pw, user.password_hash || '');
  if (!okPw) return unauthorized('Invalid credentials');

  // Load auth policy (db-driven via settings_defaults.import_config_json.auth)
  let authEffective = null;
  try {
    const s = await loadSettingsDefaults(env);
    authEffective = (s && s.importConfig && s.importConfig.auth_effective && typeof s.importConfig.auth_effective === 'object')
      ? s.importConfig.auth_effective
      : null;
  } catch {
    authEffective = null;
  }

  const tfaEnabled = (authEffective && typeof authEffective.tfa_enabled === 'boolean')
    ? authEffective.tfa_enabled === true
    : true;

  const tfaCodeTtlSec = (authEffective && Number.isFinite(Number(authEffective.tfa_code_ttl_seconds)))
    ? Math.max(30, Math.trunc(Number(authEffective.tfa_code_ttl_seconds)))
    : 300;

  const trustWindowSec = (authEffective && Number.isFinite(Number(authEffective.tfa_trust_window_seconds)))
    ? Math.max(60, Math.trunc(Number(authEffective.tfa_trust_window_seconds)))
    : (8 * 60 * 60);

  const idleLogoutSec = (authEffective && Number.isFinite(Number(authEffective.idle_logout_seconds)))
    ? Math.max(60, Math.trunc(Number(authEffective.idle_logout_seconds)))
    : (2 * 60 * 60);

  const idleWarnSec = (() => {
    const v = (authEffective && Number.isFinite(Number(authEffective.idle_warning_seconds)))
      ? Math.max(1, Math.trunc(Number(authEffective.idle_warning_seconds)))
      : (5 * 60);
    return (v >= idleLogoutSec) ? Math.max(1, Math.min(300, idleLogoutSec - 1)) : v;
  })();

  const policy = {
    idle_logout_seconds: idleLogoutSec,
    idle_warning_seconds: idleWarnSec
  };

  const getClientIp = (req0) => {
    const h = req0.headers;
    const cf = h.get('cf-connecting-ip');
    if (cf && String(cf).trim()) return String(cf).trim();

    const xff = h.get('x-forwarded-for');
    if (xff && String(xff).trim()) {
      const first = String(xff).split(',')[0];
      if (first && String(first).trim()) return String(first).trim();
    }

    const xr = h.get('x-real-ip');
    if (xr && String(xr).trim()) return String(xr).trim();

    return null;
  };

  const ip = getClientIp(req);
  const ipKey = (ip && String(ip).trim()) ? String(ip).trim() : 'UNKNOWN';

  // 2FA gate: require unless trusted within window on same IP
  if (tfaEnabled) {
    let trusted = false;

    try {
      const enc = encodeURIComponent;
      const trustUrl =
        `${env.SUPABASE_URL}/rest/v1/tms_user_2fa_trust` +
        `?user_id=eq.${enc(user.id)}` +
        `&ip_address=eq.${enc(ipKey)}` +
        `&select=verified_at_utc` +
        `&order=verified_at_utc.desc` +
        `&limit=1`;

      const tr = await fetch(trustUrl, { headers: sbAuthHeaders(env) });
      if (tr.ok) {
        const arr = await tr.json().catch(() => []);
        const row = Array.isArray(arr) ? arr[0] : null;
        const vAt = row && row.verified_at_utc ? String(row.verified_at_utc) : '';
        if (vAt) {
          const t = new Date(vAt).getTime();
          if (Number.isFinite(t) && t >= (Date.now() - (trustWindowSec * 1000))) {
            trusted = true;
          }
        }
      }
    } catch {
      trusted = false;
    }

    if (!trusted) {
      // Create 2FA challenge + send code email immediately (SYSTEM channel)

      const nowIso = new Date().toISOString();
      const expiresAtIso = new Date(Date.now() + (tfaCodeTtlSec * 1000)).toISOString();

      // Generate code + salted hash
      const rnd = crypto.getRandomValues(new Uint32Array(1))[0] >>> 0;
      const code = String(rnd % 1000000).padStart(6, '0');

      const salt = bufToBase64Url(crypto.getRandomValues(new Uint8Array(16)));
      const code_hash = await sha256Hex(`${salt}:${code}`);

      // Insert challenge row (expects public.tms_login_2fa_challenges)
      let challengeId = null;
      try {
        const insUrl = `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges`;
        const insRes = await fetch(insUrl, {
          method: 'POST',
          headers: { ...sbAuthHeaders(env), Prefer: 'return=representation' },
          body: JSON.stringify({
            user_id: user.id,
            ip_address: ipKey,
            code_salt: salt,
            code_hash,
            expires_at_utc: expiresAtIso
          })
        });

        if (!insRes.ok) {
          const txt = await insRes.text().catch(() => '');
          return serverError(`2FA challenge insert failed (${insRes.status}) ${txt || ''}`.trim());
        }

        const j = await insRes.json().catch(() => []);
        const row = Array.isArray(j) ? j[0] : j;
        challengeId = row && row.id ? String(row.id) : null;
      } catch (e) {
        return serverError(`2FA challenge insert error: ${e?.message || e}`);
      }

      if (!challengeId) {
        return serverError('2FA challenge id missing after insert');
      }

      // Resolve system replyTo email (optional)
      let replyTo = null;
      try {
        const s = await loadSettingsDefaults(env);
        if (s && s.system_email && String(s.system_email).trim()) replyTo = String(s.system_email).trim();
      } catch {}

      // Send code email via SYSTEM webhook
      const mins = Math.max(1, Math.round(tfaCodeTtlSec / 60));
      const subject = 'CloudTMS sign-in verification code';
      const bodyText =
        `Your CloudTMS verification code is: ${code}\n\n` +
        `It expires in ${mins} minute${mins === 1 ? '' : 's'}.\n\n` +
        `If you did not request this code, you can ignore this email.`;

      const htmlBody =
        `<p>Your CloudTMS verification code is:</p>` +
        `<p style="font-size:22px;font-weight:700;letter-spacing:2px;">${code}</p>` +
        `<p>This code expires in ${mins} minute${mins === 1 ? '' : 's'}.</p>` +
        `<p>If you did not request this code, you can ignore this email.</p>`;

      const emailPayload = {
        to: String(user.email || email).trim(),
        subject,
        htmlBody,
        textBody: bodyText,
        attachmentsV2: [],
        meta: { kind: '2FA', user_id: String(user.id), challenge_id: String(challengeId), ip: ipKey, issued_at_utc: nowIso }
      };
      if (replyTo) emailPayload.replyTo = replyTo;

      const pa = await postToPowerAutomate(env, emailPayload, 'system');
      if (!pa || pa.ok !== true) {
        // Best-effort: delete the challenge so we don't accumulate unusable rows
        try {
          const enc = encodeURIComponent;
          await fetch(
            `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges?id=eq.${enc(challengeId)}`,
            { method: 'DELETE', headers: sbAuthHeaders(env) }
          ).catch(() => {});
        } catch {}

        return serverError(`2FA email send failed (${pa?.status || 0}) ${pa?.body || ''}`.trim());
      }

      return new Response(JSON.stringify({
        ok: true,
        tfa_required: true,
        challenge_id: challengeId,
        expires_in: tfaCodeTtlSec,
        policy
      }), { status: 200, headers: JSON_HEADERS });
    }

    // Best-effort: touch trust row last_used_at_utc (non-fatal)
    try {
      const enc = encodeURIComponent;
      const nowIso = new Date().toISOString();
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/tms_user_2fa_trust?user_id=eq.${enc(user.id)}&ip_address=eq.${enc(ipKey)}`,
        {
          method: 'PATCH',
          headers: { ...sbAuthHeaders(env), Prefer: 'return=minimal' },
          body: JSON.stringify({ last_used_at_utc: nowIso })
        }
      ).catch(() => {});
    } catch {}
  }

  // Create KV session + tokens (login complete)
  const sid = bufToBase64Url(crypto.getRandomValues(new Uint8Array(16)));
  const sv  = user.session_version|0 || 1;
  const refresh = await mintRefreshToken(env, { sid, sv });
  const access  = await mintAccessToken(env, { user_id: user.id, email: user.email, role: user.role, sv, sid });

  await kvPutSession(env, sid, { user_id: user.id, sv, exp: refresh.exp }, refreshTtl(env));

  const headers = new Headers(JSON_HEADERS);
  setCookie(headers, cookieName(env), refresh.token, {
    maxAgeSec: refreshTtl(env),
    domain: env.COOKIE_DOMAIN || undefined,
    sameSite: pickCookieSameSite(env),
    secure: true,
    httpOnly: true,
    path: '/'
  });

  // ✅ Best-effort: stamp last_login_at_utc (only after login fully completes)
  try {
    const nowIso = new Date().toISOString();
    const url = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?id=eq.${encodeURIComponent(user.id)}`;
    await fetch(url, {
      method: 'PATCH',
      headers: { ...sbAuthHeaders(env), Prefer: 'return=minimal' },
      body: JSON.stringify({
        last_login_at_utc: nowIso,
        updated_at: nowIso
      })
    }).catch(() => {});
  } catch (_) {
    // ignore: never block login on telemetry update
  }

  return new Response(JSON.stringify({
    ok: true,
    access_token: access.token,
    expires_in: accessTtl(env),
    user: { id: user.id, email: user.email, role: user.role },
    policy
  }), { status: 200, headers });
}

async function handleAuthRefresh(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;
  const cookies = parseCookies(req);
  const raw = cookies[cookieName(env)];
  if (!raw) return unauthorized('No refresh cookie');

  const ver = await verifyToken(sessionSecret(env), raw);
  if (!ver.ok) return unauthorized('Invalid refresh token');
  const { typ, sid, sv, exp } = ver.payload || {};
  if (typ !== 'refresh' || !sid) return unauthorized('Invalid refresh claims');
  if ((exp|0) <= Math.floor(Date.now()/1000)) return unauthorized('Refresh expired');

  const sess = await kvGetSession(env, sid);
  if (!sess) return unauthorized('Session not found');

  // Check session_version still valid
  const user = await sbGetUserById(env, sess.user_id);
  if (!user || user.is_active !== true) return unauthorized('User disabled');
  if ((user.session_version|0) !== (sv|0)) {
    await kvDelSession(env, sid);
    return unauthorized('Session version changed');
  }

  const access = await mintAccessToken(env, {
    user_id: user.id, email: user.email, role: user.role, sv, sid
  });

  // Load policy so FE always stays in sync with DB
  let policy = { idle_logout_seconds: 7200, idle_warning_seconds: 300 };
  try {
    const s = await loadSettingsDefaults(env);
    const ae = (s && s.importConfig && s.importConfig.auth_effective && typeof s.importConfig.auth_effective === 'object')
      ? s.importConfig.auth_effective
      : null;

    if (ae) {
      const idleLogoutSec = Number.isFinite(Number(ae.idle_logout_seconds)) ? Math.max(60, Math.trunc(Number(ae.idle_logout_seconds))) : 7200;
      const idleWarnSec0 = Number.isFinite(Number(ae.idle_warning_seconds)) ? Math.max(1, Math.trunc(Number(ae.idle_warning_seconds))) : 300;
      const idleWarnSec = (idleWarnSec0 >= idleLogoutSec) ? Math.max(1, Math.min(300, idleLogoutSec - 1)) : idleWarnSec0;
      policy = { idle_logout_seconds: idleLogoutSec, idle_warning_seconds: idleWarnSec };
    }
  } catch {}

  const headers = new Headers(JSON_HEADERS);
  // Optional: rotate refresh if near expiry (<3d)
  const secondsLeft = exp - Math.floor(Date.now()/1000);
  if (secondsLeft < (3*24*60*60)) {
    const next = await mintRefreshToken(env, { sid, sv });
    await kvPutSession(env, sid, { user_id: user.id, sv, exp: next.exp }, refreshTtl(env));
    setCookie(headers, cookieName(env), next.token, {
      maxAgeSec: refreshTtl(env),
      domain: env.COOKIE_DOMAIN || undefined,
      sameSite: pickCookieSameSite(env),
      secure: true, httpOnly: true, path:'/'
    });
  }

  return new Response(JSON.stringify({
    access_token: access.token,
    expires_in: accessTtl(env),
    user: { id: user.id, email: user.email, role: user.role },
    policy
  }), { status: 200, headers });
}

async function handleAuthForgot(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;
  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');
  const email = String((body.email||'')).trim().toLowerCase();
  if (!email) return badRequest('email_required');

  const user = await sbGetUserByEmail(env, email);
  if (user && user.is_active === true) {
    let token = null;
    try {
      token = await sbInsertResetToken(env, user.id, resetTtl(env));
    } catch (e) {
      // Privacy-safe: never leak existence; but do log for server ops
      console.warn('[AUTH][FORGOT] failed to create reset token', e?.message || e);
      return ok({ ok:true });
    }

    // Build reset link (prefer browser Origin / Referer so it opens the frontend)
    let base = null;
    try {
      const origin = req.headers.get('origin');
      if (origin && String(origin).trim()) base = String(origin).trim();
    } catch {}

    if (!base) {
      try {
        const ref = req.headers.get('referer');
        if (ref && String(ref).trim()) {
          base = new URL(String(ref).trim()).origin;
        }
      } catch {}
    }

    if (!base) {
      // Optional env fallbacks if you set them (not required for browser calls)
      const cand = [
        env.PUBLIC_APP_BASE_URL,
        env.PUBLIC_FRONTEND_BASE_URL,
        env.PUBLIC_SITE_URL
      ].filter((x) => isNonEmptyString(x));
      if (cand.length) base = String(cand[0]).trim();
    }

    if (base) {
      let link = null;
      try {
        const u = new URL(base);
        u.pathname = '/';
        u.searchParams.set('k', token);
        link = u.toString();
      } catch {
        link = null;
      }

      if (link) {
        // Resolve system replyTo email (optional)
        let replyTo = null;
        try {
          const s = await loadSettingsDefaults(env);
          if (s && s.system_email && String(s.system_email).trim()) replyTo = String(s.system_email).trim();
        } catch {}

        const subject = 'CloudTMS password reset';
        const bodyText =
          `You requested a password reset for CloudTMS.\n\n` +
          `Click the link below to set a new password:\n${link}\n\n` +
          `If you did not request this, you can ignore this email.`;

        const htmlBody =
          `<p>You requested a password reset for CloudTMS.</p>` +
          `<p><a href="${link}">Click here to set a new password</a></p>` +
          `<p>If you did not request this, you can ignore this email.</p>`;

        const emailPayload = {
          to: String(email).trim(),
          subject,
          htmlBody,
          textBody: bodyText,
          attachmentsV2: [],
          meta: { kind: 'PASSWORD_RESET', user_id: String(user.id), issued_at_utc: new Date().toISOString() }
        };
        if (replyTo) emailPayload.replyTo = replyTo;

        // Privacy-safe: best-effort send (do not leak existence via error)
        try {
          const pa = await postToPowerAutomate(env, emailPayload, 'system');
          if (!pa || pa.ok !== true) {
            console.warn('[AUTH][FORGOT] PowerAutomate send failed', pa?.status, pa?.body);
          }
        } catch (e) {
          console.warn('[AUTH][FORGOT] PowerAutomate send error', e?.message || e);
        }
      }
    }
  }

  return ok({ ok:true }); // privacy-safe
}

async function handleAuthReset(env, req) {
  const pre = preflightIfNeeded(env, req); if (pre) return pre;
  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const token = String(body.token||'');
  const newPw = String(body.new_password||'');
  if (!token || !newPw) return badRequest('token_and_new_password_required');

  const strong = newPw.length>=8 && /[a-z]/.test(newPw) && /[A-Z]/.test(newPw) && /[0-9]/.test(newPw);
  if (!strong) return new Response(JSON.stringify({ ok:false, error:'WEAK_PASSWORD' }), { status:400, headers: JSON_HEADERS });

  const consumed = await sbConsumeResetToken(env, token);
  if (!consumed.ok) return new Response(JSON.stringify({ ok:false, error: consumed.error }), { status:400, headers: JSON_HEADERS });

  const hash = await pbkdf2Hash(newPw);
  await sbUpdateUserPassword(env, consumed.user_id, hash);

  // ✅ After password reset, clear any 2FA trust for this user (forces fresh 2FA next login)
  try {
    const enc = encodeURIComponent;
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/tms_user_2fa_trust?user_id=eq.${enc(consumed.user_id)}`,
      { method: 'DELETE', headers: sbAuthHeaders(env) }
    ).catch(() => {});
  } catch {}

  // Optional: invalidate any outstanding challenges
  try {
    const enc = encodeURIComponent;
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/tms_login_2fa_challenges?user_id=eq.${enc(consumed.user_id)}`,
      { method: 'DELETE', headers: sbAuthHeaders(env) }
    ).catch(() => {});
  } catch {}

  return ok({ ok:true });
}

// ============================================================================
// GET SETTINGS (UNCHANGED except optional normalisation comment)
// - Already includes import_config_json in explicit select list.
// - No structural change required.
// ============================================================================

// ============================================================================
// GET SETTINGS (UPDATED):
// - Removes legacy finance fields from settings_defaults payload
// - Adds finance_windows[] from RPC settings_finance_list() in the same response
//   (no new GET endpoint needed for FE; single extra RPC call)
// ============================================================================

// ============================================================================
// GET SETTINGS (UPDATED):
// - Removes legacy finance fields from settings_defaults payload
// - Adds finance_windows[] from RPC settings_finance_list() in the same response
//   (no new GET endpoint needed for FE; single extra RPC call)
// ============================================================================

// ============================================================================
// UPDATE SETTINGS (UPDATED - OPTION A):
// - Stops writing legacy finance fields on settings_defaults
// - Keeps existing behaviour for non-finance fields (timezone, buckets, BH list, bank, import_config_json, etc.)
// - Finance windows are managed via the new handler below
// ============================================================================


// ============================================================================
// NEW HANDLER (OPTION A): Finance windows CRUD (global VAT/ERNI/Holiday Pay)
// Suggested routes:
// - GET    /api/settings/finance-windows
// - POST   /api/settings/finance-windows
// - PATCH  /api/settings/finance-windows/:id
// - DELETE /api/settings/finance-windows/:id
//
// Notes:
// - Uses settings_finance_windows table directly for writes (single REST call).
// - Uses settings_finance_list RPC for list (single RPC call).
// - Overlap prevention is enforced by the DB exclusion constraint.
// ============================================================================

async function handleSettingsFinanceWindows(env, req, windowId = null) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  const enc = encodeURIComponent;
  const method = (req.method || 'GET').toUpperCase();

  // --------------------------
  // helpers
  // --------------------------
  const numOrNull = (v) => {
    if (v == null) return null;
    if (typeof v === 'string' && v.trim() === '') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  const assertNonNegOrNull = (n, fieldName) => {
    if (n == null) return null;
    if (!Number.isFinite(n)) return `Field ${fieldName} must be a number or null`;
    if (n < 0) return `Field ${fieldName} must be >= 0`;
    return null;
  };

  // --------------------------
  // GET
  // --------------------------
  if (method === 'GET') {
    try {
      const rows = await sbRpc(env, 'settings_finance_list', {});
      return withCORS(env, req, ok({ finance_windows: Array.isArray(rows) ? rows : [] }));
    } catch (e) {
      return withCORS(env, req, serverError('Failed to load finance windows'));
    }
  }

  // All non-GET need JSON body except DELETE
  let body = null;
  if (method !== 'DELETE') {
    try {
      body = await parseJSONBody(req);
    } catch {
      return withCORS(env, req, badRequest('Invalid JSON'));
    }
  }

  // --------------------------
  // POST
  // --------------------------
  if (method === 'POST') {
    const date_from = body?.date_from || null;
    const date_to = body?.date_to ?? null;

    if (!date_from) return withCORS(env, req, badRequest('date_from is required (YYYY-MM-DD)'));
    if (!body || body.vat_rate_pct == null || body.erni_pct == null || body.holiday_pay_pct == null) {
      return withCORS(env, req, badRequest('vat_rate_pct, erni_pct, holiday_pay_pct are required'));
    }

    const vat_rate_pct = Number(body.vat_rate_pct);
    const erni_pct = Number(body.erni_pct);
    const holiday_pay_pct = Number(body.holiday_pay_pct);

    if (!Number.isFinite(vat_rate_pct) || !Number.isFinite(erni_pct) || !Number.isFinite(holiday_pay_pct)) {
      return withCORS(env, req, badRequest('vat_rate_pct, erni_pct, holiday_pay_pct must be numbers'));
    }

    // ✅ NEW: global mileage defaults (nullable, but if present must be >= 0)
    const mileage_pay_defaults = numOrNull(body.mileage_pay_defaults);
    const mileage_charge_defaults = numOrNull(body.mileage_charge_defaults);

    const mpErr = assertNonNegOrNull(mileage_pay_defaults, 'mileage_pay_defaults');
    if (mpErr) return withCORS(env, req, badRequest(mpErr));
    const mcErr = assertNonNegOrNull(mileage_charge_defaults, 'mileage_charge_defaults');
    if (mcErr) return withCORS(env, req, badRequest(mcErr));

    const payload = {
      date_from,
      date_to: (date_to === '' ? null : date_to),

      vat_rate_pct,
      erni_pct,
      holiday_pay_pct,

      // ✅ NEW fields persisted to settings_finance_windows
      mileage_pay_defaults,
      mileage_charge_defaults,

      apply_holiday_to: body.apply_holiday_to ?? null,
      apply_erni_to: body.apply_erni_to ?? null,
      margin_includes: (body.margin_includes && typeof body.margin_includes === 'object') ? body.margin_includes : null
    };

    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/settings_finance_windows`, {
      method: 'POST',
      headers: { ...sbHeaders(env), Prefer: 'return=representation' },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const t = await res.text().catch(() => '');
      return withCORS(env, req, badRequest(`Create finance window failed: ${t || res.status}`));
    }

    const json = await res.json().catch(() => ([]));
    const row = Array.isArray(json) ? json[0] : json;
    return withCORS(env, req, ok({ finance_window: row }));
  }

  // --------------------------
  // PATCH
  // --------------------------
  if (method === 'PATCH') {
    if (!windowId) return withCORS(env, req, badRequest('finance window id is required'));

    const patch = {};
    const keys = [
      'date_from', 'date_to',
      'vat_rate_pct', 'erni_pct', 'holiday_pay_pct',

      // ✅ NEW mileage defaults
      'mileage_pay_defaults', 'mileage_charge_defaults',

      'apply_holiday_to', 'apply_erni_to', 'margin_includes'
    ];

    for (const k of keys) {
      if (!(k in (body || {}))) continue;

      if (k === 'margin_includes') {
        patch[k] = (body[k] && typeof body[k] === 'object') ? body[k] : null;
        continue;
      }

      if (k === 'date_to') {
        patch[k] = (body[k] === '' ? null : body[k]);
        continue;
      }

      if (
        k === 'vat_rate_pct' || k === 'erni_pct' || k === 'holiday_pay_pct' ||
        k === 'mileage_pay_defaults' || k === 'mileage_charge_defaults'
      ) {
        // allow null/blank -> null for mileage defaults, but require numbers for vat/erni/holiday if supplied
        const n = numOrNull(body[k]);

        if (k === 'vat_rate_pct' || k === 'erni_pct' || k === 'holiday_pay_pct') {
          // these should not be null if provided
          if (n == null) return withCORS(env, req, badRequest(`${k} must be a number`));
          patch[k] = n;
          continue;
        }

        // mileage defaults: nullable, but if present must be >=0
        const err = assertNonNegOrNull(n, k);
        if (err) return withCORS(env, req, badRequest(err));
        patch[k] = n;
        continue;
      }

      patch[k] = body[k];
    }

    if (!Object.keys(patch).length) {
      return withCORS(env, req, badRequest('No fields to update'));
    }

    patch.updated_at = new Date().toISOString();

    const res = await fetch(
      `${env.SUPABASE_URL}/rest/v1/settings_finance_windows?id=eq.${enc(windowId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return=representation' },
        body: JSON.stringify(patch)
      }
    );

    if (!res.ok) {
      const t = await res.text().catch(() => '');
      return withCORS(env, req, badRequest(`Update finance window failed: ${t || res.status}`));
    }

    const json = await res.json().catch(() => ([]));
    const row = Array.isArray(json) ? json[0] : json;
    return withCORS(env, req, ok({ finance_window: row }));
  }

  // --------------------------
  // DELETE
  // --------------------------
  if (method === 'DELETE') {
    if (!windowId) return withCORS(env, req, badRequest('finance window id is required'));

    const res = await fetch(
      `${env.SUPABASE_URL}/rest/v1/settings_finance_windows?id=eq.${enc(windowId)}`,
      {
        method: 'DELETE',
        headers: { ...sbHeaders(env), Prefer: 'return=minimal' }
      }
    );

    if (!res.ok) {
      const t = await res.text().catch(() => '');
      return withCORS(env, req, badRequest(`Delete finance window failed: ${t || res.status}`));
    }

    return withCORS(env, req, ok({ deleted: true, id: windowId }));
  }

  return withCORS(env, req, badRequest('Unsupported method'));
}

// ============================================================================
// UPDATE SETTINGS (UPDATED):
// - Allows import_config_json
// - Validates it (object or JSON string)
// - Writes it as a proper JSON object (preferred) to avoid double-encoding
// - Keeps existing behaviour for other fields
// ============================================================================



// Load client windows & BH list (fallback to defaults if missing)
async function loadClientTimePolicy(env, clientId) {
  const enc = encodeURIComponent;

  const cs = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/client_settings?client_id=eq.${enc(
      clientId
    )}&select=day_start,day_end,night_start,night_end,sat_start,sat_end,sun_start,sun_end,bh_start,bh_end,bh_list`
  );

  const defaults = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/settings_defaults?id=eq.1&select=day_start,day_end,night_start,night_end,sat_start,sat_end,sun_start,sun_end,bh_start,bh_end,bh_list`
  );

  const src = { ...(defaults || {}), ...(cs || {}) };

  // Normalise "HH:MM:SS" → "HH:MM" before parseHHMM
  const toHHMM = (val, fallback) => {
    const raw = (val ?? fallback ?? "").toString().trim();
    if (!raw) return fallback;

    const parts = raw.split(":"); // "06:00:00" → ["06","00","00"]
    const hh = (parts[0] ?? "00").padStart(2, "0");
    const mm = (parts[1] ?? "00").padStart(2, "0");
    return `${hh}:${mm}`;
  };

  const dayStart   = parseHHMM(toHHMM(src.day_start,   "06:00"));
  const dayEnd     = parseHHMM(toHHMM(src.day_end,     "20:00"));
  const nightStart = parseHHMM(toHHMM(src.night_start, "20:00"));
  const nightEnd   = parseHHMM(toHHMM(src.night_end,   "06:00"));
  const satStart   = parseHHMM(toHHMM(src.sat_start,   "00:00"));
  const satEnd     = parseHHMM(toHHMM(src.sat_end,     "00:00"));
  const sunStart   = parseHHMM(toHHMM(src.sun_start,   "00:00"));
  const sunEnd     = parseHHMM(toHHMM(src.sun_end,     "00:00"));

  // ✅ BH window (00:00–00:00 = full BH day). Prefer client override, else global.
  const bhStart = parseHHMM(
    toHHMM(
      (cs && cs.bh_start) ||
        (defaults && defaults.bh_start) ||
        "00:00",
      "00:00"
    )
  );
  const bhEnd = parseHHMM(
    toHHMM(
      (cs && cs.bh_end) ||
        (defaults && defaults.bh_end) ||
        "00:00",
      "00:00"
    )
  );

  // ✅ BH LIST IS GLOBAL-ONLY (ignore client_settings.bh_list entirely)
  // Normalise BH list (array or JSON string → array → Set)
  const rawBhList = (defaults && defaults.bh_list) ?? [];

  let bhListArr = [];
  if (Array.isArray(rawBhList)) {
    bhListArr = rawBhList;
  } else if (typeof rawBhList === "string") {
    try {
      const parsed = JSON.parse(rawBhList);
      if (Array.isArray(parsed)) bhListArr = parsed;
    } catch {
      // leave as []
    }
  }

  const bhList = new Set(bhListArr);

  return {
    dayStart,
    dayEnd,
    nightStart,
    nightEnd,
    satStart,
    satEnd,
    sunStart,
    sunEnd,
    bhStart,
    bhEnd,
    bhList,
  };
}


// ─────────────────────────────────────────────────────────────
// Shared helper: reference completeness (matches DB view truth)
// ─────────────────────────────────────────────────────────────

function strTrim(x) { return (x == null) ? '' : String(x).trim(); }

function dayRefsHasAny(dayRefs) {
  if (!dayRefs || typeof dayRefs !== 'object') return false;
  return Object.values(dayRefs).some(v => strTrim(v));
}

function weeklyManualScheduleHasCompleteRefs(schedule) {
  const arr = Array.isArray(schedule) ? schedule : [];
  if (!arr.length) return false;

  for (const seg of arr) {
    if (!seg || typeof seg !== 'object') continue;
    const start = strTrim(seg.start);
    const end   = strTrim(seg.end);

    // Only enforce ref on “real shift” segments
    if (start && end) {
      const ref = strTrim(seg.ref_num);
      if (!ref) return false;
    }
  }
  return true;
}

function timesheetHasInvoiceReference(ts) {
  const scope = strTrim(ts?.sheet_scope).toUpperCase();
  const mode  = strTrim(ts?.submission_mode).toUpperCase();

  // WEEKLY + MANUAL is schedule-driven
  if (scope === 'WEEKLY' && mode === 'MANUAL') {
    return weeklyManualScheduleHasCompleteRefs(ts?.actual_schedule_json);
  }

  // WEEKLY non-manual uses legacy weekly reference model
  if (scope === 'WEEKLY') {
    return !!strTrim(ts?.reference_number) || dayRefsHasAny(ts?.day_references_json);
  }

  // DAILY (and anything else) uses reference_number
  return !!strTrim(ts?.reference_number);
}

// Segment one day's chunk [a,b) in minutes (0..1440), allocate into day/night using client windows.
// Weekend/BH overlay wins over day/night; precedence BH > Sun > Sat > Night > Day.

function segmentChunkIntoBuckets(dateYmd, a, b, policy, acc) {
  const len = Math.max(0, b - a);
  if (len === 0) return;

  const clamp0_1440 = (v) => Math.max(0, Math.min(1440, v));
  const d = dow(dateYmd); // 0=Sun..6=Sat

  // Normalise BH list
  const bhList =
    policy && policy.bhList instanceof Set
      ? policy.bhList
      : new Set(Array.isArray(policy?.bhList) ? policy.bhList : []);

  const isBhDate = isBH(dateYmd, bhList);

  // Start with full segment as “remaining”; we may carve out BH & Sat/Sun sub-ranges
  let rem = [{ from: a, to: b }];

  // ──────────────────────────────
  // 1) Split out Bank Holiday time
  // ──────────────────────────────
  if (isBhDate) {
    const bhStart = typeof policy.bhStart === 'number' ? clamp0_1440(policy.bhStart) : 0;
    const bhEnd   = typeof policy.bhEnd   === 'number' ? clamp0_1440(policy.bhEnd)   : 0;

    const bhIntervals = [];

    if (bhStart === 0 && bhEnd === 0) {
      // Full BH day: all minutes on this date are BH
      bhIntervals.push({ from: 0, to: 1440 });
    } else if (bhStart < bhEnd) {
      // Simple window
      bhIntervals.push({ from: bhStart, to: bhEnd });
    } else {
      // Wrap-around window (e.g. 20:00 → 06:00)
      bhIntervals.push({ from: bhStart, to: 1440 });
      bhIntervals.push({ from: 0,       to: bhEnd });
    }

    const bhSegments = [];

    for (const wi of bhIntervals) {
      const nextRem = [];
      for (const r of rem) {
        const start = r.from;
        const end   = r.to;
        const x1 = Math.max(start, wi.from);
        const x2 = Math.min(end,   wi.to);
        if (x1 < x2) {
          // BH portion
          bhSegments.push({ from: x1, to: x2 });
          // Non-BH leftovers
          if (x1 > start) nextRem.push({ from: start, to: x1 });
          if (x2 < end)   nextRem.push({ from: x2,    to: end });
        } else {
          // No overlap; keep as-is
          nextRem.push(r);
        }
      }
      rem = nextRem;
      if (!rem.length) break;
    }

    // Accumulate BH minutes
    for (const s of bhSegments) acc.bh += (s.to - s.from);
    if (!rem.length) return;
  }

  // ──────────────────────────────
  // 2) Weekend windows (Sat/Sun)
  // ──────────────────────────────
  const satStart = typeof policy.satStart === 'number' ? policy.satStart : 0;
  const satEnd   = typeof policy.satEnd   === 'number' ? policy.satEnd   : 0;
  const sunStart = typeof policy.sunStart === 'number' ? policy.sunStart : 0;
  const sunEnd   = typeof policy.sunEnd   === 'number' ? policy.sunEnd   : 0;

  // Interpret Sat/Sun windows as:
  //  - Saturday: from sat_start on Saturday up to sat_end on Sunday (next day)
  //  - Sunday:   from sun_start on Sunday up to sun_end on Monday (next day)
  const satEndAbs = 1440 + satEnd; // minutes from Sat 00:00
  const sunEndAbs = 1440 + sunEnd; // minutes from Sun 00:00

  const weekendIntervals = [];

  if (d === 6) { // Saturday
    const fromSat = clamp0_1440(satStart);
    const toSat   = 1440; // portion of [satStart, satEndAbs] that lies on Saturday
    if (toSat > fromSat) weekendIntervals.push({ from: fromSat, to: toSat, bucket: 'sat' });
  }

  if (d === 0) { // Sunday
    // Tail of Saturday window spilling into Sunday (Sat → Sun)
    const satTail = satEndAbs - 1440;
    if (satTail > 0) {
      const from = 0;
      const to   = clamp0_1440(satTail);
      if (to > from) weekendIntervals.push({ from, to, bucket: 'sat' });
    }
    // Sunday window itself
    const fromSun = clamp0_1440(sunStart);
    let toSun = sunEndAbs > 1440 ? 1440 : clamp0_1440(sunEndAbs);
    if (toSun < fromSun) toSun = fromSun;
    if (toSun > fromSun) weekendIntervals.push({ from: fromSun, to: toSun, bucket: 'sun' });
  }

  if (d === 1) { // Monday: tail of Sunday window
    const sunTail = sunEndAbs - 1440;
    if (sunTail > 0) {
      const from = 0;
      const to   = clamp0_1440(sunTail);
      if (to > from) weekendIntervals.push({ from, to, bucket: 'sun' });
    }
  }

  for (const wi of weekendIntervals) {
    const nextRem = [];
    for (const r of rem) {
      const start = r.from;
      const end   = r.to;
      const x1 = Math.max(start, wi.from);
      const x2 = Math.min(end,   wi.to);
      if (x1 < x2) {
        acc[wi.bucket] += (x2 - x1);
        if (x1 > start) nextRem.push({ from: start, to: x1 });
        if (x2 < end)   nextRem.push({ from: x2,    to: end });
      } else {
        nextRem.push(r);
      }
    }
    rem = nextRem;
    if (!rem.length) break;
  }

  if (!rem.length) return;

  // ──────────────────────────────
  // 3) Day / Night – using dayStart/dayEnd split
  // ──────────────────────────────
  const ds = typeof policy.dayStart === 'number' ? policy.dayStart : 0;
  const de = typeof policy.dayEnd   === 'number' ? policy.dayEnd   : 1440;

  const seg = [
    { from: 0,  to: ds, bucket:'night' },
    { from: ds, to: de, bucket:'day'   },
    { from: de, to: 1440, bucket:'night' }
  ];

  for (const r of rem) {
    const start = r.from;
    const end   = r.to;
    for (const s of seg) {
      const x1 = Math.max(start, s.from);
      const x2 = Math.min(end,   s.to);
      if (x2 > x1) acc[s.bucket] += (x2 - x1);
    }
  }
}

// Apply duration-only break: subtract from largest bucket; ties: BH > Sun > Sat > Night > Day
function applyDurationBreak(acc, breakMin) {
  if (!breakMin || breakMin<=0) return;
  const order = ['bh','sun','sat','night','day'];
  let remaining = breakMin;
  while (remaining>0) {
    // find largest bucket by minutes following precedence order for ties
    let bestK = null, bestVal = -1;
    for (const k of order) {
      const v = acc[k]||0;
      if (v > bestVal) { bestVal = v; bestK = k; }
    }
    if (!bestK || bestVal<=0) break;
    const take = Math.min(remaining, bestVal);
    acc[bestK] -= take;
    remaining -= take;
  }
}

async function resolveBulkContextIdsFromSummarySelection(section, filters, selectionMode, includedIds, excludedIds, env, req) {
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const normalizeIdArray = (arr) => Array.from(new Set(
    (Array.isArray(arr) ? arr : [])
      .map(v => trimStr(v))
      .filter(Boolean)
  ));
  const clonePlain = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      const out = {};
      Object.keys(value).forEach((key) => {
        out[key] = value[key];
      });
      return out;
    }
  };

  const sectionKey = (() => {
    const s = trimStr(section).toLowerCase();
    if (s === 'candidate' || s === 'candidates') return 'candidates';
    if (s === 'client' || s === 'clients') return 'clients';
    if (s === 'contract' || s === 'contracts') return 'contracts';
    if (s === 'timesheet' || s === 'timesheets') return 'timesheets';
    if (s === 'invoice' || s === 'invoices') return 'invoices';
    if (s === 'umbrella' || s === 'umbrellas') return 'umbrellas';
    return '';
  })();

  if (!sectionKey) {
    throw new Error('invalid_section');
  }

  const mode = trimStr(selectionMode).toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';
  const normalizedIncludedIds = normalizeIdArray(includedIds);
  const normalizedExcludedIds = normalizeIdArray(excludedIds);

  const resolvedSelection = await resolveSummarySelection(
    sectionKey,
    clonePlain(filters),
    mode,
    normalizedIncludedIds,
    normalizedExcludedIds,
    env,
    req
  );

  const summaryRowIds = normalizeIdArray(resolvedSelection && resolvedSelection.summary_row_ids);
  const validSummaryIdSet = new Set(summaryRowIds);
  const skippedRows = [];

  if (mode === 'explicit') {
    normalizedIncludedIds.forEach((selectedRowId) => {
      if (!validSummaryIdSet.has(selectedRowId)) {
        skippedRows.push({
          selected_row_id: selectedRowId,
          skip_reason: 'SUMMARY_ROW_NOT_IN_DATASET'
        });
      }
    });
  }

  if (sectionKey !== 'timesheets') {
    return {
      summary_row_ids: summaryRowIds,
      context_ids: summaryRowIds.slice(),
      skipped_rows: skippedRows
    };
  }

  if (!summaryRowIds.length) {
    return {
      summary_row_ids: [],
      context_ids: [],
      skipped_rows: skippedRows
    };
  }

  const enc = encodeURIComponent;
  const rowsBySelectedId = new Map();
  const chunkSize = 200;

  for (let i = 0; i < summaryRowIds.length; i += chunkSize) {
    const chunk = summaryRowIds.slice(i, i + chunkSize);
    const inList = chunk.map(enc).join(',');
    if (!inList) continue;

    const url =
      `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary` +
      `?select=timesheet_id,contract_week_id` +
      `&or=(timesheet_id.in.(${inList}),contract_week_id.in.(${inList}))`;

    const fetched = await sbFetch(env, url, false);
    const fetchedRows = Array.isArray(fetched && fetched.rows) ? fetched.rows : [];

    fetchedRows.forEach((row) => {
      const timesheetId = trimStr(row && row.timesheet_id);
      const contractWeekId = trimStr(row && row.contract_week_id);

      if (timesheetId) {
        rowsBySelectedId.set(timesheetId, {
          selected_row_id: timesheetId,
          context_id: timesheetId,
          has_timesheet_context: true
        });
      } else if (contractWeekId) {
        rowsBySelectedId.set(contractWeekId, {
          selected_row_id: contractWeekId,
          context_id: null,
          has_timesheet_context: false
        });
      }
    });
  }

  const contextIds = [];
  const seenContextIds = new Set();

  summaryRowIds.forEach((selectedRowId) => {
    const mapped = rowsBySelectedId.get(selectedRowId) || null;

    if (!mapped) {
      skippedRows.push({
        selected_row_id: selectedRowId,
        skip_reason: 'SUMMARY_ROW_NOT_FOUND'
      });
      return;
    }

    if (!mapped.has_timesheet_context || !mapped.context_id) {
      skippedRows.push({
        selected_row_id: selectedRowId,
        skip_reason: 'NO_TIMESHEET_CONTEXT'
      });
      return;
    }

    if (!seenContextIds.has(mapped.context_id)) {
      seenContextIds.add(mapped.context_id);
      contextIds.push(mapped.context_id);
    }
  });

  return {
    summary_row_ids: summaryRowIds,
    context_ids: contextIds,
    skipped_rows: skippedRows
  };
}


async function resolveSummarySelection(section, filters, selectionMode, includedIds, excludedIds, env, req) {
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const normalizeIdArray = (arr) => Array.from(new Set(
    (Array.isArray(arr) ? arr : [])
      .map(v => trimStr(v))
      .filter(Boolean)
  ));
  const clonePlain = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      const out = {};
      Object.keys(value).forEach((key) => {
        out[key] = value[key];
      });
      return out;
    }
  };

  const sectionKey = (() => {
    const s = trimStr(section).toLowerCase();
    if (s === 'candidate' || s === 'candidates') return 'candidates';
    if (s === 'client' || s === 'clients') return 'clients';
    if (s === 'contract' || s === 'contracts') return 'contracts';
    if (s === 'timesheet' || s === 'timesheets') return 'timesheets';
    if (s === 'invoice' || s === 'invoices') return 'invoices';
    if (s === 'umbrella' || s === 'umbrellas') return 'umbrellas';
    return '';
  })();

  if (!sectionKey) {
    throw new Error('invalid_section');
  }

  const normalizeFiltersBySection = (sectionName, rawFilters) => {
    const clean = clonePlain(rawFilters);
    if (sectionName === 'candidates') return buildCandidateSummaryFilterSpec(clean);
    if (sectionName === 'clients') return buildClientSummaryFilterSpec(clean);
    if (sectionName === 'umbrellas') return buildUmbrellaSummaryFilterSpec(clean);
    if (sectionName === 'contracts') return buildContractSummaryFilterSpec(clean);
    if (sectionName === 'timesheets') return buildTimesheetSummaryFilterSpec(clean);
    if (sectionName === 'invoices') return buildInvoiceSummaryFilterSpec(clean);
    return clean;
  };

  const rpcNameBySection = {
    candidates: 'candidate_list_ids',
    clients: 'client_list_ids',
    umbrellas: 'umbrella_list_ids',
    contracts: 'contract_list_ids',
    timesheets: 'timesheet_list_ids',
    invoices: 'invoice_list_ids'
  };

  const effectiveFilters = normalizeFiltersBySection(sectionKey, clonePlain(filters));
  const mode = trimStr(selectionMode).toLowerCase() === 'all_filtered' ? 'all_filtered' : 'explicit';
  const normalizedIncludedIds = normalizeIdArray(includedIds);
  const normalizedExcludedIds = normalizeIdArray(excludedIds);

  const rpcName = rpcNameBySection[sectionKey];
  if (!rpcName) {
    throw new Error('unsupported_section');
  }

  const rows = await sbRpcAllRows(env, rpcName, { p_filters: effectiveFilters }, { pageSize: 1000 });
  const membershipRowIds = normalizeIdArray(
    rows.map((row) => {
      if (row == null) return '';
      if (typeof row === 'string') return row;
      if (typeof row === 'object' && Object.prototype.hasOwnProperty.call(row, 'id')) return row.id;
      return '';
    })
  );

  if (mode === 'all_filtered') {
    const excludedIdSet = new Set(normalizedExcludedIds);
    return {
      summary_row_ids: membershipRowIds.filter((rowId) => !excludedIdSet.has(rowId))
    };
  }

  const membershipIdSet = new Set(membershipRowIds);
  return {
    summary_row_ids: normalizedIncludedIds.filter((rowId) => membershipIdSet.has(rowId))
  };
}


// Resolve hours (minutes) by bucket from an actual_schedule_json array
async function resolveBucketsFromSchedule(env, contract, actualDays /* array */, policyOverride = null) {
  const toIso = (v) => {
    const s0 = String(v ?? '').trim();
    if (!s0) return '';
    if (s0.includes('T')) return s0;

    let s = s0.replace(' ', 'T');
    if (s.endsWith('+00')) s = s + ':00';
    if (/[\+\-]\d{2}$/.test(s)) s = s + ':00';
    if (/[\+\-]\d{4}$/.test(s)) s = s.replace(/([\+\-]\d{2})(\d{2})$/, '$1:$2');

    return s;
  };

  const hhmmLondonFromUtc = (utcLike) => {
    const iso = toIso(utcLike);
    if (!iso) return '';
    const dt = new Date(iso);
    if (!Number.isFinite(dt.getTime())) return '';
    const parts = toLocalParts(dt.toISOString(), 'Europe/London');
    return parts.hhmm || '';
  };

  const parseIsoMs = (v) => {
    const iso = toIso(v);
    if (!iso) return NaN;
    const ms = new Date(iso).getTime();
    return Number.isFinite(ms) ? ms : NaN;
  };

  const isIsoLike = (v) => {
    const s = String(v || '').trim();
    return !!s && s.includes('T') && (s.endsWith('Z') || /[\+\-]\d{2}:\d{2}$/.test(s));
  };

  const addDays = (ymd, days) => {
    const d = new Date(`${String(ymd || '').slice(0, 10)}T00:00:00Z`);
    if (!Number.isFinite(d.getTime())) return String(ymd || '').slice(0, 10);
    d.setUTCDate(d.getUTCDate() + Number(days || 0));
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
  };

  const normYmd = (v) => {
    const s = String(v || '').trim();
    if (!s) return '';
    const out = s.slice(0, 10);
    return /^\d{4}-\d{2}-\d{2}$/.test(out) ? out : '';
  };

  const localCandidateFormatter = resolveBucketsFromSchedule._localCandidateFormatter || (resolveBucketsFromSchedule._localCandidateFormatter = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    hourCycle: 'h23'
  }));

  const localToUtcCandidates = (ymd, hhmm) => {
    const ymdStr = normYmd(ymd);
    const hm = String(hhmm || '').trim();

    const mDate = ymdStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    const mTime = hm.match(/^(\d{2}):(\d{2})(?::\d{2})?$/);
    if (!mDate || !mTime) return [];

    const Y  = Number(mDate[1]);
    const Mo = Number(mDate[2]);
    const D  = Number(mDate[3]);
    const H  = Number(mTime[1]);
    const Mi = Number(mTime[2]);
    if (!Y || Mo < 1 || Mo > 12 || D < 1 || D > 31 || H < 0 || H > 23 || Mi < 0 || Mi > 59) {
      return [];
    }

    const targetYmd = ymdStr;
    const targetHm  = `${String(H).padStart(2, '0')}:${String(Mi).padStart(2, '0')}`;

    const out = [];
    const seen = new Set();

    for (const offsetHours of [0, 1]) {
      const ms = Date.UTC(Y, Mo - 1, D, H - offsetHours, Mi, 0, 0);
      const dt = new Date(ms);
      if (!Number.isFinite(dt.getTime())) continue;

      const parts = localCandidateFormatter.formatToParts(dt);
      const year  = parts.find((p) => p.type === 'year')?.value || '';
      const month = parts.find((p) => p.type === 'month')?.value || '';
      const day   = parts.find((p) => p.type === 'day')?.value || '';
      let hour    = parts.find((p) => p.type === 'hour')?.value || '';
      const min   = parts.find((p) => p.type === 'minute')?.value || '';
      if (hour === '24') hour = '00';

      const gotYmd = (year && month && day) ? `${year}-${month}-${day}` : '';
      const gotHm  = (hour && min) ? `${hour}:${min}` : '';
      if (gotYmd !== targetYmd || gotHm !== targetHm) continue;

      const iso = dt.toISOString();
      if (seen.has(iso)) continue;
      seen.add(iso);

      out.push({ iso, ms });
    }

    out.sort((a, b) => a.ms - b.ms);
    return out;
  };

  const resolveLocalInterval = (date, startHH, endHH, label) => {
    const sMin = parseHHMM(startHH);
    const eMin = parseHHMM(endHH);
    if (sMin == null || eMin == null) {
      throw new Error(`Invalid HH:MM in actual_schedule_json for ${label}`);
    }
    if (sMin === eMin) {
      throw new Error(`Shift start and end cannot be the same on ${label}`);
    }

    const overnight = (eMin <= sMin);
    const endYmd = overnight ? addDays(date, 1) : date;

    const startCandidates = localToUtcCandidates(date, startHH);
    if (!startCandidates.length) {
      throw new Error(`Non-existent local start time on ${label}`);
    }

    const endCandidates = localToUtcCandidates(endYmd, endHH);
    if (!endCandidates.length) {
      throw new Error(`Non-existent local end time on ${label}`);
    }

    const pairs = [];
    const seenPairs = new Set();
    for (const a of startCandidates) {
      for (const b of endCandidates) {
        if (b.ms <= a.ms) continue;
        const key = `${a.iso}|${b.iso}`;
        if (seenPairs.has(key)) continue;
        seenPairs.add(key);
        pairs.push({
          startIso: a.iso,
          endIso: b.iso,
          startMs: a.ms,
          endMs: b.ms
        });
      }
    }

    if (!pairs.length) {
      throw new Error(`Invalid local time range on ${label}`);
    }

    const uniquePairs = Array.from(new Map(
      pairs.map((p) => [`${p.startMs}|${p.endMs}`, p])
    ).values());

    if (uniquePairs.length > 1) {
      throw new Error(`Ambiguous local time range across DST change on ${label}`);
    }

    return uniquePairs[0];
  };

  const nextLondonTransitionMs = (afterMs) => {
    const d = new Date(afterMs);
    if (!Number.isFinite(d.getTime())) return Infinity;

    let best = Infinity;
    for (const year of [d.getUTCFullYear() - 1, d.getUTCFullYear(), d.getUTCFullYear() + 1, d.getUTCFullYear() + 2]) {
      for (const cand of [bstStartUtc(year), bstEndUtc(year)]) {
        if (cand > afterMs && cand < best) best = cand;
      }
    }
    return best;
  };

  const actualBucketsFromSegments = (segments, policy) => {
    const tmpAcc = { day: 0, night: 0, sat: 0, sun: 0, bh: 0 };

    for (const seg of segments) {
      let curMs = seg.startMs;
      const endMs = seg.endMs;

      while (curMs < endMs) {
        const curIso = new Date(curMs).toISOString();
        const parts = toLocalParts(curIso, 'Europe/London');
        if (!parts || !parts.ymd) break;

        const nextMidnightIso = ukLocalToUtcISO(addDays(parts.ymd, 1), '00:00', { prefer: 'earlier' });
        const nextMidnightMs = nextMidnightIso ? new Date(nextMidnightIso).getTime() : Infinity;
        const nextTzMs = nextLondonTransitionMs(curMs);

        let sliceEndMs = endMs;
        if (Number.isFinite(nextMidnightMs) && nextMidnightMs > curMs && nextMidnightMs < sliceEndMs) {
          sliceEndMs = nextMidnightMs;
        }
        if (Number.isFinite(nextTzMs) && nextTzMs > curMs && nextTzMs < sliceEndMs) {
          sliceEndMs = nextTzMs;
        }
        if (!(sliceEndMs > curMs)) break;

        const mins = Math.round((sliceEndMs - curMs) / 60000);
        if (mins > 0) {
          const fromMin = (parts.hh * 60) + parts.mm;
          const toMin = fromMin + mins;
          segmentChunkIntoBuckets(parts.ymd, fromMin, toMin, policy, tmpAcc);
        }

        curMs = sliceEndMs;
      }
    }

    return tmpAcc;
  };

  const normDays = (Array.isArray(actualDays) ? actualDays : []).map((d) => {
    if (!d || typeof d !== 'object') return d;
    const out = { ...d };

    const derivedDate = (!out.date && out.start_utc)
      ? (toLocalParts(toIso(out.start_utc), 'Europe/London').ymd || '')
      : '';
    if (derivedDate && !out.date) out.date = derivedDate;

    if ((!out.start || !String(out.start).trim()) && out.start_utc) {
      out.start = hhmmLondonFromUtc(out.start_utc);
    }
    if ((!out.end || !String(out.end).trim()) && out.end_utc) {
      out.end = hhmmLondonFromUtc(out.end_utc);
    }

    const bm =
      (out.break_minutes != null && String(out.break_minutes).trim() !== '')
        ? Number(out.break_minutes)
        : (out.break_mins != null && String(out.break_mins).trim() !== '')
          ? Number(out.break_mins)
          : null;

    if (Number.isFinite(bm) && bm > 0) {
      out.break_minutes = Math.floor(bm);
    }

    return out;
  });

  const toNumericPolicyFromSql = (p) => {
    const hhmmssToMin = (val, fallback = '00:00:00') => {
      const s = String(val ?? fallback).trim();
      if (!s) return 0;
      const parts = s.split(':');
      const h = parseInt(parts[0] || '0', 10) || 0;
      const m = parseInt(parts[1] || '0', 10) || 0;
      return (h * 60) + m;
    };

    let bhArr = [];
    if (Array.isArray(p?.bh_list)) {
      bhArr = p.bh_list.map(String);
    } else if (typeof p?.bh_list === 'string') {
      try {
        const parsed = JSON.parse(p.bh_list);
        if (Array.isArray(parsed)) bhArr = parsed.map(String);
      } catch {}
    }

    return {
      dayStart:   hhmmssToMin(p?.day_start,   '06:00:00'),
      dayEnd:     hhmmssToMin(p?.day_end,     '20:00:00'),
      nightStart: hhmmssToMin(p?.night_start, '20:00:00'),
      nightEnd:   hhmmssToMin(p?.night_end,   '06:00:00'),
      satStart:   hhmmssToMin(p?.sat_start,   '00:00:00'),
      satEnd:     hhmmssToMin(p?.sat_end,     '00:00:00'),
      sunStart:   hhmmssToMin(p?.sun_start,   '00:00:00'),
      sunEnd:     hhmmssToMin(p?.sun_end,     '00:00:00'),
      bhStart:    hhmmssToMin(p?.bh_start,    '00:00:00'),
      bhEnd:      hhmmssToMin(p?.bh_end,      '00:00:00'),
      bhList:     new Set(bhArr),
    };
  };

  const policy = policyOverride
    ? (typeof policyOverride?.dayStart === 'number' ? policyOverride : toNumericPolicyFromSql(policyOverride))
    : await loadClientTimePolicy(env, contract.client_id);

  const acc = { day: 0, night: 0, sat: 0, sun: 0, bh: 0 };

  if (typeof segmentChunkIntoBuckets !== 'function') {
    throw new Error('segmentChunkIntoBuckets is missing (required for BH/Sun/Sat/Night/Day precedence bucketing)');
  }
  if (typeof applyDurationBreak !== 'function') {
    throw new Error('applyDurationBreak is missing (required for floating break_minutes bucketing)');
  }

  const logBuckets = (label, payload) => {
    try {
      console.log('[BUCKETS]', label, JSON.stringify(payload));
    } catch {}
  };

  const hasText = (v) => v != null && String(v).trim() !== '';
  const byDate = new Map();

  logBuckets('policy', { client_id: contract.client_id, contract_id: contract.id, policy });

  for (const d of (normDays || [])) {
    if (!d || typeof d !== 'object') continue;

    const date = normYmd(d.date);
    if (!date) continue;
    const label = date;

    const startIsoRaw = d.start_utc || d.start_iso || null;
    const endIsoRaw   = d.end_utc   || d.end_iso   || null;
    const hasShiftIso = !!(startIsoRaw && endIsoRaw && isIsoLike(startIsoRaw) && isIsoLike(endIsoRaw));
    const hasShiftLocal = hasText(d.start) && hasText(d.end);

    const rawBreaksArr = Array.isArray(d.breaks)
      ? d.breaks.filter((b) => b && (hasText(b.start) || hasText(b.end)))
      : [];
    const hasBreakWindowScalar = hasText(d.break_start) || hasText(d.break_end);

    const rawBm =
      (d.break_minutes != null && String(d.break_minutes).trim() !== '')
        ? Number(d.break_minutes)
        : (d.break_mins != null && String(d.break_mins).trim() !== '')
          ? Number(d.break_mins)
          : null;
    const hasBreakMins = Number.isFinite(rawBm) && rawBm > 0;

    if (!hasShiftIso && !hasShiftLocal) {
      if (rawBreaksArr.length || hasBreakWindowScalar || hasBreakMins) {
        throw new Error(`Breaks require a valid shift start/end on ${label}`);
      }
      continue;
    }

    let shift = null;
    if (hasShiftIso) {
      const startIso = toIso(startIsoRaw);
      const endIso   = toIso(endIsoRaw);
      const startMs = parseIsoMs(startIso);
      const endMs   = parseIsoMs(endIso);
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        throw new Error(`Invalid UTC shift range on ${label}`);
      }
      shift = { startIso, endIso, startMs, endMs };
    } else {
      shift = resolveLocalInterval(date, String(d.start).trim(), String(d.end).trim(), label);
    }

    if (!byDate.has(date)) byDate.set(date, []);
    byDate.get(date).push({ startMs: shift.startMs, endMs: shift.endMs });

    const windowBreaks = [];
    if (rawBreaksArr.length) {
      for (const br of rawBreaksArr) {
        const hasStart = hasText(br.start);
        const hasEnd   = hasText(br.end);
        if (hasStart !== hasEnd) {
          throw new Error(`Break start/end must both be set (or both blank) on ${label}`);
        }
        if (!hasStart && !hasEnd) continue;
        windowBreaks.push({ start: String(br.start).trim(), end: String(br.end).trim() });
      }
    } else if (hasBreakWindowScalar) {
      if (!(hasText(d.break_start) && hasText(d.break_end))) {
        throw new Error(`Break start/end must both be set (or both blank) on ${label}`);
      }
      windowBreaks.push({ start: String(d.break_start).trim(), end: String(d.break_end).trim() });
    }

    if (hasBreakMins && windowBreaks.length) {
      throw new Error(`Use either break_minutes OR break start/end windows (not both) on ${label}`);
    }

    const beforeWork = { ...acc };
    const workedBuckets = actualBucketsFromSegments([shift], policy);
    for (const k of Object.keys(acc)) {
      acc[k] += (workedBuckets[k] || 0);
    }

    const workedDelta = {};
    for (const k of Object.keys(acc)) {
      const delta = (acc[k] || 0) - (beforeWork[k] || 0);
      if (delta !== 0) workedDelta[k] = delta;
    }

    logBuckets('day-entry', {
      date,
      start: d.start || null,
      end: d.end || null,
      start_utc: shift.startIso,
      end_utc: shift.endIso,
      breaks: rawBreaksArr.length ? rawBreaksArr : null,
      break_minutes: hasBreakMins ? Math.floor(rawBm) : null
    });

    logBuckets('work-chunk', {
      chunk_date: date,
      added_minutes: workedDelta,
      acc_after: acc
    });

    if (windowBreaks.length) {
      const breakSegs = [];
      for (const br of windowBreaks) {
        const brSeg = resolveLocalInterval(date, br.start, br.end, `${label} (break window)`);
        if (brSeg.startMs < shift.startMs || brSeg.endMs > shift.endMs) {
          throw new Error(`Break window must sit within shift range on ${label}`);
        }
        breakSegs.push(brSeg);
      }

      breakSegs.sort((a, b) => a.startMs - b.startMs);
      for (let i = 1; i < breakSegs.length; i++) {
        if (breakSegs[i].startMs < breakSegs[i - 1].endMs) {
          throw new Error(`Overlapping break windows detected on ${label}`);
        }
      }

      const tmp = actualBucketsFromSegments(breakSegs, policy);
      logBuckets('break-window', {
        date,
        break_minutes_per_bucket: tmp
      });

      const beforeAcc = { ...acc };
      for (const k of Object.keys(acc)) {
        acc[k] = Math.max(0, acc[k] - (tmp[k] || 0));
      }

      const diffAfter = {};
      for (const k of Object.keys(acc)) {
        const delta = (acc[k] || 0) - (beforeAcc[k] || 0);
        if (delta !== 0) diffAfter[k] = delta;
      }

      logBuckets('break-applied', { date, delta_minutes: diffAfter, acc_after: acc });
    } else if (hasBreakMins) {
      const actualShiftMinutes = Math.round((shift.endMs - shift.startMs) / 60000);
      if (rawBm >= actualShiftMinutes) {
        throw new Error(`break_minutes must be less than shift duration on ${label}`);
      }

      const mins = Math.floor(rawBm);
      const beforeAcc = { ...acc };
      applyDurationBreak(acc, mins);

      const diffAfter = {};
      for (const k of Object.keys(acc)) {
        const delta = (acc[k] || 0) - (beforeAcc[k] || 0);
        if (delta !== 0) diffAfter[k] = delta;
      }

      logBuckets('floating-break-applied', { date, break_minutes: mins, delta_minutes: diffAfter, acc_after: acc });
    }

    logBuckets('day-summary', { date, acc_after_day: { ...acc } });
  }

  for (const [date, segments] of byDate.entries()) {
    if (!Array.isArray(segments) || segments.length < 2) continue;

    segments.sort((a, b) => a.startMs - b.startMs);
    for (let i = 1; i < segments.length; i++) {
      if (segments[i].startMs < segments[i - 1].endMs) {
        throw new Error(`Overlapping shifts detected on ${date}`);
      }
    }
  }

  logBuckets('final-accumulator', acc);
  return acc;
}



// Validate that, within a single timesheet schedule:
// - Each shift has valid start/end HH:MM
// - No shift overlaps another shift on the same date
// - Break windows (primary + extras) are inside their shift window
// Throws Error with a descriptive message if invalid.
function validateScheduleStructure(actualDays /* array of {date,start,end,breaks?,break_start?,break_end?,break_minutes?} */) {
  if (!Array.isArray(actualDays) || !actualDays.length) return;

  const byDate = new Map();
  const hasText = (v) => v != null && String(v).trim() !== '';

  const pad2 = (n) => String(n).padStart(2, '0');

  const normalizeHhmm = (v) => {
    const mins = parseHHMM(v);
    if (mins == null) return null;
    const hh = Math.floor(mins / 60);
    const mm = mins % 60;
    return `${pad2(hh)}:${pad2(mm)}`;
  };

  const addDaysYmd = (ymd, days) => {
    const d = new Date(`${String(ymd)}T00:00:00Z`);
    if (!Number.isFinite(d.getTime())) return null;
    d.setUTCDate(d.getUTCDate() + Number(days || 0));
    return `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
  };

  const localToUtcIso = (ymd, hhmm, addDays = 0, opts = null) => {
    if (!ymd || !hhmm) return null;

    const base = new Date(`${String(ymd)}T00:00:00Z`);
    if (!Number.isFinite(base.getTime())) return null;
    if (addDays) {
      base.setUTCDate(base.getUTCDate() + Number(addDays || 0));
    }

    const y2 = base.getUTCFullYear();
    const m2 = base.getUTCMonth() + 1;
    const d2 = base.getUTCDate();
    const targetYmd = `${y2}-${pad2(m2)}-${pad2(d2)}`;

    if (typeof ukLocalToUtcISO === 'function') {
      const options = (opts && typeof opts === 'object') ? opts : null;
      return ukLocalToUtcISO(targetYmd, hhmm, options);
    }

    const m = String(hhmm).trim().match(/^(\d{2}):(\d{2})(?::\d{2})?$/);
    if (!m) return null;
    const hh = Number(m[1]);
    const mm = Number(m[2]);
    if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;

    return new Date(Date.UTC(y2, m2 - 1, d2, hh, mm, 0, 0)).toISOString();
  };

  const uniqueLocalUtcCandidates = (ymd, hhmm) => {
    const out = [];
    const seen = new Set();

    const pushIso = (iso) => {
      if (!iso) return;
      const ms = new Date(String(iso)).getTime();
      if (!Number.isFinite(ms)) return;
      const normIso = new Date(ms).toISOString();
      if (seen.has(normIso)) return;
      seen.add(normIso);
      out.push({ iso: normIso, ms });
    };

    if (typeof ukLocalToUtcISO === 'function') {
      pushIso(localToUtcIso(ymd, hhmm, 0, { prefer: 'earlier' }));
      pushIso(localToUtcIso(ymd, hhmm, 0, { prefer: 'later' }));
    } else {
      pushIso(localToUtcIso(ymd, hhmm, 0));
    }

    out.sort((a, b) => a.ms - b.ms);
    return out;
  };

  const resolveActualShiftMinutes = (dateYmd, startRaw, endRaw) => {
    const startHhmm = normalizeHhmm(startRaw);
    const endHhmm = normalizeHhmm(endRaw);
    if (!dateYmd || !startHhmm || !endHhmm) return null;

    const startMin = parseHHMM(startHhmm);
    const endMin = parseHHMM(endHhmm);
    if (startMin == null || endMin == null) return null;
    if (startMin === endMin) return null;

    const overnight = endMin <= startMin;
    const endYmd = overnight ? addDaysYmd(dateYmd, 1) : dateYmd;
    if (!endYmd) {
      throw new Error(`Invalid work date for ${dateYmd}`);
    }

    if (typeof ukLocalToUtcISO !== 'function') {
      const startIso = localToUtcIso(dateYmd, startHhmm, 0);
      const endIso = localToUtcIso(dateYmd, endHhmm, overnight ? 1 : 0);
      const startMs = new Date(String(startIso || '')).getTime();
      const endMs = new Date(String(endIso || '')).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        throw new Error(`Invalid local time range on ${dateYmd}`);
      }
      return Math.round((endMs - startMs) / 60000);
    }

    const startCandidates = uniqueLocalUtcCandidates(dateYmd, startHhmm);
    if (!startCandidates.length) {
      throw new Error(`Non-existent local start time on ${dateYmd}`);
    }

    const endCandidates = uniqueLocalUtcCandidates(endYmd, endHhmm);
    if (!endCandidates.length) {
      throw new Error(`Non-existent local end time on ${endYmd}`);
    }

    const pairMap = new Map();

    const pushPair = (startIso, endIso) => {
      if (!startIso || !endIso) return;
      const startMs = new Date(String(startIso)).getTime();
      const endMs = new Date(String(endIso)).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return;
      const key = `${startMs}|${endMs}`;
      if (pairMap.has(key)) return;
      pairMap.set(key, { startMs, endMs });
    };

    for (const startCand of startCandidates) {
      const endIsoAfterStart = localToUtcIso(endYmd, endHhmm, 0, { afterIso: startCand.iso, prefer: 'later' });
      pushPair(startCand.iso, endIsoAfterStart);

      for (const endCand of endCandidates) {
        pushPair(startCand.iso, endCand.iso);
      }
    }

    const pairs = Array.from(pairMap.values()).sort((a, b) => a.startMs - b.startMs || a.endMs - b.endMs);

    if (!pairs.length) {
      throw new Error(`Invalid local time range on ${dateYmd}`);
    }

    if (pairs.length > 1) {
      throw new Error(`Ambiguous local time range across DST change on ${dateYmd}`);
    }

    return Math.round((pairs[0].endMs - pairs[0].startMs) / 60000);
  };

  const breakMinutesValue = (d) => {
    if (!d) return null;
    // accept break_minutes or break_mins
    const raw = (d.break_minutes != null) ? d.break_minutes : d.break_mins;
    if (raw == null || raw === '') return null;

    const n = Number(raw);
    if (!Number.isFinite(n)) {
      throw new Error(`Invalid break_minutes (must be numeric) on ${String(d.date || '').trim() || 'unknown date'}`);
    }
    if (n < 0) {
      throw new Error(`Invalid break_minutes (must be >= 0) on ${String(d.date || '').trim() || 'unknown date'}`);
    }
    return Math.floor(n);
  };

  const hasAnyBreakTimes = (d) => {
    if (!d) return false;
    if (hasText(d.break_start) || hasText(d.break_end)) return true;
    if (Array.isArray(d.breaks)) {
      return d.breaks.some(b => b && (hasText(b.start) || hasText(b.end)));
    }
    return false;
  };

  for (const d of actualDays) {
    if (!d || !d.date) continue;
    const date = d.date;

    const hasStart = hasText(d.start);
    const hasEnd   = hasText(d.end);

    // shift start/end must both exist or neither
    if (hasStart !== hasEnd) {
      throw new Error(`Shift start/end must both be set (or both blank) for ${date}`);
    }

    const hasWindowBreaks = hasAnyBreakTimes(d);
    const bm = breakMinutesValue(d);
    const hasBreakMins = (bm != null && bm > 0);

    // If no shift, there must be no breaks of any kind
    if (!hasStart && !hasEnd) {
      if (hasWindowBreaks || hasBreakMins) {
        throw new Error(`Breaks require a valid shift start/end on ${date}`);
      }
      continue;
    }

    const s = parseHHMM(d.start);
    const e = parseHHMM(d.end);

    // hard error if invalid HH:MM
    if (s == null || e == null) {
      throw new Error(`Invalid HH:MM in actual_schedule_json for ${date}`);
    }

    // start != end
    if (s === e) {
      throw new Error(`Shift start and end cannot be the same on ${date}`);
    }

    // start after end allowed only as overnight (wrap)
    const shiftStartMin = s;
    const shiftEndMin   = (e > s) ? e : (e + 1440); // overnight ok
    const shiftMinutes  = shiftEndMin - shiftStartMin;
    const actualShiftMinutes = resolveActualShiftMinutes(date, d.start, d.end);

    // Disallow mixing break minutes with break windows on the same segment
    if (hasBreakMins && hasWindowBreaks) {
      throw new Error(`Use either break_minutes OR break start/end windows (not both) on ${date}`);
    }

    // Sanity check floating break minutes
    if (hasBreakMins) {
      if (bm >= actualShiftMinutes) {
        throw new Error(`break_minutes must be less than shift duration on ${date}`);
      }
    }

    if (!byDate.has(date)) byDate.set(date, []);
    byDate.get(date).push({
      startMin: shiftStartMin,
      endMin:   shiftEndMin,
      entry:    d,
    });

    // Validate breaks for this shift (all rules, overnight-aware)
    // - validateBreaksForShift already checks window breaks; we only call it if windows exist
    // - break_minutes is validated above
    if (hasWindowBreaks) {
      validateBreaksForShift(date, shiftStartMin, shiftEndMin, shiftMinutes, d, actualShiftMinutes);
    }
  }

  // Overlapping shifts per date (overnight-aware because endMin may exceed 1440)
  for (const [date, segments] of byDate.entries()) {
    if (!Array.isArray(segments) || segments.length < 2) continue;

    segments.sort((a, b) => a.startMin - b.startMin);

    for (let i = 1; i < segments.length; i++) {
      const prev = segments[i - 1];
      const cur  = segments[i];
      if (cur.startMin < prev.endMin) {
        throw new Error(`Overlapping shifts detected on ${date}`);
      }
    }
  }
}

function validateBreaksForShift(date, shiftStartMin, shiftEndMin, shiftMinutes, d, actualShiftMinutes) {
  const hasText = (v) => v != null && String(v).trim() !== '';

  const pad2 = (n) => String(n).padStart(2, '0');

  const normalizeHhmm = (v) => {
    const mins = parseHHMM(v);
    if (mins == null) return null;
    const hh = Math.floor(mins / 60);
    const mm = mins % 60;
    return `${pad2(hh)}:${pad2(mm)}`;
  };

  const addDaysYmd = (ymd, days) => {
    const dt = new Date(`${String(ymd)}T00:00:00Z`);
    if (!Number.isFinite(dt.getTime())) return null;
    dt.setUTCDate(dt.getUTCDate() + Number(days || 0));
    return `${dt.getUTCFullYear()}-${pad2(dt.getUTCMonth() + 1)}-${pad2(dt.getUTCDate())}`;
  };

  const localToUtcIso = (ymd, hhmm, addDays = 0, opts = null) => {
    if (!ymd || !hhmm) return null;

    const base = new Date(`${String(ymd)}T00:00:00Z`);
    if (!Number.isFinite(base.getTime())) return null;
    if (addDays) {
      base.setUTCDate(base.getUTCDate() + Number(addDays || 0));
    }

    const y2 = base.getUTCFullYear();
    const m2 = base.getUTCMonth() + 1;
    const d2 = base.getUTCDate();
    const targetYmd = `${y2}-${pad2(m2)}-${pad2(d2)}`;

    if (typeof ukLocalToUtcISO === 'function') {
      const options = (opts && typeof opts === 'object') ? opts : null;
      return ukLocalToUtcISO(targetYmd, hhmm, options);
    }

    const m = String(hhmm).trim().match(/^(\d{2}):(\d{2})(?::\d{2})?$/);
    if (!m) return null;
    const hh = Number(m[1]);
    const mm = Number(m[2]);
    if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;

    return new Date(Date.UTC(y2, m2 - 1, d2, hh, mm, 0, 0)).toISOString();
  };

  const uniqueLocalUtcCandidates = (ymd, hhmm) => {
    const out = [];
    const seen = new Set();

    const pushIso = (iso) => {
      if (!iso) return;
      const ms = new Date(String(iso)).getTime();
      if (!Number.isFinite(ms)) return;
      const normIso = new Date(ms).toISOString();
      if (seen.has(normIso)) return;
      seen.add(normIso);
      out.push({ iso: normIso, ms });
    };

    if (typeof ukLocalToUtcISO === 'function') {
      pushIso(localToUtcIso(ymd, hhmm, 0, { prefer: 'earlier' }));
      pushIso(localToUtcIso(ymd, hhmm, 0, { prefer: 'later' }));
    } else {
      pushIso(localToUtcIso(ymd, hhmm, 0));
    }

    out.sort((a, b) => a.ms - b.ms);
    return out;
  };

  const resolveActualShiftMinutes = () => {
    if (!d || !d.date) return shiftMinutes;

    const startHhmm = normalizeHhmm(d.start);
    const endHhmm = normalizeHhmm(d.end);
    if (!startHhmm || !endHhmm) return shiftMinutes;

    const startMin = parseHHMM(startHhmm);
    const endMin = parseHHMM(endHhmm);
    if (startMin == null || endMin == null || startMin === endMin) return shiftMinutes;

    const overnight = endMin <= startMin;
    const endYmd = overnight ? addDaysYmd(d.date, 1) : d.date;
    if (!endYmd) {
      throw new Error(`Invalid work date for ${date}`);
    }

    if (typeof ukLocalToUtcISO !== 'function') {
      const startIso = localToUtcIso(d.date, startHhmm, 0);
      const endIso = localToUtcIso(d.date, endHhmm, overnight ? 1 : 0);
      const startMs = new Date(String(startIso || '')).getTime();
      const endMs = new Date(String(endIso || '')).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        throw new Error(`Invalid local time range on ${date}`);
      }
      return Math.round((endMs - startMs) / 60000);
    }

    const startCandidates = uniqueLocalUtcCandidates(d.date, startHhmm);
    if (!startCandidates.length) {
      throw new Error(`Non-existent local start time on ${date}`);
    }

    const endCandidates = uniqueLocalUtcCandidates(endYmd, endHhmm);
    if (!endCandidates.length) {
      throw new Error(`Non-existent local end time on ${endYmd}`);
    }

    const pairMap = new Map();

    const pushPair = (startIso, endIso) => {
      if (!startIso || !endIso) return;
      const startMs = new Date(String(startIso)).getTime();
      const endMs = new Date(String(endIso)).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return;
      const key = `${startMs}|${endMs}`;
      if (pairMap.has(key)) return;
      pairMap.set(key, { startMs, endMs });
    };

    for (const startCand of startCandidates) {
      const endIsoAfterStart = localToUtcIso(endYmd, endHhmm, 0, { afterIso: startCand.iso, prefer: 'later' });
      pushPair(startCand.iso, endIsoAfterStart);

      for (const endCand of endCandidates) {
        pushPair(startCand.iso, endCand.iso);
      }
    }

    const pairs = Array.from(pairMap.values()).sort((a, b) => a.startMs - b.startMs || a.endMs - b.endMs);

    if (!pairs.length) {
      throw new Error(`Invalid local time range on ${date}`);
    }

    if (pairs.length > 1) {
      throw new Error(`Ambiguous local time range across DST change on ${date}`);
    }

    return Math.round((pairs[0].endMs - pairs[0].startMs) / 60000);
  };

  const effectiveShiftMinutes =
    (Number.isFinite(Number(actualShiftMinutes)) && Number(actualShiftMinutes) > 0)
      ? Number(actualShiftMinutes)
      : resolveActualShiftMinutes();

  // ✅ If break_minutes/break_mins is used, do not accept break windows too.
  // validateScheduleStructure already validates bm < shiftMinutes, but keep it defensive here too.
  const rawBm = (d && (d.break_minutes != null ? d.break_minutes : d.break_mins));
  const bm = (rawBm == null || rawBm === '') ? null : Number(rawBm);
  const hasBreakMins = (bm != null && Number.isFinite(bm) && bm > 0);

  const hasWindow =
    (hasText(d?.break_start) || hasText(d?.break_end)) ||
    (Array.isArray(d?.breaks) && d.breaks.some(b => b && (hasText(b.start) || hasText(b.end))));

  if (hasBreakMins) {
    if (hasWindow) {
      throw new Error(`Use either break_minutes OR break windows (not both) on ${date}`);
    }
    if (bm >= effectiveShiftMinutes) {
      throw new Error(`break_minutes must be less than shift length on ${date}`);
    }
    return; // nothing else to validate
  }

  // Choose canonical break windows:
  // - if breaks[] has any populated entries, use that
  // - else fall back to break_start/break_end
  let windows = [];
  const breaksArr = Array.isArray(d.breaks) ? d.breaks.filter(b => b && (hasText(b.start) || hasText(b.end))) : [];

  if (breaksArr.length) {
    windows = breaksArr.map((b, i) => ({ start: b.start, end: b.end, idx: i }));
  } else if (hasText(d.break_start) || hasText(d.break_end)) {
    windows = [{ start: d.break_start, end: d.break_end, idx: -1 }];
  }

  // break windows must both exist or neither; start!=end; ordering allows overnight only if still within shift span
  const ranges = []; // { bsAdj, beAdj }

  for (const w of windows) {
    const hasBStart = hasText(w.start);
    const hasBEnd   = hasText(w.end);

    if (hasBStart !== hasBEnd) {
      throw new Error(`Break start/end must both be set (or both blank) on ${date}`);
    }
    if (!hasBStart && !hasBEnd) continue;

    const bs0 = parseHHMM(w.start);
    const be0 = parseHHMM(w.end);

    if (bs0 == null || be0 == null) {
      throw new Error(`Invalid HH:MM in break window on ${date}`);
    }
    if (bs0 === be0) {
      throw new Error(`Break start and end cannot be the same on ${date}`);
    }

    // Place break on same timeline as shift (overnight-aware)
    let bsAdj = bs0;
    if (bsAdj < shiftStartMin) bsAdj += 1440;

    let beAdj = be0;
    if (beAdj <= bsAdj) beAdj += 1440; // break overnight allowed

    // Must be fully within shift span
    if (bsAdj < shiftStartMin || beAdj > shiftEndMin || beAdj <= bsAdj) {
      throw new Error(`Break must be within shift on ${date} (${w.start}-${w.end})`);
    }

    ranges.push({ bsAdj, beAdj });
  }

  // break windows must not overlap each other
  ranges.sort((a, b) => a.bsAdj - b.bsAdj);
  for (let i = 1; i < ranges.length; i++) {
    if (ranges[i].bsAdj < ranges[i - 1].beAdj) {
      throw new Error(`Overlapping breaks detected on ${date}`);
    }
  }

  // Optional sanity: total break minutes < shift minutes (prevents break >= shift)
  const totalBreakMin = ranges.reduce((sum, r) => sum + (r.beAdj - r.bsAdj), 0);
  if (totalBreakMin >= effectiveShiftMinutes) {
    throw new Error(`Total break time must be less than shift length on ${date}`);
  }
}

async function r2GetJSON(env, key) {
  const u8 = await r2GetBytes(env, key);
  if (!u8) return null;
  try { return JSON.parse(new TextDecoder().decode(u8)); }
  catch { return null; }
}

async function r2PutJSON(env, key, obj, opts = {}) {
  const json = JSON.stringify(obj, null, 2);
  return r2Put(env, key, json, { httpMetadata: { contentType: 'application/json' }, ...opts });
}

