  const idIn = String(timesheetId || '').trim();
  if (!idIn) return withCORS(env, req, badRequest('timesheet_id is required'));

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
