async function handleOutboxDeleteAction(rowOrItem, opts = {}) {
  const row = (rowOrItem && typeof rowOrItem === 'object') ? rowOrItem : {};
  const channel = String(row.channel || '').trim().toUpperCase();
  const outboxId = String(row.outbox_id || row.id || '').trim();

  if (!channel) throw new Error('channel is required');
  if (!outboxId) throw new Error('outbox id is required');

  let confirmed = true;
  if (typeof openUiConfirmModal === 'function') {
    const confirmRes = await openUiConfirmModal({
      title: 'Delete Outbox item?',
      message: 'This will attempt to delete the selected Outbox row. Rows that are already sent, delivered, or read will be blocked by the backend.',
      confirm_label: 'Delete',
      cancel_label: 'Cancel',
      confirm_class: 'btn btn-warn',
      cancel_class: 'btn btn-outline'
    });
    confirmed = !!(confirmRes && confirmRes.confirmed === true);
  }

  if (!confirmed) return { ok: false, cancelled: true };

  try {
    const res = await apiDeleteOutboxItem(channel, outboxId);

    try {
      window.__selection = window.__selection || {};
      const sel = window.__selection.outbox;
      if (sel && sel.ids instanceof Set) {
        sel.ids.delete(outboxId);
      }
    } catch {}

    if (typeof opts.onDone === 'function') {
      await opts.onDone(res);
    } else if (String(currentSection || '').trim().toLowerCase() === 'outbox') {
      const data = await loadSection();
      renderSummary(data);
    }

    if (opts.closeOnDelete) {
      try {
        if (typeof closeModal === 'function') closeModal();
      } catch {}
    }

    return res;
  } catch (e) {
    if (typeof openUiConfirmModal === 'function') {
      await openUiConfirmModal({
        title: 'Delete Outbox item',
        message: String(e?.message || e || 'Delete failed'),
        confirm_label: 'OK',
        hide_cancel: true,
        confirm_class: 'btn btn-primary'
      });
    }
    throw e;
  }
}





async function submitSendMailshotWizard() {
  const state = (window.modalCtx && window.modalCtx.mailshotWizard && typeof window.modalCtx.mailshotWizard === 'object')
    ? window.modalCtx.mailshotWizard
    : null;

  if (!state) throw new Error('Mailshot wizard state is not available');

  const rerender = (typeof window.__mailshotWizardRerender === 'function')
    ? window.__mailshotWizardRerender
    : null;

  const trimStr = (v) => String(v == null ? '' : v).trim();

  const htmlToText = (html) => {
    try {
      const div = document.createElement('div');
      div.innerHTML = String(html || '');
      return String(div.textContent || div.innerText || '')
        .replace(/\u00a0/g, ' ')
        .replace(/\r/g, '')
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    } catch {
      return String(html || '').trim();
    }
  };

  const syncStateFromDom = () => {
    try {
      const subjectEl = document.getElementById('msw_subject');
      if (subjectEl) state.edited_content.subject = String(subjectEl.value ?? '');

      const ccEl = document.getElementById('msw_cc');
      if (ccEl) state.edited_content.cc = String(ccEl.value ?? '');

      const bccEl = document.getElementById('msw_bcc');
      if (bccEl) state.edited_content.bcc = String(bccEl.value ?? '');

      const replyEl = document.getElementById('msw_reply_to');
      if (replyEl) state.edited_content.reply_to = String(replyEl.value ?? '');

      const impEl = document.getElementById('msw_importance');
      if (impEl) state.edited_content.importance = String(impEl.value || 'Normal');

      const emailTypeEl = document.getElementById('msw_email_type');
      if (emailTypeEl) state.edited_content.email_type = String(emailTypeEl.value || 'html').toLowerCase();

      const bodyTextEl = document.getElementById('msw_body_text');
      if (bodyTextEl) state.edited_content.body_text = String(bodyTextEl.value ?? '');

      const bodyHtmlEl = document.getElementById('msw_body_html');
      if (bodyHtmlEl) {
        state.edited_content.body_html = String(bodyHtmlEl.value ?? '');
        if (!trimStr(state.edited_content.body_text)) {
          state.edited_content.body_text = htmlToText(state.edited_content.body_html);
        }
      }

      const messageEl = document.getElementById('msw_message_text');
      if (messageEl) state.edited_content.message_text = String(messageEl.value ?? '');

      const timingModeEl = document.getElementById('msw_timing_mode');
      if (timingModeEl) state.delivery_timing.mode = trimStr(timingModeEl.value || 'NOW').toUpperCase();

      const timingAtEl = document.getElementById('msw_timing_scheduled_for_utc');
      if (timingAtEl) {
        const raw = String(timingAtEl.value ?? '').trim();
        state.delivery_timing.scheduled_for_utc = raw ? new Date(raw).toISOString() : '';
      }

      const timingDelayEl = document.getElementById('msw_timing_relative_minutes');
      if (timingDelayEl) state.delivery_timing.relative_minutes = String(timingDelayEl.value ?? '');

      state.final_action = (state.output_type === 'WORD' || state.output_type === 'EXCEL' || state.output_type === 'CSV')
        ? 'export'
        : 'enqueue';
    } catch {}
  };

  const buildFinalEditsJson = () => {
    const serialized = serializeTemplateEditorContent({
      output_type: state.output_type,
      email_type: state.edited_content.email_type,
      selected_field_keys: state.edited_content.selected_field_keys,
      subject: state.edited_content.subject,
      body_html: state.edited_content.body_html,
      body_text: state.edited_content.body_text,
      message_text: state.edited_content.message_text,
      cc: state.edited_content.cc,
      bcc: state.edited_content.bcc,
      reply_to: state.edited_content.reply_to,
      importance: state.edited_content.importance,
      editor: {
        output_type: state.output_type,
        email_type: state.edited_content.email_type,
        subject: state.edited_content.subject,
        body_html: state.edited_content.body_html,
        body_text: state.edited_content.body_text,
        message_text: state.edited_content.message_text,
        cc: state.edited_content.cc,
        bcc: state.edited_content.bcc,
        reply_to: state.edited_content.reply_to,
        importance: state.edited_content.importance,
        selected_field_keys: state.edited_content.selected_field_keys
      },
      hostId: 'msw_rich_editor_host',
      hiddenInputId: 'msw_body_html'
    });

    const content = (serialized && serialized.template_content_json && typeof serialized.template_content_json === 'object')
      ? serialized.template_content_json
      : {};

    const out = {};

    if (state.output_type === 'EMAIL') {
      out.subject = String(content.subject || '');
      out.body_html = String(content.body_html || '');
      out.body_text = String(content.body_text || '');
      out.cc = String(content.cc || '');
      out.bcc = String(content.bcc || '');
      out.reply_to = String(content.reply_to || '');
      out.importance = String(content.importance || 'Normal');
      out.email_type = String(content.email_type || 'html').toLowerCase();
    } else if (state.output_type === 'WORD') {
      out.body_html = String(content.body_html || '');
      out.body_text = String(content.body_text || '');
    } else if (state.output_type === 'WHATSAPP' || state.output_type === 'SMS' || state.output_type === 'VOICE') {
      out.message_text = String(content.message_text || '');
    } else if (state.output_type === 'EXCEL' || state.output_type === 'CSV') {
      out.body_text = String(content.body_text || '');
    }

    return out;
  };

  syncStateFromDom();

  if (!state.prepared || typeof state.prepared !== 'object') {
    throw new Error('Prepared mailshot data is not available');
  }

  state.submitting = true;
  state.submit_result = null;
  if (rerender) rerender();

  try {
    if (state.final_action === 'export') {
      const exportRes = await apiMailshotExport({
        prepare_json: state.prepared,
        final_edits_json: buildFinalEditsJson(),
        output_type: state.output_type
      });

      state.submit_result = {
        ok: !!(exportRes && exportRes.ok === true),
        kind: 'export',
        output_type: exportRes && exportRes.output_type ? exportRes.output_type : state.output_type,
        filename: exportRes && exportRes.filename ? exportRes.filename : null,
        mime_type: exportRes && exportRes.mime_type ? exportRes.mime_type : null,
        download_url: exportRes && exportRes.download_url ? exportRes.download_url : null,
        raw: exportRes || null
      };
    } else {
      const enqueueRes = await apiMailshotEnqueue({
        prepare_json: state.prepared,
        final_edits_json: buildFinalEditsJson(),
        delivery_timing_json: state.delivery_timing
      });

      state.submit_result = {
        ok: !!(enqueueRes && enqueueRes.ok === true),
        kind: 'enqueue',
        mailshot_run_id: enqueueRes && enqueueRes.mailshot_run_id ? enqueueRes.mailshot_run_id : null,
        queued: Number(enqueueRes && enqueueRes.queued != null ? enqueueRes.queued : 0),
        skipped: Number(enqueueRes && enqueueRes.skipped != null ? enqueueRes.skipped : 0),
        failed: Number(enqueueRes && enqueueRes.failed != null ? enqueueRes.failed : 0),
        delivery_timing: enqueueRes && enqueueRes.delivery_timing ? enqueueRes.delivery_timing : state.delivery_timing,
        open_run_action: true,
        open_outbox_action: true,
        raw: enqueueRes || null
      };
    }
  } catch (e) {
    state.submit_result = {
      ok: false,
      kind: state.final_action,
      error: String(e?.message || e || 'Mailshot action failed')
    };
  } finally {
    state.submitting = false;
    if (rerender) rerender();
  }

  return state.submit_result;
}


async function handleTimesheetConvertQrToManual(env, req, timesheetId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!timesheetId) return withCORS(env, req, badRequest('timesheet_id is required'));

  // ✅ NEW: guarded write (optimistic concurrency)
  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }
  const expectedTimesheetId = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  if (!expectedTimesheetId) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  // Stale-safe resolve
  const resolved = await resolveTimesheetToCurrent(env, timesheetId);
  if (!resolved) return withCORS(env, req, notFound('Timesheet not found'));

  const currentTimesheetId = resolved.current_timesheet_id;

  // Guard: if the caller's expected id is no longer current, refuse
  if (String(expectedTimesheetId) !== String(currentTimesheetId)) {
    return withCORS(
      env,
      req,
      new Response(JSON.stringify({
        error: 'TIMESHEET_MOVED',
        current_timesheet_id: currentTimesheetId
      }), { status: 409, headers: { 'Content-Type': 'application/json' } })
    );
  }

  const ts = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=*` +
      `&limit=1`
  );
  if (!ts) return withCORS(env, req, notFound('Timesheet not found'));

  const bookingId = ts.booking_id || resolved.booking_id || null;
  if (!bookingId) return withCORS(env, req, badRequest('Timesheet booking_id is missing; cannot version'));

  // ✅ UPDATED: backend defence-in-depth — block import-authoritative routes using summary view / contract overrides
  try {
    // Prefer contract via contract_week pointer (weekly), fallback to ts.contract_id
    let contractId = ts.contract_id || null;
    let contractWeekId = null;

    try {
      const cwRow = await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
          `?timesheet_id=eq.${enc(currentTimesheetId)}` +
          `&select=id,contract_id` +
          `&limit=1`
      );
      if (cwRow?.contract_id) contractId = cwRow.contract_id;
      if (cwRow?.id) contractWeekId = cwRow.id;
    } catch {}

    const rr = await resolveImportAuthoritative(env, {
      timesheet_id: currentTimesheetId,
      contract_week_id: contractWeekId,
      contract_id: contractId
    });

    if (rr && rr.is_import_authoritative) {
      return withCORS(
        env,
        req,
        badRequest('Import-authoritative timesheets (NHSP / HealthRoster weekly no-timesheets) cannot change submission route')
      );
    }
  } catch {
    // fail-open if flags cannot be loaded
  }

  const scope = String(ts.sheet_scope || '').toUpperCase();
  if (scope && scope !== 'WEEKLY' && scope !== 'DAILY') {
    return withCORS(env, req, badRequest('Unsupported sheet_scope for QR conversion'));
  }

  const subMode = String(ts.submission_mode || '').toUpperCase();
  if (subMode !== 'MANUAL') {
    return withCORS(env, req, badRequest('Timesheet is not in MANUAL mode; QR conversion not applicable'));
  }

  const qrStatus = String(ts.qr_status || '').toUpperCase();
  if (!qrStatus) {
    return withCORS(env, req, badRequest('Timesheet does not have QR metadata; nothing to convert'));
  }

  const fin = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=*`
  );
  if (!fin) return withCORS(env, req, badRequest('No financial snapshot for timesheet'));

  const hardLocked =
    !!fin.paid_at_utc ||
    !!fin.locked_by_invoice_id ||
    !!fin.locked_by_invoice ||
    !!fin.locked_by_invoice_line_id ||
    !!fin.locked_by_invoice_at_utc;

  if (hardLocked) {
    return withCORS(env, req, badRequest('Cannot convert QR: timesheet already invoiced or paid'));
  }

  const now = nowIso();

  // Next version by booking_id
  let nextVersion = Number(ts.version || 1) + 1;
  try {
    const { rows: vRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?booking_id=eq.${enc(bookingId)}` +
        `&select=version` +
        `&order=version.desc` +
        `&limit=1`
    );
    const maxV = vRows?.[0]?.version != null ? Number(vRows[0].version) : Number(ts.version || 1);
    nextVersion = Number.isFinite(maxV) ? maxV + 1 : (Number(ts.version || 1) + 1);
  } catch {}

  // 1) Demote current by booking_id
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?booking_id=eq.${enc(bookingId)}` +
      `&is_current=eq.true`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
      body: JSON.stringify({
        is_current: false,
        status: 'REVOKED',
        revoked_reason: 'QR_CONVERTED_TO_MANUAL',
        revoked_by: user.id || null,
        updated_at: now
      })
    }
  ).catch(() => {});

  // 2) Insert new current manual non-QR (NO timesheet_id)
  const base = { ...ts };
  delete base.id;
  delete base.timesheet_id;

  const newRow = {
    ...base,
    booking_id: bookingId,
    version: nextVersion,
    is_current: true,
    submission_mode: 'MANUAL',

    qr_status: null,
    qr_token: null,
    qr_generated_at: null,
    qr_scanned_at: null,
    qr_scan_info_json: null,
    qr_r2_key: null,
    qr_payload_json: {},

    manual_pdf_r2_key: null,

    created_at: now,
    updated_at: now
  };

  const insRes = await fetch(`${env.SUPABASE_URL}/rest/v1/timesheets`, {
    method: 'POST',
    headers: { ...sbHeaders(env), Prefer: 'return=representation' },
    body: JSON.stringify([newRow])
  });

  if (!insRes.ok) {
    const txt = await insRes.text().catch(() => '');
    return withCORS(env, req, serverError(`Failed to create manual non-QR version: ${txt}`));
  }

  const inserted = (await insRes.json().catch(() => []))[0] || null;
  const newTimesheetId = inserted?.timesheet_id || null;
  if (!newTimesheetId) return withCORS(env, req, serverError('Insert succeeded but no timesheet_id returned'));

  // 2b) Move contract_week pointer if it points at old current row (weekly case)
  try {
    const cw = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&select=id` +
        `&limit=1`
    );
    if (cw?.id) {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(cw.id)}`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
          body: JSON.stringify({ timesheet_id: newTimesheetId, updated_at: now })
        }
      ).catch(() => {});
    }
  } catch {}

  // 3) TSFIN: move row to new timesheet_id and gate evidence
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(fin.id)}`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
      body: JSON.stringify({
        timesheet_id: newTimesheetId,
        timesheet_version: inserted?.version ?? nextVersion,
        processing_status: 'AWAITING_MANUAL_SIGNATURE',
        updated_at: now
      })
    }
  ).catch(() => {});

  // 4) Audit
  try {
    await writeAudit(
      env,
      user,
      'QR_CONVERTED_TO_MANUAL',
      {
        booking_id: bookingId,
        old_timesheet_id: currentTimesheetId,
        new_timesheet_id: newTimesheetId,
        old_version: ts.version,
        new_version: inserted?.version ?? nextVersion,
        sheet_scope: scope || null,
        had_qr_status: qrStatus
      },
      { entity: 'timesheets', subject_id: newTimesheetId, req }
    );
  } catch {}

  // ✅ NEW: Purge superseded versions immediately (best-effort; never blocks conversion)
  try {
    await purgeSupersededTimesheetArtifactsForBooking(env, bookingId);
  } catch (e) {
    try {
      console.warn('[QR_CONVERT_TO_MANUAL] purge failed (non-fatal)', {
        booking_id: bookingId,
        err: e?.message || String(e)
      });
    } catch {}
  }

  return withCORS(env, req, ok({
    converted: true,
    booking_id: bookingId,
    old_timesheet_id: currentTimesheetId,
    current_timesheet_id: newTimesheetId,
    new_version: inserted?.version ?? nextVersion,

    requested_timesheet_id: resolved.requested_timesheet_id || timesheetId,
    was_stale: !!resolved.was_stale
  }));
}

async function handleUsersList(env, req) {
  const actor = await requireUser(env, req, ['admin']);
  if (!actor) return unauthorized('Unauthorized');

  const url = new URL(req.url);
  const q = (url.searchParams.get('q') || '').trim();
  const role = (url.searchParams.get('role') || '').trim();
  const isActiveRaw = (url.searchParams.get('is_active') || '').trim();

  const params = new URLSearchParams();

  // NOTE: last_login_at_utc requires the SQL migration to exist.
  params.set('select', [
    'id',
    'email',
    'display_name',
    'role',
    'is_active',
    'created_at',
    'updated_at',
    'last_login_at_utc',
    'email_settings',
    'payment_authoriser',
    'payment_golden_key',
    'email_signature_html'
  ].join(','));

  params.set('order', 'created_at.desc');

  // Optional filters
  if (role) params.set('role', `eq.${role}`);

  if (isActiveRaw) {
    const v = isActiveRaw.toLowerCase();
    if (v === 'true' || v === 'false') params.set('is_active', `eq.${v}`);
  }

  // q search: email OR display_name
  if (q) {
    const qq = q.replace(/[%*]/g, ''); // keep it simple/safe for ilike patterns
    // PostgREST OR filter syntax
    params.set('or', `(email.ilike.*${qq}*,display_name.ilike.*${qq}*)`);
  }

  const apiUrl = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?${params.toString()}`;
  const res = await fetch(apiUrl, { headers: sbAuthHeaders(env) });

  if (!res.ok) {
    const err = await res.text().catch(() => '');
    return serverError(`Failed to list users (${res.status}): ${err}`);
  }

  const rows = await res.json().catch(() => []);
  return ok({ ok: true, users: Array.isArray(rows) ? rows : [] });
}




async function handleUserMySignaturePatch(env, req) {
  const user = await requireUser(env, req); // any logged-in user
  if (!user) return unauthorized('Unauthorized');

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return badRequest('invalid_json');
  }

  const hasSigField =
    Object.prototype.hasOwnProperty.call(body, 'email_signature_html') ||
    Object.prototype.hasOwnProperty.call(body, 'signature_html');

  if (!hasSigField) {
    return badRequest('email_signature_html_required');
  }

  const rawSig =
    Object.prototype.hasOwnProperty.call(body, 'email_signature_html')
      ? body.email_signature_html
      : body.signature_html;

  if (rawSig !== null && rawSig !== undefined && typeof rawSig !== 'string') {
    return badRequest('email_signature_html_must_be_string_or_null');
  }

  const normalizedSig =
    (rawSig === null || rawSig === undefined || String(rawSig).trim() === '')
      ? null
      : String(rawSig);

  const enc = encodeURIComponent;
  const apiUrl = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?id=eq.${enc(String(user.id))}`;

  const res = await fetch(apiUrl, {
    method: 'PATCH',
    headers: { ...sbAuthHeaders(env), Prefer: 'return=representation' },
    body: JSON.stringify({
      email_signature_html: normalizedSig
    })
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    return serverError(`Failed to update email signature (${res.status}) ${errText || ''}`.trim());
  }

  const rows = await res.json().catch(() => []);
  const row = Array.isArray(rows) && rows[0] ? rows[0] : null;
  if (!row) return badRequest('user_not_found');

  return ok({
    ok: true,
    user: {
      id: row.id,
      email_signature_html: row.email_signature_html ?? null
    }
  });
}


async function handleUsersCreate(env, req) {
  const actor = await requireUser(env, req, ['admin']);
  if (!actor) return unauthorized('Unauthorized');

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const email = String(body.email || '').trim().toLowerCase();
  const displayName = (body.display_name == null) ? null : String(body.display_name || '').trim();
  const role = String(body.role || '').trim().toLowerCase();
  const pw = String(body.password || '');
  let emailSettings = body.email_settings;

  if (!email) return badRequest('email_required');
  if (!pw) return badRequest('password_required');

  // minimal email sanity (consistent with your overall approach)
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return badRequest('invalid_email');

  // roles currently supported
  if (!(role === 'admin' || role === 'user')) return badRequest('invalid_role');

  // strong password: same rules as /auth/reset
  const strong = pw.length >= 8 && /[a-z]/.test(pw) && /[A-Z]/.test(pw) && /[0-9]/.test(pw);
  if (!strong) return badRequest('WEAK_PASSWORD');

  // email_settings must be an object (or omitted)
  if (emailSettings == null) emailSettings = {};
  if (typeof emailSettings !== 'object' || Array.isArray(emailSettings)) return badRequest('invalid_email_settings');

  const asBoolStrict = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    return null;
  };

  let paymentAuthoriser = false;
  let paymentGoldenKey = false;

  if ('payment_authoriser' in body) {
    const b = asBoolStrict(body.payment_authoriser);
    if (b === null) return badRequest('invalid_payment_authoriser');
    paymentAuthoriser = b;
  }

  if ('payment_golden_key' in body) {
    const b = asBoolStrict(body.payment_golden_key);
    if (b === null) return badRequest('invalid_payment_golden_key');
    paymentGoldenKey = b;
  }

  // Golden Key implies Authoriser (match DB CHECK + UX rule)
  if (paymentGoldenKey) paymentAuthoriser = true;

  const hash = await pbkdf2Hash(pw);

  const row = {
    email,
    display_name: displayName || null,
    role,
    is_active: true,
    password_hash: hash,
    session_version: 1,
    email_settings: emailSettings,
    payment_authoriser: paymentAuthoriser,
    payment_golden_key: paymentGoldenKey
  };

  const apiUrl = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}`;
  const res = await fetch(apiUrl, {
    method: 'POST',
    headers: { ...sbAuthHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify(row)
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    // Uniqueness is enforced by tms_users_email_key
    return badRequest(`Failed to create user (${res.status})`, errText);
  }

  const created = await res.json().catch(() => []);
  const u = Array.isArray(created) && created[0] ? created[0] : null;
  return ok({ ok: true, user: u });
}

async function handleUsersPatch(env, req, userId) {
  const actor = await requireUser(env, req, ['admin']);
  if (!actor) return unauthorized('Unauthorized');

  // basic uuid sanity (prevents accidental routing issues)
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(userId || ''))) {
    return badRequest('invalid_user_id');
  }

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const patch = {};

  if ('email' in body) {
    const email = String(body.email || '').trim().toLowerCase();
    if (!email) return badRequest('email_required');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return badRequest('invalid_email');
    patch.email = email;
  }

  if ('display_name' in body) {
    const dn = (body.display_name == null) ? null : String(body.display_name || '').trim();
    patch.display_name = dn || null;
  }

  if ('role' in body) {
    const role = String(body.role || '').trim().toLowerCase();
    if (!(role === 'admin' || role === 'user')) return badRequest('invalid_role');
    patch.role = role;
  }

  if ('is_active' in body) {
    if (typeof body.is_active !== 'boolean') return badRequest('invalid_is_active');
    patch.is_active = body.is_active;
  }

  if ('email_settings' in body) {
    let s = body.email_settings;
    if (s == null) s = {};
    if (typeof s !== 'object' || Array.isArray(s)) return badRequest('invalid_email_settings');
    patch.email_settings = s;
  }

  if ('payment_authoriser' in body) {
    if (typeof body.payment_authoriser !== 'boolean') return badRequest('invalid_payment_authoriser');
    patch.payment_authoriser = body.payment_authoriser;
  }

  if ('payment_golden_key' in body) {
    if (typeof body.payment_golden_key !== 'boolean') return badRequest('invalid_payment_golden_key');
    patch.payment_golden_key = body.payment_golden_key;
    if (body.payment_golden_key === true) {
      // Golden Key implies Authoriser (match DB CHECK + UX rule)
      if ('payment_authoriser' in body && body.payment_authoriser === false) {
        return badRequest('golden_requires_authoriser');
      }
      if (!('payment_authoriser' in body)) {
        patch.payment_authoriser = true;
      }
    }
  }

  if ('email_signature_html' in body) {
    const rawSig = body.email_signature_html;
    if (rawSig !== null && rawSig !== undefined && typeof rawSig !== 'string') {
      return badRequest('invalid_email_signature_html');
    }
    patch.email_signature_html =
      (rawSig === null || rawSig === undefined || String(rawSig).trim() === '')
        ? null
        : String(rawSig);
  }

  if (!Object.keys(patch).length) return badRequest('empty_patch');

  const apiUrl = `${env.SUPABASE_URL}/rest/v1/${AUTH.USERS_TABLE}?id=eq.${encodeURIComponent(userId)}`;
  const res = await fetch(apiUrl, {
    method: 'PATCH',
    headers: { ...sbAuthHeaders(env), 'Prefer': 'return=representation' },
    body: JSON.stringify(patch)
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    return badRequest(`Failed to patch user (${res.status})`, errText);
  }

  const rows = await res.json().catch(() => []);
  const u = Array.isArray(rows) && rows[0] ? rows[0] : null;
  if (!u) return badRequest('user_not_found');

  return ok({ ok: true, user: u });
}


async function handleUsersResetPassword(env, req, userId) {
  const actor = await requireUser(env, req, ['admin']);
  if (!actor) return unauthorized('Unauthorized');

  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(userId || ''))) {
    return badRequest('invalid_user_id');
  }

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const newPw = String(body.new_password ?? body.password ?? '');
  if (!newPw) return badRequest('new_password_required');

  const strong = newPw.length >= 8 && /[a-z]/.test(newPw) && /[A-Z]/.test(newPw) && /[0-9]/.test(newPw);
  if (!strong) return badRequest('WEAK_PASSWORD');

  const newHash = await pbkdf2Hash(newPw);

  try {
    await sbUpdateUserPassword(env, userId, newHash); // updates hash + bumps session_version
  } catch (e) {
    return serverError(`Reset password failed: ${e?.message || e}`);
  }

  return ok({ ok: true });
}

async function handleUserChangePassword(env, req) {
  const u = await requireUser(env, req); // any logged-in user
  if (!u) return unauthorized('Unauthorized');

  const body = await parseJSONBody(req);
  if (!body) return badRequest('invalid_json');

  const oldPw = String(body.old_password || '');
  const newPw = String(body.new_password || '');
  const newPw2 = String(body.new_password2 || '');

  if (!oldPw || !newPw || !newPw2) return badRequest('old_and_new_password_required');
  if (newPw !== newPw2) return badRequest('new_password_mismatch');

  const strong = newPw.length >= 8 && /[a-z]/.test(newPw) && /[A-Z]/.test(newPw) && /[0-9]/.test(newPw);
  if (!strong) return badRequest('WEAK_PASSWORD');

  const userRow = await sbGetUserById(env, u.id); // includes password_hash per your current helper
  if (!userRow || userRow.is_active !== true) return unauthorized('Unauthorized');

  const okOld = await pbkdf2Verify(oldPw, userRow.password_hash || '');
  if (!okOld) return unauthorized('Invalid credentials');

  const newHash = await pbkdf2Hash(newPw);

  try {
    await sbUpdateUserPassword(env, u.id, newHash); // bumps session_version => tokens invalid
  } catch (e) {
    return serverError(`Change password failed: ${e?.message || e}`);
  }

  // Kill current KV session (best-effort)
  try { if (u.sid) await kvDelSession(env, u.sid); } catch {}

  // Clear refresh cookie to force logout (Option A)
  const headers = new Headers(JSON_HEADERS);
  setCookie(headers, cookieName(env), '', {
    maxAgeSec: 0,
    domain: env.COOKIE_DOMAIN || undefined,
    sameSite: pickCookieSameSite(env),
    secure: true,
    httpOnly: true,
    path: '/'
  });

  return new Response(JSON.stringify({ ok: true, logged_out: true }), { status: 200, headers });
}


