// ───────────────────────────────────────────────────────────────────────────────
// REPORT PRESETS — Create / List / Update / Delete
// Table: report_presets (id, user_id, section, name, filters_json, is_default, is_shared, created_at, updated_at)
// ───────────────────────────────────────────────────────────────────────────────
// BACKEND — UPDATED
// handleReportPresetsList: default sort name.asc; include user join; mine first then shared.

 async function handleReportPresetsList(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  try {
    const urlObj = new URL(req.url);
    const q  = (k) => urlObj.searchParams.get(k);
    const page      = Math.max(1, parseInt(q('page') || '1', 10));
    const pageSize  = Math.max(1, Math.min(200, parseInt(q('page_size') || '50', 10)));
    const section   = q('section');
    const kind      = q('kind');
    const text      = q('q');
    const includeShared = q('include_shared') === 'true';
    const orderBy   = (q('order_by') || 'name').toLowerCase(); // created_at|name|updated_at
    const orderDir  = (q('order_dir') || 'asc').toLowerCase() === 'desc' ? 'desc' : 'asc';

    const orderAllowed = new Set(['created_at','name','updated_at']);
    const orderExpr = `&order=${orderAllowed.has(orderBy) ? enc(orderBy) : 'name'}.${orderDir}`;
    const pageExpr  = `&limit=${pageSize}&offset=${(page-1)*pageSize}`;

    // include selection_json so FE can save/load selections with filters
    const sel = `id,user_id,section,kind,name,filters_json,selection_json,is_default,is_shared,created_at,updated_at,` +
                `user:tms_users(id,display_name,email)`;

    // 1) My presets
    let urlMine = `${env.SUPABASE_URL}/rest/v1/report_presets` +
      `?select=${enc(sel)}` +
      `&user_id=eq.${enc(user.id)}`;
    if (section) urlMine += `&section=eq.${enc(section)}`;
    if (kind)    urlMine += `&kind=eq.${enc(kind)}`;
    if (text)    urlMine += `&name=ilike.*${enc(text)}*`;
    urlMine += orderExpr + pageExpr;

    const { rows: mine = [] } = await sbFetch(env, urlMine);

    // 2) Shared presets (not mine)
    let shared = [];
    if (includeShared) {
      let urlShared = `${env.SUPABASE_URL}/rest/v1/report_presets` +
        `?select=${enc(sel)}` +
        `&is_shared=eq.true` +
        `&user_id=neq.${enc(user.id)}`;
      if (section) urlShared += `&section=eq.${enc(section)}`;
      if (kind)    urlShared += `&kind=eq.${enc(kind)}`;
      if (text)    urlShared += `&name=ilike.*${enc(text)}*`;
      urlShared += orderExpr + pageExpr;
      const { rows } = await sbFetch(env, urlShared);
      shared = rows || [];
    }

    return withCORS(env, req, ok({
      rows: (mine || []).concat(shared || []),
      page, page_size: pageSize,
      count: (mine?.length || 0) + (shared?.length || 0)
    }));
  } catch (err) {
    return withCORS(env, req, serverError('Failed to list report presets'));
  }
}
 async function handleReportPresetsCreate(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  try {
    let body;
    try { body = await parseJSONBody(req); } catch { return withCORS(env, req, badRequest('Invalid JSON')); }

    const section   = String(body?.section || '').trim();
    const name      = String(body?.name || '').trim();
    const filters   = body?.filters ?? {};
    const selection = body?.selection;
    const isDefault = !!body?.is_default;
    const isShared  = !!body?.is_shared;
    const kindRaw   = (body?.kind ?? 'search');
    const kind      = String(kindRaw).trim().toLowerCase();

    const KIND_ALLOWED = new Set(['search','report','dashboard','selection']);

    const clonePlain = (value) => {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
      try {
        return JSON.parse(JSON.stringify(value));
      } catch {
        const out = {};
        Object.keys(value).forEach((key) => {
          out[key] = value[key];
        });
        return out;
      }
    };

    const normalizeIdArray = (value) => Array.from(new Set(
      (Array.isArray(value) ? value : [])
        .map((v) => String(v == null ? '' : v).trim())
        .filter(Boolean)
    ));

    const normalizeExplicitSelectionPayload = (rawSelection, effectiveSection) => {
      if (!rawSelection || typeof rawSelection !== 'object' || Array.isArray(rawSelection)) {
        throw new Error('selection must be an object for kind=selection');
      }

      const selectionSection = String(rawSelection.section || '').trim();
      if (selectionSection && selectionSection !== effectiveSection) {
        throw new Error('selection.section must match section');
      }

      const rawMode = String(rawSelection.mode || rawSelection.selection_mode || '').trim().toLowerCase();
      if (rawMode === 'all_filtered') {
        throw new Error('selection presets must be stored as explicit ids only');
      }

      const explicitIds = normalizeIdArray(
        Array.isArray(rawSelection.resolved_ids)
          ? rawSelection.resolved_ids
          : (Array.isArray(rawSelection.included_ids)
              ? rawSelection.included_ids
              : (Array.isArray(rawSelection.ids) ? rawSelection.ids : []))
      );

      if (!explicitIds.length) {
        throw new Error('selection must contain at least one explicit row id');
      }

      const excludedIds = normalizeIdArray(rawSelection.excluded_ids);
      if (excludedIds.length) {
        throw new Error('selection.excluded_ids must be empty for kind=selection');
      }

      const selectionFilters =
        (rawSelection.filters && typeof rawSelection.filters === 'object' && !Array.isArray(rawSelection.filters))
          ? clonePlain(rawSelection.filters)
          : ((rawSelection.effective_filters && typeof rawSelection.effective_filters === 'object' && !Array.isArray(rawSelection.effective_filters))
              ? clonePlain(rawSelection.effective_filters)
              : {});

      const datasetKey = String(rawSelection.dataset_key || rawSelection.fingerprint || '').trim();

      const normalized = {
        section: effectiveSection,
        dataset_key: datasetKey,
        fingerprint: datasetKey,
        mode: 'explicit',
        included_ids: explicitIds.slice(),
        excluded_ids: [],
        ids: explicitIds.slice(),
        resolved_ids: explicitIds.slice(),
        membership_total: explicitIds.length
      };

      if (Object.keys(selectionFilters).length) {
        normalized.filters = clonePlain(selectionFilters);
        normalized.effective_filters = clonePlain(selectionFilters);
      }

      return normalized;
    };

    if (!section) return withCORS(env, req, badRequest('section is required'));
    if (!name)    return withCORS(env, req, badRequest('name is required'));
    if (!filters || typeof filters !== 'object' || Array.isArray(filters)) {
      return withCORS(env, req, badRequest('filters must be an object'));
    }
    if (!KIND_ALLOWED.has(kind)) {
      return withCORS(env, req, badRequest('kind must be one of search|report|dashboard|selection'));
    }

    let selectionToStore = undefined;
    if (kind === 'selection') {
      try {
        selectionToStore = normalizeExplicitSelectionPayload(selection, section);
      } catch (e) {
        return withCORS(env, req, badRequest(String(e?.message || e || 'Invalid selection payload')));
      }
    } else if (typeof selection === 'object' && selection && !Array.isArray(selection)) {
      selectionToStore = selection;
    }

    if (isDefault) {
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/report_presets` +
        `?user_id=eq.${enc(user.id)}` +
        `&section=eq.${enc(section)}` +
        `&kind=eq.${enc(kind)}` +
        `&is_default=eq.true`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
          body: JSON.stringify({ is_default: false })
        }
      );
    }

    const payload = {
      user_id: user.id,
      section,
      kind,
      name,
      filters_json: filters,
      ...(selectionToStore !== undefined ? { selection_json: selectionToStore } : {}),
      is_default: isDefault,
      is_shared: isShared
    };

    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/report_presets`,
      true,
      {
        method: 'POST',
        headers: { ...sbHeaders(env), Prefer: 'return=representation' },
        body: JSON.stringify(payload)
      }
    );

    return withCORS(env, req, ok({ row: rows?.[0] || null }));
  } catch (err) {
    return withCORS(env, req, serverError('Failed to create report preset'));
  }
}

async function handleReportPresetsUpdate(env, req, routeId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  try {
    const urlObj = new URL(req.url);
    const qsId = urlObj.searchParams.get('id');
    let body;
    try { body = await parseJSONBody(req); } catch { body = {}; }

    const id = routeId || qsId || body?.id;
    if (!id) return withCORS(env, req, badRequest('id is required'));

    const { rows: existingRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/report_presets?select=id,user_id,section,kind,is_default,selection_json&id=eq.${enc(id)}`
    );
    const existing = existingRows?.[0];
    if (!existing) return withCORS(env, req, notFound('Preset not found'));
    if (existing.user_id !== user.id) return withCORS(env, req, unauthorized());

    const KIND_ALLOWED = new Set(['search','report','dashboard','selection']);

    const clonePlain = (value) => {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
      try {
        return JSON.parse(JSON.stringify(value));
      } catch {
        const out = {};
        Object.keys(value).forEach((key) => {
          out[key] = value[key];
        });
        return out;
      }
    };

    const normalizeIdArray = (value) => Array.from(new Set(
      (Array.isArray(value) ? value : [])
        .map((v) => String(v == null ? '' : v).trim())
        .filter(Boolean)
    ));

    const normalizeExplicitSelectionPayload = (rawSelection, effectiveSection) => {
      if (!rawSelection || typeof rawSelection !== 'object' || Array.isArray(rawSelection)) {
        throw new Error('selection must be an explicit selection object for kind=selection');
      }

      const selectionSection = String(rawSelection.section || '').trim();
      if (selectionSection && selectionSection !== effectiveSection) {
        throw new Error('selection.section must match section');
      }

      const rawMode = String(rawSelection.mode || rawSelection.selection_mode || '').trim().toLowerCase();
      if (rawMode === 'all_filtered') {
        throw new Error('selection presets must be stored as explicit ids only');
      }

      const explicitIds = normalizeIdArray(
        Array.isArray(rawSelection.resolved_ids)
          ? rawSelection.resolved_ids
          : (Array.isArray(rawSelection.included_ids)
              ? rawSelection.included_ids
              : (Array.isArray(rawSelection.ids) ? rawSelection.ids : []))
      );

      if (!explicitIds.length) {
        throw new Error('selection must contain at least one explicit row id');
      }

      const excludedIds = normalizeIdArray(rawSelection.excluded_ids);
      if (excludedIds.length) {
        throw new Error('selection.excluded_ids must be empty for kind=selection');
      }

      const selectionFilters =
        (rawSelection.filters && typeof rawSelection.filters === 'object' && !Array.isArray(rawSelection.filters))
          ? clonePlain(rawSelection.filters)
          : ((rawSelection.effective_filters && typeof rawSelection.effective_filters === 'object' && !Array.isArray(rawSelection.effective_filters))
              ? clonePlain(rawSelection.effective_filters)
              : {});

      const datasetKey = String(rawSelection.dataset_key || rawSelection.fingerprint || '').trim();

      const normalized = {
        section: effectiveSection,
        dataset_key: datasetKey,
        fingerprint: datasetKey,
        mode: 'explicit',
        included_ids: explicitIds.slice(),
        excluded_ids: [],
        ids: explicitIds.slice(),
        resolved_ids: explicitIds.slice(),
        membership_total: explicitIds.length
      };

      if (Object.keys(selectionFilters).length) {
        normalized.filters = clonePlain(selectionFilters);
        normalized.effective_filters = clonePlain(selectionFilters);
      }

      return normalized;
    };

    const patch = {};

    if ('name' in body) {
      if (typeof body.name !== 'string') return withCORS(env, req, badRequest('name must be a string'));
      patch.name = body.name.trim();
    }

    if ('section' in body) {
      if (typeof body.section !== 'string') return withCORS(env, req, badRequest('section must be a string'));
      patch.section = body.section.trim();
    }

    if ('filters' in body) {
      if (!body.filters || typeof body.filters !== 'object' || Array.isArray(body.filters)) {
        return withCORS(env, req, badRequest('filters must be an object'));
      }
      patch.filters_json = body.filters;
    }

    if (typeof body.is_shared === 'boolean') patch.is_shared = body.is_shared;
    if (typeof body.is_default === 'boolean') patch.is_default = body.is_default;

    if (typeof body.kind === 'string') {
      const k = body.kind.trim().toLowerCase();
      if (!KIND_ALLOWED.has(k)) {
        return withCORS(env, req, badRequest('kind must be one of search|report|dashboard|selection'));
      }
      patch.kind = k;
    }

    const effectiveSection = String(
      (typeof patch.section === 'string' && patch.section.trim()) ||
      existing.section ||
      ''
    ).trim();

    const effectiveKind = String(
      (typeof patch.kind === 'string' && patch.kind.trim()) ||
      existing.kind ||
      ''
    ).trim().toLowerCase();

    if (effectiveKind === 'selection' && existing.kind !== 'selection' && !('selection' in body)) {
      return withCORS(env, req, badRequest('selection is required when changing kind to selection'));
    }

    if ('selection' in body) {
      if (effectiveKind === 'selection') {
        try {
          patch.selection_json = normalizeExplicitSelectionPayload(body.selection, effectiveSection);
        } catch (e) {
          return withCORS(env, req, badRequest(String(e?.message || e || 'Invalid selection payload')));
        }
      } else {
        if (body.selection === null) patch.selection_json = null;
        else if (typeof body.selection === 'object' && body.selection && !Array.isArray(body.selection)) patch.selection_json = body.selection;
        else return withCORS(env, req, badRequest('selection must be an object or null'));
      }
    }

    if (patch.is_default === true) {
      const sectionEff = effectiveSection || existing.section;
      const kindEff = effectiveKind || existing.kind;
      await fetch(
        `${env.SUPABASE_URL}/rest/v1/report_presets` +
        `?user_id=eq.${enc(user.id)}` +
        `&section=eq.${enc(sectionEff)}` +
        `&kind=eq.${enc(kindEff)}` +
        `&is_default=eq.true` +
        `&id=neq.${enc(id)}`,
        {
          method: 'PATCH',
          headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
          body: JSON.stringify({ is_default: false })
        }
      );
    }

    const { rows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/report_presets?id=eq.${enc(id)}`,
      true,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return=representation' },
        body: JSON.stringify(patch)
      }
    );

    return withCORS(env, req, ok({ row: rows?.[0] || null }));
  } catch (err) {
    return withCORS(env, req, serverError('Failed to update report preset'));
  }
}

async function handleSummaryTypeAheadLookup(env, req, section) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  try {
    let body;
    try { body = await parseJSONBody(req); } catch { return withCORS(env, req, badRequest('Invalid JSON')); }

    const trimStr = (v) => String(v == null ? '' : v).trim();

    const clonePlain = (value) => {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
      try {
        return JSON.parse(JSON.stringify(value));
      } catch {
        const out = {};
        Object.keys(value).forEach((key) => {
          out[key] = value[key];
        });
        return out;
      }
    };

    const normalizeIdArray = (arr) => Array.from(new Set(
      (Array.isArray(arr) ? arr : [])
        .map((v) => trimStr(v))
        .filter(Boolean)
    ));

    const normalizeDatasetValue = (value) => {
      if (value === undefined) return undefined;
      if (value === null) return undefined;

      if (Array.isArray(value)) {
        const arr = value
          .map(normalizeDatasetValue)
          .filter((v) => v !== undefined)
          .map((v) => (v && typeof v === 'object') ? JSON.parse(JSON.stringify(v)) : v);

        if (!arr.length) return undefined;

        return arr.sort((leftValue, rightValue) => {
          const leftJson = JSON.stringify(leftValue);
          const rightJson = JSON.stringify(rightValue);
          if (leftJson < rightJson) return -1;
          if (leftJson > rightJson) return 1;
          return 0;
        });
      }

      if (value && typeof value === 'object') {
        const out = {};
        Object.keys(value).sort().forEach((key) => {
          const normalized = normalizeDatasetValue(value[key]);
          if (normalized !== undefined) out[key] = normalized;
        });
        return Object.keys(out).length ? out : undefined;
      }

      if (typeof value === 'string') {
        const s = trimStr(value);
        return s ? s : undefined;
      }

      if (typeof value === 'number' && !Number.isFinite(value)) return undefined;
      return value;
    };

    const sectionFromRoute = trimStr(section).toLowerCase();
    const sectionFromBody = trimStr(body?.section).toLowerCase();

    const normalizeSection = (rawSection) => {
      const s = trimStr(rawSection).toLowerCase();
      if (s === 'candidate' || s === 'candidates') return 'candidates';
      if (s === 'client' || s === 'clients') return 'clients';
      if (s === 'contract' || s === 'contracts') return 'contracts';
      if (s === 'timesheet' || s === 'timesheets') return 'timesheets';
      if (s === 'invoice' || s === 'invoices') return 'invoices';
      if (s === 'umbrella' || s === 'umbrellas') return 'umbrellas';
      return '';
    };

    const routeSectionKey = normalizeSection(sectionFromRoute);
    const bodySectionKey = normalizeSection(sectionFromBody);

    if (routeSectionKey && bodySectionKey && routeSectionKey !== bodySectionKey) {
      return withCORS(env, req, badRequest('section in route must match section in body'));
    }

    const sectionKey = routeSectionKey || bodySectionKey;
    if (!sectionKey) {
      return withCORS(env, req, badRequest('section is required'));
    }

    const rawFilters =
      (body?.effective_filters && typeof body.effective_filters === 'object' && !Array.isArray(body.effective_filters))
        ? body.effective_filters
        : ((body?.filters && typeof body.filters === 'object' && !Array.isArray(body.filters))
            ? body.filters
            : {});

    const sortKey = trimStr(body?.sort_key);
    const sortDir = trimStr(body?.sort_dir).toLowerCase() === 'desc' ? 'desc' : 'asc';
    const prefix = trimStr(body?.prefix);
    const requestDatasetKey = trimStr(body?.dataset_key);

    if (!sortKey) {
      return withCORS(env, req, badRequest('sort_key is required'));
    }

    if (!prefix) {
      return withCORS(env, req, badRequest('prefix is required'));
    }

    const pageSizeRaw = body?.page_size;
    const pageSize =
      (String(pageSizeRaw || '').trim().toUpperCase() === 'ALL')
        ? 'ALL'
        : Number(pageSizeRaw);

    if (pageSize !== 'ALL' && (!Number.isFinite(pageSize) || pageSize < 1)) {
      return withCORS(env, req, badRequest('page_size must be a positive integer or ALL'));
    }

    const normalizeFiltersBySection = (targetSection, sourceFilters) => {
      const clean = clonePlain(sourceFilters);
      if (targetSection === 'candidates') return buildCandidateSummaryFilterSpec(clean);
      if (targetSection === 'clients') return buildClientSummaryFilterSpec(clean);
      if (targetSection === 'umbrellas') return buildUmbrellaSummaryFilterSpec(clean);
      if (targetSection === 'contracts') return buildContractSummaryFilterSpec(clean);
      if (targetSection === 'timesheets') return buildTimesheetSummaryFilterSpec(clean);
      if (targetSection === 'invoices') return buildInvoiceSummaryFilterSpec(clean);
      return clean;
    };

    const buildCanonicalDatasetKey = (targetSection, sourceFilters) => {
      const normalizedSection = normalizeSection(targetSection) || sectionKey;
      const normalizedSourceFilters = normalizeFiltersBySection(normalizedSection, sourceFilters);

      if (Object.prototype.hasOwnProperty.call(normalizedSourceFilters, 'ids')) {
        normalizedSourceFilters.ids = normalizeIdArray(normalizedSourceFilters.ids);
        if (!normalizedSourceFilters.ids.length) delete normalizedSourceFilters.ids;
      }

      return JSON.stringify({
        section: normalizedSection,
        filters: normalizeDatasetValue(normalizedSourceFilters) || {}
      });
    };

    const normalizedFilters = normalizeFiltersBySection(sectionKey, rawFilters);

    if (Object.prototype.hasOwnProperty.call(normalizedFilters, 'ids')) {
      normalizedFilters.ids = normalizeIdArray(normalizedFilters.ids);
      if (!normalizedFilters.ids.length) delete normalizedFilters.ids;
    }

    const serverDatasetKey = buildCanonicalDatasetKey(sectionKey, normalizedFilters);

    let normalizedRequestDatasetKey = '';
    if (requestDatasetKey) {
      try {
        const parsedRequestKey = JSON.parse(requestDatasetKey);
        const parsedSectionKey = normalizeSection(parsedRequestKey?.section) || sectionKey;
        const parsedFilters =
          (parsedRequestKey?.filters && typeof parsedRequestKey.filters === 'object' && !Array.isArray(parsedRequestKey.filters))
            ? parsedRequestKey.filters
            : {};
        normalizedRequestDatasetKey = buildCanonicalDatasetKey(parsedSectionKey, parsedFilters);
      } catch {
        normalizedRequestDatasetKey = requestDatasetKey;
      }
    }

    const rpcRes = await sbRpc(env, 'summary_typeahead_lookup', {
      p_section: sectionKey,
      p_filters: normalizedFilters,
      p_sort_key: sortKey,
      p_sort_dir: sortDir,
      p_prefix: prefix,
      p_page_size: (pageSize === 'ALL') ? null : Number(pageSize)
    });

    let payload = rpcRes;
    try {
      if (Array.isArray(rpcRes) && rpcRes.length === 1 && rpcRes[0] && typeof rpcRes[0] === 'object') {
        payload = rpcRes[0];
      }
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'summary_typeahead_lookup')) {
        payload = payload.summary_typeahead_lookup;
      }
      if (payload && typeof payload === 'object' && Array.isArray(payload.rows) && payload.rows.length === 1) {
        payload = payload.rows[0];
      }
    } catch {}

    const target = (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};

    const responseDatasetKey = serverDatasetKey;

    if (normalizedRequestDatasetKey && responseDatasetKey && normalizedRequestDatasetKey !== responseDatasetKey) {
      return withCORS(env, req, ok({
        row_id: null,
        ordinal_index: null,
        target_page: (pageSize === 'ALL') ? 1 : null,
        matched_value: '',
        dataset_key: responseDatasetKey,
        section: sectionKey,
        dataset_key_mismatch: true,
        requested_dataset_key: requestDatasetKey
      }));
    }

    const rowId = trimStr(
      target.row_id ??
      target.id ??
      target.target_row_id ??
      ''
    );

    const ordinalIndexRaw = Number(
      target.ordinal_index ??
      target.ordinal ??
      target.row_ordinal ??
      null
    );

    const targetPageRaw = Number(
      target.target_page ??
      target.page ??
      null
    );

    const hasValidOrdinal = Number.isFinite(ordinalIndexRaw) && ordinalIndexRaw >= 0;
    const hasValidTargetPage = Number.isFinite(targetPageRaw) && targetPageRaw >= 1;

    const computedTargetPage = (() => {
      if (!rowId) return null;
      if (pageSize === 'ALL') return 1;
      if (hasValidTargetPage) return Math.max(1, targetPageRaw);
      if (hasValidOrdinal) {
        return Math.floor(ordinalIndexRaw / Number(pageSize)) + 1;
      }
      return null;
    })();

    return withCORS(env, req, ok({
      row_id: (rowId && computedTargetPage !== null) ? rowId : null,
      ordinal_index: hasValidOrdinal ? ordinalIndexRaw : null,
      target_page: (rowId && computedTargetPage !== null) ? computedTargetPage : ((pageSize === 'ALL') ? 1 : null),
      matched_value: trimStr(target.matched_value ?? target.value ?? ''),
      dataset_key: responseDatasetKey,
      section: sectionKey
    }));
  } catch (err) {
    return withCORS(env, req, serverError('Failed to resolve summary type-ahead target'));
  }
}

 async function handleReportPresetsDelete(env, req, routeId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const urlObj = new URL(req.url);
  const qsId   = urlObj.searchParams.get('id'); // optional ?id=...

  // Prefer route param, then query
  const id = routeId || qsId;
  if (!id) return withCORS(env, req, badRequest('id is required'));

  // Ownership check
  const { rows: existingRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/report_presets?select=id,user_id&id=eq.${enc(id)}`
  );
  const existing = existingRows?.[0];
  if (!existing) return withCORS(env, req, notFound('Preset not found'));
  if (existing.user_id !== user.id) return withCORS(env, req, unauthorized());

  await fetch(
    `${env.SUPABASE_URL}/rest/v1/report_presets?id=eq.${enc(id)}`,
    { method: 'DELETE', headers: { ...sbHeaders(env), Prefer: 'return=minimal' } }
  );

  return withCORS(env, req, ok({ deleted_id: id }));
}




/*
  Email Outbox Broker – queue + drain + provider integration (Power Automate)
  ---------------------------------------------------------------------------
  Drop this file into your Worker codebase (or merge the functions into your existing
  handler module). It uses your existing helper utilities and DB conventions.

  Assumptions / dependencies already present in your codebase (as seen in snippets):
    - requireUser(env, req, roles?) -> returns user or null
    - withCORS(env, req, response)
    - ok/json helpers: ok(data), badRequest(msg), unauthorized(), notFound(msg), serverError(msg)
    - sbHeaders(env) -> { 'apikey': ..., 'Authorization': 'Bearer ...', 'Content-Type': 'application/json' }
    - sbFetch(env, url, single = false, init?) -> { rows } JSON wrapper for Supabase REST
    - writeAudit(env, user, action, afterJson, opts) -> writes audit_events
    - handleInvoiceRender(env, req, invoiceId) -> returns Response JSON { pdf_url }

  New ed handlers in this module:
    - handleOutboxDrain
    - handleEmailSend
    - handleQueueTsoFailureEmail
    - handleOutboxRetry
    - handleListOutbox
    - handleGetOutboxItem
    - handleOutboxMarkSent
    - handleOutboxMarkFailed

  Helpers (pure logic or provider-facing):
    - drainEmailOutboxOnce
    - buildEmailPayloadFromOutboxRow
    - postToPowerAutomate
    - fetchAttachmentBase64FromR2
    - limitOrLinkAttachments
    - normalizeEmailPayload, validateEmailPayload, estimatePayloadSizeBytes
    - resolveTsoRecipientForTimesheet
    - recordEmailAudit (thin wrapper over writeAudit)
    - signDownloadUrlForR2Key

  Revised functions from your snippets:
    - handleRemittanceEmailForCandidate (queues REMITTANCE table row)
    - handleInvoiceEmail (queues INVOICE row; ensures PDF exists; audit)

  Router wiring helper:
    - wireEmailRoutes(router)

  Scheduled drain (optional):
    - scheduled(event, env, ctx) example at bottom – call drainEmailOutboxOnce periodically.
*/

// ------------------------------
// Config knobs (override via env if you like)
// ------------------------------
const DEFAULT_DRAIN_LIMIT = 10;                 // how many queued rows to pick per drain
const EMAIL_MAX_PAYLOAD_BYTES = 18 * 1024 * 1024; // 18MB safety cap before trimming/links
const SIGNED_LINK_TTL_SECS = 7 * 24 * 60 * 60;  // 7 days

// ------------------------------
// Small utilities
// ------------------------------

// best-effort byte size estimate for JSON payload
function estimatePayloadSizeBytes(obj) {
  try {
    return new TextEncoder().encode(JSON.stringify(obj)).byteLength;
  } catch {
    return 0;
  }
}

function isNonEmptyString(x) {
  return typeof x === 'string' && x.trim().length > 0;
}

function toArray(x) {
  if (!x) return [];
  if (Array.isArray(x)) return x;
  return [x];
}

function splitCsvMaybe(s) {
  if (!isNonEmptyString(s)) return [];
  return s.split(',').map((p) => p.trim()).filter(Boolean);
}

// robust base64 from ArrayBuffer for Workers (avoid large String.fromCharCode spread)
function base64FromArrayBuffer(buf) {
  let binary = '';
  const bytes = new Uint8Array(buf);
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

// ------------------------------
// Provider integration (Power Automate)
// ------------------------------

// ------------------------------
// Attachments
// ------------------------------
async function fetchAttachmentBase64FromR2(env, r2Key) {
  // Try common binding names – adjust if your binding name differs.
  const bucket = env.DOCS_BUCKET || env.R2 || env.R2_BUCKET || env.FILES_BUCKET;
  if (!bucket || typeof bucket.get !== 'function') {
    throw new Error('R2 binding not available on env (expected DOCS_BUCKET or R2)');
  }
  const obj = await bucket.get(r2Key);
  if (!obj) throw new Error(`R2 object not found for key: ${r2Key}`);
  const arrBuf = await obj.arrayBuffer();
  const base64 = base64FromArrayBuffer(arrBuf);
  // if the filename is not known here, caller should supply display name
  return base64;
}


function _asEmailString(v) {
  // Apps Script expects strings for to/cc/bcc/replyTo. :contentReference[oaicite:6]{index=6}
  if (v == null) return '';
  if (Array.isArray(v)) {
    return v.map(x => String(x || '').trim()).filter(Boolean).join(', ');
  }
  return String(v || '').trim();
}

function normalizeEmailPayload(raw) {
  // Match Apps Script: to/cc/bcc/replyTo are strings, not arrays.
  const to = _asEmailString(raw.to);
  const cc = _asEmailString(raw.cc);
  const bcc = _asEmailString(raw.bcc);
  const replyTo = _asEmailString(raw.replyTo);

  const subject = String(raw.subject || '').trim();

  // Apps Script uses htmlBody + body (Flow coalesce).
  const htmlBodyStr =
    raw.htmlBody != null ? String(raw.htmlBody) :
    raw.html != null ? String(raw.html) :
    raw.body_html != null ? String(raw.body_html) :
    null;

  const textBodyStr =
    raw.textBody != null ? String(raw.textBody) :
    raw.text != null ? String(raw.text) :
    raw.body_text != null ? String(raw.body_text) :
    null;

  const actualBody =
    htmlBodyStr != null ? htmlBodyStr :
    textBodyStr != null ? textBodyStr :
    String(raw.body || '');

  const htmlBody = (htmlBodyStr != null ? htmlBodyStr : (actualBody || ''));
  const body = (textBodyStr != null ? textBodyStr : (actualBody || ''));

  // Importance (optional): normalize to High|Normal|Low. Default is Normal if omitted.
  const rawImp = (raw && raw.importance != null) ? String(raw.importance).trim() : '';
  const impLower = rawImp.toLowerCase();
  const importance =
    impLower === 'high' ? 'High' :
    impLower === 'low' ? 'Low' :
    impLower ? 'Normal' : ''; // omit if not supplied; callers may default it later

  // Attachments can arrive as:
  // - attachmentsV2: [{Name,ContentBytes}] (already PA-ready)
  // - attachments:   [{name,contentBase64}] or [{filename,contentBase64}] or placeholders
  // - stringified JSON of the above
  let attachmentsRaw = raw.attachmentsV2 ?? raw.attachments ?? [];
  const parsed = _safeJsonParseMaybe(attachmentsRaw);
  if (parsed != null) attachmentsRaw = parsed;

  const attachments = [];
  const arr = Array.isArray(attachmentsRaw) ? attachmentsRaw : (attachmentsRaw ? [attachmentsRaw] : []);

  for (const a of arr) {
    if (!a) continue;

    // If a is a string (bad outbox normalisation), ignore safely
    if (typeof a !== 'object') continue;

    // Already in Apps Script "new" shape: { Name, ContentBytes }
    if (a.ContentBytes && (a.Name || a.name || a.filename)) {
      attachments.push({
        name: String(a.Name || a.name || a.filename || 'attachment'),
        contentBase64: String(a.ContentBytes)
      });
      continue;
    }

    // Direct base64: { name, contentBase64 } or { filename, contentBase64 }
    if (a.contentBase64 && (a.name || a.filename)) {
      attachments.push({
        name: String(a.name || a.filename || 'attachment'),
        contentBase64: String(a.contentBase64)
      });
      continue;
    }

    // R2 placeholder: { r2_key, filename/name }
    if (a.r2_key) {
      attachments.push({
        r2_key: String(a.r2_key),
        name: String(a.name || a.filename || 'attachment'),
        filename: a.filename ? String(a.filename) : undefined
      });
      continue;
    }

    // Invoice placeholder: { invoice_id, filename/name }
    if (a.invoice_id) {
      attachments.push({
        invoice_id: String(a.invoice_id),
        filename: String(a.filename || a.name || `Invoice_${String(a.invoice_id)}.pdf`),
        name: String(a.name || a.filename || `Invoice_${String(a.invoice_id)}.pdf`)
      });
      continue;
    }
  }

  return {
    to,
    cc: cc || '',
    bcc: bcc || '',
    replyTo: replyTo || '',
    importance,
    subject,
    htmlBody,
    body,
    attachments,
    metadata: raw.metadata ?? null
  };
}
function validateEmailPayload(p) {
  if (!p || typeof p !== 'object') return 'Missing payload';
  if (!p.to || !String(p.to).trim()) return 'Recipient is required.';
  if (!p.subject || !String(p.subject).trim()) return 'Subject is required.';
  if (!((p.htmlBody && String(p.htmlBody).length) || (p.body && String(p.body).length))) {
    return 'Email body is required.';
  }
  return null;
}

// ---------- Build PA payload (single email) in Apps Script structure ----------

async function buildEmailPayloadFromOutboxRow(env, outboxRow) {
  const base = normalizeEmailPayload({
    to: outboxRow.to,
    cc: outboxRow.cc,
    bcc: outboxRow.bcc,

    // ✅ FIX: DB column is reply_to (snake_case); preserve backward compatibility if any callers used replyTo.
    replyTo: (outboxRow.reply_to != null ? outboxRow.reply_to : (outboxRow.replyTo != null ? outboxRow.replyTo : null)),

    importance: outboxRow.importance,
    subject: outboxRow.subject,
    body_html: outboxRow.body_html,
    body_text: outboxRow.body_text,
    // IMPORTANT: outboxRow.attachments may be jsonb OR a JSON-string-in-text
    attachments: outboxRow.attachments,
    metadata: {
      outbox_id: outboxRow.id || null,
      type: outboxRow.type || null,
      reference: outboxRow.reference || null,
      sender_user_id: outboxRow.created_by || null,
      recipient_kind: outboxRow.recipient_kind || null,
      recipient_id: outboxRow.recipient_id || null,
      context_kind: outboxRow.context_kind || null,
      context_id: outboxRow.context_id || null,
      mailshot_run_id: outboxRow.mailshot_run_id || null,
      document_template_id: outboxRow.document_template_id || null
    }
  });

  const err = validateEmailPayload(base);
  if (err) throw new Error(err);

  // Pull invpdf effective config (kept from your existing code)
  let invpdfEffective = null;
  try {
    const s = await loadSettingsDefaults(env);
    invpdfEffective =
      (s && s.importConfig && s.importConfig.invpdf_effective && typeof s.importConfig.invpdf_effective === 'object')
        ? s.importConfig.invpdf_effective
        : null;
  } catch {}

  const invpdfMode = String(invpdfEffective?.mode || 'free').trim().toLowerCase() === 'paid' ? 'paid' : 'free';
  const emailWorkerCanRender = (invpdfMode === 'paid') && (invpdfEffective?.email_worker_can_render === true);

  const enc = encodeURIComponent;

  // Resolve to Apps Script attachmentsV2: [{ Name, ContentBytes }]
  const attachmentsV2 = [];

  for (const a of (base.attachments || [])) {
    if (!a) continue;

    // Direct base64
    if (a.contentBase64 && a.name) {
      attachmentsV2.push({
        Name: String(a.name || 'attachment'),
        ContentBytes: String(a.contentBase64 || '')
      });
      continue;
    }

    // Invoice placeholder -> fetch invoice_pdf_r2_key -> load from R2 -> base64
    if (a.invoice_id) {
      const invId = String(a.invoice_id).trim();
      if (!invId) throw new Error('Invalid invoice_id attachment');

      let pdfKey = null;

      if (emailWorkerCanRender) {
        const ensured = await ensureInvoicePdf(env, invId, { req: outboxRow?._req || undefined, user: null });
        if (!ensured?.ok || !ensured.invoice_pdf_r2_key) throw new Error(`PDF_NOT_READY: invoice ${invId}`);
        pdfKey = String(ensured.invoice_pdf_r2_key).trim();
      } else {
        const { rows } = await sbFetch(
          env,
          `${env.SUPABASE_URL}/rest/v1/invoices` +
            `?id=eq.${enc(invId)}` +
            `&select=invoice_pdf_r2_key,invoice_pdf_generated_at_utc,updated_at` +
            `&limit=1`,
          false
        );

        const inv = rows && rows.length ? rows[0] : null;
        const key = (inv && typeof inv.invoice_pdf_r2_key === 'string') ? inv.invoice_pdf_r2_key.trim() : '';
        const genAt = inv ? inv.invoice_pdf_generated_at_utc : null;
        const updAt = inv ? inv.updated_at : null;

        const fresh = (() => {
          if (!key || !genAt || !updAt) return false;
          const tUpd = new Date(updAt).getTime();
          const tGen = new Date(genAt).getTime();
          return (Number.isFinite(tUpd) && Number.isFinite(tGen) && tUpd <= tGen);
        })();

        if (!fresh) throw new Error(`PDF_NOT_READY: invoice ${invId}`);
        pdfKey = key;
      }

      if (!pdfKey) throw new Error(`PDF_NOT_READY: invoice ${invId}`);

      const contentBase64 = await fetchAttachmentBase64FromR2(env, pdfKey);

      attachmentsV2.push({
        Name: String(a.filename || a.name || `Invoice_${invId}.pdf`),
        ContentBytes: String(contentBase64 || '')
      });

      continue;
    }

    // r2_key attachment
    if (a.r2_key) {
      const key = String(a.r2_key).trim();
      if (!key) throw new Error('Invalid r2_key attachment');

      const contentBase64 = await fetchAttachmentBase64FromR2(env, key);

      attachmentsV2.push({
        Name: String(a.name || a.filename || 'attachment'),
        ContentBytes: String(contentBase64 || '')
      });

      continue;
    }
  }

  // Filter out empties (Apps Script does this too)
  const attachmentsV2Clean = attachmentsV2.filter(x => x && x.ContentBytes);

  // FINAL payload: match Flow keys exactly (schema expects textBody, NOT body).
  const payload = {
    to: String(base.to).trim(),
    subject: String(base.subject).trim(),
    htmlBody: String(base.htmlBody || ''),
    textBody: String(base.body || ''),
    attachmentsV2: attachmentsV2Clean,
    // ✅ meta is echoed back by the batch Flow so we can map results to outbox rows
    meta: {
      outbox_id: outboxRow.id || null,
      type: outboxRow.type || null,
      reference: outboxRow.reference || null,
      sender_user_id: outboxRow.created_by || null,
      recipient_kind: outboxRow.recipient_kind || null,
      recipient_id: outboxRow.recipient_id || null,
      context_kind: outboxRow.context_kind || null,
      context_id: outboxRow.context_id || null,
      mailshot_run_id: outboxRow.mailshot_run_id || null,
      document_template_id: outboxRow.document_template_id || null,
      ...(base.metadata && typeof base.metadata === 'object' ? base.metadata : {})
    }
  };

  // Optional fields: only add if non-empty.
  if (base.cc && String(base.cc).trim()) payload.cc = String(base.cc).trim();
  if (base.bcc && String(base.bcc).trim()) payload.bcc = String(base.bcc).trim();
  if (base.replyTo && String(base.replyTo).trim()) payload.replyTo = String(base.replyTo).trim();

  // ✅ Importance: default Normal if not supplied
  payload.importance = String(base.importance || 'Normal');

  return payload;
}

async function limitOrLinkAttachments(env, { payload }) {
  const limitBytes = Number(env.EMAIL_MAX_PAYLOAD_BYTES) || EMAIL_MAX_PAYLOAD_BYTES;
  let currentBytes = estimatePayloadSizeBytes(payload);
  if (currentBytes <= limitBytes) return { payload, trimmed: false };

  // Prefer to keep a PDF invoice if present, trim the rest and inject links.
  const kept = [];
  const trimmed = [];
  for (const a of (payload.attachments || [])) {
    const isInvoice = /invoice/i.test(a.name || '') && /\.pdf$/i.test(a.name || '');
    if (isInvoice && kept.length === 0) { kept.push(a); } else { trimmed.push(a); }
  }
  if (kept.length === 0 && (payload.attachments || []).length > 0) {
    // keep the first as a compromise
    kept.push(payload.attachments[0]);
    trimmed.splice(0, 1);
  }

  let linksHtml = '';
  let linksText = '';

  // If original attachments came from R2 we may have lost their original keys.
  // Encourage callers to include `r2_key` in attachments for graceful linking.
  for (const a of trimmed) {
    const key = a.r2_key || (a.meta && a.meta.r2_key) || null;
    if (!key) continue;
    const url = await signDownloadUrlForR2Key(env, key, { ttlSecs: SIGNED_LINK_TTL_SECS });
    linksHtml += `<li><a href="${url}">${a.name || key}</a></li>`;
    linksText += `\n- ${a.name || key}: ${url}`;
  }

  let htmlBody = payload.htmlBody || '';
  let body = payload.body || '';

  if (linksHtml) {
    htmlBody += `\n<hr/><p>Some large attachments were replaced with links:</p><ul>${linksHtml}</ul>`;
  }
  if (linksText) {
    body += `\n\nSome large attachments were replaced with links:${linksText}`;
  }

  const newPayload = { ...payload, attachments: kept, htmlBody, body };
  return { payload: newPayload, trimmed: true };
}

async function handleMailshotEnqueue(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const prepareJson = body.prepare_json ?? body.prepareJson ?? null;
  const finalEditsJson = body.final_edits_json ?? body.finalEditsJson ?? {};
  const deliveryTimingJson = body.delivery_timing_json ?? body.deliveryTimingJson ?? { mode: 'NOW' };

  if (!prepareJson || typeof prepareJson !== 'object' || Array.isArray(prepareJson)) {
    return withCORS(env, req, badRequest('prepare_json object required'));
  }
  if (finalEditsJson == null || typeof finalEditsJson !== 'object' || Array.isArray(finalEditsJson)) {
    return withCORS(env, req, badRequest('final_edits_json must be an object'));
  }
  if (deliveryTimingJson == null || typeof deliveryTimingJson !== 'object' || Array.isArray(deliveryTimingJson)) {
    return withCORS(env, req, badRequest('delivery_timing_json must be an object'));
  }

  const normalizeDeliveryTimingJson = async (raw) => {
    const timingRaw = (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : { mode: 'NOW' };

    let mode = String(timingRaw.mode || 'NOW').trim().toUpperCase();
    if (mode === 'RELATIVE_DELAY') mode = 'AFTER_DELAY';

    if (!['NOW', 'AT_TIME', 'AFTER_DELAY'].includes(mode)) {
      throw new Error('delivery_timing_json.mode must be NOW, AT_TIME or AFTER_DELAY');
    }

    let scheduledForUtc = null;
    let nextAttemptAtUtc = null;
    let requestedTimezone = null;
    let requestedLocalText = null;
    let relativeMinutes = null;

    if (timingRaw.requested_timezone != null) {
      requestedTimezone = String(timingRaw.requested_timezone || '').trim() || null;
    }
    if (timingRaw.requested_local_text != null) {
      requestedLocalText = String(timingRaw.requested_local_text || '').trim() || null;
    }
    if (timingRaw.relative_minutes != null && timingRaw.relative_minutes !== '') {
      const n = Number(timingRaw.relative_minutes);
      if (!Number.isFinite(n)) throw new Error('delivery_timing_json.relative_minutes must be numeric');
      relativeMinutes = Math.trunc(n);
    }

    let maxFutureDays = 365;
    let allowPastGraceMinutes = 15;
    try {
      const s = await loadSettingsDefaults(env);
      const cj = s && s.comms_adaptors_json && typeof s.comms_adaptors_json === 'object' && !Array.isArray(s.comms_adaptors_json)
        ? s.comms_adaptors_json
        : null;
      const scheduling = cj && cj.scheduling && typeof cj.scheduling === 'object' && !Array.isArray(cj.scheduling)
        ? cj.scheduling
        : null;
      if (scheduling) {
        const mfd = Number(scheduling.max_future_days);
        const apg = Number(scheduling.allow_past_grace_minutes);
        if (Number.isFinite(mfd) && Math.trunc(mfd) > 0) maxFutureDays = Math.trunc(mfd);
        if (Number.isFinite(apg) && Math.trunc(apg) > 0) allowPastGraceMinutes = Math.trunc(apg);
      }
    } catch {}

    const nowMs = Date.now();
    const maxFutureMs = nowMs + (maxFutureDays * 24 * 60 * 60 * 1000);
    const minPastMs = nowMs - (allowPastGraceMinutes * 60 * 1000);

    if (mode === 'AT_TIME') {
      const rawScheduled = String(timingRaw.scheduled_for_utc || '').trim();
      if (!rawScheduled) throw new Error('delivery_timing_json.scheduled_for_utc required when mode=AT_TIME');

      const dt = new Date(rawScheduled);
      if (Number.isNaN(dt.getTime())) throw new Error('delivery_timing_json.scheduled_for_utc invalid');

      const scheduledMs = dt.getTime();
      if (scheduledMs > maxFutureMs) throw new Error('delivery_timing_json.scheduled_for_utc exceeds max_future_days');
      if (scheduledMs < minPastMs) throw new Error('delivery_timing_json.scheduled_for_utc too far in past');

      scheduledForUtc = dt.toISOString();
      nextAttemptAtUtc = scheduledMs <= nowMs ? new Date(nowMs).toISOString() : scheduledForUtc;
    } else if (mode === 'AFTER_DELAY') {
      let scheduledMs = null;
      const rawScheduled = String(timingRaw.scheduled_for_utc || '').trim();

      if (rawScheduled) {
        const dt = new Date(rawScheduled);
        if (Number.isNaN(dt.getTime())) throw new Error('delivery_timing_json.scheduled_for_utc invalid');
        scheduledMs = dt.getTime();
      } else {
        if (relativeMinutes == null) throw new Error('delivery_timing_json.relative_minutes required when mode=AFTER_DELAY');
        scheduledMs = nowMs + (relativeMinutes * 60 * 1000);
      }

      if (scheduledMs > maxFutureMs) throw new Error('delivery_timing_json.scheduled_for_utc exceeds max_future_days');
      if (scheduledMs < minPastMs) throw new Error('delivery_timing_json.scheduled_for_utc too far in past');

      scheduledForUtc = new Date(scheduledMs).toISOString();
      nextAttemptAtUtc = scheduledMs <= nowMs ? new Date(nowMs).toISOString() : scheduledForUtc;
    }

    return {
      mode,
      scheduled_for_utc: scheduledForUtc,
      next_attempt_at_utc: nextAttemptAtUtc,
      requested_timezone: requestedTimezone,
      requested_local_text: requestedLocalText,
      relative_minutes: relativeMinutes
    };
  };

  const normalizeArrayLike = (value, fieldName) => {
    let out = value;
    if (out == null) return [];
    if (typeof out === 'string') {
      try {
        out = JSON.parse(out);
      } catch {
        throw new Error(`${fieldName} must be an array`);
      }
    }
    if (!Array.isArray(out)) {
      throw new Error(`${fieldName} must be an array`);
    }
    return out;
  };

  const normalizeDirectAttachment = (attachment) => {
    if (!attachment || typeof attachment !== 'object' || Array.isArray(attachment)) return null;

    const filename = attachment.filename != null
      ? String(attachment.filename || '').trim()
      : (attachment.name != null ? String(attachment.name || '').trim() : '');

    const contentType = attachment.content_type != null
      ? String(attachment.content_type || '').trim()
      : (attachment.contentType != null ? String(attachment.contentType || '').trim() : '');

    if (attachment.invoice_id != null && String(attachment.invoice_id || '').trim()) {
      return {
        invoice_id: String(attachment.invoice_id || '').trim(),
        filename: filename || null,
        content_type: contentType || null
      };
    }

    if (attachment.r2_key != null && String(attachment.r2_key || '').trim()) {
      return {
        r2_key: String(attachment.r2_key || '').trim(),
        filename: filename || null,
        content_type: contentType || null
      };
    }

    if (attachment.contentBase64 && (filename || (attachment.name && String(attachment.name).trim()))) {
      return {
        contentBase64: String(attachment.contentBase64 || ''),
        name: filename || String(attachment.name || '').trim(),
        content_type: contentType || null
      };
    }

    return null;
  };

  const dedupeAttachments = (attachments) => {
    const seen = new Set();
    const out = [];

    for (const a of (attachments || [])) {
      if (!a || typeof a !== 'object' || Array.isArray(a)) continue;

      const signature = JSON.stringify({
        invoice_id: a.invoice_id || null,
        r2_key: a.r2_key || null,
        filename: a.filename || a.name || null,
        contentBase64: a.contentBase64 ? true : false
      });

      if (seen.has(signature)) continue;
      seen.add(signature);
      out.push(a);
    }

    return out;
  };

  let normalizedTiming;
  try {
    normalizedTiming = await normalizeDeliveryTimingJson(deliveryTimingJson);
  } catch (e) {
    return withCORS(env, req, badRequest(String(e?.message || e || 'Invalid delivery timing')));
  }

  let normalizedFinalEditsJson;
  try {
    normalizedFinalEditsJson = { ...finalEditsJson };
    const globalAttachmentsRaw = normalizeArrayLike(normalizedFinalEditsJson.attachments ?? [], 'final_edits_json.attachments');
    const globalAttachmentsNormalized = [];

    for (const attachment of globalAttachmentsRaw) {
      const normalized = normalizeDirectAttachment(attachment);
      if (!normalized) continue;
      globalAttachmentsNormalized.push(normalized);
    }

    normalizedFinalEditsJson.attachments = dedupeAttachments(globalAttachmentsNormalized);
  } catch (e) {
    return withCORS(env, req, badRequest(String(e?.message || e || 'Invalid final edits attachments')));
  }

  const normalizedPrepareJson = { ...prepareJson };
  normalizedPrepareJson.rows = Array.isArray(prepareJson.rows) ? [...prepareJson.rows] : [];

  const prepareOutputType = String(normalizedPrepareJson.output_type || '').trim().toUpperCase();
  const prepareEntityType = String(normalizedPrepareJson.entity_type || '').trim().toLowerCase();

  if (prepareOutputType === 'EMAIL' && normalizedPrepareJson.rows.length > 0) {
    const timesheetPdfKeyCache = new Map();

    const resolveTimesheetPdfKey = async (timesheetId) => {
      const tsId = String(timesheetId || '').trim();
      if (!tsId) throw new Error('Missing timesheet attachment context_id');

      if (timesheetPdfKeyCache.has(tsId)) return timesheetPdfKeyCache.get(tsId);

      const pdfKeyRaw = await ensureTimesheetPdf(env, tsId, { force_regen: false });
      const pdfKey = String(pdfKeyRaw || '').trim();

      if (!pdfKey) {
        throw new Error(`Failed to resolve authoritative timesheet PDF for ${tsId}`);
      }

      timesheetPdfKeyCache.set(tsId, pdfKey);
      return pdfKey;
    };

    const normalizeRowAttachmentInstructions = async (row) => {
      const rawRow = (row && typeof row === 'object' && !Array.isArray(row)) ? row : {};
      const entityType = String(rawRow.entity_type || prepareEntityType || '').trim().toLowerCase();
      const rowContextId = String(rawRow.context_id || '').trim();

      const rawInstructions = rawRow.attachment_instructions ?? rawRow.attachments ?? [];
      const instructions = normalizeArrayLike(rawInstructions, 'prepare_json.rows[].attachment_instructions');

      const normalized = [];

      for (const instruction of instructions) {
        const direct = normalizeDirectAttachment(instruction);
        if (direct) {
          normalized.push(direct);
          continue;
        }

        if (!instruction || typeof instruction !== 'object' || Array.isArray(instruction)) continue;

        const kind = String(
          instruction.kind ??
          instruction.attachment_kind ??
          instruction.type ??
          instruction.instruction ??
          instruction.code ??
          ''
        ).trim().toUpperCase();

        const attachmentContextId = String(
          instruction.context_id ??
          instruction.contextId ??
          rowContextId ??
          ''
        ).trim();

        const filename = instruction.filename != null
          ? String(instruction.filename || '').trim()
          : (instruction.name != null ? String(instruction.name || '').trim() : '');

        const contentType = instruction.content_type != null
          ? String(instruction.content_type || '').trim()
          : (instruction.contentType != null ? String(instruction.contentType || '').trim() : 'application/pdf');

        const isRootPdfKind =
          kind === 'ROOT_DOCUMENT_PDF' ||
          kind === 'AUTHORITATIVE_ROOT_PDF' ||
          kind === 'ROOT_PDF';

        const isTimesheetPdfKind =
          kind === 'AUTHORITATIVE_TIMESHEET_PDF' ||
          kind === 'TIMESHEET_PDF' ||
          (isRootPdfKind && entityType === 'timesheet');

        const isInvoicePdfKind =
          kind === 'AUTHORITATIVE_INVOICE_PDF' ||
          kind === 'INVOICE_PDF' ||
          (isRootPdfKind && entityType === 'invoice');

        if (isTimesheetPdfKind) {
          if (!attachmentContextId || !uuidRe.test(attachmentContextId)) {
            throw new Error('Invalid context_id for authoritative timesheet PDF attachment');
          }

          const pdfKey = await resolveTimesheetPdfKey(attachmentContextId);

          normalized.push({
            r2_key: pdfKey,
            filename: filename || `Timesheet_${attachmentContextId}.pdf`,
            content_type: contentType || 'application/pdf'
          });
          continue;
        }

        if (isInvoicePdfKind) {
          if (!attachmentContextId || !uuidRe.test(attachmentContextId)) {
            throw new Error('Invalid context_id for authoritative invoice PDF attachment');
          }

          normalized.push({
            invoice_id: attachmentContextId,
            filename: filename || `Invoice_${attachmentContextId}.pdf`,
            content_type: contentType || 'application/pdf'
          });
          continue;
        }
      }

      return dedupeAttachments(normalized);
    };

    try {
      const rebuiltRows = [];

      for (const row of normalizedPrepareJson.rows) {
        const rawRow = (row && typeof row === 'object' && !Array.isArray(row)) ? row : {};
        const rowAttachments = await normalizeRowAttachmentInstructions(rawRow);

        rebuiltRows.push({
          ...rawRow,
          attachment_instructions: rowAttachments,
          attachments: rowAttachments
        });
      }

      normalizedPrepareJson.rows = rebuiltRows;
    } catch (e) {
      return withCORS(env, req, badRequest(String(e?.message || e || 'Invalid prepare attachment instructions')));
    }
  }

  try {
    let payload = await sbRpc(env, 'mailshot_enqueue', {
      p_prepare_json: normalizedPrepareJson,
      p_final_edits_json: normalizedFinalEditsJson,
      p_delivery_timing_json: normalizedTiming,
      p_actor_user_id: user.id
    });

    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'mailshot_enqueue')) payload = payload.mailshot_enqueue;
    } catch {}

    return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
  } catch (e) {
    const msg = String(e?.message || e || 'MAILSHOT_ENQUEUE_FAILED');
    return withCORS(env, req, serverError(msg));
  }
}
async function drainEmailOutboxOnce(env, { limit, types } = {}) {
  const enc = encodeURIComponent;

  const toPositiveInt = (value) => {
    const n = Number(value);
    return Number.isFinite(n) && n > 0 ? Math.trunc(n) : null;
  };

  const maxPerCall = Math.max(
    1,
    toPositiveInt(env.EMAIL_DRAIN_MAX_PER_CALL) || 200
  );
  const maxCallsPerDrain = Math.max(
    1,
    toPositiveInt(env.EMAIL_DRAIN_MAX_CALLS_PER_DRAIN) || 25
  );
  const maxDrainJobs = Math.max(1, maxPerCall * maxCallsPerDrain);

  const requestedTake =
    toPositiveInt(limit) ||
    toPositiveInt(env.EMAIL_DRAIN_LIMIT_DEFAULT) ||
    maxDrainJobs;

  const take = Math.max(1, Math.min(requestedTake, maxDrainJobs));
  const typeFilter = Array.isArray(types) && types.length ? types : null;
  const typeFilterSet = typeFilter
    ? new Set(typeFilter.map((tp) => String(tp || '').trim().toUpperCase()).filter(Boolean))
    : null;

  let sent = 0;
  let failed = 0;
  let deferred = 0;
  const errors = [];

  const nowIsoUtc = () => new Date().toISOString();
  const nowPlusMinutesIso = (mins) => {
    const ms = Date.now() + Math.max(1, Number(mins) || 5) * 60 * 1000;
    return new Date(ms).toISOString();
  };

  const leaseMinutes = 5;
  const attemptLeaseToken =
    (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function')
      ? globalThis.crypto.randomUUID()
      : `lease_${Date.now()}_${Math.random().toString(16).slice(2)}`;

  const patchMailOutboxRows = async (query, body) => {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/mail_outbox?${query}`, {
      method: 'PATCH',
      headers: {
        ...sbHeaders(env),
        Prefer: 'return=representation'
      },
      body: JSON.stringify(body)
    });

    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(errTxt || `mail_outbox patch failed (${res.status})`);
    }

    const rows = await res.json().catch(() => []);
    if (Array.isArray(rows)) return rows;
    return rows ? [rows] : [];
  };

  const clearClaimedLease = async (rowId, currentLeaseToken) => {
    const rows = await patchMailOutboxRows(
      `id=eq.${enc(rowId)}&attempt_lease_token=eq.${enc(currentLeaseToken)}`,
      {
        attempt_lease_token: null,
        attempt_leased_at_utc: null,
        attempt_lease_expires_at_utc: null
      }
    );
    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const patchClaimedRowFailed = async (rowId, msg, currentLeaseToken) => {
    const rows = await patchMailOutboxRows(
      `id=eq.${enc(rowId)}&attempt_lease_token=eq.${enc(currentLeaseToken)}&sent_at=is.null`,
      {
        status: 'FAILED',
        failed_at: nowIsoUtc(),
        last_error: String(msg || 'FAILED'),
        provider_status: 'FAILED',
        attempt_lease_token: null,
        attempt_leased_at_utc: null,
        attempt_lease_expires_at_utc: null
      }
    );
    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const patchClaimedRowSent = async (rowId, providerMessageId, currentLeaseToken) => {
    const rows = await patchMailOutboxRows(
      `id=eq.${enc(rowId)}&attempt_lease_token=eq.${enc(currentLeaseToken)}`,
      {
        status: 'SENT',
        sent_at: nowIsoUtc(),
        provider_message_id: providerMessageId || null,
        provider_status: 'ACCEPTED',
        delivered_at: null,
        read_at: null,
        last_error: null,
        failed_at: null,
        attempt_lease_token: null,
        attempt_leased_at_utc: null,
        attempt_lease_expires_at_utc: null
      }
    );
    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const patchClaimedRowDeferred = async (rowId, msg, currentLeaseToken) => {
    const rows = await patchMailOutboxRows(
      `id=eq.${enc(rowId)}&attempt_lease_token=eq.${enc(currentLeaseToken)}&sent_at=is.null`,
      {
        status: 'QUEUED',
        last_error: String(msg || 'DEFERRED'),
        next_attempt_at_utc: nowPlusMinutesIso(10),
        failed_at: null,
        provider_status: null,
        provider_message_id: null,
        attempt_lease_token: null,
        attempt_leased_at_utc: null,
        attempt_lease_expires_at_utc: null
      }
    );
    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const claimEmailOutboxReadyBatch = async (takeCount) => {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/email_outbox_claim_ready_batch`, {
      method: 'POST',
      headers: sbHeaders(env),
      body: JSON.stringify({
        p_limit: takeCount,
        p_attempt_lease_token: attemptLeaseToken,
        p_lease_minutes: leaseMinutes
      })
    });

    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(errTxt || `email_outbox_claim_ready_batch failed (${res.status})`);
    }

    const rows = await res.json().catch(() => []);
    return Array.isArray(rows) ? rows : [];
  };

  const claimTake = typeFilterSet ? maxDrainJobs : take;
  const claimed = await claimEmailOutboxReadyBatch(claimTake);

  if (claimed.length === 0) {
    return { picked: 0, sent: 0, failed: 0, deferred: 0, errors: [] };
  }

  const picked = [];
  const toRelease = [];

  if (typeFilterSet) {
    for (const row of claimed) {
      const rowType = String(row && row.type ? row.type : '').trim().toUpperCase();
      if (typeFilterSet.has(rowType) && picked.length < take) {
        picked.push(row);
      } else {
        toRelease.push(row);
      }
    }
  } else {
    picked.push(...claimed.slice(0, take));
    toRelease.push(...claimed.slice(take));
  }

  for (const row of toRelease) {
    try {
      await clearClaimedLease(row.id, attemptLeaseToken);
    } catch {}
  }

  if (picked.length === 0) {
    return { picked: 0, sent: 0, failed: 0, deferred: 0, errors: [] };
  }

  const routeBuckets = new Map();

  const addJobToBucket = (bucketKey, bucketChannel, rowId, payload) => {
    if (!routeBuckets.has(bucketKey)) {
      routeBuckets.set(bucketKey, {
        channel: bucketChannel,
        jobs: [],
        rowIds: []
      });
    }
    const bucket = routeBuckets.get(bucketKey);
    bucket.jobs.push(payload);
    bucket.rowIds.push(rowId);
  };

  const reconcileBatchResult = async (res, rowIds, currentLeaseToken) => {
    if (!res || !res.ok) {
      const errMsg = String((res && res.body) || (res && `HTTP ${res.status}`) || 'Provider transport failure');
      for (const rowId of rowIds) {
        const updatedRow = await patchClaimedRowFailed(rowId, errMsg, currentLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        failed += 1;
        errors.push({ id: rowId, error: errMsg });
        await recordEmailAudit(env, null, 'EMAIL_FAILED', {
          outbox_id: rowId,
          error: errMsg,
          type: 'BATCH'
        });
      }
      return;
    }

    let results = null;
    try {
      const j = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
      results = Array.isArray(j?.results) ? j.results : null;
    } catch {
      results = null;
    }

    if (!Array.isArray(results) || results.length === 0) {
      const errMsg = 'Provider returned no per-item results (cannot reconcile)';
      for (const rowId of rowIds) {
        const updatedRow = await patchClaimedRowFailed(rowId, errMsg, currentLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        failed += 1;
        errors.push({ id: rowId, error: errMsg });
        await recordEmailAudit(env, null, 'EMAIL_FAILED', {
          outbox_id: rowId,
          error: errMsg,
          type: 'BATCH'
        });
      }
      return;
    }

    const byOutboxId = new Map();
    for (const r of results) {
      const oid =
        r?.outbox_id ||
        r?.outboxId ||
        r?.meta?.outbox_id ||
        r?.meta?.outboxId ||
        r?.meta?.id ||
        null;
      if (!oid) continue;
      byOutboxId.set(String(oid), r);
    }

    for (const rowId of rowIds) {
      const r = byOutboxId.get(String(rowId)) || null;

      if (!r) {
        const errMsg = 'PROVIDER_RESULT_MISSING_FOR_ITEM';
        const updatedRow = await patchClaimedRowFailed(rowId, errMsg, currentLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        failed += 1;
        errors.push({ id: rowId, error: errMsg });
        await recordEmailAudit(env, null, 'EMAIL_FAILED', {
          outbox_id: rowId,
          error: errMsg,
          type: 'BATCH'
        });
        continue;
      }

      const status = String(r?.status || '').toUpperCase();
      const isSuccess = status === 'SUCCESS';
      const isFailed = status === 'FAILED' || status === 'FAIL' || status === 'ERROR';

      if (isSuccess) {
        const providerMessageId =
          r?.provider_message_id ||
          r?.providerMessageId ||
          null;

        const updatedRow = await patchClaimedRowSent(rowId, providerMessageId, currentLeaseToken).catch(() => null);
        if (!updatedRow) continue;

        sent += 1;
        await recordEmailAudit(env, null, 'EMAIL_SENT', {
          outbox_id: rowId,
          provider_message_id: providerMessageId,
          type: r?.meta?.type || 'BATCH'
        });
        continue;
      }

      if (isFailed) {
        const errMsg = String(r?.error || r?.body || r?.message || 'Provider failed');
        const updatedRow = await patchClaimedRowFailed(rowId, errMsg, currentLeaseToken).catch(() => null);
        if (!updatedRow) continue;

        failed += 1;
        errors.push({ id: rowId, error: errMsg });
        await recordEmailAudit(env, null, 'EMAIL_FAILED', {
          outbox_id: rowId,
          error: errMsg,
          type: r?.meta?.type || 'BATCH'
        });
        continue;
      }

      {
        const errMsg = String(r?.error || r?.body || r?.message || 'Unknown provider status');
        const updatedRow = await patchClaimedRowFailed(rowId, errMsg, currentLeaseToken).catch(() => null);
        if (!updatedRow) continue;

        failed += 1;
        errors.push({ id: rowId, error: errMsg });
        await recordEmailAudit(env, null, 'EMAIL_FAILED', {
          outbox_id: rowId,
          error: errMsg,
          type: 'BATCH'
        });
      }
    }
  };

  for (const row of picked) {
    try {
      const payloadBase = await buildEmailPayloadFromOutboxRow(env, row);
      const payload = {
        ...payloadBase,
        meta: {
          ...((payloadBase && payloadBase.meta && typeof payloadBase.meta === 'object') ? payloadBase.meta : {}),
          outbox_id: row.id || null,
          type: row.type || null,
          reference: row.reference || null,
          sender_user_id: row.created_by || null,
          recipient_kind: row.recipient_kind || null,
          recipient_id: row.recipient_id || null,
          context_kind: row.context_kind || null,
          context_id: row.context_id || null,
          mailshot_run_id: row.mailshot_run_id || null,
          document_template_id: row.document_template_id || null
        }
      };

      const rowType = String(row && row.type ? row.type : '').trim().toUpperCase();
      const senderUserId = (row && row.created_by != null) ? String(row.created_by).trim() : '';

      if (rowType === 'MAILSHOT_EMAIL') {
        if (!senderUserId) {
          const msg = 'MAILSHOT_SENDER_USER_MISSING';
          const updatedRow = await patchClaimedRowFailed(row.id, msg, attemptLeaseToken).catch(() => null);
          if (!updatedRow) continue;
          failed += 1;
          errors.push({ id: row.id, error: msg });
          await recordEmailAudit(env, null, 'EMAIL_FAILED', { outbox_id: row.id, error: msg, type: row.type });
          continue;
        }

        addJobToBucket(`mailshot:${senderUserId}`, { kind: 'mailshot', user_id: senderUserId }, row.id, payload);
      } else {
        addJobToBucket('finance', 'finance', row.id, payload);
      }
    } catch (e) {
      const msg = String(e?.message || e);

      if (msg.startsWith('PDF_NOT_READY:')) {
        const updatedRow = await patchClaimedRowDeferred(row.id, msg, attemptLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        deferred += 1;
        errors.push({ id: row.id, error: msg, deferred: true });
        await recordEmailAudit(env, null, 'EMAIL_DEFERRED', {
          outbox_id: row.id,
          reason: msg,
          type: row.type,
        });
        continue;
      }

      const updatedRow = await patchClaimedRowFailed(row.id, msg, attemptLeaseToken).catch(() => null);
      if (!updatedRow) continue;
      failed += 1;
      errors.push({ id: row.id, error: msg });
      await recordEmailAudit(env, null, 'EMAIL_FAILED', { outbox_id: row.id, error: msg, type: row.type });
    }
  }

  if (routeBuckets.size === 0) {
    return { picked: picked.length, sent, failed, deferred, errors };
  }

  let outboundCallCount = 0;

  for (const bucket of routeBuckets.values()) {
    for (let start = 0; start < bucket.jobs.length; start += maxPerCall) {
      if (outboundCallCount >= maxCallsPerDrain) break;

      const batchJobs = bucket.jobs.slice(start, start + maxPerCall);
      const batchRowIds = bucket.rowIds.slice(start, start + maxPerCall);
      if (!batchJobs.length) continue;

      const batchPayload = { items: batchJobs };

      let res = null;
      try {
        res = await postToPowerAutomate(env, batchPayload, bucket.channel);
      } catch (e) {
        res = {
          ok: false,
          status: 0,
          body: String(e?.message || e || 'Provider transport failure')
        };
      }

      await reconcileBatchResult(res, batchRowIds, attemptLeaseToken);
      outboundCallCount += 1;
    }

    if (outboundCallCount >= maxCallsPerDrain) break;
  }

  return { picked: picked.length, sent, failed, deferred, errors };
}

async function drainCommsOutboxOnce(env, { limit } = {}) {
  const enc = encodeURIComponent;

  const nowIso = () => new Date().toISOString();

  const clampInt = (n, lo, hi, dflt) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return dflt;
    const y = Math.trunc(x);
    if (y < lo) return lo;
    if (y > hi) return hi;
    return y;
  };

  const isPlainObject = (x) => !!(x && typeof x === 'object' && !Array.isArray(x));

  const leaseMinutes = 5;
  const attemptLeaseToken =
    (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function')
      ? globalThis.crypto.randomUUID()
      : `lease_${Date.now()}_${Math.random().toString(16).slice(2)}`;

  let cfgAll = {};
  try {
    const s = await loadSettingsDefaults(env);
    const cj = s && isPlainObject(s.comms_adaptors_json) ? s.comms_adaptors_json : {};
    cfgAll = isPlainObject(cj) ? cj : {};
  } catch {
    cfgAll = {};
  }

  const channelsCfg = isPlainObject(cfgAll.channels) ? cfgAll.channels : {};
  const adaptorsCfg = isPlainObject(cfgAll.adaptors) ? cfgAll.adaptors : {};

  const watiCfgRaw = isPlainObject(adaptorsCfg.wati)
    ? adaptorsCfg.wati
    : (isPlainObject(cfgAll.wati) ? cfgAll.wati : {});
  const csCfgRaw = isPlainObject(adaptorsCfg.clicksend)
    ? adaptorsCfg.clicksend
    : (isPlainObject(cfgAll.clicksend) ? cfgAll.clicksend : {});

  const watiCfg = {
    base_url: watiCfgRaw.base_url,
    bulk_send_limit: watiCfgRaw.bulk_send_limit,
  };

  const csCfg = {
    base_url: csCfgRaw.base_url,
    sms_max_chars: csCfgRaw.sms_max_chars,
    voice_max_chars: csCfgRaw.voice_max_chars,
    bulk_send_limit: csCfgRaw.bulk_send_limit,
    voice: csCfgRaw.voice,
    country: csCfgRaw.country,
    lang: csCfgRaw.lang,
  };

  const drainLimitsCfg = isPlainObject(cfgAll.drain_limits) ? cfgAll.drain_limits : {};
  const defaultDrainLimits = { WHATSAPP: 200, SMS: 200, VOICE: 50 };
  const drainLimits = {
    WHATSAPP: clampInt(drainLimitsCfg.WHATSAPP, 1, 20000, defaultDrainLimits.WHATSAPP),
    SMS: clampInt(drainLimitsCfg.SMS, 1, 20000, defaultDrainLimits.SMS),
    VOICE: clampInt(drainLimitsCfg.VOICE, 1, 20000, defaultDrainLimits.VOICE),
  };

  const channelToAdaptor = {
    WHATSAPP: String(channelsCfg.WHATSAPP || 'wati').trim().toLowerCase(),
    SMS: String(channelsCfg.SMS || 'clicksend').trim().toLowerCase(),
    VOICE: String(channelsCfg.VOICE || 'clicksend').trim().toLowerCase(),
  };

  const watiBatchMax = clampInt(watiCfg.bulk_send_limit, 1, 20000, drainLimits.WHATSAPP);
  const csBatchMax = clampInt(csCfg.bulk_send_limit, 1, 20000, Math.max(drainLimits.SMS, drainLimits.VOICE));

  const globalLimit = (limit == null) ? null : clampInt(limit, 1, 50000, null);
  let remaining = globalLimit;

  const alloc = (channel) => {
    const ch = String(channel || '').toUpperCase();
    const dl = drainLimits[ch] || 0;
    const ad = channelToAdaptor[ch] || '';
    const adCap =
      (ch === 'WHATSAPP' && ad === 'wati') ? watiBatchMax :
      ((ch === 'SMS' || ch === 'VOICE') && ad === 'clicksend') ? csBatchMax :
      dl;

    const cap = Math.min(dl, adCap);

    if (remaining == null) return cap;
    if (remaining <= 0) return 0;
    const take = Math.min(cap, remaining);
    remaining -= take;
    return take;
  };

  const patchCommsOutboxRows = async (query, body) => {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/comms_outbox?${query}`, {
      method: 'PATCH',
      headers: {
        ...sbHeaders(env),
        Prefer: 'return=representation'
      },
      body: JSON.stringify(body)
    });

    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(errTxt || `comms_outbox patch failed (${res.status})`);
    }

    const rows = await res.json().catch(() => []);
    if (Array.isArray(rows)) return rows;
    return rows ? [rows] : [];
  };

  const claimCommsOutboxReadyBatch = async (channel, take) => {
    if (!take || take <= 0) return [];
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/comms_outbox_claim_ready_batch`, {
      method: 'POST',
      headers: sbHeaders(env),
      body: JSON.stringify({
        p_channel: String(channel || '').toUpperCase(),
        p_limit: take,
        p_attempt_lease_token: attemptLeaseToken,
        p_lease_minutes: leaseMinutes
      })
    });

    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(errTxt || `comms_outbox_claim_ready_batch failed (${res.status})`);
    }

    const rows = await res.json().catch(() => []);
    return Array.isArray(rows) ? rows : [];
  };

  const patchFailRow = async (id, msg, providerKey, currentLeaseToken) => {
    const rows = await patchCommsOutboxRows(
      `id=eq.${enc(id)}&attempt_lease_token=eq.${enc(currentLeaseToken)}&sent_at=is.null`,
      {
        status: 'FAILED',
        failed_at: nowIso(),
        last_error: String(msg || 'FAILED').slice(0, 500),
        provider_key: providerKey || null,
        attempt_lease_token: null,
        attempt_leased_at_utc: null,
        attempt_lease_expires_at_utc: null
      }
    );
    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const report = {
    picked: 0,
    sent: 0,
    failed: 0,
    errors: [],
    by_channel: {
      WHATSAPP: { picked: 0, sent: 0, failed: 0 },
      SMS: { picked: 0, sent: 0, failed: 0 },
      VOICE: { picked: 0, sent: 0, failed: 0 },
    },
    now_utc: null
  };

  const pickedWhatsapp = await claimCommsOutboxReadyBatch('WHATSAPP', alloc('WHATSAPP'));
  const pickedSms = await claimCommsOutboxReadyBatch('SMS', alloc('SMS'));
  const pickedVoice = await claimCommsOutboxReadyBatch('VOICE', alloc('VOICE'));

  report.by_channel.WHATSAPP.picked = pickedWhatsapp.length;
  report.by_channel.SMS.picked = pickedSms.length;
  report.by_channel.VOICE.picked = pickedVoice.length;
  report.picked = pickedWhatsapp.length + pickedSms.length + pickedVoice.length;

  if (pickedWhatsapp.length) {
    const ad = channelToAdaptor.WHATSAPP;
    if (ad === 'wati') {
      const r = await sendViaWatiBulkTemplate(env, watiCfg, pickedWhatsapp, { attemptLeaseToken });
      report.sent += r.sent;
      report.failed += r.failed;
      report.errors.push(...(r.errors || []));
      report.by_channel.WHATSAPP.sent += r.sent;
      report.by_channel.WHATSAPP.failed += r.failed;
    } else {
      for (const row of pickedWhatsapp) {
        const id = row && row.id ? String(row.id) : '';
        if (!id) continue;
        const updatedRow = await patchFailRow(id, `NO_ADAPTOR_FOR_WHATSAPP:${ad || 'missing'}`, null, attemptLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        report.failed += 1;
        report.by_channel.WHATSAPP.failed += 1;
        report.errors.push({ id, error: `NO_ADAPTOR_FOR_WHATSAPP:${ad || 'missing'}` });
      }
    }
  }

  if (pickedSms.length) {
    const ad = channelToAdaptor.SMS;
    if (ad === 'clicksend') {
      const r = await sendViaClicksendSmsBulk(env, csCfg, pickedSms, { attemptLeaseToken });
      report.sent += r.sent;
      report.failed += r.failed;
      report.errors.push(...(r.errors || []));
      report.by_channel.SMS.sent += r.sent;
      report.by_channel.SMS.failed += r.failed;
    } else {
      for (const row of pickedSms) {
        const id = row && row.id ? String(row.id) : '';
        if (!id) continue;
        const updatedRow = await patchFailRow(id, `NO_ADAPTOR_FOR_SMS:${ad || 'missing'}`, null, attemptLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        report.failed += 1;
        report.by_channel.SMS.failed += 1;
        report.errors.push({ id, error: `NO_ADAPTOR_FOR_SMS:${ad || 'missing'}` });
      }
    }
  }

  if (pickedVoice.length) {
    const ad = channelToAdaptor.VOICE;
    if (ad === 'clicksend') {
      const r = await sendViaClicksendVoiceBulk(env, csCfg, pickedVoice, { attemptLeaseToken });
      report.sent += r.sent;
      report.failed += r.failed;
      report.errors.push(...(r.errors || []));
      report.by_channel.VOICE.sent += r.sent;
      report.by_channel.VOICE.failed += r.failed;
    } else {
      for (const row of pickedVoice) {
        const id = row && row.id ? String(row.id) : '';
        if (!id) continue;
        const updatedRow = await patchFailRow(id, `NO_ADAPTOR_FOR_VOICE:${ad || 'missing'}`, null, attemptLeaseToken).catch(() => null);
        if (!updatedRow) continue;
        report.failed += 1;
        report.by_channel.VOICE.failed += 1;
        report.errors.push({ id, error: `NO_ADAPTOR_FOR_VOICE:${ad || 'missing'}` });
      }
    }
  }

  report.now_utc = nowIso();
  return report;
}

async function sendViaWatiBulkTemplate(env, watiCfg, rows, opts = {}) {
  const enc = encodeURIComponent;

  const nowIso = () => new Date().toISOString();

  const isPlainObject = (x) => !!(x && typeof x === 'object' && !Array.isArray(x));

  const clampInt = (n, lo, hi, dflt) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return dflt;
    const y = Math.trunc(x);
    if (y < lo) return lo;
    if (y > hi) return hi;
    return y;
  };

  const firstNonBlank = (...vals) => {
    for (const v of vals) {
      if (v == null) continue;
      const s = String(v).trim();
      if (s) return s;
    }
    return '';
  };

const toWatiWhatsAppNumber = (raw) => {
  let s = String(raw || '').trim();
  if (!s) return '';
  s = s.replace(/[^\d]/g, '');
  if (!s) return '';
  if (s.startsWith('0')) s = '44' + s.slice(1);
  else if (!s.startsWith('44')) s = '44' + s;
  return s;
};

  const getRowWatiContract = (row) => {
    const providerPayload = isPlainObject(row && row.provider_payload_json) ? row.provider_payload_json : {};
    const providerContract = isPlainObject(providerPayload.provider_contract) ? providerPayload.provider_contract : {};
    const wati = isPlainObject(providerPayload.wati) ? providerPayload.wati : {};
    const whatsapp = isPlainObject(providerPayload.whatsapp) ? providerPayload.whatsapp : {};
    const provider = firstNonBlank(
      providerContract.provider,
      providerContract.provider_key,
      providerPayload.provider,
      providerPayload.provider_key,
      wati.provider,
      whatsapp.provider
    );
    const templateName = firstNonBlank(
      providerContract.template_name,
      providerContract.templateName,
      wati.template_name,
      wati.templateName,
      whatsapp.template_name,
      whatsapp.templateName,
      providerPayload.template_name,
      providerPayload.templateName,
      providerPayload.wati_template_name,
      providerPayload.watiTemplateName
    );
    const paramName = firstNonBlank(
      providerContract.param_name,
      providerContract.paramName,
      wati.param_name,
      wati.paramName,
      whatsapp.param_name,
      whatsapp.paramName,
      providerPayload.param_name,
      providerPayload.paramName,
      providerPayload.wati_param_name,
      providerPayload.watiParamName
    );
    return { provider, templateName, paramName };
  };

  const attemptLeaseToken = (opts && typeof opts === 'object' && opts.attemptLeaseToken != null)
    ? String(opts.attemptLeaseToken || '').trim()
    : '';

  const patchClaimedRows = async (query, body) => {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/comms_outbox?${query}`, {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return=representation' },
      body: JSON.stringify(body)
    });

    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(errTxt || `comms_outbox patch failed (${res.status})`);
    }

    const rows = await res.json().catch(() => []);
    if (Array.isArray(rows)) return rows;
    return rows ? [rows] : [];
  };

  const patchSuccess = async (id, providerMessageId, respJson) => {
    const query =
      `id=eq.${enc(id)}` +
      (attemptLeaseToken ? `&attempt_lease_token=eq.${enc(attemptLeaseToken)}` : '');

    const rows = await patchClaimedRows(query, {
      provider_key: 'WATI',
      status: 'SENT',
      sent_at: nowIso(),
      provider_message_id: providerMessageId || null,
      provider_response_json: respJson || {},
      last_error: null,
      failed_at: null,
      delivered_at: null,
      read_at: null,
      attempt_lease_token: null,
      attempt_leased_at_utc: null,
      attempt_lease_expires_at_utc: null
    });

    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const patchFailure = async (id, errMsg, respJson) => {
    const query =
      `id=eq.${enc(id)}` +
      (attemptLeaseToken ? `&attempt_lease_token=eq.${enc(attemptLeaseToken)}` : '') +
      `&sent_at=is.null`;

    const rows = await patchClaimedRows(query, {
      provider_key: 'WATI',
      status: 'FAILED',
      failed_at: nowIso(),
      provider_response_json: respJson || {},
      last_error: String(errMsg || 'FAILED').slice(0, 500),
      attempt_lease_token: null,
      attempt_leased_at_utc: null,
      attempt_lease_expires_at_utc: null
    });

    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const cfg = isPlainObject(watiCfg) ? watiCfg : {};

  const baseUrlRaw = (cfg.base_url != null) ? String(cfg.base_url).trim() : '';
  let bearerRaw = (env && env.WATI_API_TOKEN != null) ? String(env.WATI_API_TOKEN).trim() : '';
  if (/^Bearer\s+/i.test(bearerRaw)) bearerRaw = bearerRaw.replace(/^Bearer\s+/i, '').trim();
  const batchMax = clampInt(cfg.bulk_send_limit, 1, 20000, 200);

  const report = { sent: 0, failed: 0, errors: [] };

  if (!baseUrlRaw) {
    const msg = 'WATI_CONFIG_MISSING';
    const detail = {
      error: msg,
      missing_field: 'base_url',
      missing_config_path: 'settings_defaults.comms_adaptors_json.wati.base_url'
    };
    for (const r of (Array.isArray(rows) ? rows : [])) {
      if (!r || !r.id) continue;
      const updatedRow = await patchFailure(r.id, msg, detail).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: r.id, error: msg, missing_field: 'base_url', missing_config_path: 'settings_defaults.comms_adaptors_json.wati.base_url' });
    }
    return report;
  }

  if (!bearerRaw) {
    const msg = 'WATI_API_TOKEN_MISSING';
    const detail = {
      error: msg,
      missing_field: 'WATI_API_TOKEN',
      missing_config_path: 'env.WATI_API_TOKEN'
    };
    for (const r of (Array.isArray(rows) ? rows : [])) {
      if (!r || !r.id) continue;
      const updatedRow = await patchFailure(r.id, msg, detail).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: r.id, error: msg, missing_field: 'WATI_API_TOKEN', missing_config_path: 'env.WATI_API_TOKEN' });
    }
    return report;
  }

  const baseUrl = baseUrlRaw.replace(/\/+$/, '');
  const url = `${baseUrl}/api/v2/sendTemplateMessages`;

  const slice = Array.isArray(rows) ? rows : [];
  const groups = new Map();

  for (const r of slice) {
    const id = r && r.id ? String(r.id) : '';
    const toRaw = r && r.to_address != null ? String(r.to_address) : '';
    const bodyRaw = r && r.message_text != null ? String(r.message_text) : '';

    if (!id) continue;

    const waNum = toWatiWhatsAppNumber(toRaw);
    const msg = String(bodyRaw || '').trim();
    const contract = getRowWatiContract(r);
    const provider = String(contract.provider || '').trim().toUpperCase();
    const templateName = String(contract.templateName || '').trim();
    const paramName = String(contract.paramName || '').trim();

    if (!waNum) {
      const updatedRow = await patchFailure(id, 'MISSING_TO', { error: 'MISSING_TO' }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'MISSING_TO' });
      continue;
    }

    if (!msg) {
      const updatedRow = await patchFailure(id, 'EMPTY_MESSAGE', { error: 'EMPTY_MESSAGE' }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'EMPTY_MESSAGE' });
      continue;
    }

    if (provider && provider !== 'WATI') {
      const updatedRow = await patchFailure(id, 'INVALID_WATI_PROVIDER_CONTRACT', { error: 'INVALID_WATI_PROVIDER_CONTRACT', provider_contract: contract }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'INVALID_WATI_PROVIDER_CONTRACT' });
      continue;
    }

    if (!templateName) {
      const updatedRow = await patchFailure(id, 'WATI_TEMPLATE_NAME_MISSING', { error: 'WATI_TEMPLATE_NAME_MISSING', provider_contract: contract }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'WATI_TEMPLATE_NAME_MISSING' });
      continue;
    }

    if (!paramName) {
      const updatedRow = await patchFailure(id, 'WATI_PARAM_NAME_MISSING', { error: 'WATI_PARAM_NAME_MISSING', provider_contract: contract }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'WATI_PARAM_NAME_MISSING' });
      continue;
    }

    const groupKey = `${templateName}\u0000${paramName}`;
    if (!groups.has(groupKey)) {
      groups.set(groupKey, {
        templateName,
        paramName,
        items: []
      });
    }

    groups.get(groupKey).items.push({
      id,
      waNum,
      msg
    });
  }

  for (const group of groups.values()) {
    const templateName = group.templateName;
    const paramName = group.paramName;
    const items = Array.isArray(group.items) ? group.items : [];

    for (let start = 0; start < items.length; start += batchMax) {
      const chunk = items.slice(start, start + batchMax);

      if (!chunk.length) continue;

      const payload = {
        template_name: templateName,
        broadcast_name: `CloudTMS_${Date.now()}`,
        receivers: chunk.map((item) => ({
          whatsappNumber: item.waNum,
          customParams: [
            { name: paramName, value: item.msg }
          ]
        }))
      };

      let respText = '';
      let respJson = null;
      let httpOk = false;
      let httpStatus = 0;

      try {
        const res = await fetch(url, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${bearerRaw}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(payload)
        });

        httpOk = !!res.ok;
        httpStatus = res.status;

        respText = await res.text().catch(() => '');
        try { respJson = respText ? JSON.parse(respText) : null; } catch { respJson = null; }
      } catch (e) {
        const errMsg = String(e?.message || e || 'WATI_REQUEST_FAILED');
        for (const item of chunk) {
          const updatedRow = await patchFailure(item.id, errMsg, { error: errMsg }).catch(() => null);
          if (!updatedRow) continue;
          report.failed += 1;
          report.errors.push({ id: item.id, error: errMsg });
        }
        continue;
      }

      if (!httpOk) {
        const errMsg = `WATI_HTTP_${httpStatus}`;
        for (const item of chunk) {
          const updatedRow = await patchFailure(item.id, errMsg, { http_status: httpStatus, body: respText || null }).catch(() => null);
          if (!updatedRow) continue;
          report.failed += 1;
          report.errors.push({ id: item.id, error: errMsg });
        }
        continue;
      }

      const topResult = !!(respJson && typeof respJson === 'object' && respJson.result === true);
      const receiversResp = (respJson && typeof respJson === 'object' && Array.isArray(respJson.receivers)) ? respJson.receivers : [];

      if (!topResult || receiversResp.length === 0) {
        const errMsg = topResult ? 'WATI_NO_RECEIVER_RESULTS' : (respJson && respJson.error ? String(respJson.error) : 'WATI_RESULT_FALSE');
        for (const item of chunk) {
          const updatedRow = await patchFailure(item.id, errMsg, isPlainObject(respJson) ? respJson : { error: errMsg, body: respText || null }).catch(() => null);
          if (!updatedRow) continue;
          report.failed += 1;
          report.errors.push({ id: item.id, error: errMsg });
        }
        continue;
      }

      for (let i = 0; i < chunk.length; i++) {
        const item = chunk[i];
        const rr = receiversResp[i] || null;

        if (!(rr && typeof rr === 'object')) {
          const msg = 'WATI_MISSING_RECEIVER_RESULT';
          const updatedRow = await patchFailure(item.id, msg, { full: respJson }).catch(() => null);
          if (!updatedRow) continue;
          report.failed += 1;
          report.errors.push({ id: item.id, error: msg });
          continue;
        }

        const localMessageId = rr && (rr.localMessageId || rr.localMessageID || rr.local_message_id) ? String(rr.localMessageId || rr.localMessageID || rr.local_message_id) : null;
        const isValid = Object.prototype.hasOwnProperty.call(rr, 'isValidWhatsAppNumber')
          ? (rr.isValidWhatsAppNumber === true)
          : true;
        const errs = rr && Array.isArray(rr.errors) ? rr.errors : [];
        const errStr = errs.length ? errs.map(x => String(x)).join('; ').slice(0, 500) : null;

        if (!isValid || errStr) {
          const msg = errStr || 'WATI_INVALID_WHATSAPP_NUMBER';
          const updatedRow = await patchFailure(item.id, msg, { wati: rr, full: respJson }).catch(() => null);
          if (!updatedRow) continue;
          report.failed += 1;
          report.errors.push({ id: item.id, error: msg });
          continue;
        }

        const updatedRow = await patchSuccess(item.id, localMessageId, { wati: rr, full: respJson }).catch(() => null);
        if (!updatedRow) continue;
        report.sent += 1;
      }
    }
  }

  return report;
}

async function sendViaClicksendSmsBulk(env, csCfg, rows, opts = {}) {
  const enc = encodeURIComponent;

  const nowIso = () => new Date().toISOString();

  const isPlainObject = (x) => !!(x && typeof x === 'object' && !Array.isArray(x));

  const clampInt = (n, lo, hi, dflt) => {
    const x = Number(n);
    if (!Number.isFinite(x)) return dflt;
    const y = Math.trunc(x);
    if (y < lo) return lo;
    if (y > hi) return hi;
    return y;
  };

  const normalizeE164 = (raw) => {
    let s = String(raw || '').trim();
    if (!s) return '';
    if (s.startsWith('00')) s = '+' + s.slice(2);
    s = s.replace(/[^\d+]/g, '');
    if (s.startsWith('+')) {
      return '+' + s.slice(1).replace(/[^\d]/g, '');
    }
    const digits = s.replace(/[^\d]/g, '');
    if (!digits) return '';
    if (digits.length === 11 && digits.startsWith('07')) return '+44' + digits.slice(1);
    if (digits.startsWith('44')) return '+' + digits;
    return '+' + digits;
  };

  const attemptLeaseToken = (opts && typeof opts === 'object' && opts.attemptLeaseToken != null)
    ? String(opts.attemptLeaseToken || '').trim()
    : '';

  const makeScopedCustomString = (id) => {
    const rowId = String(id || '').trim();
    if (!rowId) return '';
    if (!attemptLeaseToken) return rowId;
    return `${rowId}|${attemptLeaseToken}`;
  };

  const patchClaimedRows = async (query, body) => {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/comms_outbox?${query}`, {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return=representation' },
      body: JSON.stringify(body)
    });

    if (!res.ok) {
      const errTxt = await res.text().catch(() => '');
      throw new Error(errTxt || `comms_outbox patch failed (${res.status})`);
    }

    const rows = await res.json().catch(() => []);
    if (Array.isArray(rows)) return rows;
    return rows ? [rows] : [];
  };

  const patchSuccess = async (id, providerMessageId, respJson) => {
    const query =
      `id=eq.${enc(id)}` +
      (attemptLeaseToken ? `&attempt_lease_token=eq.${enc(attemptLeaseToken)}` : '');

    const rows = await patchClaimedRows(query, {
      provider_key: 'CLICKSEND',
      status: 'SENT',
      sent_at: nowIso(),
      provider_message_id: providerMessageId || null,
      provider_response_json: respJson || {},
      last_error: null,
      failed_at: null,
      attempt_lease_token: null,
      attempt_leased_at_utc: null,
      attempt_lease_expires_at_utc: null
    });

    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const patchFailure = async (id, errMsg, respJson) => {
    const query =
      `id=eq.${enc(id)}` +
      (attemptLeaseToken ? `&attempt_lease_token=eq.${enc(attemptLeaseToken)}` : '') +
      `&sent_at=is.null`;

    const rows = await patchClaimedRows(query, {
      provider_key: 'CLICKSEND',
      status: 'FAILED',
      failed_at: nowIso(),
      provider_response_json: respJson || {},
      last_error: String(errMsg || 'FAILED').slice(0, 500),
      attempt_lease_token: null,
      attempt_leased_at_utc: null,
      attempt_lease_expires_at_utc: null
    });

    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  };

  const cfg = isPlainObject(csCfg) ? csCfg : {};

  const username = (env && env.CLICKSEND_API_USERNAME != null) ? String(env.CLICKSEND_API_USERNAME).trim() : '';
  const apiKey = (env && env.CLICKSEND_API_KEY != null) ? String(env.CLICKSEND_API_KEY).trim() : '';
  const baseUrl = ((cfg.base_url != null) ? String(cfg.base_url).trim() : 'https://rest.clicksend.com').replace(/\/+$/, '');
  const smsMax = clampInt(cfg.sms_max_chars, 1, 5000, 1000);
  const batchMax = clampInt(cfg.bulk_send_limit, 1, 20000, 200);

  const report = { sent: 0, failed: 0, errors: [] };

  if (!username || !apiKey) {
    const missingEnv = [];
    if (!username) missingEnv.push('CLICKSEND_API_USERNAME');
    if (!apiKey) missingEnv.push('CLICKSEND_API_KEY');
    const msg = (missingEnv.length === 1) ? `${missingEnv[0]}_MISSING` : 'CLICKSEND_API_CREDENTIALS_MISSING';
    for (const r of (Array.isArray(rows) ? rows : [])) {
      if (!r || !r.id) continue;
      const updatedRow = await patchFailure(r.id, msg, { error: msg }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: r.id, error: msg });
    }
    return report;
  }

  const auth = `Basic ${btoa(`${username}:${apiKey}`)}`;
  const url = `${baseUrl}/v3/sms/send`;

  const slice = (Array.isArray(rows) ? rows : []).slice(0, batchMax);

  const items = [];

  for (const r of slice) {
    const id = r && r.id ? String(r.id) : '';
    const toRaw = r && r.to_address != null ? String(r.to_address) : '';
    let bodyRaw = r && r.message_text != null ? String(r.message_text) : '';

    if (!id) continue;

    const to = normalizeE164(toRaw);
    if (!to) {
      const updatedRow = await patchFailure(id, 'MISSING_TO', { error: 'MISSING_TO' }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'MISSING_TO' });
      continue;
    }

    if (bodyRaw.length > smsMax) bodyRaw = bodyRaw.slice(0, smsMax);

    if (!String(bodyRaw).trim()) {
      const updatedRow = await patchFailure(id, 'EMPTY_MESSAGE', { error: 'EMPTY_MESSAGE' }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id, error: 'EMPTY_MESSAGE' });
      continue;
    }

    const customString = makeScopedCustomString(id);

    items.push({
      id,
      customString,
      message: {
        source: 'cloudtms',
        body: bodyRaw,
        to,
        custom_string: customString
      }
    });
  }

  if (items.length === 0) return report;

  const messages = items.map((item) => item.message);
  const rowIds = items.map((item) => item.id);

  let respText = '';
  let respJson = null;
  let httpOk = false;
  let httpStatus = 0;

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: auth,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ messages })
    });

    httpOk = !!res.ok;
    httpStatus = res.status;
    respText = await res.text().catch(() => '');
    try { respJson = respText ? JSON.parse(respText) : null; } catch { respJson = null; }
  } catch (e) {
    const errMsg = String(e?.message || e || 'CLICKSEND_REQUEST_FAILED');
    for (const item of items) {
      const updatedRow = await patchFailure(item.id, errMsg, { error: errMsg }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: item.id, error: errMsg });
    }
    return report;
  }

  if (!httpOk) {
    const errMsg = `CLICKSEND_HTTP_${httpStatus}`;
    for (const item of items) {
      const updatedRow = await patchFailure(item.id, errMsg, { http_status: httpStatus, body: respText || null }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: item.id, error: errMsg });
    }
    return report;
  }

  const okTop = !!(respJson && typeof respJson === 'object' && String(respJson.response_code || '').toUpperCase() === 'SUCCESS');
  const data = (respJson && typeof respJson === 'object') ? (respJson.data || null) : null;
  const msgsResp = (data && typeof data === 'object' && Array.isArray(data.messages)) ? data.messages : [];

  if (!okTop) {
    const errMsg = (respJson && respJson.response_msg) ? String(respJson.response_msg) : 'CLICKSEND_RESPONSE_NOT_SUCCESS';
    for (const item of items) {
      const updatedRow = await patchFailure(item.id, errMsg, isPlainObject(respJson) ? respJson : { error: errMsg, body: respText || null }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: item.id, error: errMsg });
    }
    return report;
  }

  const byCustom = new Map();
  for (const m of msgsResp) {
    const cs = (m && m.custom_string != null) ? String(m.custom_string) : '';
    if (cs) byCustom.set(cs, m);
  }

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const m = byCustom.get(item.customString) || msgsResp[i] || null;

    const messageId = m && (m.message_id || m.messageId) ? String(m.message_id || m.messageId) : null;
    const status = m && m.status ? String(m.status).toUpperCase() : '';

    if (status && status !== 'SUCCESS' && status !== 'QUEUED') {
      const msg = m && m.status ? `CLICKSEND_${status}` : 'CLICKSEND_MESSAGE_FAILED';
      const updatedRow = await patchFailure(item.id, msg, { clicksend: m, full: respJson }).catch(() => null);
      if (!updatedRow) continue;
      report.failed += 1;
      report.errors.push({ id: item.id, error: msg });
      continue;
    }

    const updatedRow = await patchSuccess(item.id, messageId, { clicksend: m, full: respJson }).catch(() => null);
    if (!updatedRow) continue;
    report.sent += 1;
  }

  return report;
}
