      if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(s)) {
        const parts = s.split(':');
        const hh = pad2(Number(parts[0]) || 0);
        const mm = pad2(Number(parts[1]) || 0);
        return `${hh}:${mm}`;
      }
      return safe(v);
