 async function computeWeeklyAdditionalFromTs(env, ts, cw, contract, policyOverride = null) {
    let additional_units_json = {};
    let additional_pay_ex_vat = 0;
    let additional_charge_ex_vat = 0;

    const cfgArrRaw = contract?.additional_rates_json;
    if (!Array.isArray(cfgArrRaw) || !cfgArrRaw.length) {
      return {
        additional_units_json,
        additional_pay_ex_vat,
        additional_charge_ex_vat,
        additional_margin_ex_vat: 0,
      };
    }

    let cfgArr = cfgArrRaw;
    if (typeof cfgArrRaw === "string") {
      try { cfgArr = JSON.parse(cfgArrRaw); } catch { cfgArr = []; }
    }
    if (!Array.isArray(cfgArr)) cfgArr = [];

    let unitsWeek = ts?.additional_units_week || {};
    let unitsPerDay = ts?.additional_units_per_day || {};
    if (typeof unitsWeek === "string") { try { unitsWeek = JSON.parse(unitsWeek); } catch { unitsWeek = {}; } }
    if (typeof unitsPerDay === "string") { try { unitsPerDay = JSON.parse(unitsPerDay); } catch { unitsPerDay = {}; } }
    if (!unitsWeek || typeof unitsWeek !== "object") unitsWeek = {};
    if (!unitsPerDay || typeof unitsPerDay !== "object") unitsPerDay = {};

    const weekEnd = cw?.week_ending_date || null;
    const dates = [];
    try {
      if (weekEnd) {
        const weDate = new Date(`${weekEnd}T00:00:00Z`);
        for (let i = 6; i >= 0; i--) {
          const d = new Date(weDate);
          d.setUTCDate(weDate.getUTCDate() - i);
          dates.push(toYmd(d));
        }
      }
    } catch {}

    // ✅ Prefer SQL policy bh_list (no REST); fallback to empty set
    const bhList = Array.isArray(policyOverride?.bh_list) ? policyOverride.bh_list : [];
    const bhSet = new Set(bhList.map(String));

    const dow = (ymd) => {
      try { return new Date(`${ymd}T00:00:00Z`).getUTCDay(); } catch { return null; }
    };

    const freqEnum = new Set([
      "ONE_PER_WEEK",
      "ONE_PER_DAY",
      "WEEKENDS_AND_BH_ONLY",
      "WEEKDAYS_EXCL_BH_ONLY",
    ]);

    for (const cfg of cfgArr) {
      if (!cfg || !cfg.code) continue;
      const code = String(cfg.code).toUpperCase();

      const freqRaw = (cfg.frequency || "").toString().toUpperCase();
      const freq = freqEnum.has(freqRaw) ? freqRaw : "ONE_PER_WEEK";

      const weekUnits = Number((unitsWeek && unitsWeek[code]) || 0) || 0;
      const perDayRaw =
        unitsPerDay && typeof unitsPerDay[code] === "object"
          ? unitsPerDay[code]
          : {};

      let unitCount = 0;
      const perDayOut = {};

      if (freq === "ONE_PER_WEEK") {
        unitCount = weekUnits;
      } else {
        for (const ymd of dates) {
          const u = Number(perDayRaw?.[ymd] || 0) || 0;
          if (!u) continue;

          const d = dow(ymd);
          const isBh = bhSet.has(String(ymd));

          let include = false;
          if (freq === "ONE_PER_DAY") include = true;
          else if (freq === "WEEKENDS_AND_BH_ONLY") include = isBh || d === 0 || d === 6;
          else if (freq === "WEEKDAYS_EXCL_BH_ONLY") include = !isBh && d != null && d >= 1 && d <= 5;

          if (!include) continue;
          unitCount += u;
          perDayOut[ymd] = (perDayOut[ymd] || 0) + u;
        }
      }

      if (!unitCount || !Number.isFinite(unitCount) || unitCount <= 0) continue;

      const payRate = Number(cfg.pay_rate ?? 0) || 0;
      const chargeRate = Number(cfg.charge_rate ?? 0) || 0;

      const payEx = round2(unitCount * payRate);
      const chgEx = round2(unitCount * chargeRate);

      additional_units_json[code] = {
        bucket_name: cfg.bucket_name || null,
        unit_name: cfg.unit_name || null,
        frequency: freq,
        unit_count: unitCount,
        pay_rate: payRate,
        charge_rate: chargeRate,
        pay_ex_vat: payEx,
        charge_ex_vat: chgEx,
        days: Object.keys(perDayOut).length ? perDayOut : undefined,
      };

      additional_pay_ex_vat += payEx;
      additional_charge_ex_vat += chgEx;
    }

 additional_pay_ex_vat = round2(additional_pay_ex_vat);
additional_charge_ex_vat = round2(additional_charge_ex_vat);

// ERNI applies based on SQL policyOverride + PAYE
const applyTo = String(policyOverride?.apply_erni_to || 'PAYE_ONLY').toUpperCase();
const erniPctRaw = Number(policyOverride?.erni_pct ?? 0);

let erniMult = 1;
if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
  const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
  erniMult = 1 + p;
}

const payMethodUpper = String(
  (contract?.pay_method_snapshot || contract?.pay_method || '')
).toUpperCase();

const erniApplies =
  (applyTo === 'ALL') ||
  (applyTo === 'PAYE_ONLY' && payMethodUpper === 'PAYE');

const addPayCostEx = round2(erniApplies ? (additional_pay_ex_vat * erniMult) : additional_pay_ex_vat);
const additional_margin_ex_vat = round2(additional_charge_ex_vat - addPayCostEx);

return {
  additional_units_json,
  additional_pay_ex_vat,
  additional_charge_ex_vat,
  additional_margin_ex_vat,
};

  }

async function rpcTsfinRepairMergeSegmentsLocked(env, {
  timesheetId,
  newSegments,
  actorUserId = null,
  correlationId = null
} = {}) {
  const p_timesheet_id = timesheetId ? String(timesheetId).trim() : '';
  if (!p_timesheet_id) throw new Error('rpcTsfinRepairMergeSegmentsLocked: timesheetId is required');

  const p_new_segments = Array.isArray(newSegments) ? newSegments : null;
  if (!p_new_segments) throw new Error('rpcTsfinRepairMergeSegmentsLocked: newSegments must be an array');

  const args = {
    p_timesheet_id,
    p_new_segments
  };
  if (actorUserId != null) args.p_actor_user_id = actorUserId;
  if (correlationId != null) args.p_correlation_id = String(correlationId);

  const unwrapRpcJsonb = (r, fnName) => {
    if (r == null) return null;
    if (Array.isArray(r)) {
      if (r.length === 0) return null;
      if (r.length === 1) {
        const o = r[0];
        if (o && typeof o === 'object' && fnName && Object.prototype.hasOwnProperty.call(o, fnName)) return o[fnName];
        return o;
      }
      return r;
    }
    if (r && typeof r === 'object' && fnName && Object.prototype.hasOwnProperty.call(r, fnName)) {
      return r[fnName];
    }
    return r;
  };

  _tsfinRpcLog('tsfin_repair_merge_segments_locked -> call', { timesheet_id: p_timesheet_id, seg_count: p_new_segments.length });
  try {
    const res = await sbRpc(env, 'tsfin_repair_merge_segments_locked', args);
    const out = unwrapRpcJsonb(res, 'tsfin_repair_merge_segments_locked');
    _tsfinRpcLog('tsfin_repair_merge_segments_locked -> ok', {
      ok: out?.ok === true,
      old_invalid_count: out?.old_invalid_count ?? null,
      new_invalid_count: out?.new_invalid_count ?? null,
      preserved_locked_count: out?.preserved_locked_count ?? null
    });
    return out;
  } catch (e) {
    _tsfinRpcLog('tsfin_repair_merge_segments_locked -> fail', { err: String(e?.message || e) });
    throw e;
  }
}

async function applyWeeklyHealthRosterCrosscheck(env, { import_id }) {
  const enc = encodeURIComponent;
  if (!import_id) return { triples: 0, timesheets_checked: 0 };

  const chunk = (arr, n) => {
    const out = [];
    for (let i = 0; i < (arr?.length || 0); i += n) out.push(arr.slice(i, i + n));
    return out;
  };

  // ─────────────────────────────────────────────
  // Step 1 (FIXED): fetch Phase2 rows for this import (hr_rows table does NOT have client_id/candidate_id/week fields)
  // ─────────────────────────────────────────────
  let p2Rows = [];
  try {
    const res = await fetch(
      `${env.SUPABASE_URL}/rest/v1/rpc/weekly_import_phase2`,
      {
        method: 'POST',
        headers: { ...sbHeaders(env), 'content-type': 'application/json' },
        body: JSON.stringify({ p_import_id: import_id, p_system_type: 'HR_WEEKLY' })
      }
    );
    const txt = await res.text().catch(() => '');
    if (!res.ok) throw new Error(txt || `weekly_import_phase2 ${res.status}`);
    const j = txt ? JSON.parse(txt) : null;
    p2Rows = Array.isArray(j) ? j : [];
  } catch (e) {
    console.warn('[applyWeeklyHealthRosterCrosscheck] weekly_import_phase2 failed', {
      import_id,
      err: e?.message || String(e)
    });
    return { triples: 0, timesheets_checked: 0 };
  }

  const okRows = (p2Rows || []).filter(r => r && String(r.action || '').toUpperCase() === 'OK');
  if (!okRows.length) return { triples: 0, timesheets_checked: 0 };

  // ─────────────────────────────────────────────
  // Step 2: compute distinct (client_id, candidate_id, week_ending_date)
  // ─────────────────────────────────────────────
  const triplesMap = new Map();

  for (const r of okRows) {
    const clientId = r?.client_id ? String(r.client_id) : null;
    const candidateId = r?.candidate_id ? String(r.candidate_id) : null;
    const weekEnd = r?.week_ending_date ? String(r.week_ending_date) : null;
    if (!clientId || !candidateId || !weekEnd) continue;

    const key = `${clientId}__${candidateId}__${weekEnd}`;
    if (!triplesMap.has(key)) {
      triplesMap.set(key, { client_id: clientId, candidate_id: candidateId, week_ending_date: weekEnd });
    }
  }

  if (!triplesMap.size) return { triples: 0, timesheets_checked: 0 };

  // ─────────────────────────────────────────────
  // Step 3: for each triple, run enrichTsfinWithHrCrosscheck on all TSs
  // Batches:
  //   - context via rpcTsfinLoadContextBatch
  //   - nhsp_shifts via SQL RPC tsfin_load_nhsp_shifts_batch
  // ─────────────────────────────────────────────
  let timesheetsChecked = 0;

  for (const triple of triplesMap.values()) {
    const { client_id, candidate_id, week_ending_date } = triple;

    // Find WEEKLY timesheet_ids via v_timesheets_funnel
    let tsIds = [];
    try {
      const { rows: fRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_timesheets_funnel` +
          `?kind=eq.WEEK` +
          `&client_id=eq.${enc(client_id)}` +
          `&candidate_id=eq.${enc(candidate_id)}` +
          `&week_ending_date=eq.${enc(week_ending_date)}` +
          `&select=timesheet_id`
      );

      tsIds = Array.from(new Set((fRows || []).map(r => r?.timesheet_id).filter(Boolean)));
    } catch (e) {
      console.warn('[applyWeeklyHealthRosterCrosscheck] failed to load v_timesheets_funnel', {
        import_id,
        client_id,
        candidate_id,
        week_ending_date,
        err: e?.message || String(e)
      });
      continue;
    }

    if (!tsIds.length) continue;

    // Batch context load (timesheet + current TSFIN + effective flags)
    let ctxRowsAll = [];
    try {
      for (const idsChunk of chunk(tsIds, 50)) {
        const ctxRows = await rpcTsfinLoadContextBatch(env, { timesheetIds: idsChunk });
        if (Array.isArray(ctxRows) && ctxRows.length) ctxRowsAll.push(...ctxRows);
      }
    } catch (e) {
      console.warn('[applyWeeklyHealthRosterCrosscheck] rpcTsfinLoadContextBatch failed', {
        import_id,
        client_id,
        candidate_id,
        week_ending_date,
        err: e?.message || String(e)
      });
      continue;
    }

    if (!ctxRowsAll.length) continue;

    // Batch nhsp_shifts load via SQL RPC (one per chunk)
    const shiftsByTimesheetId = new Map();
    try {
      for (const idsChunk of chunk(tsIds, 50)) {
        const rows = await sbRpc(env, 'tsfin_load_nhsp_shifts_batch', {
          p_timesheet_ids: idsChunk
        });

        for (const r of (rows || [])) {
          const tid = r?.timesheet_id || null;
          if (!tid) continue;
          const shifts = Array.isArray(r?.shifts) ? r.shifts : [];
          shiftsByTimesheetId.set(tid, shifts);
        }
      }
    } catch (e) {
      console.warn('[applyWeeklyHealthRosterCrosscheck] tsfin_load_nhsp_shifts_batch failed', {
        import_id,
        client_id,
        candidate_id,
        week_ending_date,
        err: e?.message || String(e)
      });
      // If shifts batch fails, we still proceed; enrich will fallback to REST fetch.
    }

    // Enrich each ctx row (no per-timesheet context RPC; and shifts provided if we have them)
    for (const ctx of ctxRowsAll) {
      const ts = ctx?.out_timesheet || null;
      const fin = ctx?.out_cur_fin || null;
      const flags = ctx?.out_effective_flags || null;

      if (!ts || !fin) continue;

      const tid = fin?.timesheet_id || ctx?.effective_timesheet_id || null;
      const preloadedShifts = (tid && shiftsByTimesheetId.has(tid)) ? shiftsByTimesheetId.get(tid) : null;

      try {
        await enrichTsfinWithHrCrosscheck(env, ts, fin, flags, preloadedShifts);
        timesheetsChecked++;
      } catch (e) {
        console.warn('[applyWeeklyHealthRosterCrosscheck] enrich failed', {
          import_id,
          timesheet_id: tid,
          tsfin_id: fin?.id || null,
          err: e?.message || String(e)
        });
      }
    }
  }

  return { triples: triplesMap.size, timesheets_checked: timesheetsChecked };
}

async function runTsfinWorkerOnce(env, { limit = 50, onlyTimesheetIds = null } = {}) {
  // Local helpers used by both branches
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const asNumberLocal = (v) => (v == null ? 0 : Number(v) || 0);
  const enc = encodeURIComponent;

  const chunk = (arr, n) => {
    const out = [];
    for (let i = 0; i < (arr?.length || 0); i += n) out.push(arr.slice(i, i + n));
    return out;
  };

  // Helper: derive Mon–Sun week start from a week-ending date (ymd)
  const computeWeekStartFromWeekEnding = (weYmd) => {
    if (!weYmd) return null;
    const d = new Date(`${weYmd}T00:00:00Z`);
    if (Number.isNaN(d.getTime())) return weYmd;
    d.setUTCDate(d.getUTCDate() - 6);
    const yyyy = d.getUTCFullYear();
    const mm   = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd   = String(d.getUTCDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ NEW: No-op TSFIN write guard (1A)
  // If the computed snapshot is identical to the current TSFIN row (for all snapshot keys),
  // DO NOT write a new timesheets_financials row; just mark outbox success.
  // ─────────────────────────────────────────────────────────────
  const _isPlainObj = (v) => !!(v && typeof v === 'object' && !Array.isArray(v) && !(v instanceof Date));

  const _stableCanonical = (v) => {
    if (v === undefined) return null;
    if (v === null) return null;

    if (v instanceof Date) return v.toISOString();

    if (Array.isArray(v)) return v.map(_stableCanonical);

    if (_isPlainObj(v)) {
      const out = {};
      const keys = Object.keys(v).sort();
      for (const k of keys) out[k] = _stableCanonical(v[k]);
      return out;
    }

    // keep primitives as-is
    return v;
  };

  const _stableStringify = (v) => {
    try { return JSON.stringify(_stableCanonical(v)); } catch { return String(v); }
  };

  const _tryParseJson = (s) => {
    if (typeof s !== 'string') return null;
    const t = s.trim();
    if (!t) return null;
    if (!(t.startsWith('{') || t.startsWith('['))) return null;
    try { return JSON.parse(t); } catch { return null; }
  };

  const _coerceLike = (template, actual) => {
    if (template === undefined) return null;

    if (template === null) return (actual == null ? null : actual);

    // Objects/arrays: try to parse JSON strings from DB
    if (Array.isArray(template) || _isPlainObj(template)) {
      if (typeof actual === 'string') {
        const parsed = _tryParseJson(actual);
        return parsed != null ? parsed : actual;
      }
      return actual == null ? null : actual;
    }

    // Numbers: accept numeric strings
    if (typeof template === 'number') {
      if (actual == null) return null;
      const n = (typeof actual === 'number') ? actual : Number(actual);
      return Number.isFinite(n) ? n : null;
    }

    // Booleans: accept string/boolish forms
    if (typeof template === 'boolean') {
      if (actual === true || actual === false) return actual;
      if (actual == null) return false;
      const s = String(actual).trim().toLowerCase();
      return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
    }

    // Strings: stringify
    if (typeof template === 'string') {
      return (actual == null) ? '' : String(actual);
    }

    // Fallback
    return actual == null ? null : actual;
  };

  const _isSnapshotNoop = (snapshot, curFin) => {
    if (!snapshot || typeof snapshot !== 'object') return false;
    if (!curFin || typeof curFin !== 'object') return false;

    const keys = Object.keys(snapshot);
    if (!keys.length) return false;

    const a = {};
    const b = {};

    for (const k of keys) {
      a[k] = snapshot[k];
      b[k] = _coerceLike(snapshot[k], curFin[k]);
    }

    return _stableStringify(a) === _stableStringify(b);
  };

  // ─────────────────────────────────────────────────────────────
  // Weekly helpers (contract-driven)
  // ─────────────────────────────────────────────────────────────

  // ✅ Updated: accepts policyOverride so it never triggers REST in resolveBucketsFromSchedule
  async function computeWeeklyHours(env, ts, contract, policyOverride = null) {
    const zeroHours = { day: 0, night: 0, sat: 0, sun: 0, bh: 0 };

    if (Array.isArray(ts.actual_schedule_json) && ts.actual_schedule_json.length) {
      const minsByBucket = await resolveBucketsFromSchedule(env, contract, ts.actual_schedule_json, policyOverride);
      const hours = {
        day: +(asNumberLocal(minsByBucket.day) / 60).toFixed(2),
        night: +(asNumberLocal(minsByBucket.night) / 60).toFixed(2),
        sat: +(asNumberLocal(minsByBucket.sat) / 60).toFixed(2),
        sun: +(asNumberLocal(minsByBucket.sun) / 60).toFixed(2),
        bh: +(asNumberLocal(minsByBucket.bh) / 60).toFixed(2),
      };
      return hours;
    }

    const scope = String(ts.sheet_scope || "").toUpperCase();
    if (scope === "WEEKLY") return zeroHours;

    const n = (v) => (v == null ? 0 : Number(v) || 0);
    return {
      day: n(ts.hours_day),
      night: n(ts.hours_night),
      sat: n(ts.hours_sat),
      sun: n(ts.hours_sun),
      bh: n(ts.hours_bh),
    };
  }

  // ─────────────────────────────────────────────────────────────
  // DAILY helpers
  // ─────────────────────────────────────────────────────────────
  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  const norm = (s) => String(s || "").trim();
  const normRole = (s) => norm(s).replace(/\s+/g, " ").trim().toUpperCase();
  const normBand = (v) => {
    const s = norm(v);
    if (!s) return null;
    let m = s.match(/^\s*band\s*([0-9]+)\s*$/i);
    if (!m) m = s.match(/^\s*b\s*([0-9]+)\s*$/i);
    if (!m) m = s.match(/^\s*([0-9]+)\s*$/);
    if (m && m[1]) return `Band ${parseInt(m[1], 10)}`;
    return s;
  };

  const parseCandidateRoleCodes = (rolesVal) => {
    try {
      let roles = rolesVal;
      if (typeof roles === "string") roles = JSON.parse(roles);
      if (!Array.isArray(roles)) return [];
      return roles
        .map((r) => (r && typeof r === "object" ? r.code : r))
        .map((c) => normRole(c))
        .filter(Boolean);
    } catch {
      return [];
    }
  };

  const anyMissingRatesLocal = (usedBuckets, pay, charge) => {
    const u = usedBuckets || {};
    const p = pay || {};
    const c = charge || {};
    const used = (x) => (Number(x || 0) > 0);
    return (
      (used(u.day)   && (p.day   == null || c.day   == null)) ||
      (used(u.night) && (p.night == null || c.night == null)) ||
      (used(u.sat)   && (p.sat   == null || c.sat   == null)) ||
      (used(u.sun)   && (p.sun   == null || c.sun   == null)) ||
      (used(u.bh)    && (p.bh    == null || c.bh    == null))
    );
  };

  // ─────────────────────────────────────────────────────────────
  // Worker core (SQL-driven dequeue + context + rate batch + batch write)
  // ─────────────────────────────────────────────────────────────

  // 1) Lease outbox rows
  let lease = [];
  if (Array.isArray(onlyTimesheetIds) && onlyTimesheetIds.length) {
    const rows = await rpcTsfinDequeueSpecific(env, { timesheetIds: onlyTimesheetIds, limit });
    lease = (rows || []).map(r => ({
      outbox_id: r.id,
      timesheet_id: r.timesheet_id,
      reason: r.reason
    }));
  } else {
    lease = await rpcTsfinDequeueBatchIds(env, { limit });
  }

  if (!Array.isArray(lease) || !lease.length) return { picked: 0, ok: 0, fail: 0 };

  // ✅ NEW (logging only): map outbox_id -> reason for invoice_debug gating (no functional impact)
  const reasonByOutboxId = new Map();
  try {
    for (const it of (lease || [])) {
      const ob = it?.outbox_id != null ? String(it.outbox_id) : '';
      if (!ob) continue;
      const rs = it?.reason != null ? String(it.reason) : '';
      if (rs) reasonByOutboxId.set(ob, rs);
    }
  } catch {}

  // 2) Map original timesheet_id -> effective/current timesheet_id
  const origIds = [...new Set(lease.map(x => String(x.timesheet_id)).filter(Boolean))];

  let origToCurrent = new Map();
  try {
    const inIds = origIds.map(enc).join(',');
    const { rows: tsRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=in.(${inIds})` +
        `&select=timesheet_id,booking_id,is_current,version,updated_at,created_at`
    );

    const bookingIds = [...new Set((tsRows || []).map(r => r.booking_id).filter(Boolean))];
    const bookingToBest = new Map();

    if (bookingIds.length) {
      const inBookings = bookingIds.map(enc).join(',');
      const { rows: allRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?booking_id=in.(${inBookings})` +
          `&select=booking_id,timesheet_id,is_current,version,updated_at,created_at`
      );

      const byBooking = new Map();
      for (const r of (allRows || [])) {
        const bid = r?.booking_id ? String(r.booking_id) : '';
        const tid = r?.timesheet_id ? String(r.timesheet_id) : '';
        if (!bid || !tid) continue;
        if (!byBooking.has(bid)) byBooking.set(bid, []);
        byBooking.get(bid).push(r);
      }

      for (const [bid, arr] of byBooking.entries()) {
        const rows = Array.isArray(arr) ? arr.slice() : [];
        const currents = rows.filter(x => x && x.is_current === true);
        const pool = currents.length ? currents : rows;

        pool.sort((a, b) => {
          const va = Number(a?.version || 0) || 0;
          const vb = Number(b?.version || 0) || 0;
          if (vb !== va) return vb - va;

          const ua = a?.updated_at ? new Date(a.updated_at).getTime() : 0;
          const ub = b?.updated_at ? new Date(b.updated_at).getTime() : 0;
          if (ub !== ua) return ub - ua;

          const ca = a?.created_at ? new Date(a.created_at).getTime() : 0;
          const cb = b?.created_at ? new Date(b.created_at).getTime() : 0;
          return cb - ca;
        });

        const best = pool[0];
        if (best?.timesheet_id) bookingToBest.set(String(bid), String(best.timesheet_id));
      }
    }

    for (const r of (tsRows || [])) {
      const tid = String(r?.timesheet_id || '');
      if (!tid) continue;
      const bid = r?.booking_id ? String(r.booking_id) : '';
      const best = (bid && bookingToBest.get(bid)) ? bookingToBest.get(bid) : tid;
      origToCurrent.set(tid, best);
    }
  } catch {
    for (const id of origIds) origToCurrent.set(String(id), String(id));
  }

  // 3) Group outbox rows by effective timesheet_id (dedupe)
  const effToOutboxIds = new Map();
  const effToPrimary = new Map();
  const effIds = [];

  for (const it of lease) {
    const orig = String(it.timesheet_id || '');
    const eff = origToCurrent.get(orig) || orig;
    if (!eff) continue;

    if (!effToOutboxIds.has(eff)) effToOutboxIds.set(eff, []);
    effToOutboxIds.get(eff).push(it.outbox_id);

    if (!effToPrimary.has(eff)) {
      effToPrimary.set(eff, it.outbox_id);
      effIds.push(eff);
    }
  }

  // 4) Load batch context for effective IDs (one RPC)
  const ctxRows2 = await rpcTsfinLoadContextBatch(env, { timesheetIds: effIds });
  const ctxByEff = new Map();
  for (const r of (ctxRows2 || [])) {
    const eid = String(r?.effective_timesheet_id || '');
    if (!eid) continue;
    ctxByEff.set(eid, r);
  }

  let ok = 0, fail = 0;

  const preFailPrimaryOutboxSet = new Set();
  const weeklyWork = [];
  const dailyItemsForRates = [];
  const dailyWork = [];

  // 5) First pass: collect WEEKLY + DAILY work
  for (const effId of effIds) {
    const outboxIds = effToOutboxIds.get(effId) || [];
    const primaryOutboxId = effToPrimary.get(effId) || outboxIds[0] || null;

    const ctx = ctxByEff.get(effId) || null;
    if (!ctx) {
      for (const ob of outboxIds) {
        try {
          await sbRpc(env, "tsfin_mark_revoked", { p_timesheet_id: effId });
          await sbRpc(env, "tsfin_work_success", { p_id: ob });
          ok++;
        } catch (e) {
          await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: String(e?.message || e) });
          fail++;
        }
      }
      continue;
    }

    const ts = ctx.out_timesheet || null;
    const curFin = ctx.out_cur_fin || null;
    const effFlags = ctx.out_effective_flags || null;

    const isLocked = !!(curFin?.locked_by_invoice_id || curFin?.paid_at_utc);
    if (isLocked) {
      for (const ob of outboxIds) {
        try { await sbRpc(env, "tsfin_work_success", { p_id: ob }); ok++; } catch { fail++; }
      }
      continue;
    }

    const scope = String(ts?.sheet_scope || '').toUpperCase();

    if (scope === 'WEEKLY') {
      try {
        const basis = String(curFin?.basis || '').toUpperCase();
        const routeType = String(effFlags?.route_type || '').toUpperCase();

        const isNhspRoute =
          (routeType === 'WEEKLY_NHSP' || routeType === 'WEEKLY_NHSP_ADJUSTMENT' || boolish(effFlags?.client_is_nhsp));

        const isHrRoute =
          (routeType === 'WEEKLY_HEALTHROSTER' || boolish(effFlags?.client_autoprocess_hr));

        const isNhspBasis = isNhspRoute || (basis === 'NHSP' || basis === 'NHSP_ADJUSTMENT');
        const isHrBasis = isHrRoute || (
          basis === 'HEALTHROSTER_SELF_BILL' ||
          basis === 'HEALTHROSTER_SELF_BILL_ADJUSTMENT' ||
          basis === 'HEALTHROSTER_ADJUSTMENT' ||
          basis === 'HEALTHROSTER_WEEKLY' ||
          basis === 'HEALTHROSTER_WEEKLY_ADJUSTMENT'
        );

        weeklyWork.push({
          effId: String(effId),
          outbox_id: primaryOutboxId,
          extra_outbox_ids: outboxIds.filter(x => x !== primaryOutboxId),
          ts,
          curFin,
          effFlags,
          policySql: (ctx.out_policy || null),
          routeType,
          basis,
          isNhspRoute,
          isHrRoute,
          isNhspBasis,
          isHrBasis,
          cw: null,
          contract: null,
        });
      } catch (e) {
        for (const ob of outboxIds) {
          await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: String(e?.message || e) });
          fail++;
        }
      }
      continue;
    }

    // DAILY / ROTA batch path
    try {
      const candidate = ctx.out_candidate || null;
      const candidate_id = candidate?.id || null;
      const candidate_assignment = candidate_id ? 'ASSIGNED' : 'UNASSIGNED';

      const client_id = ctx.out_client_id || null;
      const workedDateYmd = ts?.worked_start_iso ? (toLocalParts(ts.worked_start_iso, null)?.ymd || null) : null;
      const policy = ctx.out_policy || {};

      const candidateRoleCodes = parseCandidateRoleCodes(candidate?.roles);
      const tsRoleRaw = norm(ts?.job_title_norm || '');
      const tsRole = tsRoleRaw ? normRole(tsRoleRaw) : null;
      const tsBand = normBand(ts?.band);

      let roleForRates = null;
      if (candidate_id) {
        if (tsRole && candidateRoleCodes.includes(tsRole)) {
          roleForRates = tsRole;
        } else {
          roleForRates = null;
        }
      } else {
        roleForRates = tsRole;
      }

      const bandForRates = tsBand || null;

      let rate_type = 'UMBRELLA';
      const pm = String(candidate?.pay_method || '').toUpperCase();
      if (pm === 'PAYE' || pm === 'UMBRELLA') rate_type = pm;

      dailyItemsForRates.push({
        k: String(effId),
        candidate_id: candidate_id || null,
        client_id: client_id || null,
        role: roleForRates || null,
        band: bandForRates || null,
        date: workedDateYmd || null,
        rate_type
      });

      dailyWork.push({
        effId: String(effId),
        outbox_id: primaryOutboxId,
        extra_outbox_ids: outboxIds.filter(x => x !== primaryOutboxId),
        ts,
        curFin, // ✅ allow no-op compare for daily too
        ctx,
        policy,
        candidate,
        candidate_id,
        candidate_assignment,
        client_id,
        workedDateYmd,
        roleForRates,
        bandForRates,
        rate_type,
        isAuthorised: !!ts?.authorised_at_server
      });
    } catch (e) {
      for (const ob of outboxIds) {
        await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: String(e?.message || e) });
        fail++;
      }
    }
  }

  // WEEKLY: batch-load contract_week + contract in ONE RPC
  try {
    const wkIds = [...new Set(weeklyWork.map(w => String(w?.ts?.timesheet_id || '')).filter(Boolean))];

    if (wkIds.length) {
      const wkRows = await sbRpc(env, 'tsfin_load_weekly_context_batch', { p_timesheet_ids: wkIds });

      const wkByTsId = new Map();
      for (const r of (wkRows || [])) {
        const tid = r?.timesheet_id ? String(r.timesheet_id) : '';
        if (!tid) continue;
        wkByTsId.set(tid, r);
      }

      for (const w of weeklyWork) {
        const tid = String(w?.ts?.timesheet_id || '');
        const row = tid ? (wkByTsId.get(tid) || null) : null;
        w.cw = row?.out_cw || null;
        w.contract = row?.out_contract || null;
      }
    }
  } catch (e) {
    try { console.warn('[TSFIN][WEEKLY_CTX_BATCH] failed', { err: e?.message || String(e) }); } catch {}
  }

  // WEEKLY: batch-load nhsp_shifts ONCE for all weekly timesheets
  let shiftsByTsId = new Map();
  try {
    const weeklyTsIds = [...new Set(
      weeklyWork.map(w => w?.ts?.timesheet_id).filter(Boolean).map(x => String(x))
    )];

    if (weeklyTsIds.length) {
      const rows = await sbRpc(env, 'tsfin_load_nhsp_shifts_batch', { p_timesheet_ids: weeklyTsIds });
      for (const r of (rows || [])) {
        const tid = r?.timesheet_id ? String(r.timesheet_id) : null;
        if (!tid) continue;
        let arr = r?.shifts;
        if (typeof arr === 'string') {
          try { arr = JSON.parse(arr); } catch { arr = []; }
        }
        if (!Array.isArray(arr)) arr = [];
        shiftsByTsId.set(tid, arr);
      }
    }
  } catch {
    shiftsByTsId = new Map();
  }

  // ✅ NEW: WEEKLY batch-load timesheet_validations so we only apply import refs once HR validation is OK
  let weeklyValidationByTsId = new Map();
  try {
    const weeklyTsIds = [...new Set(
      weeklyWork.map(w => w?.ts?.timesheet_id).filter(Boolean).map(x => String(x))
    )];

    if (weeklyTsIds.length) {
      const inTs = weeklyTsIds.map(enc).join(',');
      const { rows: vRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheet_validations` +
          `?timesheet_id=in.(${inTs})` +
          `&select=timesheet_id,status,reason_code,validated_at_utc,updated_at`
      );

      for (const vr of (vRows || [])) {
        const tid = vr?.timesheet_id ? String(vr.timesheet_id) : '';
        if (!tid) continue;
        weeklyValidationByTsId.set(tid, {
          status: vr?.status != null ? String(vr.status) : null,
          reason_code: vr?.reason_code != null ? String(vr.reason_code) : null,
          validated_at_utc: vr?.validated_at_utc ?? null,
          updated_at: vr?.updated_at ?? null
        });
      }
    }
  } catch {
    weeklyValidationByTsId = new Map();
  }

  // 6) Resolve rates in one RPC for all DAILY items
  const ratesRows = await rpcTsfinResolveRatesBatch(env, { items: dailyItemsForRates });
  const ratesByK = new Map();
  for (const r of (ratesRows || [])) {
    const k = String(r?.k || '');
    if (!k) continue;
    ratesByK.set(k, r);
  }

  // 7) Build WEEKLY + DAILY snapshots, then batch-write ONCE
  const rowsToWriteAll = [];

  // --- WEEKLY snapshots ---
  for (const w of weeklyWork) {
    const {
      outbox_id,
      extra_outbox_ids,
      ts,
      curFin,
      effFlags,
      cw,
      contract,
      routeType,
      basis,
      isNhspRoute,
      isHrRoute,
      isNhspBasis,
      isHrBasis,
      policySql
    } = w;

    if (!outbox_id) {
      for (const ob of [outbox_id, ...(extra_outbox_ids || [])].filter(Boolean)) {
        await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: "NO_OUTBOX_ID" });
        fail++;
      }
      continue;
    }

    if (!cw || !contract) {
      const reason = 'WEEKLY_CTX_MISSING_CW_OR_CONTRACT';
      for (const ob of [outbox_id, ...(extra_outbox_ids || [])].filter(Boolean)) {
        await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: reason });
        fail++;
      }
      continue;
    }

    try {
      const tsid = ts?.timesheet_id ? String(ts.timesheet_id) : null;
      const preloadedShifts = tsid ? (shiftsByTsId.get(tsid) || []) : [];
      const hasImportedShifts = Array.isArray(preloadedShifts) && preloadedShifts.length > 0;

      const val = tsid ? (weeklyValidationByTsId.get(tsid) || null) : null;

      const weeklyOptions = {
        policy_override: policySql || null,
        hr_eff_flags: effFlags || null,
        hr_preloaded_shifts: preloadedShifts,

        // ✅ NEW: validation state (so ref_num can be overridden ONLY after validation OK)
        hr_validation_status: val?.status || null,
        hr_validation_reason_code: val?.reason_code || null,

        outbox_id,
        write_now: false
      };

      // ✅ FIX (correction model):
      const corrKindU = String(ts?.correction_kind || '').trim().toUpperCase();
      const adjOriginU = String(ts?.adjustment_origin || '').trim().toUpperCase();
      const isCorrectionTs =
        !!corrKindU ||
        adjOriginU === 'IMPORT_CORRECTION' ||
        adjOriginU === 'IMPORT_CANCELLATION';

      let buildRes = null;

      if (isCorrectionTs) {
        buildRes = await buildWeeklyScheduleSegmentsSnapshot(
          env,
          ts,
          cw,
          contract,
          curFin,
          weeklyOptions
        );
      } else if (hasImportedShifts && (isNhspRoute || isHrRoute || isNhspBasis || isHrBasis)) {
        const routeU = String(routeType || '').toUpperCase();
        const basisU = String(basis || '').toUpperCase();

        const basisForBuild =
          (isHrRoute || isHrBasis)
            ? ((basisU && basisU.startsWith('HEALTHROSTER')) ? basisU : 'HEALTHROSTER_SELF_BILL')
            : ((routeU === 'WEEKLY_NHSP_ADJUSTMENT' || basisU === 'NHSP_ADJUSTMENT') ? 'NHSP_ADJUSTMENT' : 'NHSP');

        const getPolicyFn =
          (policySql && typeof policySql === 'object')
            ? (_clientId, _date) => policySql
            : (typeof getPolicyCached === 'function' ? getPolicyCached : async () => null);

        buildRes = await buildNhspWeeklySnapshotCached(
          env,
          ts,
          contract,
          preloadedShifts,
          curFin?.nhsp_import_id || null,
          basisForBuild,
          getPolicyFn,
          curFin,
          weeklyOptions
        );
      } else if (isNhspBasis) {
        buildRes = await rebuildFromExistingSegmentsEvidence(
          env,
          ts,
          cw,
          contract,
          curFin,
          weeklyOptions
        );
      } else if (isHrBasis) {
        buildRes = await rebuildFromExistingSegmentsEvidence(
          env,
          ts,
          cw,
          contract,
          curFin,
          weeklyOptions
        );
      } else {
        buildRes = await buildWeeklyScheduleSegmentsSnapshot(
          env,
          ts,
          cw,
          contract,
          curFin,
          weeklyOptions
        );
      }

      if (!buildRes || buildRes.ok !== true || !buildRes.snapshot) {
        const reason = buildRes?.reason ? String(buildRes.reason) : 'WEEKLY_BUILD_FAILED';
        for (const ob of [outbox_id, ...(extra_outbox_ids || [])].filter(Boolean)) {
          await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: reason });
          fail++;
        }
        continue;
      }

      const snapshot = buildRes.snapshot;

      if (snapshot && snapshot.occupant_key_norm == null && ts?.occupant_key_norm != null) {
        snapshot.occupant_key_norm = ts.occupant_key_norm;
      }

      // ✅ NEW (logging only): invoice_debug-gated audit for SEGMENTS recompute attempts (no functional impact)
      try {
        const ibBefore = curFin?.invoice_breakdown_json || null;
        const modeBefore = String(ibBefore?.mode || '').toUpperCase();
        const segsBefore = Array.isArray(ibBefore?.segments) ? ibBefore.segments : null;

        const ibAfter = snapshot?.invoice_breakdown_json || null;
        const modeAfter = String(ibAfter?.mode || '').toUpperCase();
        const segsAfter = Array.isArray(ibAfter?.segments) ? ibAfter.segments : null;

        if (modeAfter === 'SEGMENTS' && Array.isArray(segsAfter)) {
          let lockedBefore = 0, unlockedBefore = 0;
          let lockedAfter = 0, unlockedAfter = 0;

          const oldUnlockedShiftIds = new Set();
          const newUnlockedShiftIds = new Set();

          if (modeBefore === 'SEGMENTS' && Array.isArray(segsBefore)) {
            for (const s of segsBefore) {
              const lockId = String(s?.invoice_locked_invoice_id || '').trim();
              const isLockedSeg = !!lockId;
              if (isLockedSeg) lockedBefore++; else unlockedBefore++;
              if (!isLockedSeg) {
                const sid = String(s?.nhsp_shift_id || '').trim();
                if (sid) oldUnlockedShiftIds.add(sid);
              }
            }
          }

          for (const s of segsAfter) {
            const lockId = String(s?.invoice_locked_invoice_id || '').trim();
            const isLockedSeg = !!lockId;
            if (isLockedSeg) lockedAfter++; else unlockedAfter++;
            if (!isLockedSeg) {
              const sid = String(s?.nhsp_shift_id || '').trim();
              if (sid) newUnlockedShiftIds.add(sid);
            }
          }

          const removed = [];
          for (const sid of oldUnlockedShiftIds) {
            if (!newUnlockedShiftIds.has(sid)) {
              removed.push(sid);
              if (removed.length >= 20) break;
            }
          }

          const staleU = String(curFin?.stale_reason || '').trim().toUpperCase();
          const reasonU = String(reasonByOutboxId.get(String(outbox_id)) || '').trim().toUpperCase();

          const shouldLog =
            (lockedBefore > 0 || lockedAfter > 0) ||
            (staleU === 'IMPORT_CANCEL_DETACH') ||
            (reasonU.includes('IMPORT_'));

          if (shouldLog) {
            await sbRpc(env, "_imp_debug_audit", {
              p_actor_user_id: null,
              p_action: "TSFIN_SEGMENTS_RECOMPUTE_DEBUG",
              p_after_json: {
                timesheet_id: String(ts?.timesheet_id || ''),
                outbox_id: String(outbox_id || ''),
                locked_before_count: lockedBefore,
                locked_after_count: lockedAfter,
                unlocked_before_count: unlockedBefore,
                unlocked_after_count: unlockedAfter,
                removed_unlocked_nhsp_shift_ids: removed,
                used_locked_merge: (lockedBefore > 0 || lockedAfter > 0)
              },
              p_entity: "timesheets_financials",
              p_subject_id: String(ts?.timesheet_id || ''),
              p_before_json: null,
              p_ip: null,
              p_user_agent: null,
              p_correlation_id: outbox_id ? `tsfin_recompute:${String(outbox_id)}` : null
            });
          }
        }
      } catch {}

      // Enrich HR cross-check BEFORE write (mutates snapshot)
      try {
        await enrichTsfinWithHrCrosscheck(env, ts, snapshot, effFlags || null, preloadedShifts);
      } catch {}

      // Self-heal locked segments (unchanged)
      try {
        const curIb0 = curFin?.invoice_breakdown_json || null;
        const curMode0 = String(curIb0?.mode || '').toUpperCase();
        const curSegs0 = Array.isArray(curIb0?.segments) ? curIb0.segments : null;

        let invalidSegCount0 = 0;
        let lockedSegCount0 = 0;

        if (curMode0 === 'SEGMENTS' && Array.isArray(curSegs0)) {
          for (const s0 of curSegs0) {
            const isObj0 = !!(s0 && typeof s0 === 'object' && !Array.isArray(s0));
            const segId0 = isObj0 ? String(s0.segment_id || '').trim() : '';
            if (!isObj0 || !segId0) {
              invalidSegCount0++;
              continue;
            }
            const lockId0 = String(s0.invoice_locked_invoice_id || '').trim();
            if (lockId0) lockedSegCount0++;
          }
        }

        const needsHeal0 = (invalidSegCount0 > 0 && lockedSegCount0 > 0);

        if (needsHeal0) {
          const newSegs0 = snapshot?.invoice_breakdown_json?.segments;
          const healRes0 = await rpcTsfinRepairMergeSegmentsLocked(env, {
            timesheetId: ts.timesheet_id,
            newSegments: Array.isArray(newSegs0) ? newSegs0 : [],
            actorUserId: null,
            correlationId: outbox_id ? `tsfin_selfheal:${String(outbox_id)}` : null
          });

          const okHeal0 =
            !!(healRes0 && typeof healRes0 === 'object' && healRes0.ok === true && Number(healRes0.new_invalid_count || 0) === 0);

          if (okHeal0) {
            await sbRpc(env, "tsfin_work_success", { p_id: outbox_id });
            ok++;
            continue;
          } else {
            const errMsg0 =
              (healRes0 && typeof healRes0 === 'object' && healRes0.error) ? String(healRes0.error) :
              'TSFIN_SELFHEAL_MERGE_FAILED';

            for (const ob0 of [outbox_id, ...(extra_outbox_ids || [])].filter(Boolean)) {
              await sbRpc(env, "tsfin_work_fail", { p_id: ob0, p_error: errMsg0 });
              fail++;
            }
            preFailPrimaryOutboxSet.add(String(outbox_id));
            continue;
          }
        }
      } catch (e0) {
        const errMsg0 = `TSFIN_SELFHEAL_ERROR:${String(e0?.message || e0)}`;
        for (const ob0 of [outbox_id, ...(extra_outbox_ids || [])].filter(Boolean)) {
          await sbRpc(env, "tsfin_work_fail", { p_id: ob0, p_error: errMsg0 });
          fail++;
        }
        preFailPrimaryOutboxSet.add(String(outbox_id));
        continue;
      }

      // ✅ NEW: no-op write optimisation (skip DB write if identical)
      if (_isSnapshotNoop(snapshot, curFin)) {
        try {
          await sbRpc(env, "tsfin_work_success", { p_id: outbox_id });
          ok++;
        } catch (e) {
          await sbRpc(env, "tsfin_work_fail", { p_id: outbox_id, p_error: String(e?.message || e) });
          fail++;
        }
        continue;
      }

      rowsToWriteAll.push({
        outbox_id,
        timesheet_id: ts.timesheet_id,
        snapshot
      });
    } catch (e) {
      for (const ob of [outbox_id, ...(extra_outbox_ids || [])].filter(Boolean)) {
        await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: String(e?.message || e) });
        fail++;
      }
    }
  }

  // --- DAILY snapshots (UPDATED: uses batch fields hr_validation_required_for_invoice + validation_status; no per-timesheet queries) ---
  for (const w of dailyWork) {
    const { effId, outbox_id, ts, policy, candidate, candidate_id, client_id, isAuthorised, curFin } = w;

    try {
      const r = ratesByK.get(String(effId)) || null;

      const pay = {
        day:   r?.pay_day   ?? null,
        night: r?.pay_night ?? null,
        sat:   r?.pay_sat   ?? null,
        sun:   r?.pay_sun   ?? null,
        bh:    r?.pay_bh    ?? null
      };
      const charge = {
        day:   r?.charge_day   ?? null,
        night: r?.charge_night ?? null,
        sat:   r?.charge_sat   ?? null,
        sun:   r?.charge_sun   ?? null,
        bh:    r?.charge_bh    ?? null
      };

      let segments = [];
      if (ts.worked_start_iso && ts.worked_end_iso) segments.push([ts.worked_start_iso, ts.worked_end_iso]);

      segments = subtractBreak(
        segments,
        ts.break_start_iso || null,
        ts.break_end_iso   || null,
        ts.break_minutes   || null
      );

      const hours = classifyMinutes(env, policy, segments);

      const missingRates = anyMissingRatesLocal(
        {
          day:   hours.hours_day,
          night: hours.hours_night,
          sat:   hours.hours_sat,
          sun:   hours.hours_sun,
          bh:    hours.hours_bh,
        },
        pay,
        charge
      );

      const effFlags = w.ctx?.out_effective_flags || null;

      // ✅ NEW: authoritative invoice gating inputs from batch context (no REST)
      const hrValidationRequiredForInvoice =
        effFlags && Object.prototype.hasOwnProperty.call(effFlags, 'hr_validation_required_for_invoice')
          ? boolish(effFlags.hr_validation_required_for_invoice)
          : false;

      const validationStatusU =
        (effFlags && Object.prototype.hasOwnProperty.call(effFlags, 'validation_status') && effFlags.validation_status != null)
          ? String(effFlags.validation_status).toUpperCase()
          : '';

      const validationOk = (validationStatusU === 'VALIDATION_OK' || validationStatusU === 'OVERRIDDEN');
      const mustHoldForHrValidation = (hrValidationRequiredForInvoice && !validationOk);

      // ✅ NEW: unsigned QR truth model (priority over unauthorised)
      const qrStatusU = String(ts?.qr_status || '').toUpperCase();
      const qrToken = (ts?.qr_token != null) ? String(ts.qr_token).trim() : '';
      const hasQrIssuedProof = (
        ((qrToken && !!ts?.qr_generated_at) === true) ||
        ((ts?.qr_last_sent_hash != null) && String(ts.qr_last_sent_hash).trim() !== '')
      );
      const qrAwaitingSignatureUpload = (
        qrStatusU === 'PENDING' &&
        hasQrIssuedProof &&
        !ts?.qr_scanned_at
      );

      const pay_method =
        String(candidate?.pay_method || '').toUpperCase() === 'PAYE' ? 'PAYE'
        : String(candidate?.pay_method || '').toUpperCase() === 'UMBRELLA' ? 'UMBRELLA'
        : (ts.pay_method || null);

      let payChannelBad = false;
      try {
        if (candidate_id && client_id && typeof resolveEffectivePayChannel === 'function') {
          const umbrella = w.ctx?.out_umbrella || null;
          const channel = resolveEffectivePayChannel({
            pay_method: pay_method || candidate?.pay_method || null,
            candidate,
            umbrella,
          });
          payChannelBad = !channel || channel.ok === false;
        }
      } catch {
        payChannelBad = true;
      }

      let processing_status;
      let hasRateIssue = false;
      let hasPayChannelIssue = false;

      // Hard blockers first, then authoritative status ladder:
      if (!candidate_id) {
        processing_status = "UNASSIGNED";
      } else if (!client_id) {
        processing_status = "CLIENT_UNRESOLVED";
      } else if (missingRates) {
        processing_status = "RATE_MISSING";
        hasRateIssue = true;
        hasPayChannelIssue = !!payChannelBad;
      } else if (payChannelBad) {
        processing_status = "PAY_CHANNEL_MISSING";
        hasPayChannelIssue = true;
      } else if (qrAwaitingSignatureUpload) {
        processing_status = "AWAITING_MANUAL_SIGNATURE";
      } else if (!isAuthorised) {
        processing_status = "PENDING_AUTH";
      } else if (mustHoldForHrValidation) {
        processing_status = "READY_FOR_HR";
      } else {
        processing_status = "READY_FOR_INVOICE";
      }

      const total_pay_ex_vat = round2(
        hours.hours_day   * asNumberLocal(pay.day)   +
        hours.hours_night * asNumberLocal(pay.night) +
        hours.hours_sat   * asNumberLocal(pay.sat)   +
        hours.hours_sun   * asNumberLocal(pay.sun)   +
        hours.hours_bh    * asNumberLocal(pay.bh)
      );

      const total_charge_ex_vat = round2(
        hours.hours_day   * asNumberLocal(charge.day)   +
        hours.hours_night * asNumberLocal(charge.night) +
        hours.hours_sat   * asNumberLocal(charge.sat)   +
        hours.hours_sun   * asNumberLocal(charge.sun)   +
        hours.hours_bh    * asNumberLocal(charge.bh)
      );

      const applyTo = String(policy?.apply_erni_to || 'PAYE_ONLY').toUpperCase();
      const erniPctRaw = Number(policy?.erni_pct ?? 0);
      let erniMult = 1;
      if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
        const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
        erniMult = 1 + p;
      }

      const erniApplies =
        (applyTo === 'ALL') ||
        (applyTo === 'PAYE_ONLY' && String(pay_method || '').toUpperCase() === 'PAYE');

      const payCostEx = round2(erniApplies ? (total_pay_ex_vat * erniMult) : total_pay_ex_vat);
      const margin_ex_vat = round2(total_charge_ex_vat - payCostEx);

      const invoice_breakdown_json = {
        mode: "AGGREGATE",
        base_hours: {
          day:   hours.hours_day,
          night: hours.hours_night,
          sat:   hours.hours_sat,
          sun:   hours.hours_sun,
          bh:    hours.hours_bh,
          pay_rates: {
            day:   pay.day,
            night: pay.night,
            sat:   pay.sat,
            sun:   pay.sun,
            bh:    pay.bh,
          },
          charge_rates: {
            day:   charge.day,
            night: charge.night,
            sat:   charge.sat,
            sun:   charge.sun,
            bh:    charge.bh,
          },
          pay_ex_vat:    total_pay_ex_vat,
          charge_ex_vat: total_charge_ex_vat,
        },
        additional: { units: {}, pay_ex_vat: 0, charge_ex_vat: 0, margin_ex_vat: 0 },
        totals: { total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat },
      };

      const rate_source_refs_json = {
        kind: r?.source_kind || 'NONE',
        override_id: r?.override_id || null,
        default_id: r?.default_id || null,
        rate_type: r?.rate_type || w.rate_type || null
      };

      const snapshot = {
        timesheet_id: ts.timesheet_id,
        timesheet_version: ts.version || 1,
        basis: "SELF_REPORTED",

        occupant_key_norm: ts.occupant_key_norm || null,
        worked_start_iso: ts.worked_start_iso || null,
        worked_end_iso:   ts.worked_end_iso   || null,
        break_start_iso:  ts.break_start_iso  || null,
        break_end_iso:    ts.break_end_iso    || null,
        break_minutes:    ts.break_minutes    || null,

        candidate_id,
        client_id: client_id || null,

        role: w.roleForRates || null,
        band: w.bandForRates || null,

        pay_method,

        policy_snapshot_json: policy || {},
        rate_source_refs_json,

        hours_day:   hours.hours_day,
        hours_night: hours.hours_night,
        hours_sat:   hours.hours_sat,
        hours_sun:   hours.hours_sun,
        hours_bh:    hours.hours_bh,

        pay_day:      pay.day,
        pay_night:    pay.night,
        pay_sat:      pay.sat,
        pay_sun:      pay.sun,
        pay_bh:       pay.bh,
        charge_day:   charge.day,
        charge_night: charge.night,
        charge_sat:   charge.sat,
        charge_sun:   charge.sun,
        charge_bh:    charge.bh,

        total_hours: round2(
          hours.hours_day +
          hours.hours_night +
          hours.hours_sat +
          hours.hours_sun +
          hours.hours_bh
        ),
        total_pay_ex_vat,
        total_charge_ex_vat,
        margin_ex_vat,

        additional_units_json: {},
        additional_pay_ex_vat: 0,
        additional_charge_ex_vat: 0,
        additional_margin_ex_vat: 0,

        pay_wtr_rate_pct_snapshot: null,
        candidate_assignment: w.candidate_assignment,
        processing_status,

        has_rate_issue:        !!hasRateIssue,
        has_pay_channel_issue: !!hasPayChannelIssue,

        invoice_breakdown_json,
      };

      // ✅ NEW: no-op write optimisation for daily too
      if (_isSnapshotNoop(snapshot, curFin)) {
        try {
          await sbRpc(env, "tsfin_work_success", { p_id: outbox_id });
          ok++;
        } catch (e) {
          await sbRpc(env, "tsfin_work_fail", { p_id: outbox_id, p_error: String(e?.message || e) });
          fail++;
        }
        continue;
      }

      rowsToWriteAll.push({
        outbox_id,
        timesheet_id: ts.timesheet_id,
        snapshot
      });
    } catch (e) {
      const allObs = [w.outbox_id, ...(w.extra_outbox_ids || [])].filter(Boolean);
      for (const ob of allObs) {
        await sbRpc(env, "tsfin_work_fail", { p_id: ob, p_error: String(e?.message || e) });
        fail++;
      }
    }
  }

  // 8) One batch write for WEEKLY + DAILY
  let wr = null;
  let failOutboxSet = new Set();

  if (rowsToWriteAll.length) {
    wr = await rpcTsfinWriteSnapshotsAndComplete(env, { rows: rowsToWriteAll });

    ok += Number(wr?.ok_count || 0) || 0;
    fail += Number(wr?.fail_count || 0) || 0;

    try {
      let errs = wr?.errors;
      if (typeof errs === 'string') {
        try { errs = JSON.parse(errs); } catch { errs = null; }
      }
      if (Array.isArray(errs)) {
        for (const e of errs) {
          const ob = e?.outbox_id ? String(e.outbox_id) : '';
          if (ob) failOutboxSet.add(ob);
        }
      }
    } catch {
      failOutboxSet = new Set();
    }
  }

  // Bulk-clear duplicate outbox rows ONLY if primary succeeded
  const extrasToClear = [];

  for (const w of weeklyWork) {
    const p = String(w?.outbox_id || '');
    if (!p) continue;
    if (failOutboxSet.has(p)) continue;
    if (preFailPrimaryOutboxSet.has(p)) continue;
    for (const ob of (w.extra_outbox_ids || [])) {
      if (ob) extrasToClear.push(ob);
    }
  }

  for (const w of dailyWork) {
    const p = String(w?.outbox_id || '');
    if (!p) continue;
    if (failOutboxSet.has(p)) continue;
    if (preFailPrimaryOutboxSet.has(p)) continue;
    for (const ob of (w.extra_outbox_ids || [])) {
      if (ob) extrasToClear.push(ob);
    }
  }

  if (extrasToClear.length) {
    for (const idsChunk of chunk(extrasToClear, 200)) {
      try {
        const cleared = await sbRpc(env, 'tsfin_work_success_bulk', { p_ids: idsChunk });
        ok += Number(cleared || 0) || 0;
      } catch {
        // best-effort only
      }
    }
  }

  return { picked: lease.length, ok, fail, write: wr };
}
async function handleTimesheetAuthoriseGeneric(env, req, timesheetId) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  let body;
  try { body = await parseJSONBody(req); }
  catch { return withCORS(env, req, badRequest('Invalid JSON')); }

  const expectedTimesheetId = body?.expected_timesheet_id || null;
  const guard = await guardCurrentTimesheetWrite(env, req, timesheetId, expectedTimesheetId);
  if (!guard.ok) return guard.res;

  const currentTimesheetId = guard.resolved.current_timesheet_id;
  const now = nowIso();

  const warnings = [];

  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  const hasAnySegmentInvoiceLock = (tf) => {
    try {
      const ib = tf?.invoice_breakdown_json;
      if (!ib || typeof ib !== 'object') return false;
      const mode = String(ib?.mode || '').toUpperCase();
      if (mode !== 'SEGMENTS') return false;
      const segs = Array.isArray(ib?.segments) ? ib.segments : [];
      return segs.some(s => {
        const v = s?.invoice_locked_invoice_id;
        return v != null && String(v).trim() !== '';
      });
    } catch {
      return false;
    }
  };

  // Load current TS + TSFIN
  const tsBefore = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=` +
        [
          'timesheet_id',
          'contract_id',
          'authorised_at_server',
          'submission_mode',
          'sheet_scope',
          'week_ending_date',
          'worked_start_iso',
          'worked_end_iso',
          'break_start_iso',
          'break_end_iso',
          'break_minutes',
          'reference_number',
          'day_references_json',
          'actual_schedule_json',
          'additional_units_week',
          'additional_units_per_day',
          'qr_status',
          'qr_token',
          'qr_generated_at',
          'qr_last_sent_hash',
          'qr_signed_hash',
          'qr_signed_at_utc',
          'qr_scanned_at',
          'version',
          'status'
        ].join(','),
  ).catch(() => null);

  const { rows: finRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=id,client_id,basis,processing_status,locked_by_invoice_id,paid_at_utc,invoice_breakdown_json` +
      `&limit=1`
  );
  const fin = finRows?.[0] || null;

  const finBeforeStatus = String(fin?.processing_status || '').toUpperCase();
  let finAfterStatus = fin?.processing_status || null;

  if (!fin) {
    return withCORS(env, req, badRequest('Cannot authorise: no financial snapshot exists for this timesheet'));
  }

  if (fin.locked_by_invoice_id || fin.paid_at_utc || hasAnySegmentInvoiceLock(fin)) {
    return withCORS(env, req, badRequest('Cannot authorise: timesheet is locked or paid'));
  }

  const qrStatusU = String(tsBefore?.qr_status || '').toUpperCase();
  const qrToken = (tsBefore?.qr_token != null) ? String(tsBefore.qr_token).trim() : '';
  const hasQrIssuedProof = (
    ((qrToken && !!tsBefore?.qr_generated_at) === true) ||
    ((tsBefore?.qr_last_sent_hash != null) && String(tsBefore.qr_last_sent_hash).trim() !== '')
  );
  const qrAwaitingSignatureUpload = (
    qrStatusU === 'PENDING' &&
    hasQrIssuedProof &&
    !tsBefore?.qr_scanned_at
  );

  // ✅ NEW RULE: unsigned QR cannot be authorised
  if (qrAwaitingSignatureUpload || finBeforeStatus === 'AWAITING_MANUAL_SIGNATURE') {
    return withCORS(env, req, badRequest('Cannot authorise: awaiting signed QR timesheet'));
  }

  // ✅ NEW: warn if invoice-precheck is blocked by missing timesheet PDF/evidence
  // (not a blocker to authorise; invoicing will be blocked until evidence is attached)
  try {
    const { rows: pRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/v_ts_invoice_precheck` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&select=precheck_status` +
        `&limit=1`
    );
    const ps = (pRows?.[0]?.precheck_status != null) ? String(pRows[0].precheck_status).trim().toUpperCase() : '';
    if (ps === 'BLOCK_NO_PDF') {
      warnings.push('NO_TIMESHEET_EVIDENCE_INVOICE_BLOCKED');
    }
  } catch {
    // non-fatal
  }

  // Signed QR stale check (unchanged)
  try {
    const signedHash = (tsBefore?.qr_signed_hash != null) ? String(tsBefore.qr_signed_hash).trim() : '';
    const hasSignedHash = !!signedHash;

    if (hasSignedHash) {
      const scope = String(tsBefore?.sheet_scope || '').toUpperCase();

      const stableClone = (v) => {
        if (Array.isArray(v)) return v.map(stableClone);
        if (v && typeof v === 'object') {
          const out = {};
          for (const k of Object.keys(v).sort()) out[k] = stableClone(v[k]);
          return out;
        }
        return v;
      };

      const currentObj = (scope === 'WEEKLY')
        ? {
            sheet_scope: 'WEEKLY',
            week_ending_date: tsBefore?.week_ending_date || null,
            actual_schedule_json: tsBefore?.actual_schedule_json || null,
            reference_number: tsBefore?.reference_number || null,
            day_references_json: tsBefore?.day_references_json || null,
            additional_units_week: tsBefore?.additional_units_week || {},
            additional_units_per_day: tsBefore?.additional_units_per_day || {}
          }
        : {
            sheet_scope: 'DAILY',
            worked_start_iso: tsBefore?.worked_start_iso || null,
            worked_end_iso: tsBefore?.worked_end_iso || null,
            break_start_iso: tsBefore?.break_start_iso || null,
            break_end_iso: tsBefore?.break_end_iso || null,
            break_minutes: (tsBefore?.break_minutes != null ? tsBefore.break_minutes : null),
            reference_number: tsBefore?.reference_number || null,
            day_references_json: tsBefore?.day_references_json || null
          };

      const currentHash = await sha256Hex(JSON.stringify(stableClone(currentObj)));

      if (String(currentHash) !== String(signedHash)) {
        return withCORS(env, req, badRequest('Cannot authorise: signed QR timesheet no longer matches current hours (revoke and request resubmission)'));
      }
    }
  } catch (e) {
    return withCORS(env, req, serverError(`Failed to validate QR signed hash: ${e?.message || e}`));
  }

  // Stamp timesheet authorised (best effort)
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTimesheetId)}&is_current=eq.true`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
      body: JSON.stringify({ authorised_at_server: now, updated_at: now })
    }
  ).catch(() => {});

  const basisU = String(fin?.basis || '').toUpperCase();
  const forceReadyForInvoice =
    (basisU === 'NHSP' ||
     basisU === 'NHSP_ADJUSTMENT' ||
     basisU === 'HEALTHROSTER_SELF_BILL' ||
     basisU === 'HEALTHROSTER_ADJUSTMENT');

  // Fetch policy switch + validation status from v_timesheets_summary_base
  let eff = null;
  try {
    const { rows: eRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary_base` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&select=client_requires_hr,hr_validation_required_for_invoice,validation_status` +
        `&limit=1`
    );
    eff = eRows?.[0] || null;
  } catch {
    eff = null;
  }

  // Fetch pre_validated from timesheet_validations (separate fetch; view may not expose it)
  let validationPreValidated = false;
  try {
    const { rows: pvRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheet_validations` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&select=pre_validated` +
        `&limit=1`
    );
    validationPreValidated = boolish(pvRows?.[0]?.pre_validated);
  } catch {
    validationPreValidated = false;
  }

  const requiresHr = eff ? boolish(eff.client_requires_hr) : false;

  const hrValidationRequiredForInvoice = eff ? boolish(eff.hr_validation_required_for_invoice) : false;
  const validationStatus = (eff?.validation_status != null) ? String(eff.validation_status).toUpperCase() : '';
  const validationOk = (validationStatus === 'VALIDATION_OK' || validationStatus === 'OVERRIDDEN');

  // ✅ HR validation requirement blocks READY_FOR_INVOICE until OK/OVERRIDDEN
  const mustHoldForHrValidation = (hrValidationRequiredForInvoice && !validationOk);

  let newStatus = fin.processing_status;
  const ps = finBeforeStatus;

  if (ps === 'PENDING_AUTH' || ps === 'READY_FOR_HR') {
    if (mustHoldForHrValidation) {
      newStatus = 'READY_FOR_HR';
    } else {
      // ✅ Pre-validated + OK => straight to READY_FOR_INVOICE (even if requiresHr)
      const preValidatedFastTrack = (validationPreValidated && validationOk);

      newStatus = forceReadyForInvoice
        ? 'READY_FOR_INVOICE'
        : (preValidatedFastTrack ? 'READY_FOR_INVOICE' : (requiresHr ? 'READY_FOR_HR' : 'READY_FOR_INVOICE'));
    }
  }

  finAfterStatus = newStatus;

  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(fin.id)}`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return=minimal' },
      body: JSON.stringify({
        processing_status: newStatus,
        authorised_by_user_id: user.id,
        authorised_at_utc: now,
        updated_at: now
      })
    }
  ).catch(() => {});

  // Audit (kept)
  try {
    const wasAlreadyAuthorised = !!(tsBefore && tsBefore.authorised_at_server);
    const didPromoteStatus = String(finBeforeStatus || '') !== String(finAfterStatus || '').toUpperCase();

    if (!wasAlreadyAuthorised || didPromoteStatus) {
      await writeAudit(
        env,
        user,
        'TIMESHEET_AUTHORISED',
        {
          timesheet_id: currentTimesheetId,
          authorised_at_utc: now,
          tsfin_processing_status_before: finBeforeStatus || null,
          tsfin_processing_status_after: finAfterStatus ? String(finAfterStatus).toUpperCase() : null,
          hr_validation_required_for_invoice: hrValidationRequiredForInvoice,
          validation_status: validationStatus || null,
          validation_pre_validated: validationPreValidated,
          warnings: warnings.length ? warnings : null
        },
        {
          entity: 'timesheets',
          subject_id: currentTimesheetId,
          req,
          before: {
            authorised_at_server: tsBefore?.authorised_at_server || null,
            tsfin_processing_status: finBeforeStatus || null
          },
          reason: didPromoteStatus ? 'PROMOTED_TSFIN_STATUS' : 'STAMPED_AUTHORISE'
        }
      );
    }
  } catch {}

  return withCORS(env, req, ok({
    authorised: true,
    tsfin_updated: true,
    processing_status: newStatus,
    warnings,
    booking_id: guard.resolved.booking_id || null,
    requested_timesheet_id: guard.resolved.requested_timesheet_id || timesheetId,
    current_timesheet_id: currentTimesheetId,
    current_version: guard.resolved.current_version ?? null,
    was_stale: !!guard.resolved.was_stale
  }));
}

async function handleContractWeekManualAuthorise(env, req, weekId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  const enc = encodeURIComponent;

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }

  const expected = body?.expected_timesheet_id ? String(body.expected_timesheet_id) : '';
  if (!expected) return withCORS(env, req, badRequest('expected_timesheet_id is required'));

  const warnings = [];

  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  let cw = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}&select=id,contract_id,timesheet_id`
  );
  if (!cw?.id) return withCORS(env, req, notFound('Week not found'));

  let linkedTimesheetId = cw?.timesheet_id ? String(cw.timesheet_id) : '';
  let repairedLinkageFromExpected = false;

  // ✅ stale-resolution path: re-read the week once in case FE just created the timesheet
  if (!linkedTimesheetId) {
    const cwReload = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}&select=id,contract_id,timesheet_id`
    ).catch(() => null);

    if (cwReload?.id) {
      cw = cwReload;
      linkedTimesheetId = cwReload?.timesheet_id ? String(cwReload.timesheet_id) : '';
    }
  }

  // ✅ stale-resolution path: if the week still has no linked timesheet, try the FE expected/current id
  if (!linkedTimesheetId && expected) {
    const resolvedExpected = await resolveTimesheetToCurrent(env, expected).catch(() => null);
    const expectedCurrentTimesheetId =
      resolvedExpected?.current_timesheet_id ? String(resolvedExpected.current_timesheet_id) : '';

    if (expectedCurrentTimesheetId) {
      const expectedTsRow = await sbGetOne(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheets` +
          `?timesheet_id=eq.${enc(expectedCurrentTimesheetId)}` +
          `&is_current=eq.true` +
          `&select=timesheet_id,contract_id`
      ).catch(() => null);

      const contractMatches =
        !!expectedTsRow &&
        (
          !cw?.contract_id ||
          !expectedTsRow?.contract_id ||
          String(expectedTsRow.contract_id) === String(cw.contract_id)
        );

      if (contractMatches) {
        linkedTimesheetId = expectedCurrentTimesheetId;
        repairedLinkageFromExpected = true;
      }
    }
  }

  if (!linkedTimesheetId) {
    return withCORS(
      env,
      req,
      new Response(
        JSON.stringify({
          error: 'TIMESHEET_NOT_LINKED_YET',
          contract_week_id: weekId,
          current_timesheet_id: null,
          expected_timesheet_id: expected || null
        }),
        {
          status: 409,
          headers: { 'Content-Type': 'application/json' }
        }
      )
    );
  }

  // Resolve + guard
  const resolved = await resolveTimesheetToCurrent(env, linkedTimesheetId);
  const currentTimesheetId = resolved?.current_timesheet_id ? String(resolved.current_timesheet_id) : '';
  if (!currentTimesheetId) return withCORS(env, req, notFound('Timesheet not found'));

  if (String(expected) !== String(currentTimesheetId)) {
    return withCORS(
      env,
      req,
      new Response(JSON.stringify({ error: 'TIMESHEET_MOVED', current_timesheet_id: currentTimesheetId }), {
        status: 409,
        headers: { 'Content-Type': 'application/json' }
      })
    );
  }

  const now = nowIso();

  // ✅ heal week linkage if we recovered via expected/current id
  if (repairedLinkageFromExpected && String(cw?.timesheet_id || '') !== String(currentTimesheetId)) {
    await fetch(
      `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({
          timesheet_id: currentTimesheetId,
          updated_at: now
        })
      }
    ).catch(() => {});
  }

  // Load CURRENT TS + TSFIN (include QR fields for unsigned gating)
  const tsBefore = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=timesheet_id,contract_id,authorised_at_server,submission_mode,sheet_scope,version,status,qr_status,qr_token,qr_generated_at,qr_last_sent_hash,qr_scanned_at`
  ).catch(() => null);

  const { rows: finRows } = await sbFetch(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
      `?timesheet_id=eq.${enc(currentTimesheetId)}` +
      `&is_current=eq.true` +
      `&select=id,client_id,basis,processing_status,locked_by_invoice_id,paid_at_utc`
  );
  const fin = finRows?.[0] || null;

  const finBeforeStatus = String(fin?.processing_status || '').toUpperCase();
  let finAfterStatus = fin?.processing_status || null;

  const qrStatusU = String(tsBefore?.qr_status || '').toUpperCase();
  const qrToken = (tsBefore?.qr_token != null) ? String(tsBefore.qr_token).trim() : '';
  const hasQrIssuedProof = (
    ((qrToken && !!tsBefore?.qr_generated_at) === true) ||
    ((tsBefore?.qr_last_sent_hash != null) && String(tsBefore.qr_last_sent_hash).trim() !== '')
  );
  const qrAwaitingSignatureUpload = (
    qrStatusU === 'PENDING' &&
    hasQrIssuedProof &&
    !tsBefore?.qr_scanned_at
  );

  // ✅ NEW RULE: unsigned QR cannot be authorised
  if (qrAwaitingSignatureUpload || finBeforeStatus === 'AWAITING_MANUAL_SIGNATURE') {
    return withCORS(env, req, badRequest('Cannot authorise: awaiting signed QR timesheet'));
  }

  // ✅ NEW: warn if invoice-precheck is blocked by missing timesheet PDF/evidence
  // (not a blocker to authorise; invoicing will be blocked until evidence is attached)
  try {
    const { rows: pRows } = await sbFetch(
      env,
      `${env.SUPABASE_URL}/rest/v1/v_ts_invoice_precheck` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&select=precheck_status` +
        `&limit=1`
    );
    const ps0 = (pRows?.[0]?.precheck_status != null) ? String(pRows[0].precheck_status).trim().toUpperCase() : '';
    if (ps0 === 'BLOCK_NO_PDF') {
      warnings.push('NO_TIMESHEET_EVIDENCE_INVOICE_BLOCKED');
    }
  } catch {
    // non-fatal
  }

  if (fin) {
    const ps = finBeforeStatus;

    if (fin.locked_by_invoice_id || fin.paid_at_utc) {
      return withCORS(env, req, badRequest('Cannot authorise: timesheet is locked or paid'));
    }

    // Policy B bases: authorise must unlock invoicing directly (unless HR validation hold)
    const basisU = String(fin?.basis || '').toUpperCase();
    const forceReadyForInvoice =
      (basisU === 'NHSP' ||
       basisU === 'NHSP_ADJUSTMENT' ||
       basisU === 'HEALTHROSTER_SELF_BILL' ||
       basisU === 'HEALTHROSTER_ADJUSTMENT');

    // Effective flags from v_timesheets_summary_base (required for validation gating)
    let eff = null;
    try {
      const { rows: eRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary_base` +
          `?timesheet_id=eq.${enc(currentTimesheetId)}` +
          `&select=client_requires_hr,hr_validation_required_for_invoice,validation_status` +
          `&limit=1`
      );
      eff = eRows?.[0] || null;
    } catch {
      eff = null;
    }

    // pre_validated from timesheet_validations
    let validationPreValidated = false;
    try {
      const { rows: pvRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/timesheet_validations` +
          `?timesheet_id=eq.${enc(currentTimesheetId)}` +
          `&select=pre_validated` +
          `&limit=1`
      );
      validationPreValidated = boolish(pvRows?.[0]?.pre_validated);
    } catch {
      validationPreValidated = false;
    }

    const requiresHr = eff ? boolish(eff.client_requires_hr) : false;

    const hrValidationRequiredForInvoice = eff ? boolish(eff.hr_validation_required_for_invoice) : false;
    const validationStatus = (eff?.validation_status != null) ? String(eff.validation_status).toUpperCase() : '';
    const validationOk = (validationStatus === 'VALIDATION_OK' || validationStatus === 'OVERRIDDEN');
    const mustHoldForHrValidation = (hrValidationRequiredForInvoice && !validationOk);

    let newStatus = fin.processing_status;

    if (ps === 'PENDING_AUTH' || ps === 'READY_FOR_HR') {
      if (mustHoldForHrValidation) {
        newStatus = 'READY_FOR_HR';
      } else {
        const preValidatedFastTrack = (validationPreValidated && validationOk);
        newStatus = forceReadyForInvoice
          ? 'READY_FOR_INVOICE'
          : (preValidatedFastTrack ? 'READY_FOR_INVOICE' : (requiresHr ? 'READY_FOR_HR' : 'READY_FOR_INVOICE'));
      }
    }

    finAfterStatus = newStatus;

    await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(fin.id)}&is_current=eq.true`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({
          processing_status: newStatus,
          authorised_by_user_id: user.id,
          authorised_at_utc: now,
          updated_at: now
        })
      }
    ).catch(() => {});
  }

  // Stamp timesheet as authorised (CURRENT only)
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(currentTimesheetId)}&is_current=eq.true`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
      body: JSON.stringify({ authorised_at_server: now, updated_at: now })
    }
  ).catch(() => {});

  // Update week status → AUTHORISED
  await fetch(
    `${env.SUPABASE_URL}/rest/v1/contract_weeks?id=eq.${enc(weekId)}`,
    {
      method: 'PATCH',
      headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
      body: JSON.stringify({ status: 'AUTHORISED', updated_at: now })
    }
  ).catch(() => {});

  // Audit
  try {
    const wasAlreadyAuthorised = !!(tsBefore && tsBefore.authorised_at_server);
    const didPromoteStatus = !!(finAfterStatus && String(finBeforeStatus || '') !== String(finAfterStatus || ''));

    if (!wasAlreadyAuthorised || didPromoteStatus) {
      await writeAudit(
        env,
        user,
        'TIMESHEET_AUTHORISED',
        {
          timesheet_id: currentTimesheetId,
          contract_week_id: weekId,
          authorised_at_utc: now,
          tsfin_processing_status_before: finBeforeStatus || null,
          tsfin_processing_status_after: finAfterStatus ? String(finAfterStatus).toUpperCase() : null,
          warnings: warnings.length ? warnings : null
        },
        {
          entity: 'timesheets',
          subject_id: currentTimesheetId,
          req,
          before: {
            authorised_at_server: tsBefore?.authorised_at_server || null,
            tsfin_processing_status: finBeforeStatus || null
          },
          reason: didPromoteStatus ? 'PROMOTED_TSFIN_STATUS' : 'STAMPED_AUTHORISE'
        }
      );
    }
  } catch {}

  return withCORS(env, req, ok({
    authorised: true,
    timesheet_id: currentTimesheetId,
    contract_week_id: weekId,
    linkage_repaired_from_expected: repairedLinkageFromExpected,
    warnings
  }));
}


async function handleTimesheetQrScan(env, req) {
  const enc = encodeURIComponent;

  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());

  let body;
  try {
    body = await parseJSONBody(req);
  } catch {
    return withCORS(env, req, badRequest('Invalid JSON'));
  }

  const qrText = String(body?.qr_text || '').trim();
  const image_r2_key_raw = body?.image_r2_key ? String(body.image_r2_key) : '';

  if (!qrText) {
    return withCORS(env, req, badRequest('qr_text is required'));
  }

  // ✅ For signed acceptance, we require the uploaded scan key.
  // This endpoint is the “signed upload/scan acceptance” endpoint.
  const cleanKey = (k) => String(k || '').replace(/^\/+/, '').trim();
  const image_r2_key = cleanKey(image_r2_key_raw);
  if (!image_r2_key) {
    return withCORS(env, req, badRequest('image_r2_key is required'));
  }

  try {
    console.log('[QR][SCAN] incoming', {
      preview: qrText.slice(0, 64) + (qrText.length > 64 ? '…' : '')
    });
  } catch {}

  // 1) Verify signature + parse payload
  const verification = await verifyTsq1(qrText, env);
  if (!verification?.ok) {
    return withCORS(env, req, badRequest(`Invalid QR: ${verification?.reason || 'UNKNOWN'}`));
  }

  const p = verification.payload || {};
  const payloadToken = (p && typeof p.tok === 'string') ? p.tok.trim() : '';

  // ✅ New minimal TSQ1 payload is { v, tok } only
  if (!payloadToken) {
    return withCORS(env, req, badRequest('Invalid QR: missing tok'));
  }

  // 2) Resolve timesheet by token (NOT by timesheet_id in payload anymore)
  const ts = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/timesheets` +
      `?qr_token=eq.${enc(payloadToken)}` +
      `&is_current=eq.true` +
      `&select=*` +
      `&limit=1`
  );

  if (!ts) {
    return withCORS(env, req, notFound('Timesheet not found for QR token'));
  }

  const sheetScope = String(ts.sheet_scope || '').toUpperCase();
  const wasAuthorisedAlready = !!ts.authorised_at_server;

  const qrStatusNow = String(ts.qr_status || '').toUpperCase();
  if (qrStatusNow !== 'PENDING') {
    if (qrStatusNow === 'USED')      return withCORS(env, req, badRequest('QR already used'));
    if (qrStatusNow === 'CANCELLED') return withCORS(env, req, badRequest('QR cancelled; a new QR must be issued'));
    if (qrStatusNow === 'EXPIRED')   return withCORS(env, req, badRequest('QR expired; a new QR must be issued'));
    return withCORS(env, req, badRequest(`QR invalid state (qr_status=${qrStatusNow || 'NULL'})`));
  }

  // 3) Token enforcement (reissue invalidation)
  const tsToken = ts.qr_token ? String(ts.qr_token) : '';
  if (!tsToken) {
    return withCORS(env, req, badRequest('Timesheet has no active QR token; cannot accept scan'));
  }
  if (String(payloadToken) !== String(tsToken)) {
    return withCORS(env, req, badRequest('QR token is no longer valid for this timesheet'));
  }

  const now = nowIso();

  // Helpers for stable hashing (shared basis across send/resend/evidence)
  const stableClone = (v) => {
    if (Array.isArray(v)) return v.map(stableClone);
    if (v && typeof v === 'object') {
      const out = {};
      for (const k of Object.keys(v).sort()) out[k] = stableClone(v[k]);
      return out;
    }
    return v;
  };

  const computeCurrentHash = async (sheetScopeU, tsRow, finRow) => {
    if (sheetScopeU === 'WEEKLY') {
      const obj = {
        sheet_scope: 'WEEKLY',
        week_ending_date: tsRow.week_ending_date || null,
        actual_schedule_json: tsRow.actual_schedule_json || null,
        reference_number: tsRow.reference_number || null,
        day_references_json: tsRow.day_references_json || null,
        additional_units_week: tsRow.additional_units_week || {},
        additional_units_per_day: tsRow.additional_units_per_day || {}
      };
      return await sha256Hex(JSON.stringify(stableClone(obj)));
    }

    // DAILY
    const obj = {
      sheet_scope: 'DAILY',
      worked_start_iso: tsRow.worked_start_iso || null,
      worked_end_iso: tsRow.worked_end_iso || null,
      break_start_iso: tsRow.break_start_iso || null,
      break_end_iso: tsRow.break_end_iso || null,
      break_minutes: (tsRow.break_minutes != null ? tsRow.break_minutes : null),
      reference_number: tsRow.reference_number || null,
      day_references_json: tsRow.day_references_json || null
    };
    return await sha256Hex(JSON.stringify(stableClone(obj)));
  };

  // ✅ Canonical deterministic PDF key (the “one PDF only” rule)
  const canonicalPdfKey = cleanKey(`docs-pdf/timesheets/ts_${ts.timesheet_id}.pdf`);

  // ✅ Step A: Copy the uploaded signed scan OVER the canonical key (overwrite).
  // Do NOT patch DB if this fails.
  try {
    await r2CopyOverwrite(env, image_r2_key, canonicalPdfKey);
  } catch (e) {
    console.warn('[QR][SCAN] failed to copy signed scan to canonical key', {
      timesheet_id: ts.timesheet_id,
      from: image_r2_key,
      to: canonicalPdfKey,
      err: e?.message || String(e)
    });
    return withCORS(env, req, serverError(`Failed to store signed scan: ${e?.message || e}`));
  }

  // Helper to resolve next TSFIN status when scan completes
  const computeNextStatusAfterScan = async (tsId) => {
    if (!wasAuthorisedAlready) return 'PENDING_AUTH';

    // If authorised already, promote to READY_FOR_INVOICE unless HR validation requires hold
    let eff = null;
    try {
      const { rows: eRows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/v_timesheets_summary_base` +
          `?timesheet_id=eq.${enc(tsId)}` +
          `&select=hr_validation_required_for_invoice,validation_status` +
          `&limit=1`
      );
      eff = eRows?.[0] || null;
    } catch {
      eff = null;
    }

    const boolishLocal = (v) => {
      if (v === true) return true;
      if (v === false) return false;
      if (v == null) return false;
      const s = String(v).trim().toLowerCase();
      return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
    };

    const hrValidationRequiredForInvoice = eff ? boolishLocal(eff.hr_validation_required_for_invoice) : false;
    const validationStatus = (eff?.validation_status != null) ? String(eff.validation_status).toUpperCase() : '';
    const validationOk = (validationStatus === 'VALIDATION_OK' || validationStatus === 'OVERRIDDEN');

    if (hrValidationRequiredForInvoice && !validationOk) return 'READY_FOR_HR';
    return 'READY_FOR_INVOICE';
  };

  // ─────────────────────────────────────────────────────────────
  // WEEKLY
  // ─────────────────────────────────────────────────────────────
  if (sheetScope === 'WEEKLY') {
    const cw = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
        `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
        `&select=*` +
        `&limit=1`
    ).catch(() => null);

    const contract = ts.contract_id
      ? await sbGetOne(
          env,
          `${env.SUPABASE_URL}/rest/v1/contracts` +
            `?id=eq.${enc(ts.contract_id)}` +
            `&select=*` +
            `&limit=1`
        )
      : null;

    if (!contract) return withCORS(env, req, notFound('Contract not found for QR'));

    const fin = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
        `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
        `&is_current=eq.true` +
        `&select=*`
    );
    if (!fin) return withCORS(env, req, serverError('No financial snapshot for timesheet'));

    if (fin.locked_by_invoice_id || fin.paid_at_utc) {
      return withCORS(env, req, badRequest('Timesheet already invoiced or paid; cannot process QR scan'));
    }

    const finStatus = String(fin.processing_status || '').toUpperCase();
    if (finStatus !== 'AWAITING_MANUAL_SIGNATURE') {
      return withCORS(
        env,
        req,
        badRequest(`Unexpected processing_status=${fin.processing_status}; expected AWAITING_MANUAL_SIGNATURE`)
      );
    }

    // ✅ Compute signed hash at acceptance time
    let signedHash = null;
    try {
      signedHash = await computeCurrentHash('WEEKLY', ts, fin);
    } catch (e) {
      return withCORS(env, req, serverError(`Failed to compute signed hash: ${e?.message || e}`));
    }

    // ✅ Patch timesheet: point manual_pdf_r2_key to the CANONICAL key (not image_r2_key)
    const tsPatch = {
      qr_status: 'USED',
      qr_scanned_at: now,
      qr_signed_hash: signedHash,
      qr_signed_at_utc: now,
      manual_pdf_r2_key: canonicalPdfKey,
      qr_scan_info_json: {
        kind: 'WEEKLY_QR_TIMESHEET',
        payload: p,
        original_image_r2_key: image_r2_key,
        canonical_pdf_r2_key: canonicalPdfKey
      },
      updated_at: now
    };

    const tsRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(ts.timesheet_id)}&is_current=eq.true`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify(tsPatch)
      }
    );

    if (!tsRes.ok) {
      const t = await tsRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to patch timesheet after QR scan: ${t}`));
    }

    const nextStatus = await computeNextStatusAfterScan(ts.timesheet_id);

    const finRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(fin.id)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({ processing_status: nextStatus, updated_at: now })
      }
    );

    if (!finRes.ok) {
      const t = await finRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to update TSFIN after QR scan: ${t}`));
    }

    // ✅ Best-effort delete original uploaded key (only if it differs from canonical)
    try {
      const bucket = env.R2_BUCKET || env.R2;
      if (bucket && typeof bucket.delete === 'function' && image_r2_key !== canonicalPdfKey) {
        await bucket.delete(image_r2_key);
      }
    } catch (e) {
      console.warn('[QR_WEEKLY][SCAN] delete original image key failed (non-fatal)', {
        timesheet_id: ts.timesheet_id,
        original_image_r2_key: image_r2_key,
        err: e?.message || String(e)
      });
    }

    try {
      await writeAudit(
        env,
        user,
        'WEEKLY_QR_SCANNED',
        {
          timesheet_id: ts.timesheet_id,
          contract_week_id: cw?.id || null,
          contract_id: contract.id,
          qr_text: qrText,
          qr_payload: p,

          // record both keys explicitly
          original_image_r2_key: image_r2_key,
          canonical_pdf_r2_key: canonicalPdfKey,

          processing_status_from: fin.processing_status,
          processing_status_to: nextStatus,
          qr_signed_hash: signedHash
        },
        { entity: 'timesheets', subject_id: ts.timesheet_id, req }
      );
    } catch (e) {
      console.warn('[QR_WEEKLY][SCAN] audit failed', e?.message || e);
    }

    return withCORS(env, req, ok({
      timesheet_id: ts.timesheet_id,
      contract_week_id: cw?.id || null,
      contract_id: contract.id,
      candidate_id: contract.candidate_id || null,
      client_id: contract.client_id || null,
      week_ending_date: cw?.week_ending_date || ts.week_ending_date || null,
      sheet_scope: 'WEEKLY',
      processing_status: nextStatus,
      qr_status: 'USED',

      // keep old field for caller compatibility
      image_r2_key,

      // new: explicit canonical key
      canonical_pdf_r2_key: canonicalPdfKey
    }));
  }

  // ─────────────────────────────────────────────────────────────
  // DAILY
  // ─────────────────────────────────────────────────────────────
  if (sheetScope === 'DAILY') {
    const fin = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
        `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
        `&is_current=eq.true` +
        `&select=*`
    );
    if (!fin) return withCORS(env, req, serverError('No financial snapshot for timesheet'));

    if (fin.locked_by_invoice_id || fin.paid_at_utc) {
      return withCORS(env, req, badRequest('Timesheet already invoiced or paid; cannot process QR scan'));
    }

    const finStatus = String(fin.processing_status || '').toUpperCase();
    if (finStatus !== 'AWAITING_MANUAL_SIGNATURE') {
      return withCORS(
        env,
        req,
        badRequest(`Unexpected processing_status=${fin.processing_status}; expected AWAITING_MANUAL_SIGNATURE`)
      );
    }

    // ✅ Compute signed hash at acceptance time
    let signedHash = null;
    try {
      signedHash = await computeCurrentHash('DAILY', ts, fin);
    } catch (e) {
      return withCORS(env, req, serverError(`Failed to compute signed hash: ${e?.message || e}`));
    }

    // ✅ Patch timesheet: point manual_pdf_r2_key to the CANONICAL key (not image_r2_key)
    const tsPatch = {
      qr_status: 'USED',
      qr_scanned_at: now,
      updated_at: now,
      qr_signed_hash: signedHash,
      qr_signed_at_utc: now,
      manual_pdf_r2_key: canonicalPdfKey,
      qr_scan_info_json: {
        kind: 'DAILY_QR_TIMESHEET',
        payload: p,
        original_image_r2_key: image_r2_key,
        canonical_pdf_r2_key: canonicalPdfKey
      }
    };

    const tsRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets?timesheet_id=eq.${enc(ts.timesheet_id)}&is_current=eq.true`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify(tsPatch)
      }
    );

    if (!tsRes.ok) {
      const t = await tsRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to patch timesheet after QR scan: ${t}`));
    }

    const nextStatus = await computeNextStatusAfterScan(ts.timesheet_id);

    const finRes = await fetch(
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials?id=eq.${enc(fin.id)}`,
      {
        method: 'PATCH',
        headers: { ...sbHeaders(env), Prefer: 'return-minimal' },
        body: JSON.stringify({ processing_status: nextStatus, updated_at: now })
      }
    );

    if (!finRes.ok) {
      const t = await finRes.text().catch(() => '');
      return withCORS(env, req, serverError(`Failed to update TSFIN after QR scan: ${t}`));
    }

    // ✅ Best-effort delete original uploaded key (only if it differs from canonical)
    try {
      const bucket = env.R2_BUCKET || env.R2;
      if (bucket && typeof bucket.delete === 'function' && image_r2_key !== canonicalPdfKey) {
        await bucket.delete(image_r2_key);
      }
    } catch (e) {
      console.warn('[QR_DAILY][SCAN] delete original image key failed (non-fatal)', {
        timesheet_id: ts.timesheet_id,
        original_image_r2_key: image_r2_key,
        err: e?.message || String(e)
      });
    }

    let contract = null;
    if (ts.contract_id) {
      try {
        contract = await sbGetOne(env, `${env.SUPABASE_URL}/rest/v1/contracts?id=eq.${enc(ts.contract_id)}&select=*`);
      } catch {
        contract = null;
      }
    }

    try {
      await writeAudit(
        env,
        user,
        'DAILY_QR_SCANNED',
        {
          timesheet_id: ts.timesheet_id,
          contract_id: contract?.id || ts.contract_id || null,
          qr_text: qrText,
          qr_payload: p,

          // record both keys explicitly
          original_image_r2_key: image_r2_key,
          canonical_pdf_r2_key: canonicalPdfKey,

          processing_status_from: fin.processing_status,
          processing_status_to: nextStatus,
          qr_signed_hash: signedHash
        },
        { entity: 'timesheets', subject_id: ts.timesheet_id, req }
      );
    } catch (e) {
      console.warn('[QR_DAILY][SCAN] audit failed', e?.message || e);
    }

    return withCORS(env, req, ok({
      timesheet_id: ts.timesheet_id,
      contract_id: contract?.id || ts.contract_id || null,
      candidate_id: contract?.candidate_id || null,
      client_id: contract?.client_id || null,
      sheet_scope: 'DAILY',
      processing_status: nextStatus,
      qr_status: 'USED',

      // keep old field for caller compatibility
      image_r2_key,

      // new: explicit canonical key
      canonical_pdf_r2_key: canonicalPdfKey
    }));
  }

  return withCORS(env, req, badRequest('QR mismatch: unsupported sheet_scope for QR'));
}
async function buildWeeklyScheduleSegmentsSnapshot(env, ts, cw, contract, curFin, options = {}) {
  const pc = payChargeFromContract(contract);
  const pay = pc?.pay || null;
  const chg = pc?.charge || null;
  const method = pc?.method || contract?.pay_method_snapshot || null;

  const {
    outbox_id = null,
    write_now = false,
    hr_eff_flags = null,
    hr_preloaded_shifts = null,

    // ✅ NEW: HR weekly validation status (controls when we overwrite refs from import)
    hr_validation_status = null,
    hr_validation_reason_code = null,

    // ✅ allow caller to pass SQL policy (ctx.out_policy) to avoid any REST policy loads
    policy_override = null
  } = (options && typeof options === 'object') ? options : {};

  if (!pay || !chg) {
    throw new Error('CONTRACT_RATES_MISSING');
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Stable segment identity helpers
  // ─────────────────────────────────────────────────────────────
  const _normStr = (v) => (v == null ? '' : String(v).trim());
  const _normNumInt = (v, d = 0) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };

  // FNV-1a 32-bit hash (deterministic, fast, no async crypto)
  const _hash32 = (s) => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return (h >>> 0).toString(16).padStart(8, '0');
  };

  const _stableSegKey = (segObj) => {
    if (!segObj || typeof segObj !== 'object') return '';

    // Prefer stable upstream IDs if available
    const shiftId =
      _normStr(segObj.shift_id) ||
      _normStr(segObj.hr_shift_id) ||
      _normStr(segObj.source_shift_id) ||
      _normStr(segObj.rota_shift_id) ||
      _normStr(segObj.import_shift_id);

    if (shiftId) return `shift:${shiftId}`;

    const date = _normStr(segObj.date);

    // ✅ IMPORTANT: prefer local start/end first (keeps stable IDs aligned to schedule JSON)
    const start =
      _normStr(segObj.start) ||
      _normStr(segObj.start_utc) ||
      _normStr(segObj.start_iso) ||
      _normStr(segObj.startUtc);

    const end =
      _normStr(segObj.end) ||
      _normStr(segObj.end_utc) ||
      _normStr(segObj.end_iso) ||
      _normStr(segObj.endUtc);

    const breakMins = _normNumInt(segObj.break_mins ?? segObj.break_minutes ?? 0, 0);

    const fallbackSid = _normStr(segObj.segment_id);
    if (!start && !end && !date) return fallbackSid;

    return `d:${date}|s:${start}|e:${end}|b:${breakMins}`;
  };

  const _stableSegId = (tsId, segKey) => {
    const k = _normStr(segKey);
    if (!k) return `ts:${tsId}:unknown`;
    return `ts:${tsId}:${_hash32(k)}`;
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ Local-time → UTC ISO helpers
  // Europe/London uses the canonical strict interval-resolution model.
  // Non-London timezones preserve the existing local→UTC fallback behaviour.
  // ─────────────────────────────────────────────────────────────
  const _addDaysYmd = (ymd, addDays) => {
    const s = String(ymd || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
    const [yy, mm, dd] = s.split('-').map(Number);
    const dt = new Date(Date.UTC(yy, mm - 1, dd));
    dt.setUTCDate(dt.getUTCDate() + Number(addDays || 0));
    return dt.toISOString().slice(0, 10);
  };

  const _tzParts = (dateObj, tzId) => {
    const fmt = new Intl.DateTimeFormat('en-GB', {
      timeZone: tzId,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
    const parts = fmt.formatToParts(dateObj);
    const m = {};
    for (const p of parts) m[p.type] = p.value;
    return {
      y: Number(m.year),
      mo: Number(m.month),
      d: Number(m.day),
      h: Number(m.hour),
      mi: Number(m.minute)
    };
  };

  const _localYmdHmToUtcIso = (ymd, hhmm, tzId) => {
    const sY = String(ymd || '').slice(0, 10);
    const sT = String(hhmm || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(sY)) return null;
    const m = sT.match(/^(\d{2}):(\d{2})/);
    if (!m) return null;

    const [yy, mm, dd] = sY.split('-').map(Number);
    const hh = Number(m[1]);
    const mi = Number(m[2]);

    // desired local components treated as UTC (initial reference)
    const desiredAsUtcMs = Date.UTC(yy, mm - 1, dd, hh, mi, 0, 0);

    // pass 1: get offset at the guessed UTC time
    const guess1 = new Date(desiredAsUtcMs);
    const p1 = _tzParts(guess1, tzId);
    const asUtcOfParts1 = Date.UTC(p1.y, p1.mo - 1, p1.d, p1.h, p1.mi, 0, 0);
    const offsetMs1 = asUtcOfParts1 - guess1.getTime();
    const utcMs1 = desiredAsUtcMs - offsetMs1;

    // pass 2: refine offset at the refined UTC time (DST boundary safety)
    const guess2 = new Date(utcMs1);
    const p2 = _tzParts(guess2, tzId);
    const asUtcOfParts2 = Date.UTC(p2.y, p2.mo - 1, p2.d, p2.h, p2.mi, 0, 0);
    const offsetMs2 = asUtcOfParts2 - guess2.getTime();
    const utcMs2 = desiredAsUtcMs - offsetMs2;

    return new Date(utcMs2).toISOString();
  };

  const _pickTzId = () => {
    try {
      const tz = (policy_override && typeof policy_override === 'object')
        ? String(policy_override.timezone_id || '').trim()
        : '';
      return tz || 'Europe/London';
    } catch {
      return 'Europe/London';
    }
  };

  const tzId = _pickTzId();

  const _isIsoLike = (s) => {
    const x = String(s || '');
    return x.includes('T') && (x.endsWith('Z') || /[+\-]\d{2}:\d{2}$/.test(x));
  };

  const _uniqueLocalUtcCandidates = (ymd, hhmm) => {
    const out = [];
    const seen = new Set();

    const pushIso = (iso) => {
      if (!iso) return;
      const ms = new Date(iso).getTime();
      if (!Number.isFinite(ms)) return;
      const normIso = new Date(ms).toISOString();
      if (seen.has(normIso)) return;
      seen.add(normIso);
      out.push({ iso: normIso, ms });
    };

    pushIso(ukLocalToUtcISO(ymd, hhmm, { prefer: 'earlier' }));
    pushIso(ukLocalToUtcISO(ymd, hhmm, { prefer: 'later' }));

    out.sort((a, b) => a.ms - b.ms);
    return out;
  };

  const _scheduleEntryToUtcRange = (seg) => {
    const date = String(seg?.date || '').trim();
    if (!date) return { startUtcIso: null, endUtcIso: null, error: 'Schedule segment date is required' };

    const startIsoRaw = seg?.start_utc || seg?.start_iso || seg?.startUtc || null;
    const endIsoRaw   = seg?.end_utc   || seg?.end_iso   || seg?.endUtc   || null;
    if (startIsoRaw && endIsoRaw && _isIsoLike(startIsoRaw) && _isIsoLike(endIsoRaw)) {
      const startMs = new Date(String(startIsoRaw)).getTime();
      const endMs   = new Date(String(endIsoRaw)).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid UTC shift range on ${date}` };
      }
      return {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        error: null
      };
    }

    const startHH = String(seg?.start || '').trim();
    const endHH = String(seg?.end || '').trim();
    if (!startHH || !endHH) {
      return { startUtcIso: null, endUtcIso: null, error: `Shift start/end must both be set for ${date}` };
    }

    const sMin = parseHHMM(startHH);
    const eMin = parseHHMM(endHH);
    if (sMin == null || eMin == null) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid HH:MM in actual_schedule_json for ${date}` };
    }
    if (sMin === eMin) {
      return { startUtcIso: null, endUtcIso: null, error: `Shift start and end cannot be the same on ${date}` };
    }

    const overnight = (eMin <= sMin);
    const endYmd = overnight ? (_addDaysYmd(date, 1) || date) : date;

    if (tzId !== 'Europe/London') {
      const startUtcIso = _localYmdHmToUtcIso(date, startHH, tzId);
      const endUtcIso = _localYmdHmToUtcIso(endYmd, endHH, tzId);
      if (!startUtcIso) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local start time on ${date}` };
      }
      if (!endUtcIso) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local end time on ${date}` };
      }
      const startMs = new Date(startUtcIso).getTime();
      const endMs = new Date(endUtcIso).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local time range on ${date}` };
      }
      return {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        error: null
      };
    }

    const startCandidates = _uniqueLocalUtcCandidates(date, startHH);
    if (!startCandidates.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Non-existent local start time on ${date}` };
    }

    const endCandidates = _uniqueLocalUtcCandidates(endYmd, endHH);
    if (!endCandidates.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Non-existent local end time on ${endYmd}` };
    }

    const pairMap = new Map();

    const pushPair = (startIso, endIso) => {
      if (!startIso || !endIso) return;
      const startMs = new Date(startIso).getTime();
      const endMs = new Date(endIso).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return;
      const key = `${startMs}|${endMs}`;
      if (pairMap.has(key)) return;
      pairMap.set(key, {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        startMs,
        endMs
      });
    };

    for (const startCand of startCandidates) {
      const endIsoAfterStart = ukLocalToUtcISO(endYmd, endHH, { afterIso: startCand.iso, prefer: 'later' });
      pushPair(startCand.iso, endIsoAfterStart);
      for (const endCand of endCandidates) {
        pushPair(startCand.iso, endCand.iso);
      }
    }

    const pairs = Array.from(pairMap.values()).sort((a, b) => a.startMs - b.startMs || a.endMs - b.endMs);

    if (!pairs.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid local time range on ${date}` };
    }

    if (pairs.length > 1) {
      return { startUtcIso: null, endUtcIso: null, error: `Ambiguous local time range across DST change on ${date}` };
    }

    return {
      startUtcIso: pairs[0].startUtcIso,
      endUtcIso: pairs[0].endUtcIso,
      error: null
    };
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ Reversal handling for correction timesheets (locked policy)
  // ─────────────────────────────────────────────────────────────
  const corrKindU = String(ts?.correction_kind || '').trim().toUpperCase();
  const adjOriginU = String(ts?.adjustment_origin || '').trim().toUpperCase();
  const isCorrection = !!corrKindU || adjOriginU === 'IMPORT_CORRECTION' || adjOriginU === 'IMPORT_CANCELLATION';
  const isReversal = isCorrection && corrKindU.includes('REVERSAL');
  const sign = isReversal ? -1 : 1;

  // ✅ Basis normalisation for correction timesheets:
  const boolishLocal = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on' || s === 't');
  };

  const routeTypeU = String(hr_eff_flags?.route_type || '').trim().toUpperCase();
  const isNhspRoute =
    routeTypeU === 'WEEKLY_NHSP' ||
    routeTypeU === 'WEEKLY_NHSP_ADJUSTMENT' ||
    boolishLocal(hr_eff_flags?.client_is_nhsp);

  const isHrRoute =
    routeTypeU === 'WEEKLY_HEALTHROSTER' ||
    boolishLocal(hr_eff_flags?.client_autoprocess_hr);

  const effective_basis = (() => {
    const cur = (curFin?.basis || 'CONTRACT_WEEKLY');
    const curU = String(cur).trim().toUpperCase();

    if (!isCorrection) return cur;

    if (isNhspRoute) {
      if (curU === 'NHSP' || curU === 'NHSP_ADJUSTMENT') return cur;
      return 'NHSP_ADJUSTMENT';
    }

    if (isHrRoute) {
      if (curU.startsWith('HEALTHROSTER')) return cur;
      return 'HEALTHROSTER_ADJUSTMENT';
    }

    return cur;
  })();

  const basisU = String(effective_basis || 'CONTRACT_WEEKLY').toUpperCase();
  const isHrCreateNoTs =
    (basisU === 'HEALTHROSTER_SELF_BILL' || basisU === 'HEALTHROSTER_ADJUSTMENT');

  const isAuthorised = !!(ts && ts.authorised_at_server);

  // ✅ QR unsigned gating (must block invoicing even if authorised)
  const qrStatusU = String(ts?.qr_status || '').trim().toUpperCase();
  const qrToken = (ts?.qr_token != null) ? String(ts.qr_token).trim() : '';
  const hasQrIssuedProof = (
    ((qrToken && !!ts?.qr_generated_at) === true) ||
    ((ts?.qr_last_sent_hash != null) && String(ts.qr_last_sent_hash).trim() !== '')
  );
  const qrAwaitingSignatureUpload =
    (qrStatusU === 'PENDING' && hasQrIssuedProof && !ts?.qr_scanned_at);

  // ✅ initial status (may be refined below after validation flags are evaluated)
  let processing_status = (qrAwaitingSignatureUpload)
    ? 'AWAITING_MANUAL_SIGNATURE'
    : ((!isAuthorised) ? 'PENDING_AUTH' : 'READY_FOR_INVOICE');

  // ✅ preserve expenses/mileage (+ units) from current snapshot (curFin)
  const expPay   = round2(asNumberLocal(curFin?.expenses_pay_ex_vat ?? 0));
  const expChg   = round2(asNumberLocal(curFin?.expenses_charge_ex_vat ?? 0));
  const milUnits = round2(asNumberLocal(curFin?.mileage_units ?? 0));
  const milPay   = round2(asNumberLocal(curFin?.mileage_pay_ex_vat ?? 0));
  const milChg   = round2(asNumberLocal(curFin?.mileage_charge_ex_vat ?? 0));

  const actualRaw = Array.isArray(ts?.actual_schedule_json) ? ts.actual_schedule_json : [];
  const actualNorm = normaliseScheduleBreakFields(actualRaw);

  // ✅ Determine whether we should override segment ref_num from imported HealthRoster shifts.
  const hrValidationRequired =
    boolishLocal(hr_eff_flags?.client_hr_validation_required) ||
    boolishLocal(hr_eff_flags?.hr_validation_required_for_invoice) ||
    false;

  const valStatusU = String(hr_validation_status || '').trim().toUpperCase();
  const valReasonU = String(hr_validation_reason_code || '').trim().toUpperCase();

  const isValidatedOk =
    (valStatusU === 'VALIDATION_OK' || valStatusU === 'OVERRIDDEN' || valStatusU === 'OVERRIDE');

  const isWeeklyHrValidation =
    (!valReasonU) ? true : valReasonU.includes('HEALTHROSTER_WEEKLY');

  const useImportRefs = !!(hrValidationRequired && isValidatedOk && isWeeklyHrValidation);

  // ✅ NEW: processing_status priority:
  // 1) QR awaiting signature => AWAITING_MANUAL_SIGNATURE (even if authorised)
  // 2) Not authorised => PENDING_AUTH
  // 3) HR validation required for invoice and NOT OK/OVERRIDDEN => READY_FOR_HR
  // 4) Else => READY_FOR_INVOICE
  if (qrAwaitingSignatureUpload) {
    processing_status = 'AWAITING_MANUAL_SIGNATURE';
  } else if (!isAuthorised) {
    processing_status = 'PENDING_AUTH';
  } else if (hrValidationRequired && !isValidatedOk && isWeeklyHrValidation) {
    processing_status = 'READY_FOR_HR';
  } else {
    processing_status = 'READY_FOR_INVOICE';
  }

  const parseUtcMs = (v) => {
    if (v == null) return null;
    let s = String(v).trim();
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s) && !s.includes('T')) {
      s = s.replace(' ', 'T');
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) return null;
    return d.getTime();
  };

  // ✅ Build a fast lookup from imported HealthRoster shifts to their ref_num (Request Id)
  const hrRefByKey = new Map();     // `${date}|${startMs}|${endMs}` -> ref_num
  const hrListByDate = new Map();   // date -> [{ startMs, endMs, ref_num }]
  if (useImportRefs && Array.isArray(hr_preloaded_shifts) && hr_preloaded_shifts.length) {
    for (const sh of hr_preloaded_shifts) {
      const ss = String(sh?.source_system || '').trim().toUpperCase();
      if (ss !== 'HEALTHROSTER') continue;

      const d = sh?.work_date ? String(sh.work_date).slice(0, 10) : '';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;

      const ref = (sh?.ref_num != null) ? String(sh.ref_num).trim() : '';
      if (!ref) continue;

      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);
      if (sMs == null || eMs == null) continue;

      const k = `${d}|${sMs}|${eMs}`;
      if (!hrRefByKey.has(k)) hrRefByKey.set(k, ref);

      if (!hrListByDate.has(d)) hrListByDate.set(d, []);
      hrListByDate.get(d).push({ startMs: sMs, endMs: eMs, ref_num: ref });
    }
  }

  // ✅ Preserve ref_num through normalisation (candidate-entered refs)
  const actual = (Array.isArray(actualNorm) ? actualNorm : []).map((seg, idx) => {
    if (!seg || typeof seg !== 'object') return seg;

    const raw = (Array.isArray(actualRaw) && actualRaw[idx] && typeof actualRaw[idx] === 'object')
      ? actualRaw[idx]
      : null;

    const v =
      seg.ref_num ?? seg.ref ?? seg.reference ?? seg.refNum ??
      raw?.ref_num ?? raw?.ref ?? raw?.reference ?? raw?.refNum ??
      null;

    const s = (v == null) ? '' : String(v).trim();
    if (!s) return seg;

    return { ...seg, ref_num: s };
  });

  if (!actual.length) {
    let policy_snapshot_json = {};
    if (policy_override && typeof policy_override === 'object') {
      policy_snapshot_json = policy_override;
    }

    const base_pay_ex_vat = 0;
    const base_charge_ex_vat = 0;
    const addl_pay_ex_vat = 0;
    const addl_charge_ex_vat = 0;

    const total_pay_ex_vat = round2(base_pay_ex_vat + addl_pay_ex_vat + expPay + milPay);
    const total_charge_ex_vat = round2(base_charge_ex_vat + addl_charge_ex_vat + expChg + milChg);

    const pol0 = (policy_override && typeof policy_override === 'object') ? policy_override : {};
    const applyTo0 = String(pol0.apply_erni_to || 'PAYE_ONLY').toUpperCase();
    const erniPctRaw0 = Number(pol0.erni_pct ?? 0);

    let erniMult0 = 1;
    if (Number.isFinite(erniPctRaw0) && erniPctRaw0 > 0) {
      const p = erniPctRaw0 > 1 ? (erniPctRaw0 / 100) : erniPctRaw0;
      erniMult0 = 1 + p;
    }

    const payMethodUpper0 = String(method || contract?.pay_method_snapshot || '').toUpperCase();
    const erniApplies0 =
      (applyTo0 === 'ALL') ||
      (applyTo0 === 'PAYE_ONLY' && payMethodUpper0 === 'PAYE');

    const payCostEx0 = round2(erniApplies0 ? (total_pay_ex_vat * erniMult0) : total_pay_ex_vat);
    const margin_ex_vat = round2(total_charge_ex_vat - payCostEx0);

    const snapshot = {
      timesheet_id: ts.timesheet_id,
      timesheet_version: ts.version || 1,
      basis: (effective_basis || 'CONTRACT_WEEKLY'),
      candidate_id: contract?.candidate_id || null,
      client_id: contract?.client_id || null,
      role: contract?.role || null,
      band: contract?.band || null,
      pay_method: method,
      policy_snapshot_json,
      rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract?.id || null },

      hours_day: 0,
      hours_night: 0,
      hours_sat: 0,
      hours_sun: 0,
      hours_bh: 0,
      total_hours: 0,

      pay_day: pay.day, pay_night: pay.night, pay_sat: pay.sat, pay_sun: pay.sun, pay_bh: pay.bh,
      charge_day: chg.day, charge_night: chg.night, charge_sat: chg.sat, charge_sun: chg.sun, charge_bh: chg.bh,

      additional_units_json: {},
      additional_pay_ex_vat: 0,
      additional_charge_ex_vat: 0,
      additional_margin_ex_vat: 0,

      total_pay_ex_vat,
      total_charge_ex_vat,
      margin_ex_vat,

      expenses_pay_ex_vat: expPay,
      expenses_charge_ex_vat: expChg,
      expenses_description: curFin?.expenses_description ?? null,
      expenses_evidence_r2_key: curFin?.expenses_evidence_r2_key ?? null,
      expenses_evidence_manifest: curFin?.expenses_evidence_manifest ?? null,

      mileage_units: milUnits,
      mileage_pay_ex_vat: milPay,
      mileage_charge_ex_vat: milChg,
      mileage_evidence_r2_key: curFin?.mileage_evidence_r2_key ?? null,
      mileage_evidence_manifest: curFin?.mileage_evidence_manifest ?? null,
      mileage_pay_rate: curFin?.mileage_pay_rate ?? null,
      mileage_charge_rate: curFin?.mileage_charge_rate ?? null,

      candidate_assignment: (contract?.candidate_id ? 'ASSIGNED' : 'UNASSIGNED'),
      processing_status,

      invoice_breakdown_json: {
        mode: 'SEGMENTS',
        segments: [],
        totals: { total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat }
      }
    };

    if (typeof enrichTsfinWithHrCrosscheck === 'function') {
      try { await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null); } catch {}
    }

    if (write_now) {
      if (!outbox_id) throw new Error('buildWeeklyScheduleSegmentsSnapshot: write_now requires options.outbox_id');
      const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
        rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
      });
      return { ok: true, snapshot, write: wr };
    }

    return { ok: true, snapshot };
  }

  // ✅ Preserve locked segment evidence immutability (non-correction only)
  // Build lookups from existing snapshot segments.
  const preserved = new Map(); // stableKey -> { ... }
  const preservedBySegId = new Map(); // segment_id -> { ... }  ✅ (critical for legacy rows missing start/end fields)
  const preservedLockedByTime = new Map(); // `${date}|${startMs}|${endMs}` -> seg_obj

  try {
    const ib = curFin?.invoice_breakdown_json || null;
    const mode = String(ib?.mode || '').toUpperCase();
    const segs = Array.isArray(ib?.segments) ? ib.segments : null;

    if (mode === 'SEGMENTS' && segs) {
      for (const s of segs) {
        if (!s || typeof s !== 'object') continue;

        const segId0 = _normStr(s.segment_id);
        const key = _stableSegKey(s);

        const invLockRaw = (s.invoice_locked_invoice_id != null) ? String(s.invoice_locked_invoice_id).trim() : '';
        const isLocked = !!invLockRaw;

        const meta = {
          is_locked: isLocked,
          seg_obj: (isLocked ? s : null),
          exclude_from_pay: (typeof s.exclude_from_pay === 'boolean') ? s.exclude_from_pay : undefined,
          invoice_target_week_start: (s.invoice_target_week_start != null) ? String(s.invoice_target_week_start) : undefined,
          invoice_locked_invoice_id: (invLockRaw ? invLockRaw : undefined)
        };

        if (key) preserved.set(key, meta);
        if (segId0) preservedBySegId.set(segId0, meta);

        if (isLocked) {
          const d = (s?.date != null) ? String(s.date).slice(0, 10) : '';
          const sMs = parseUtcMs(s?.start_utc || s?.startUtc || null);
          const eMs = parseUtcMs(s?.end_utc || s?.endUtc || null);
          if (d && sMs != null && eMs != null) {
            const k2 = `${d}|${sMs}|${eMs}`;
            if (!preservedLockedByTime.has(k2)) preservedLockedByTime.set(k2, s);
          }
        }
      }
    }
  } catch {}

  const segments = [];
  let sumDay = 0, sumNight = 0, sumSat = 0, sumSun = 0, sumBh = 0;
  let sumPay = 0, sumChg = 0;

  const seenLockedKeys = new Set();

  for (let i = 0; i < actual.length; i++) {
    const seg = actual[i] || {};

    const key = _stableSegKey(seg);
    const sid = _stableSegId(ts.timesheet_id, key);

    const { startUtcIso, endUtcIso, error: utcRangeError } = _scheduleEntryToUtcRange(seg);
    if (utcRangeError) {
      throw new Error(utcRangeError);
    }

    // If this corresponds to an invoice-locked segment, preserve evidence as-is (immutability), non-correction only.
    if (!isCorrection) {
      // ✅ First try: match by segment_id (robust even if old rows missed start/end fields)
      const pById = preservedBySegId.get(sid) || null;
      const pByKey = preserved.get(key) || null;
      const p0 = pById || pByKey;

      let lockedSegObj = (p0 && p0.is_locked && p0.seg_obj) ? p0.seg_obj : null;

      // Fallback match by date+start+end (ignores break differences)
      if (!lockedSegObj) {
        const d = (seg?.date != null) ? String(seg.date).slice(0, 10) : '';
        const sMs = parseUtcMs(startUtcIso);
        const eMs = parseUtcMs(endUtcIso);
        if (d && sMs != null && eMs != null) {
          const k2 = `${d}|${sMs}|${eMs}`;
          lockedSegObj = preservedLockedByTime.get(k2) || null;
          if (lockedSegObj) {
            const key2 = _stableSegKey(lockedSegObj);
            if (key2) seenLockedKeys.add(key2);
          }
        }
      }

      if (lockedSegObj && typeof lockedSegObj === 'object') {
        // Keep locked segment immutable
        segments.push(lockedSegObj);

        const hDay   = asNumberLocal(lockedSegObj.hours_day);
        const hNight = asNumberLocal(lockedSegObj.hours_night);
        const hSat   = asNumberLocal(lockedSegObj.hours_sat);
        const hSun   = asNumberLocal(lockedSegObj.hours_sun);
        const hBh    = asNumberLocal(lockedSegObj.hours_bh);

        sumDay += hDay; sumNight += hNight; sumSat += hSat; sumSun += hSun; sumBh += hBh;

        const excludeFromPay = !!lockedSegObj.exclude_from_pay;
        const payAmt = asNumberLocal(lockedSegObj.pay_amount);
        const chgAmt = asNumberLocal(lockedSegObj.charge_amount);

        if (!excludeFromPay) sumPay += payAmt;
        sumChg += chgAmt;

        const keyLocked = _stableSegKey(lockedSegObj);
        if (keyLocked) seenLockedKeys.add(keyLocked);

        continue;
      }
    }

    const mins = await resolveBucketsFromSchedule(env, contract, [seg], policy_override);

    const hDayRaw   = +(asNumberLocal(mins.day)   / 60).toFixed(2);
    const hNightRaw = +(asNumberLocal(mins.night) / 60).toFixed(2);
    const hSatRaw   = +(asNumberLocal(mins.sat)   / 60).toFixed(2);
    const hSunRaw   = +(asNumberLocal(mins.sun)   / 60).toFixed(2);
    const hBhRaw    = +(asNumberLocal(mins.bh)    / 60).toFixed(2);

    const hDay   = round2(hDayRaw * sign);
    const hNight = round2(hNightRaw * sign);
    const hSat   = round2(hSatRaw * sign);
    const hSun   = round2(hSunRaw * sign);
    const hBh    = round2(hBhRaw * sign);

    sumDay += hDay; sumNight += hNight; sumSat += hSat; sumSun += hSun; sumBh += hBh;

    const payExRaw = round2(
      hDayRaw   * asNumberLocal(pay.day) +
      hNightRaw * asNumberLocal(pay.night) +
      hSatRaw   * asNumberLocal(pay.sat) +
      hSunRaw   * asNumberLocal(pay.sun) +
      hBhRaw    * asNumberLocal(pay.bh)
    );

    const chgExRaw = round2(
      hDayRaw   * asNumberLocal(chg.day) +
      hNightRaw * asNumberLocal(chg.night) +
      hSatRaw   * asNumberLocal(chg.sat) +
      hSunRaw   * asNumberLocal(chg.sun) +
      hBhRaw    * asNumberLocal(chg.bh)
    );

    const payEx = round2(payExRaw * sign);
    const chgEx = round2(chgExRaw * sign);

    sumPay += payEx;
    sumChg += chgEx;

    // ✅ Preserve metadata from existing segments:
    // prefer by segment_id, then fallback to by stable key
    const p = preservedBySegId.get(sid) || preserved.get(key) || null;

    const exclude_from_pay =
      (p && typeof p.exclude_from_pay === 'boolean') ? p.exclude_from_pay : false;

    const invoice_target_week_start =
      (p && p.invoice_target_week_start != null) ? p.invoice_target_week_start : undefined;

    const invoice_locked_invoice_id =
      (p && p.invoice_locked_invoice_id != null) ? p.invoice_locked_invoice_id : undefined;

    // Candidate-entered ref (kept only if we are NOT overriding from import)
    const scheduleRef = (() => {
      const v = seg?.ref_num ?? seg?.ref ?? seg?.reference ?? seg?.refNum ?? null;
      const s = (v == null) ? '' : String(v).trim();
      return s ? s : null;
    })();

    // ✅ If validated OK for HR weekly, force ref_num from imported HealthRoster shifts (Request Id)
    let segRefNum = scheduleRef;

    if (useImportRefs) {
      const dateYmd = (seg?.date != null) ? String(seg.date).slice(0, 10) : '';
      const sMs = parseUtcMs(startUtcIso);
      const eMs = parseUtcMs(endUtcIso);

      let hrRef = null;

      if (dateYmd && sMs != null && eMs != null) {
        const k2 = `${dateYmd}|${sMs}|${eMs}`;
        hrRef = hrRefByKey.get(k2) || null;
      }

      // Fallback: if exactly one HR shift exists for that date, use its ref_num
      if (!hrRef && dateYmd && hrListByDate.has(dateYmd)) {
        const arr = hrListByDate.get(dateYmd) || [];
        const uniq = new Set(arr.map(x => String(x.ref_num || '').trim()).filter(Boolean));
        if (uniq.size === 1) {
          hrRef = Array.from(uniq)[0];
        }
      }

      // After validation, use the import ref. If no match found, keep it null.
      segRefNum = hrRef ? String(hrRef) : null;
    }

    // ✅ Populate BOTH local start/end and UTC ISO start_utc/end_utc (fixes blank QR PDFs + stable preservation)
    const startLocal = (seg?.start != null) ? String(seg.start).trim() : '';
    const endLocal = (seg?.end != null) ? String(seg.end).trim() : '';
    const startLocalMins = parseHHMM(startLocal);
    const endLocalMins = parseHHMM(endLocal);
    const overnight =
      (startLocalMins != null && endLocalMins != null)
        ? (endLocalMins <= startLocalMins)
        : !!seg?.overnight;

    segments.push({
      segment_id: sid,

      date: seg.date || null,

      // ✅ local clock times (for stability + display)
      start: startLocal || null,
      end: endLocal || null,
      overnight: overnight,

      // ✅ UTC ISO timestamps (for PDF reference rows + evidence matching)
      start_utc: startUtcIso,
      end_utc: endUtcIso,

      break_mins: Number(seg.break_mins ?? seg.break_minutes ?? 0) || 0,

      ref_num: segRefNum,

      breaks: Array.isArray(seg.breaks) ? seg.breaks : [],

      hours_day: hDay,
      hours_night: hNight,
      hours_sat: hSat,
      hours_sun: hSun,
      hours_bh: hBh,

      pay_amount: payEx,
      charge_amount: chgEx,

      is_reversal: isReversal,

      exclude_from_pay,
      ...(invoice_target_week_start != null ? { invoice_target_week_start } : {}),
      ...(invoice_locked_invoice_id != null ? { invoice_locked_invoice_id } : {})
    });
  }

  // Ensure we never drop invoice-locked segments that are not present in schedule (immutability), non-correction only
  if (!isCorrection) {
    try {
      for (const [, p] of preserved.entries()) {
        if (!p || !p.is_locked || !p.seg_obj) continue;
        const k = _stableSegKey(p.seg_obj);
        if (!k) continue;
        if (seenLockedKeys.has(k)) continue;

        segments.push(p.seg_obj);

        const hDay   = asNumberLocal(p.seg_obj.hours_day);
        const hNight = asNumberLocal(p.seg_obj.hours_night);
        const hSat   = asNumberLocal(p.seg_obj.hours_sat);
        const hSun   = asNumberLocal(p.seg_obj.hours_sun);
        const hBh    = asNumberLocal(p.seg_obj.hours_bh);

        sumDay += hDay; sumNight += hNight; sumSat += hSat; sumSun += hSun; sumBh += hBh;

        const excludeFromPay = !!p.seg_obj.exclude_from_pay;
        const payAmt = asNumberLocal(p.seg_obj.pay_amount);
        const chgAmt = asNumberLocal(p.seg_obj.charge_amount);

        if (!excludeFromPay) sumPay += payAmt;
        sumChg += chgAmt;

        seenLockedKeys.add(k);
      }
    } catch {}
  }

  const hours = {
    day: round2(sumDay),
    night: round2(sumNight),
    sat: round2(sumSat),
    sun: round2(sumSun),
    bh: round2(sumBh)
  };

  const total_hours = round2(hours.day + hours.night + hours.sat + hours.sun + hours.bh);

  const addl = await computeWeeklyAdditionalFromTs(env, ts, cw, contract, policy_override);

  const addlPayRaw = round2(addl.additional_pay_ex_vat || 0);
  const addlChgRaw = round2(addl.additional_charge_ex_vat || 0);
  const addlMarRaw = round2(addl.additional_margin_ex_vat || 0);

  const addlPay = round2(addlPayRaw * sign);
  const addlChg = round2(addlChgRaw * sign);
  const addlMar = round2(addlMarRaw * sign);

  const core_total_pay_ex_vat = round2(round2(sumPay) + addlPay);
  const core_total_charge_ex_vat = round2(round2(sumChg) + addlChg);

  const total_pay_ex_vat = round2(core_total_pay_ex_vat + expPay + milPay);
  const total_charge_ex_vat = round2(core_total_charge_ex_vat + expChg + milChg);

  const pol = (policy_override && typeof policy_override === 'object') ? policy_override : {};
  const applyTo = String(pol.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const erniPctRaw = Number(pol.erni_pct ?? 0);

  let erniMult = 1;
  if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
    const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
    erniMult = 1 + p;
  }

  const payMethodUpper = String(method || contract?.pay_method_snapshot || '').toUpperCase();
  const erniApplies =
    (applyTo === 'ALL') ||
    (applyTo === 'PAYE_ONLY' && payMethodUpper === 'PAYE');

  const payCostEx = round2(erniApplies ? (total_pay_ex_vat * erniMult) : total_pay_ex_vat);
  const margin_ex_vat = round2(total_charge_ex_vat - payCostEx);

  let policy_snapshot_json = {};
  if (policy_override && typeof policy_override === 'object') {
    policy_snapshot_json = policy_override;
  } else {
    try {
      const we = String(ts?.week_ending_date || cw?.week_ending_date || '');
      if (we && contract?.client_id && typeof getPolicyCached === 'function') {
        policy_snapshot_json = await getPolicyCached(contract.client_id, we);
      }
      if (!policy_snapshot_json || typeof policy_snapshot_json !== 'object') policy_snapshot_json = {};
    } catch {
      policy_snapshot_json = {};
    }
  }

  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,

    basis: (effective_basis || 'CONTRACT_WEEKLY'),
    candidate_id: contract?.candidate_id || null,
    client_id: contract?.client_id || null,
    role: contract?.role || null,
    band: contract?.band || null,
    pay_method: method,

    policy_snapshot_json,
    rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract?.id || null },

    hours_day: hours.day,
    hours_night: hours.night,
    hours_sat: hours.sat,
    hours_sun: hours.sun,
    hours_bh: hours.bh,
    total_hours,

    pay_day: pay.day, pay_night: pay.night, pay_sat: pay.sat, pay_sun: pay.sun, pay_bh: pay.bh,
    charge_day: chg.day, charge_night: chg.night, charge_sat: chg.sat, charge_sun: chg.sun, charge_bh: chg.bh,

    additional_units_json: addl.additional_units_json || {},
    additional_pay_ex_vat: addlPay,
    additional_charge_ex_vat: addlChg,
    additional_margin_ex_vat: addlMar,

    total_pay_ex_vat,
    total_charge_ex_vat,
    margin_ex_vat,

    expenses_pay_ex_vat: expPay,
    expenses_charge_ex_vat: expChg,
    expenses_description: curFin?.expenses_description ?? null,
    expenses_evidence_r2_key: curFin?.expenses_evidence_r2_key ?? null,
    expenses_evidence_manifest: curFin?.expenses_evidence_manifest ?? null,

    mileage_units: milUnits,
    mileage_pay_ex_vat: milPay,
    mileage_charge_ex_vat: milChg,
    mileage_evidence_r2_key: curFin?.mileage_evidence_r2_key ?? null,
    mileage_evidence_manifest: curFin?.mileage_evidence_manifest ?? null,
    mileage_pay_rate: curFin?.mileage_pay_rate ?? null,
    mileage_charge_rate: curFin?.mileage_charge_rate ?? null,

    candidate_assignment: (contract?.candidate_id ? 'ASSIGNED' : 'UNASSIGNED'),
    processing_status,

    invoice_breakdown_json: {
      mode: 'SEGMENTS',
      segments,
      additional: {
        units: addl.additional_units_json || {},
        pay_ex_vat: addlPay,
        charge_ex_vat: addlChg,
        margin_ex_vat: addlMar
      },
      totals: {
        total_pay_ex_vat,
        total_charge_ex_vat,
        margin_ex_vat
      }
    }
  };

  if (typeof enrichTsfinWithHrCrosscheck === 'function') {
    try { await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null); } catch {}
  }

  if (write_now) {
    if (!outbox_id) throw new Error('buildWeeklyScheduleSegmentsSnapshot: write_now requires options.outbox_id');
    const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
      rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
    });
    return { ok: true, snapshot, write: wr };
  }

  return { ok: true, snapshot };
}

async function rebuildFromExistingSegmentsEvidence(env, ts, cw, contract, curFin, options = {}) {
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const asNumberLocal = (v) => (v == null ? 0 : Number(v) || 0);
  const trimStr = (v) => (v == null ? '' : String(v).trim());

  const ib = curFin?.invoice_breakdown_json || null;
  const mode = String(ib?.mode || '').toUpperCase();
  const segs = Array.isArray(ib?.segments) ? ib.segments : null;
  if (mode !== 'SEGMENTS' || !segs || !segs.length) {
    throw new Error('NO_EXISTING_SEGMENTS_EVIDENCE');
  }

  const {
    outbox_id = null,
    write_now = false,
    hr_eff_flags = null,
    hr_preloaded_shifts = null,

    // ✅ NEW: HR weekly validation status (controls when we overwrite refs from import)
    hr_validation_status = null,
    hr_validation_reason_code = null,

    // ✅ allow caller to pass SQL policy (ctx.out_policy) to avoid REST
    policy_override = null
  } = (options && typeof options === 'object') ? options : {};

  const pc = payChargeFromContract(contract);
  const pay = pc?.pay || null;
  const chg = pc?.charge || null;
  const method = pc?.method || contract.pay_method_snapshot || null;
  if (!pay || !chg) throw new Error('CONTRACT_RATES_MISSING');

  // ✅ GLOBAL RULE: never allow weekly to be READY_* unless authorised
  const isAuthorised = !!(ts && ts.authorised_at_server);
  const processing_status = (!isAuthorised) ? 'PENDING_AUTH' : 'READY_FOR_INVOICE';

  // ✅ Determine whether we should override segment ref_num from imported HealthRoster shifts.
  const boolishLocal = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on' || s === 't');
  };

  const hrValidationRequired =
    boolishLocal(hr_eff_flags?.client_hr_validation_required) ||
    boolishLocal(hr_eff_flags?.hr_validation_required_for_invoice) ||
    false;

  const valStatusU = String(hr_validation_status || '').trim().toUpperCase();
  const valReasonU = String(hr_validation_reason_code || '').trim().toUpperCase();

  const isValidatedOk =
    (valStatusU === 'VALIDATION_OK' || valStatusU === 'OVERRIDDEN' || valStatusU === 'OVERRIDE');

  const isWeeklyHrValidation =
    (!valReasonU) ? true : valReasonU.includes('HEALTHROSTER_WEEKLY');

  const useImportRefs = !!(hrValidationRequired && isValidatedOk && isWeeklyHrValidation);

  const parseUtcMs = (v) => {
    if (v == null) return null;
    let s = String(v).trim();
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s) && !s.includes('T')) {
      s = s.replace(' ', 'T');
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) return null;
    return d.getTime();
  };

  const hrRefByKey = new Map();   // `${date}|${startMs}|${endMs}` -> ref_num
  const hrListByDate = new Map(); // date -> [{startMs,endMs,ref_num}]
  if (useImportRefs && Array.isArray(hr_preloaded_shifts) && hr_preloaded_shifts.length) {
    for (const sh of hr_preloaded_shifts) {
      const ss = String(sh?.source_system || '').trim().toUpperCase();
      if (ss !== 'HEALTHROSTER') continue;

      const d = sh?.work_date ? String(sh.work_date).slice(0, 10) : '';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;

      const ref = (sh?.ref_num != null) ? String(sh.ref_num).trim() : '';
      if (!ref) continue;

      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);
      if (sMs == null || eMs == null) continue;

      const k = `${d}|${sMs}|${eMs}`;
      if (!hrRefByKey.has(k)) hrRefByKey.set(k, ref);

      if (!hrListByDate.has(d)) hrListByDate.set(d, []);
      hrListByDate.get(d).push({ startMs: sMs, endMs: eMs, ref_num: ref });
    }
  }

  // ✅ Policy snapshot: prefer SQL policy_override; fallback to getPolicyCached only if missing
  let policy_snapshot_json = {};
  if (policy_override && typeof policy_override === 'object') {
    policy_snapshot_json = policy_override;
  } else {
    try {
      const we = String(ts.week_ending_date || cw.week_ending_date || '');
      policy_snapshot_json =
        (contract.client_id && we && typeof getPolicyCached === 'function')
          ? (await getPolicyCached(contract.client_id, we))
          : {};
      if (!policy_snapshot_json || typeof policy_snapshot_json !== 'object') policy_snapshot_json = {};
    } catch {
      policy_snapshot_json = {};
    }
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Option A expense rollup (travel+accom+other, fallback to expenses_*)
  // ─────────────────────────────────────────────────────────────
  const catPay = round2(
    asNumberLocal(curFin?.travel_pay_ex_vat ?? 0) +
    asNumberLocal(curFin?.accommodation_pay_ex_vat ?? 0) +
    asNumberLocal(curFin?.other_pay_ex_vat ?? 0)
  );
  const catChg = round2(
    asNumberLocal(curFin?.travel_charge_ex_vat ?? 0) +
    asNumberLocal(curFin?.accommodation_charge_ex_vat ?? 0) +
    asNumberLocal(curFin?.other_charge_ex_vat ?? 0)
  );

  const expPayEff = round2((catPay !== 0) ? catPay : asNumberLocal(curFin?.expenses_pay_ex_vat ?? 0));
  const expChgEff = round2((catChg !== 0) ? catChg : asNumberLocal(curFin?.expenses_charge_ex_vat ?? 0));

  const milUnits = round2(asNumberLocal(curFin?.mileage_units ?? 0));
  const milPay = round2(asNumberLocal(curFin?.mileage_pay_ex_vat ?? 0));
  const milChg = round2(asNumberLocal(curFin?.mileage_charge_ex_vat ?? 0));

  // Preserve additional (wage-like) fields from current snapshot
  const addlUnitsJson =
    (curFin?.additional_units_json && typeof curFin.additional_units_json === 'object')
      ? curFin.additional_units_json
      : {};

  const addlPay = round2(asNumberLocal(curFin?.additional_pay_ex_vat ?? 0));
  const addlChg = round2(asNumberLocal(curFin?.additional_charge_ex_vat ?? 0));
  const addlMar = round2(asNumberLocal(curFin?.additional_margin_ex_vat ?? (addlChg - addlPay)));

  const staleReason = (curFin && curFin.stale_reason != null) ? String(curFin.stale_reason) : '';
  const dropUnlockedBecauseCantRebuildTruth = (staleReason === 'IMPORT_CANCEL_DETACH');

  let sumDay = 0, sumNight = 0, sumSat = 0, sumSun = 0, sumBh = 0;
  let segPaySum = 0;    // pay totals must respect exclude_from_pay
  let segChgSum = 0;

  const nextSegments = [];
  for (const s of segs) {
    if (!s || typeof s !== 'object') continue;

    const invLock = trimStr(s.invoice_locked_invoice_id);
    const isLocked = invLock !== '';

    if (dropUnlockedBecauseCantRebuildTruth && !isLocked) {
      continue;
    }

    const hDay   = asNumberLocal(s.hours_day);
    const hNight = asNumberLocal(s.hours_night);
    const hSat   = asNumberLocal(s.hours_sat);
    const hSun   = asNumberLocal(s.hours_sun);
    const hBh    = asNumberLocal(s.hours_bh);

    sumDay += hDay; sumNight += hNight; sumSat += hSat; sumSun += hSun; sumBh += hBh;

    const excludeFromPay = !!s.exclude_from_pay;

    if (isLocked) {
      // ✅ Locked segment evidence is immutable: do NOT change ref_num or amounts.
      const payExLocked = asNumberLocal(s.pay_amount);
      const chgExLocked = asNumberLocal(s.charge_amount);

      if (!excludeFromPay) segPaySum += payExLocked;
      segChgSum += chgExLocked;

      nextSegments.push(s);
      continue;
    }

    // Unlocked segment: recalc amounts from stored hours using current contract rates.
    const payEx = round2(
      hDay   * asNumberLocal(pay.day) +
      hNight * asNumberLocal(pay.night) +
      hSat   * asNumberLocal(pay.sat) +
      hSun   * asNumberLocal(pay.sun) +
      hBh    * asNumberLocal(pay.bh)
    );

    const chgEx = round2(
      hDay   * asNumberLocal(chg.day) +
      hNight * asNumberLocal(chg.night) +
      hSat   * asNumberLocal(chg.sat) +
      hSun   * asNumberLocal(chg.sun) +
      hBh    * asNumberLocal(chg.bh)
    );

    if (!excludeFromPay) segPaySum += payEx;
    segChgSum += chgEx;

    // ✅ Import ref propagation (unlocked only)
    let nextRefNum = (s.ref_num != null) ? String(s.ref_num).trim() : '';
    if (useImportRefs) {
      const dateYmd = (s?.date != null) ? String(s.date).slice(0, 10) : '';
      const sMs = parseUtcMs(s?.start_utc || s?.startUtc || null);
      const eMs = parseUtcMs(s?.end_utc || s?.endUtc || null);

      let hrRef = null;
      if (dateYmd && sMs != null && eMs != null) {
        const k2 = `${dateYmd}|${sMs}|${eMs}`;
        hrRef = hrRefByKey.get(k2) || null;
      }

      if (!hrRef && dateYmd && hrListByDate.has(dateYmd)) {
        const arr = hrListByDate.get(dateYmd) || [];
        const uniq = new Set(arr.map(x => String(x.ref_num || '').trim()).filter(Boolean));
        if (uniq.size === 1) hrRef = Array.from(uniq)[0];
      }

      nextRefNum = hrRef ? String(hrRef) : '';
    }

    nextSegments.push({
      ...s,
      ref_num: nextRefNum ? nextRefNum : null,
      pay_amount: payEx,
      charge_amount: chgEx
    });
  }

  segPaySum = round2(segPaySum);
  segChgSum = round2(segChgSum);

  // ✅ Totals include non-segment amounts (additional + expenses + mileage)
  const nonsegPay = round2(addlPay + expPayEff + milPay);
  const nonsegChg = round2(addlChg + expChgEff + milChg);

  const totalPayEx = round2(segPaySum + nonsegPay);
  const totalChgEx = round2(segChgSum + nonsegChg);

  // ✅ ERNI-aware margin (PAYE only; wage pay only; NEVER on expenses/mileage)
  const pol = (policy_snapshot_json && typeof policy_snapshot_json === 'object') ? policy_snapshot_json : {};
  const applyTo = String(pol.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const erniPctRaw = Number(pol.erni_pct ?? 0);

  let erniMult = 1;
  if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
    const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
    erniMult = 1 + p;
  }

  const payMethodU = String(method || '').toUpperCase();

  const erniApplies =
    (payMethodU === 'PAYE') &&
    (applyTo === 'ALL' || applyTo === 'PAYE_ONLY');

  const wagePay = round2(segPaySum + addlPay);
  const reimbPay = round2(expPayEff + milPay);

  const wageCost = round2(erniApplies ? (wagePay * erniMult) : wagePay);
  const payCostEx = round2(wageCost + reimbPay);

  const marginEx = round2(totalChgEx - payCostEx);

  // ✅ Non-seg margin: ERNI only on additional pay, never on expenses/mileage
  const addlWageCost = round2(erniApplies ? (addlPay * erniMult) : addlPay);
  const nonsegPayCost = round2(addlWageCost + reimbPay);
  const nonsegMar = round2(nonsegChg - nonsegPayCost);

  const hours_day   = round2(sumDay);
  const hours_night = round2(sumNight);
  const hours_sat   = round2(sumSat);
  const hours_sun   = round2(sumSun);
  const hours_bh    = round2(sumBh);
  const total_hours = round2(hours_day + hours_night + hours_sat + hours_sun + hours_bh);

  const priorUnits =
    (ib && typeof ib === 'object' && ib.additional && typeof ib.additional === 'object' && ib.additional.units && typeof ib.additional.units === 'object')
      ? ib.additional.units
      : addlUnitsJson;

  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,

    basis: curFin?.basis || 'CONTRACT_WEEKLY',
    candidate_id: contract.candidate_id || null,
    client_id: contract.client_id || null,
    role: contract.role || null,
    band: contract.band || null,
    pay_method: method,

    policy_snapshot_json,
    rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract.id || null },

    hours_day,
    hours_night,
    hours_sat,
    hours_sun,
    hours_bh,
    total_hours,

    pay_day: pay.day, pay_night: pay.night, pay_sat: pay.sat, pay_sun: pay.sun, pay_bh: pay.bh,
    charge_day: chg.day, charge_night: chg.night, charge_sat: chg.sat, charge_sun: chg.sun, charge_bh: chg.bh,

    additional_units_json: addlUnitsJson,
    additional_pay_ex_vat: addlPay,
    additional_charge_ex_vat: addlChg,
    additional_margin_ex_vat: addlMar,

    total_pay_ex_vat: totalPayEx,
    total_charge_ex_vat: totalChgEx,
    margin_ex_vat: marginEx,

    expenses_pay_ex_vat: expPayEff,
    expenses_charge_ex_vat: expChgEff,
    expenses_description: curFin?.expenses_description ?? null,
    expenses_evidence_r2_key: curFin?.expenses_evidence_r2_key ?? null,
    expenses_evidence_manifest: curFin?.expenses_evidence_manifest ?? null,

    travel_pay_ex_vat: round2(asNumberLocal(curFin?.travel_pay_ex_vat ?? 0)),
    travel_charge_ex_vat: round2(asNumberLocal(curFin?.travel_charge_ex_vat ?? 0)),
    accommodation_pay_ex_vat: round2(asNumberLocal(curFin?.accommodation_pay_ex_vat ?? 0)),
    accommodation_charge_ex_vat: round2(asNumberLocal(curFin?.accommodation_charge_ex_vat ?? 0)),
    other_pay_ex_vat: round2(asNumberLocal(curFin?.other_pay_ex_vat ?? 0)),
    other_charge_ex_vat: round2(asNumberLocal(curFin?.other_charge_ex_vat ?? 0)),

    mileage_units: milUnits,
    mileage_pay_ex_vat: milPay,
    mileage_charge_ex_vat: milChg,
    mileage_evidence_r2_key: curFin?.mileage_evidence_r2_key ?? null,
    mileage_evidence_manifest: curFin?.mileage_evidence_manifest ?? null,
    mileage_pay_rate: curFin?.mileage_pay_rate ?? null,
    mileage_charge_rate: curFin?.mileage_charge_rate ?? null,

    candidate_assignment: (contract.candidate_id ? 'ASSIGNED' : 'UNASSIGNED'),
    processing_status,

    invoice_breakdown_json: {
      mode: 'SEGMENTS',
      segments: nextSegments,
      additional: {
        units: priorUnits || {},
        pay_ex_vat: nonsegPay,
        charge_ex_vat: nonsegChg,
        margin_ex_vat: nonsegMar
      },
      totals: {
        total_pay_ex_vat: totalPayEx,
        total_charge_ex_vat: totalChgEx,
        margin_ex_vat: marginEx
      }
    },

    external_source_rows_json: curFin?.external_source_rows_json || {}
  };

  if (typeof enrichTsfinWithHrCrosscheck === 'function') {
    try { await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null); } catch {}
  }

  if (write_now) {
    if (!outbox_id) throw new Error('rebuildFromExistingSegmentsEvidence: write_now requires options.outbox_id');
    const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
      rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
    });
    return { ok: true, snapshot, write: wr };
  }

  return { ok: true, snapshot };
}


async function tsfinTargetedDrainNow(env, {
  timesheetIds = [],
  reason = 'CONTEXT_CHANGED',
  chunkSize = 50,

  // ✅ NEW (backwards-compatible):
  // If true, drains to completion for ALL provided timesheetIds (Strategy A helper).
  // Default false preserves existing behaviour (enqueue all; drain only a small inline set).
  drainAll = false,

  // ✅ NEW (used only when drainAll=true):
  // Safety caps to avoid runaway loops / budgets.
  maxLoops = 60,

  // ✅ NEW (used only when drainAll=true):
  // Limit per runTsfinWorkerOnce iteration (keeps subrequest budget stable).
  drainLimit = 50
} = {}) {
  const LOG = (typeof wranglerimportlog !== 'undefined' && wranglerimportlog === true);
  const L = (...a) => { if (LOG) console.log('[TSFIN][TARGET]', ...a); };

  const unwrapRpcJsonb = (raw, fnName) => {
    const j = raw;
    if (Array.isArray(j)) {
      const row0 = j[0];
      if (row0 && typeof row0 === 'object' && fnName && Object.prototype.hasOwnProperty.call(row0, fnName)) {
        return row0[fnName];
      }
      return row0;
    }
    if (j && typeof j === 'object' && fnName && Object.prototype.hasOwnProperty.call(j, fnName)) {
      return j[fnName];
    }
    return j;
  };

  // Load TSFIN knobs (adaptability layer)
  // Falls back safely if settings load fails
  let cfg = null;
  try { cfg = await loadSettingsDefaults(env); } catch {}
  const tsfinCfg = cfg?.importConfig?.tsfin || {};

  const maxInlineItems =
    Number(tsfinCfg.maxInlineItems || 0) > 0 ? Number(tsfinCfg.maxInlineItems) : 3;

  const maxLoopsCfg =
    Number(tsfinCfg.maxDrainLoops || 0) > 0 ? Number(tsfinCfg.maxDrainLoops) : null;

  const drainLimitCfg =
    Number(tsfinCfg.drainLimit || 0) > 0 ? Number(tsfinCfg.drainLimit) : null;

  const effectiveMaxLoops = drainAll ? (maxLoopsCfg ?? maxLoops ?? 60) : 0;
  const effectiveDrainLimit = drainAll ? (drainLimitCfg ?? drainLimit ?? 50) : 0;

  // Dedupe and normalize input ids
  const uniq = Array.from(new Set((timesheetIds || [])
    .map(x => String(x || '').trim())
    .filter(Boolean)));

  if (!uniq.length) {
    return {
      enqueued: 0,
      processed_now: 0,
      deferred: 0,
      ran: 0,
      picked: 0,
      ok: 0,
      fail: 0,

      // NEW (safe additions)
      drain_all: !!drainAll,
      loops: 0,
      pending_total: 0,
      pending_ready: 0,
      pending_next_attempt_at_min: null,
      done: true
    };
  }

  // Preserve legacy behavior unless drainAll is requested:
  // enqueue ALL; drain only a small number inline (configurable)
  const inlineIds = drainAll ? uniq : uniq.slice(0, maxInlineItems);
  const deferred = drainAll ? 0 : Math.max(0, uniq.length - inlineIds.length);

  L('START', {
    total: uniq.length,
    inline: inlineIds.length,
    deferred,
    reason,
    chunkSize,
    maxInlineItems,
    drainAll,
    maxLoops: effectiveMaxLoops,
    drainLimit: effectiveDrainLimit
  });

  let enq = 0;
  let ran = 0;
  let picked = 0;
  let ok = 0;
  let fail = 0;
  let loops = 0;

  let pendingTotal = 0;
  let pendingReady = 0;
  let pendingNextAttemptAtMin = null;

  // Enqueue all IDs (priority enqueue), chunked
  for (let i = 0; i < uniq.length; i += chunkSize) {
    const chunk = uniq.slice(i, i + chunkSize);
    try {
      const res = await sbRpc(env, 'enqueue_ts_financials_priority', {
        _timesheet_ids: chunk,
        _reason: reason
      });

      // enqueue_ts_financials_priority returns integer in SQL.
      // PostgREST may return it as a number or as [{...}].
      // Treat success as "chunk.length enqueued" if we can't parse the return.
      let cnt = 0;
      if (typeof res === 'number') cnt = res;
      else if (typeof res === 'string') {
        const n = Number(res);
        cnt = Number.isFinite(n) ? n : 0;
      } else if (Array.isArray(res) && res[0] != null) {
        const v = res[0]?.enqueue_ts_financials_priority ?? res[0]?.count ?? res[0]?.row_count ?? null;
        const n = Number(v);
        cnt = Number.isFinite(n) ? n : 0;
      }

      enq += (cnt > 0 ? cnt : chunk.length);

      L('ENQ_OK', { chunk: chunk.length, parsed_count: cnt });
    } catch (e) {
      const msg = String(e?.message || e || '');
      console.warn('[TSFIN][TARGET] enqueue_ts_financials_priority failed', msg);
      L('ENQ_FAIL', { chunk: chunk.length, err: msg });
      // Continue; some ids may already be enqueued from earlier calls.
    }
  }

  const getPendingSummary = async () => {
    const raw = await sbRpc(env, 'tsfin_outbox_pending_summary', {
      p_timesheet_ids: uniq
    });
    const payload = unwrapRpcJsonb(raw, 'tsfin_outbox_pending_summary');
    const total = Number(payload?.total ?? 0);
    const ready = Number(payload?.ready ?? 0);
    return {
      total: Number.isFinite(total) ? total : 0,
      ready: Number.isFinite(ready) ? ready : 0,
      next_attempt_at_min: payload?.next_attempt_at_min ?? null
    };
  };

  // Drain mode A (legacy): drain only inlineIds once
  if (!drainAll) {
    if (inlineIds.length) {
      try {
        const res = await runTsfinWorkerOnce(env, {
          limit: inlineIds.length,
          onlyTimesheetIds: inlineIds
        });

        ran += 1;
        picked += Number(res?.picked || 0);
        ok += Number(res?.ok || 0);
        fail += Number(res?.fail || 0);

        L('DRAIN_OK', { ran, picked, ok, fail });
      } catch (e) {
        const msg = String(e?.message || e || '');
        console.warn('[TSFIN][TARGET] runTsfinWorkerOnce failed', msg);
        L('DRAIN_FAIL', { err: msg });
      }
    }

    // Legacy return contract
    return {
      enqueued: enq,
      processed_now: inlineIds.length,
      deferred,
      ran,
      picked,
      ok,
      fail,

      // NEW (safe additions)
      drain_all: false,
      loops: 0,
      pending_total: null,
      pending_ready: null,
      pending_next_attempt_at_min: null,
      done: null
    };
  }

  // Drain mode B (Strategy A): drain-to-completion across ALL ids
  // Deterministic completion is defined as: pending_total == 0
  // If outbox rows remain but none are ready (next_attempt_at in future) or leased elsewhere, we return done=false.
  let done = true;

  try {
    for (loops = 0; loops < effectiveMaxLoops; loops++) {
      const res = await runTsfinWorkerOnce(env, {
        limit: Math.max(1, Math.min(effectiveDrainLimit, uniq.length)),
        onlyTimesheetIds: uniq
      });

      ran += 1;
      picked += Number(res?.picked || 0);
      ok += Number(res?.ok || 0);
      fail += Number(res?.fail || 0);

      const pending = await getPendingSummary();
      pendingTotal = pending.total;
      pendingReady = pending.ready;
      pendingNextAttemptAtMin = pending.next_attempt_at_min;

      L('DRAIN_LOOP', {
        loops: loops + 1,
        ran,
        picked,
        ok,
        fail,
        pendingTotal,
        pendingReady,
        pendingNextAttemptAtMin
      });

      if (pendingTotal === 0) {
        done = (fail === 0);
        break;
      }

      // If nothing picked but work still pending, we cannot claim completion:
      // could be leased, delayed, or otherwise not runnable "now".
      if (Number(res?.picked || 0) === 0) {
        done = false;
        break;
      }
    }

    if (pendingTotal > 0) done = false;
    if (fail > 0) done = false;
    if (loops >= effectiveMaxLoops && pendingTotal > 0) done = false;
  } catch (e) {
    const msg = String(e?.message || e || '');
    console.warn('[TSFIN][TARGET] drainAll loop exception', msg);
    L('DRAIN_ALL_EXCEPTION', { err: msg });
    done = false;
  }

  return {
    enqueued: enq,
    processed_now: uniq.length,
    deferred: 0,
    ran,
    picked,
    ok,
    fail,

    // NEW (safe additions)
    drain_all: true,
    loops,
    pending_total: pendingTotal,
    pending_ready: pendingReady,
    pending_next_attempt_at_min: pendingNextAttemptAtMin,
    done
  };
}


// ---------------------------
// Pay channel resolution (pure)
// ---------------------------
function resolveEffectivePayChannel(input) {
  const pm = (input.pay_method || '').toUpperCase();
  const cand = input.candidate || {};
  const umb = input.umbrella || {};

  const trim = (v) => (v ?? '').toString().trim() || null;

  if (pm === 'PAYE') {
    const out = {
      pay_method: 'PAYE',
      source: 'CANDIDATE',
      account_holder: trim(cand.account_holder),
      bank_name: trim(cand.bank_name),
      sort_code: trim(cand.sort_code),
      account_number: trim(cand.account_number)
    };
    const missing = [];
    if (!out.sort_code) missing.push('sort_code');
    if (!out.account_number) missing.push('account_number');
    return { ...out, ok: missing.length === 0, missing };
  }

  if (pm === 'UMBRELLA') {
    const out = {
      pay_method: 'UMBRELLA',
      source: 'UMBRELLA',
      account_holder: trim(umb.name) || null,
      bank_name: trim(umb.bank_name),
      sort_code: trim(umb.sort_code),
      account_number: trim(umb.account_number)
    };
    const missing = [];
    if (!trim(cand.umbrella_id)) missing.push('umbrella_id');
    if (!out.sort_code) missing.push('sort_code');
    if (!out.account_number) missing.push('account_number');
    return { ...out, ok: missing.length === 0, missing };
  }

  return {
    pay_method: pm || null,
    source: 'MISSING',
    account_holder: null,
    bank_name: null,
    sort_code: null,
    account_number: null,
    ok: false,
    missing: ['pay_method']
  };
}

