async function loadWeeklyContext(env, ts) {
  const enc = encodeURIComponent; // ✅ define here so global move is safe

  if (!ts || !ts.timesheet_id || !ts.contract_id || !ts.week_ending_date) {
    return null;
  }

  const cw = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/contract_weeks` +
      `?timesheet_id=eq.${enc(ts.timesheet_id)}` +
      `&select=*` +
      `&limit=1`
  );
  if (!cw) return null;

  const contract = await sbGetOne(
    env,
    `${env.SUPABASE_URL}/rest/v1/contracts` +
      `?id=eq.${enc(cw.contract_id)}` +
      `&select=*`
  );
  if (!contract) return null;

  return { cw, contract };
}


async function handleDocumentTemplatesList(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  try {
    const url = new URL(req.url);
    const entityTypeRaw = String(url.searchParams.get('entity_type') || '').trim();
    const outputTypeRaw = String(url.searchParams.get('output_type') || '').trim();

    const entityType = entityTypeRaw.toLowerCase();
    const outputType = outputTypeRaw.toUpperCase();

    if (!entityType) return withCORS(env, req, badRequest('entity_type is required'));
    if (!outputType) return withCORS(env, req, badRequest('output_type is required'));

    // Basic allowlist (matches DB usage; keep strict to prevent junk)
    const allowedEntity = new Set(['client', 'candidate', 'contract', 'timesheet', 'invoice', 'umbrella']);
    const allowedOutput = new Set(['EMAIL', 'WORD', 'EXCEL', 'WHATSAPP', 'SMS', 'VOICE', 'SIGNATURE']);

    if (!allowedEntity.has(entityType)) return withCORS(env, req, badRequest('invalid_entity_type'));
    if (!allowedOutput.has(outputType)) return withCORS(env, req, badRequest('invalid_output_type'));

    const rpcRes = await sbRpc(env, 'document_templates_list', {
      p_entity_type: entityType,
      p_output_type: outputType
    });

    const items = Array.isArray(rpcRes) ? rpcRes : [];

    return withCORS(env, req, ok({ ok: true, items }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to list document templates');
    return withCORS(env, req, serverError(msg));
  }
}


async function handleDocumentTemplatesGet(env, req, templateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  const id = String(templateId || '').trim();
  if (!id) return withCORS(env, req, badRequest('template_id is required'));
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    return withCORS(env, req, badRequest('invalid_template_id'));
  }

  try {
    let payload = await sbRpc(env, 'document_templates_get', { p_template_id: id });

    // Normalize possible wrappers (supabase/postgrest sometimes wraps)
    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'document_templates_get')) {
        payload = payload.document_templates_get;
      }
    } catch {}

    if (!payload || typeof payload !== 'object') {
      return withCORS(env, req, notFound('document_template not found'));
    }

    return withCORS(env, req, ok({ ok: true, template: payload }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to fetch document template');
    return withCORS(env, req, serverError(msg));
  }
}


async function handleMailshotFieldsList(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  try {
    const url = new URL(req.url);

    const entityTypeRaw = String(url.searchParams.get('entity_type') || '').trim();
    const includeDisabledRaw = String(url.searchParams.get('include_disabled') || '').trim().toLowerCase();

    const entityType = entityTypeRaw ? entityTypeRaw.toLowerCase() : null;

    const includeDisabled =
      includeDisabledRaw === 'true' ||
      includeDisabledRaw === '1' ||
      includeDisabledRaw === 'yes' ||
      includeDisabledRaw === 'y' ||
      includeDisabledRaw === 'on';

    if (entityType != null) {
      const allowedEntity = new Set(['client', 'candidate', 'contract', 'timesheet', 'invoice', 'umbrella']);
      if (!allowedEntity.has(entityType)) {
        return withCORS(env, req, badRequest('invalid_entity_type'));
      }
    }

    const rpcRes = await sbRpc(env, 'mailshot_fields_catalog_list', {
      p_entity_type: entityType,
      p_include_disabled: includeDisabled
    });

    const rows = Array.isArray(rpcRes) ? rpcRes : [];

    const items = rows.map((row) => {
      const raw = (row && typeof row === 'object') ? row : {};

      const fieldId = raw.field_id != null ? String(raw.field_id) : null;
      const fieldKey = raw.field_key != null ? String(raw.field_key) : '';
      const sourceFamily = raw.source_family != null ? String(raw.source_family) : '';
      const labelDefault = raw.label_default != null ? String(raw.label_default) : '';
      const labelOverride = raw.label_override == null ? null : String(raw.label_override);
      const labelEffective =
        raw.label_effective != null
          ? String(raw.label_effective)
          : (labelOverride != null && labelOverride !== '' ? labelOverride : labelDefault);

      const enabledGlobal = raw.enabled_global != null ? !!raw.enabled_global : true;
      const enabledLocal = raw.enabled_local == null ? null : !!raw.enabled_local;
      const enabledEffective =
        raw.enabled_effective != null
          ? !!raw.enabled_effective
          : (enabledLocal == null ? enabledGlobal : (enabledGlobal && enabledLocal));

      const allowedEntityTypes = Array.isArray(raw.allowed_entity_types)
        ? raw.allowed_entity_types.map((v) => String(v == null ? '' : v).trim().toLowerCase()).filter(Boolean)
        : [];

      const isResolvableForRoot =
        raw.is_resolvable_for_root == null
          ? null
          : !!raw.is_resolvable_for_root;

      const stale = !!raw.stale;
      const resolverSpecJson =
        raw.resolver_spec_json && typeof raw.resolver_spec_json === 'object' && !Array.isArray(raw.resolver_spec_json)
          ? raw.resolver_spec_json
          : {};

      const itemEntityType =
        raw.entity_type != null
          ? String(raw.entity_type).trim().toLowerCase()
          : entityType;

      return {
        field_id: fieldId,
        id: fieldId,
        field_key: fieldKey,
        source_family: sourceFamily,
        entity_type: itemEntityType,
        label_default: labelDefault,
        label_override: labelOverride,
        label_effective: labelEffective,
        enabled_global: enabledGlobal,
        enabled_local: enabledLocal,
        enabled_effective: enabledEffective,
        allowed_entity_types: allowedEntityTypes,
        is_resolvable_for_root: isResolvableForRoot,
        stale,
        resolver_spec_json: resolverSpecJson,

        global_label: labelDefault,
        override_label: labelOverride,
        effective_label: labelEffective,
        global_enabled: enabledGlobal,
        override_enabled: enabledLocal,
        effective_enabled: enabledEffective,
        label: labelDefault,
        enabled: enabledGlobal,

        raw
      };
    });

    return withCORS(env, req, ok({
      ok: true,
      entity_type: entityType,
      include_disabled: includeDisabled,
      items
    }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to list mailshot fields');
    return withCORS(env, req, serverError(msg));
  }
}

async function handleMailshotFieldsUpsertGlobal(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const fieldIdRaw = (body.field_id ?? body.fieldId ?? body.id);
  const fieldKeyRaw = (body.field_key ?? body.fieldKey);
  const entityTypeRaw = (body.entity_type ?? body.entityType);
  const labelDefaultRaw = (body.label_default ?? body.labelDefault ?? body.label ?? body.global_label ?? body.globalLabel);
  const enabledGlobalRaw = (body.enabled_global ?? body.enabledGlobal ?? body.enabled ?? body.global_enabled ?? body.globalEnabled);

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  const fieldId = (fieldIdRaw == null) ? null : String(fieldIdRaw).trim();
  if (fieldId && !uuidRe.test(fieldId)) return withCORS(env, req, badRequest('invalid_field_id'));

  const fieldKey = (fieldKeyRaw == null) ? '' : String(fieldKeyRaw).trim();
  if (fieldKey && fieldKey.indexOf('.') === -1) {
    return withCORS(env, req, badRequest('field_key must be namespaced'));
  }

  const entityType = (entityTypeRaw == null) ? '' : String(entityTypeRaw).trim().toLowerCase();
  if (entityType) {
    const allowedEntity = new Set(['client', 'candidate', 'contract', 'timesheet', 'invoice', 'umbrella']);
    if (!allowedEntity.has(entityType)) return withCORS(env, req, badRequest('invalid_entity_type'));
  }

  const labelDefault = (labelDefaultRaw == null) ? null : (String(labelDefaultRaw).trim() || null);

  const parseOptionalBool = (v) => {
    if (v == null) return { ok: true, value: null };
    if (typeof v === 'boolean') return { ok: true, value: v };
    const s = String(v).trim().toLowerCase();
    if (!s) return { ok: true, value: null };
    if (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on') return { ok: true, value: true };
    if (s === 'false' || s === '0' || s === 'no' || s === 'n' || s === 'off') return { ok: true, value: false };
    return { ok: false, value: null };
  };

  const enabledParsed = parseOptionalBool(enabledGlobalRaw);
  if (!enabledParsed.ok) return withCORS(env, req, badRequest('invalid_enabled_global'));
  const enabledGlobal = enabledParsed.value;

  if (!fieldId && !fieldKey) {
    return withCORS(env, req, badRequest('field_id or field_key is required'));
  }

  try {
    let payload = await sbRpc(env, 'mailshot_fields_upsert_global', {
      p_field_id: fieldId || null,
      p_field_key: fieldKey || null,
      p_label_default: labelDefault,
      p_enabled_global: enabledGlobal,
      p_allowed_entity_types: null,
      p_resolver_spec_json: null,
      p_actor_user_id: user.id
    });

    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'mailshot_fields_upsert_global')) {
        payload = payload.mailshot_fields_upsert_global;
      }
    } catch {}

    const rawField =
      (payload && payload.field && typeof payload.field === 'object') ? payload.field :
      (payload && typeof payload === 'object') ? payload :
      null;

    if (!rawField || typeof rawField !== 'object') {
      return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
    }

    const item = {
      field_id: rawField.id != null ? String(rawField.id) : (fieldId || null),
      id: rawField.id != null ? String(rawField.id) : (fieldId || null),
      field_key: rawField.field_key != null ? String(rawField.field_key) : fieldKey,
      entity_type: entityType || null,
      label_default: rawField.label_default != null ? String(rawField.label_default) : (labelDefault || ''),
      label: rawField.label_default != null ? String(rawField.label_default) : (labelDefault || ''),
      global_label: rawField.label_default != null ? String(rawField.label_default) : (labelDefault || ''),
      enabled_global: rawField.enabled_global != null ? !!rawField.enabled_global : (enabledGlobal == null ? true : !!enabledGlobal),
      enabled: rawField.enabled_global != null ? !!rawField.enabled_global : (enabledGlobal == null ? true : !!enabledGlobal),
      global_enabled: rawField.enabled_global != null ? !!rawField.enabled_global : (enabledGlobal == null ? true : !!enabledGlobal),
      allowed_entity_types: Array.isArray(rawField.allowed_entity_types) ? rawField.allowed_entity_types : [],
      resolver_spec_json: rawField.resolver_spec_json && typeof rawField.resolver_spec_json === 'object' && !Array.isArray(rawField.resolver_spec_json)
        ? rawField.resolver_spec_json
        : {},
      created_at_utc: rawField.created_at_utc != null ? String(rawField.created_at_utc) : null,
      updated_at_utc: rawField.updated_at_utc != null ? String(rawField.updated_at_utc) : null,
      raw: rawField
    };

    return withCORS(env, req, ok({
      ok: true,
      field: item,
      item
    }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to upsert mailshot field');
    return withCORS(env, req, serverError(msg));
  }
}


async function handleMailshotFieldsUpsertOverride(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  const fieldIdRaw = (body.field_id ?? body.fieldId ?? body.id);
  const fieldKeyRaw = (body.field_key ?? body.fieldKey);
  const entityTypeRaw = (body.entity_type ?? body.entityType);
  const labelOverrideRaw = (body.label_override ?? body.labelOverride ?? body.override_label ?? body.overrideLabel);
  const enabledLocalRaw = (body.enabled_local ?? body.enabledLocal ?? body.override_enabled ?? body.overrideEnabled ?? body.enabled_override ?? body.enabledOverride);

  let fieldId = (fieldIdRaw == null) ? '' : String(fieldIdRaw).trim();
  const fieldKey = (fieldKeyRaw == null) ? '' : String(fieldKeyRaw).trim();

  if (!fieldId && !fieldKey) {
    return withCORS(env, req, badRequest('field_id or field_key is required'));
  }

  if (fieldId && !uuidRe.test(fieldId)) {
    return withCORS(env, req, badRequest('invalid_field_id'));
  }

  if (fieldKey && fieldKey.indexOf('.') === -1) {
    return withCORS(env, req, badRequest('field_key must be namespaced'));
  }

  const entityType = (entityTypeRaw == null) ? '' : String(entityTypeRaw).trim().toLowerCase();
  if (!entityType) return withCORS(env, req, badRequest('entity_type is required'));

  const allowedEntity = new Set(['client', 'candidate', 'contract', 'timesheet', 'invoice', 'umbrella']);
  if (!allowedEntity.has(entityType)) return withCORS(env, req, badRequest('invalid_entity_type'));

  const labelOverride = (labelOverrideRaw == null) ? null : (String(labelOverrideRaw).trim() || null);

  const parseOptionalBool = (v) => {
    if (v == null) return { ok: true, value: null };
    if (typeof v === 'boolean') return { ok: true, value: v };
    const s = String(v).trim().toLowerCase();
    if (!s) return { ok: true, value: null };
    if (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on') return { ok: true, value: true };
    if (s === 'false' || s === '0' || s === 'no' || s === 'n' || s === 'off') return { ok: true, value: false };
    return { ok: false, value: null };
  };

  const enabledParsed = parseOptionalBool(enabledLocalRaw);
  if (!enabledParsed.ok) return withCORS(env, req, badRequest('invalid_enabled_local'));
  const enabledLocal = enabledParsed.value;

  let resolvedFieldKey = fieldKey;

  if (!fieldId) {
    const enc = encodeURIComponent;

    try {
      const { rows } = await sbFetch(
        env,
        `${env.SUPABASE_URL}/rest/v1/mailshot_fields` +
          `?field_key=eq.${enc(fieldKey)}` +
          `&select=id,field_key` +
          `&limit=1`
      );

      const row = (rows && rows[0]) || null;
      if (!row || !row.id) {
        return withCORS(env, req, badRequest('field_key not found'));
      }

      fieldId = String(row.id).trim();
      resolvedFieldKey = row.field_key != null ? String(row.field_key) : fieldKey;
    } catch (e) {
      const msg = String(e?.message || e || 'Failed to resolve field_key');
      return withCORS(env, req, serverError(msg));
    }
  }

  try {
    let payload = await sbRpc(env, 'mailshot_fields_upsert_override', {
      p_field_id: fieldId,
      p_entity_type: entityType,
      p_label_override: labelOverride,
      p_enabled_local: enabledLocal,
      p_actor_user_id: user.id
    });

    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'mailshot_fields_upsert_override')) {
        payload = payload.mailshot_fields_upsert_override;
      }
    } catch {}

    const rawOverride =
      (payload && payload.override && typeof payload.override === 'object') ? payload.override :
      (payload && typeof payload === 'object') ? payload :
      null;

    if (!rawOverride || typeof rawOverride !== 'object') {
      return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
    }

    const item = {
      id: rawOverride.id != null ? String(rawOverride.id) : null,
      override_id: rawOverride.id != null ? String(rawOverride.id) : null,
      field_id: rawOverride.field_id != null ? String(rawOverride.field_id) : fieldId,
      field_key: resolvedFieldKey || null,
      entity_type: rawOverride.entity_type != null ? String(rawOverride.entity_type).toLowerCase() : entityType,
      label_override: rawOverride.label_override == null ? labelOverride : String(rawOverride.label_override),
      override_label: rawOverride.label_override == null ? labelOverride : String(rawOverride.label_override),
      enabled_local: rawOverride.enabled_local != null ? !!rawOverride.enabled_local : enabledLocal,
      override_enabled: rawOverride.enabled_local != null ? !!rawOverride.enabled_local : enabledLocal,
      raw: rawOverride
    };

    return withCORS(env, req, ok({
      ok: true,
      override: item,
      item
    }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to upsert mailshot field override');
    return withCORS(env, req, serverError(msg));
  }
}

async function handleMailshotFieldsBulkApply(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const fieldIdsRaw = (body.field_ids ?? body.fieldIds ?? body.ids);
  const actionRaw = (body.action ?? body.bulk_action ?? body.bulkAction);
  const entityTypeRaw = (body.entity_type ?? body.entityType);

  let fieldIds = fieldIdsRaw;
  if (fieldIds == null) fieldIds = [];
  if (typeof fieldIds === 'string') {
    try {
      fieldIds = JSON.parse(fieldIds);
    } catch {
      return withCORS(env, req, badRequest('field_ids must be an array (or JSON string array)'));
    }
  }
  if (!Array.isArray(fieldIds)) {
    return withCORS(env, req, badRequest('field_ids must be an array'));
  }

  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  const cleanFieldIds = [];
  for (const value of fieldIds) {
    const id = String(value == null ? '' : value).trim();
    if (!id) continue;
    if (!uuidRe.test(id)) return withCORS(env, req, badRequest('invalid_field_id'));
    cleanFieldIds.push(id);
  }

  if (!cleanFieldIds.length) {
    return withCORS(env, req, badRequest('field_ids is required'));
  }

  const action = String(actionRaw == null ? '' : actionRaw).trim().toUpperCase();
  if (!action) return withCORS(env, req, badRequest('action is required'));

  const allowedActions = new Set([
    'GLOBAL_ENABLE',
    'GLOBAL_DISABLE',
    'ADD_VISIBLE_IN_ENTITY',
    'REMOVE_VISIBLE_IN_ENTITY',
    'OVERRIDE_ENABLE',
    'OVERRIDE_DISABLE',
    'CLEAR_OVERRIDE'
  ]);
  if (!allowedActions.has(action)) {
    return withCORS(env, req, badRequest('invalid_action'));
  }

  const entityType = entityTypeRaw == null ? null : (String(entityTypeRaw).trim().toLowerCase() || null);
  const allowedEntity = new Set(['client', 'candidate', 'contract', 'timesheet', 'invoice', 'umbrella']);
  if (entityType != null && !allowedEntity.has(entityType)) {
    return withCORS(env, req, badRequest('invalid_entity_type'));
  }

  const requiresEntity = new Set([
    'ADD_VISIBLE_IN_ENTITY',
    'REMOVE_VISIBLE_IN_ENTITY',
    'OVERRIDE_ENABLE',
    'OVERRIDE_DISABLE',
    'CLEAR_OVERRIDE'
  ]);
  if (requiresEntity.has(action) && !entityType) {
    return withCORS(env, req, badRequest('entity_type is required'));
  }

  try {
    let payload = await sbRpc(env, 'mailshot_fields_bulk_apply', {
      p_field_ids: cleanFieldIds,
      p_action: action,
      p_entity_type: entityType,
      p_actor_user_id: user.id
    });

    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'mailshot_fields_bulk_apply')) {
        payload = payload.mailshot_fields_bulk_apply;
      }
    } catch {}

    return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to apply bulk mailshot field action');
    return withCORS(env, req, serverError(msg));
  }
}

async function handleMailshotFieldsSeedFromSchema(env, req) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  try {
    let payload = await sbRpc(env, 'mailshot_fields_seed_from_schema', {
      p_actor_user_id: user.id
    });

    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') {
        payload = payload[0];
      }
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'mailshot_fields_seed_from_schema')) {
        payload = payload.mailshot_fields_seed_from_schema;
      }
    } catch {}

    const normalized = (payload && typeof payload === 'object' && !Array.isArray(payload))
      ? { ...payload }
      : { ok: true, result: payload };

    normalized.operation = 'refresh_catalogue_from_approved_views';
    normalized.message = 'Catalogue refreshed from approved views';

    return withCORS(env, req, ok(normalized));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to refresh catalogue from approved views');
    return withCORS(env, req, serverError(msg));
  }
}
async function handleDocumentTemplatesUpsert(env, req, templateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const idFromPath = (templateId == null) ? null : String(templateId || '').trim();
  if (idFromPath && !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(idFromPath)) {
    return withCORS(env, req, badRequest('invalid_template_id'));
  }

  const entityTypeRaw = String(body.entity_type || body.entityType || '').trim();
  const outputTypeRaw = String(body.output_type || body.outputType || '').trim();
  const filenameRaw = String(body.filename || body.file_name || '').trim();

  const entityType = entityTypeRaw.toLowerCase();
  const outputType = outputTypeRaw.toUpperCase();
  const filename = filenameRaw;

  if (!entityType) return withCORS(env, req, badRequest('entity_type is required'));
  if (!outputType) return withCORS(env, req, badRequest('output_type is required'));
  if (!filename) return withCORS(env, req, badRequest('filename is required'));

  const allowedEntity = new Set(['client', 'candidate', 'contract', 'timesheet', 'invoice', 'umbrella']);
  const allowedOutput = new Set(['EMAIL', 'WORD', 'EXCEL', 'WHATSAPP', 'SMS', 'VOICE']);

  if (!allowedEntity.has(entityType)) return withCORS(env, req, badRequest('invalid_entity_type'));
  if (!allowedOutput.has(outputType)) return withCORS(env, req, badRequest('invalid_output_type'));

  const description = (body.description == null) ? null : String(body.description);
  const emailTypeRaw = (body.email_type ?? body.emailType);
  const emailType = (emailTypeRaw == null) ? null : String(emailTypeRaw || '').trim().toLowerCase() || null;

  if (emailType != null && emailType !== 'plain' && emailType !== 'html') {
    return withCORS(env, req, badRequest('invalid_email_type'));
  }

  let selectedFieldKeys = body.selected_field_keys ?? body.selectedFieldKeys;
  if (selectedFieldKeys == null) selectedFieldKeys = [];
  if (typeof selectedFieldKeys === 'string') {
    try {
      const j = JSON.parse(selectedFieldKeys);
      selectedFieldKeys = j;
    } catch {
      return withCORS(env, req, badRequest('selected_field_keys must be an array (or JSON string array)'));
    }
  }
  if (!Array.isArray(selectedFieldKeys)) {
    return withCORS(env, req, badRequest('selected_field_keys must be an array'));
  }
  selectedFieldKeys = selectedFieldKeys
    .map((x) => (x == null ? '' : String(x).trim()))
    .filter(Boolean);

  let templateContent = body.template_content_json ?? body.templateContentJson ?? body.template_content ?? body.templateContent;
  if (templateContent == null) templateContent = {};
  if (typeof templateContent === 'string') {
    try {
      const j = JSON.parse(templateContent);
      templateContent = j;
    } catch {
      return withCORS(env, req, badRequest('template_content_json must be an object (or JSON string object)'));
    }
  }
  if (!(templateContent && typeof templateContent === 'object' && !Array.isArray(templateContent))) {
    return withCORS(env, req, badRequest('template_content_json must be an object'));
  }

  const trimStr = (v) => String(v == null ? '' : v).trim();
  const isPlainObject = (v) => !!(v && typeof v === 'object' && !Array.isArray(v));
  const own = (obj, key) => Object.prototype.hasOwnProperty.call(obj || {}, key);

  const failBadRequest = (message) => {
    const err = new Error(String(message || 'Invalid request'));
    err.__badRequest = true;
    throw err;
  };

  const parseBooleanField = (obj, snakeKey, camelKey, path) => {
    if (own(obj, snakeKey)) {
      if (typeof obj[snakeKey] !== 'boolean') failBadRequest(`${path} must be boolean`);
      return !!obj[snakeKey];
    }
    if (own(obj, camelKey)) {
      if (typeof obj[camelKey] !== 'boolean') failBadRequest(`${path.replace(snakeKey, camelKey)} must be boolean`);
      return !!obj[camelKey];
    }
    return false;
  };

  const parseOptionalNonNegativeInteger = (obj, snakeKey, camelKey, path) => {
    const rawSnake = trimStr(obj && obj[snakeKey]);
    const rawCamel = trimStr(obj && obj[camelKey]);

    if (rawSnake) {
      if (!/^\d+$/.test(rawSnake)) failBadRequest(`${path} must be non-negative integer`);
      return Math.trunc(Number(rawSnake));
    }
    if (rawCamel) {
      const camelPath = path.replace(snakeKey, camelKey);
      if (!/^\d+$/.test(rawCamel)) failBadRequest(`${camelPath} must be non-negative integer`);
      return Math.trunc(Number(rawCamel));
    }
    return null;
  };

  const sanitizeFilenameSegment = (name) => {
    const base = trimStr(name)
      .replace(/[/\\?%*:|"<>]/g, '_')
      .replace(/\s+/g, '_')
      .replace(/_+/g, '_')
      .replace(/^_+|_+$/g, '');
    return base || 'attachment';
  };

  const decodeBase64Payload = (value, path) => {
    const rawInput = trimStr(value);
    if (!rawInput) failBadRequest(`${path}.r2_key required`);

    let contentTypeFromDataUrl = '';
    let base64Part = rawInput;

    const dataUrlMatch = /^data:([^;,]+)?;base64,(.*)$/is.exec(rawInput);
    if (dataUrlMatch) {
      contentTypeFromDataUrl = trimStr(dataUrlMatch[1] || '');
      base64Part = trimStr(dataUrlMatch[2] || '');
    }

    const cleanBase64 = base64Part.replace(/[\r\n\s]/g, '');
    if (!cleanBase64) failBadRequest(`${path}.r2_key required`);

    const padLen = (4 - (cleanBase64.length % 4)) % 4;
    const paddedBase64 = cleanBase64 + '='.repeat(padLen);

    let binary = '';
    try {
      binary = atob(paddedBase64);
    } catch {
      failBadRequest(`${path}.contentBase64 must be valid base64`);
    }

    const bytes = new Uint8Array(binary.length);
    for (let idx = 0; idx < binary.length; idx += 1) {
      bytes[idx] = binary.charCodeAt(idx);
    }

    return {
      bytes,
      contentTypeFromDataUrl
    };
  };

  try {
    if (own(templateContent, 'mailshot_attachments')) {
      if (!isPlainObject(templateContent.mailshot_attachments)) {
        return withCORS(env, req, badRequest('mailshot_attachments must be object'));
      }

      const bucket = env.DOCS_BUCKET || env.R2 || env.R2_BUCKET || env.FILES_BUCKET;
      const attachmentCfg = templateContent.mailshot_attachments || {};

      if (own(attachmentCfg, 'attachments') && !Array.isArray(attachmentCfg.attachments)) {
        return withCORS(env, req, badRequest('mailshot_attachments.attachments must be array'));
      }
      if (own(attachmentCfg, 'template_files') && !Array.isArray(attachmentCfg.template_files)) {
        return withCORS(env, req, badRequest('mailshot_attachments.template_files must be array'));
      }
      if (own(attachmentCfg, 'files') && !Array.isArray(attachmentCfg.files)) {
        return withCORS(env, req, badRequest('mailshot_attachments.files must be array'));
      }

      const attachTimesheetPdf = parseBooleanField(
        attachmentCfg,
        'attach_authoritative_timesheet_pdf',
        'attachAuthoritativeTimesheetPdf',
        'mailshot_attachments.attach_authoritative_timesheet_pdf'
      );
      const attachInvoicePdf = parseBooleanField(
        attachmentCfg,
        'attach_authoritative_invoice_pdf',
        'attachAuthoritativeInvoicePdf',
        'mailshot_attachments.attach_authoritative_invoice_pdf'
      );

      const attachmentsRaw = Array.isArray(attachmentCfg.attachments) ? attachmentCfg.attachments : [];
      const templateFilesRaw = Array.isArray(attachmentCfg.template_files) ? attachmentCfg.template_files : [];
      const filesRaw = Array.isArray(attachmentCfg.files) ? attachmentCfg.files : [];
      const totalInlineAttachmentItems = attachmentsRaw.length + templateFilesRaw.length + filesRaw.length;

      if (outputType !== 'EMAIL' && totalInlineAttachmentItems > 0) {
        return withCORS(env, req, badRequest('mailshot attachments are only supported for EMAIL templates'));
      }

      const normalizeAttachmentArray = async (items, arrayName) => {
        const out = [];

        for (let idx = 0; idx < items.length; idx += 1) {
          const raw = items[idx];
          const path = `mailshot_attachments.${arrayName}[${idx + 1}]`;

          if (!isPlainObject(raw)) failBadRequest(`${path} must be object`);

          const existingR2Key = trimStr(raw.r2_key ?? raw.r2Key ?? '');
          const rawContentBase64 = trimStr(raw.contentBase64 ?? raw.content_base64 ?? '');
          const filenameValue = trimStr(raw.filename ?? raw.file_name ?? raw.name ?? '');
          const sourceValue = trimStr(raw.source ?? '');
          const sourceLabelValue = trimStr(raw.source_label ?? raw.sourceLabel ?? '');
          const readOnlyValue = parseBooleanField(raw, 'read_only', 'readOnly', `${path}.read_only`);
          const sizeBytesValue = parseOptionalNonNegativeInteger(raw, 'size_bytes', 'sizeBytes', `${path}.size_bytes`);

          let contentTypeValue = trimStr(raw.content_type ?? raw.contentType ?? '');
          let normalizedR2Key = existingR2Key ? normalizeKey(existingR2Key) : '';

          if (normalizedR2Key) {
            if (!filenameValue) failBadRequest(`${path}.filename required`);

            out.push({
              r2_key: normalizedR2Key,
              filename: filenameValue,
              content_type: contentTypeValue || null,
              source: sourceValue || null,
              source_label: sourceLabelValue || null,
              read_only: readOnlyValue,
              size_bytes: sizeBytesValue
            });
            continue;
          }

          if (!rawContentBase64) {
            failBadRequest(`${path}.r2_key required`);
          }

          if (!filenameValue) {
            failBadRequest(`${path}.filename required`);
          }

          if (!bucket || typeof bucket.put !== 'function') {
            throw new Error('Storage not configured for template attachments (expected DOCS_BUCKET, R2, R2_BUCKET, or FILES_BUCKET with put())');
          }

          const decoded = decodeBase64Payload(rawContentBase64, path);
          if (!contentTypeValue) {
            contentTypeValue = trimStr(decoded.contentTypeFromDataUrl || '') || 'application/octet-stream';
          }

          const sizeBytesFinal = sizeBytesValue == null ? decoded.bytes.byteLength : sizeBytesValue;
          const safeFilename = sanitizeFilenameSegment(filenameValue);
          const dayPart = new Date().toISOString().slice(0, 10);
          const hashSeed = `${user.id}|${entityType}|${outputType}|${filenameValue}|${contentTypeValue}|${rawContentBase64}`;
          const contentHash = await sha256Hex(hashSeed);
          const generatedKey = normalizeKey(
            `mailshot-template-attachments/${dayPart}/${user.id}/${contentHash}_${crypto.randomUUID()}_${safeFilename}`
          );

          await bucket.put(generatedKey, decoded.bytes, {
            httpMetadata: { contentType: contentTypeValue || 'application/octet-stream' },
            customMetadata: {
              uploaded_by_user_id: String(user.id || ''),
              entity_type: entityType,
              output_type: outputType,
              template_id: String(idFromPath || ''),
              original_filename: filenameValue
            }
          });

          out.push({
            r2_key: generatedKey,
            filename: filenameValue,
            content_type: contentTypeValue || null,
            source: sourceValue || 'template_upload',
            source_label: sourceLabelValue || 'Uploaded with template',
            read_only: readOnlyValue,
            size_bytes: sizeBytesFinal
          });
        }

        return out;
      };

      const attachmentsNorm = await normalizeAttachmentArray(attachmentsRaw, 'attachments');
      const templateFilesNorm = await normalizeAttachmentArray(templateFilesRaw, 'template_files');
      const filesNorm = await normalizeAttachmentArray(filesRaw, 'files');

      templateContent = {
        ...templateContent,
        mailshot_attachments: {
          ...attachmentCfg,
          attach_authoritative_timesheet_pdf: attachTimesheetPdf,
          attach_authoritative_invoice_pdf: attachInvoicePdf,
          attachments: [...attachmentsNorm, ...templateFilesNorm, ...filesNorm]
        }
      };

      delete templateContent.mailshot_attachments.template_files;
      delete templateContent.mailshot_attachments.files;
    }
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to normalize template attachments');
    if (e && e.__badRequest) {
      return withCORS(env, req, badRequest(msg));
    }
    return withCORS(env, req, serverError(msg));
  }

  const p_template_id = idFromPath || null;

  try {
    let payload = await sbRpc(env, 'document_templates_upsert', {
      p_template_id,
      p_entity_type: entityType,
      p_output_type: outputType,
      p_filename: filename,
      p_description: description,
      p_email_type: emailType,
      p_selected_field_keys: selectedFieldKeys,
      p_template_content_json: templateContent,
      p_actor_user_id: user.id
    });

    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'document_templates_upsert')) {
        payload = payload.document_templates_upsert;
      }
    } catch {}

    return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to upsert document template');
    return withCORS(env, req, serverError(msg));
  }
}


async function handleDocumentTemplatesDuplicate(env, req, templateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  const id = String(templateId || '').trim();
  if (!id) return withCORS(env, req, badRequest('template_id is required'));
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    return withCORS(env, req, badRequest('invalid_template_id'));
  }

  let body;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const newFilenameRaw = String(body.new_filename || body.newFilename || '').trim();
  if (!newFilenameRaw) return withCORS(env, req, badRequest('new_filename is required'));

  try {
    let payload = await sbRpc(env, 'document_templates_duplicate', {
      p_template_id: id,
      p_new_filename: newFilenameRaw,
      p_actor_user_id: user.id
    });

    // Normalize possible wrappers
    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'document_templates_duplicate')) {
        payload = payload.document_templates_duplicate;
      }
    } catch {}

    return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to duplicate document template');
    return withCORS(env, req, serverError(msg));
  }
}

async function handleDocumentTemplatesDelete(env, req, templateId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized('Unauthorized'));

  const id = String(templateId || '').trim();
  if (!id) return withCORS(env, req, badRequest('template_id is required'));
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    return withCORS(env, req, badRequest('invalid_template_id'));
  }

  try {
    let payload = await sbRpc(env, 'document_templates_delete', {
      p_template_id: id,
      p_actor_user_id: user.id
    });

    // Normalize possible wrappers
    try {
      if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === 'object') payload = payload[0];
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'document_templates_delete')) {
        payload = payload.document_templates_delete;
      }
    } catch {}

    return withCORS(env, req, ok(payload && typeof payload === 'object' ? payload : { ok: true, result: payload }));
  } catch (e) {
    const msg = String(e?.message || e || 'Failed to delete document template');
    return withCORS(env, req, serverError(msg));
  }
}





async function handleTimesheetDeletePreview(env, req, timesheetId) {
  const user = await requireUser(env, req, ['admin']);
  if (!user) return withCORS(env, req, unauthorized());
  if (!timesheetId) return withCORS(env, req, badRequest('timesheet_id is required'));

  const enc = encodeURIComponent;

  const traceId = (() => {
    try {
      if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') {
        return globalThis.crypto.randomUUID();
      }
    } catch {}
    return `tsdelprev_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  })();

  const fail = (status, stage, message, details) => {
    try {
      console.error('[TS][DELETE_PREVIEW][FAIL]', {
        traceId,
        stage,
        status,
        message: String(message || ''),
        requested_timesheet_id: String(timesheetId || ''),
        details: details && typeof details === 'object' ? details : null
      });
    } catch {}

    const payload = {
      error: 'DELETE_PREVIEW_FAILED',
      trace_id: traceId,
      stage: String(stage || 'unknown'),
      message: String(message || 'Delete preview failed')
    };

    if (details != null) payload.details = details;

    return withCORS(
      env,
      req,
      new Response(JSON.stringify(payload), {
        status: Number(status || 500),
        headers: { 'Content-Type': 'application/json' }
      })
    );
  };

  let stage = 'start';

  try {
    stage = 'resolve_timesheet_to_current';
    const resolved = await resolveTimesheetToCurrent(env, timesheetId);
    if (!resolved || !resolved.current_timesheet_id) {
      return withCORS(env, req, notFound('Timesheet not found'));
    }

    const currentTimesheetId = String(resolved.current_timesheet_id);

    stage = 'load_timesheet_row';
    const cur = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&select=timesheet_id,booking_id,sheet_scope,is_adjustment,adjustment_origin,correction_id,correction_kind,contract_id,week_ending_date,status` +
        `&limit=1`
    );
    if (!cur) return withCORS(env, req, notFound('Timesheet not found'));

    const sheetScope = String(cur.sheet_scope || '').toUpperCase();
    const isWeekly = sheetScope === 'WEEKLY';
    const isAdjustment = cur.is_adjustment === true;

    const originUpper = String(cur.adjustment_origin || '').trim().toUpperCase();
    const hasCorrectionId = !!String(cur.correction_id || '').trim();
    const hasCorrectionKind = !!String(cur.correction_kind || '').trim();

    const isImportDerivedChild =
      isWeekly &&
      isAdjustment &&
      (
        originUpper === 'IMPORT_CORRECTION' ||
        originUpper === 'IMPORT_CANCELLATION' ||
        hasCorrectionId ||
        hasCorrectionKind
      );

    stage = 'load_tsfin_snapshot';

    // ✅ DB-verified columns on public.timesheets_financials used here:
    // timesheet_id,total_hours,total_pay_ex_vat,total_charge_ex_vat,paid_at_utc,locked_by_invoice_id
    const tsfin = await sbGetOne(
      env,
      `${env.SUPABASE_URL}/rest/v1/timesheets_financials` +
        `?timesheet_id=eq.${enc(currentTimesheetId)}` +
        `&is_current=eq.true` +
        `&select=timesheet_id,total_hours,total_pay_ex_vat,total_charge_ex_vat,paid_at_utc,locked_by_invoice_id` +
        `&limit=1`
    );

    // ✅ Align with actual schema (no locked_by_invoice*, only locked_by_invoice_id + paid_at_utc)
    const hardLocked =
      !!(tsfin && (
        tsfin.paid_at_utc ||
        tsfin.locked_by_invoice_id
      ));

    const baseDeleteItem = {
      timesheet_id: String(cur.timesheet_id),
      booking_id: String(cur.booking_id || ''),
      week_ending_date: cur.week_ending_date ? String(cur.week_ending_date) : null,
      status: cur.status ? String(cur.status) : null,
      is_adjustment: !!cur.is_adjustment,
      adjustment_origin: cur.adjustment_origin ?? null,
      correction_id: cur.correction_id ?? null,
      correction_kind: cur.correction_kind ?? null,
      display_role: isImportDerivedChild ? 'IMPORT_CHILD_ADJUSTMENT' : (isAdjustment ? 'ADJUSTMENT' : 'STANDARD'),
      total_hours: tsfin && tsfin.total_hours != null ? Number(tsfin.total_hours) : 0,
      total_pay_ex_vat: tsfin && tsfin.total_pay_ex_vat != null ? Number(tsfin.total_pay_ex_vat) : 0,
      total_charge_ex_vat: tsfin && tsfin.total_charge_ex_vat != null ? Number(tsfin.total_charge_ex_vat) : 0
    };

    // 1) Hard-block import-derived NHSP/HR child adjustments
    if (isImportDerivedChild) {
      return withCORS(env, req, ok({
        kind: 'IMPORT_CHILD_ADJUSTMENT',
        requested_timesheet_id: String(timesheetId),
        current_timesheet_id: String(currentTimesheetId),
        was_stale: !!resolved.was_stale,
        eligible: false,
        blocked_reasons: [
          {
            code: 'IMPORT_DERIVED_CHILD',
            message: 'This is an NHSP/HR import adjustment child timesheet and cannot be deleted directly. Delete via the parent timesheet (if eligible).'
          }
        ],
        delete_items: [baseDeleteItem]
      }));
    }

    // Helper: normalize RPC outputs (sbRpc wrappers vary)
    const normalizeRpc = (v) => {
      try {
        if (v == null) return null;
        if (Array.isArray(v)) return (v[0] ?? v);
        if (typeof v === 'object' && Object.prototype.hasOwnProperty.call(v, 'data')) return v.data;
        return v;
      } catch {
        return v;
      }
    };

    // 2) Weekly parent → chain preview RPC
    if (isWeekly && !isAdjustment) {
      stage = 'rpc_chain_preview';
      try {
        const outRaw = await sbRpc(env, 'timesheet_weekly_chain_delete_preview', {
          p_timesheet_id: String(currentTimesheetId),
          p_actor_user_id: String(user.id)
        });
        const out = normalizeRpc(outRaw);

        if (!out || typeof out !== 'object') {
          return fail(
            500,
            stage,
            'Delete preview RPC returned an unexpected response.',
            { requested_timesheet_id: String(timesheetId), current_timesheet_id: String(currentTimesheetId) }
          );
        }

        return withCORS(env, req, ok({
          requested_timesheet_id: String(timesheetId),
          current_timesheet_id: String(currentTimesheetId),
          was_stale: !!resolved.was_stale,
          ...out
        }));
      } catch (e) {
        const msg = e?.message ? String(e.message) : String(e || 'RPC failed');
        const detail = e?.json || e?.body || null;
        return fail(400, stage, `Delete preview failed: ${msg}`, detail);
      }
    }

    // 3) Weekly manual adjustment → manual adjustment preview RPC
    if (isWeekly && isAdjustment) {
      stage = 'rpc_manual_adjustment_preview';
      try {
        const outRaw = await sbRpc(env, 'timesheet_weekly_manual_adjustment_delete_preview', {
          p_timesheet_id: String(currentTimesheetId),
          p_actor_user_id: String(user.id)
        });
        const out = normalizeRpc(outRaw);

        if (!out || typeof out !== 'object') {
          return fail(
            500,
            stage,
            'Delete preview RPC returned an unexpected response.',
            { requested_timesheet_id: String(timesheetId), current_timesheet_id: String(currentTimesheetId) }
          );
        }

        return withCORS(env, req, ok({
          requested_timesheet_id: String(timesheetId),
          current_timesheet_id: String(currentTimesheetId),
          was_stale: !!resolved.was_stale,
          ...out
        }));
      } catch (e) {
        const msg = e?.message ? String(e.message) : String(e || 'RPC failed');
        const detail = e?.json || e?.body || null;
        return fail(400, stage, `Delete preview failed: ${msg}`, detail);
      }
    }

    // 4) Non-weekly / other cases → preserve existing policy (only TSFIN hard lock blocks)
    const eligible = !hardLocked;
    const blocked = eligible
      ? []
      : [{ code: 'TSFIN_LOCK_OR_PAID', message: 'Cannot delete: invoiced or paid.' }];

    return withCORS(env, req, ok({
      kind: 'STANDARD_DELETE',
      requested_timesheet_id: String(timesheetId),
      current_timesheet_id: String(currentTimesheetId),
      was_stale: !!resolved.was_stale,
      eligible,
      blocked_reasons: blocked,
      delete_items: [baseDeleteItem]
    }));
  } catch (e) {
    const msg = e?.message ? String(e.message) : String(e || 'Unhandled error');
    return fail(500, stage || 'unknown', msg, null);
  }
}




// NEW helper: copy an existing R2 object to another key (overwrite destination).
// - Uses the same bucket selection style already present in your codebase: env.R2_BUCKET || env.R2
// - Preserves httpMetadata/customMetadata when present.
// - Throws on failure so caller can avoid patching DB on copy failure.
async function r2CopyOverwrite(env, fromKey, toKey) {
  const bucket = env.R2_BUCKET || env.R2;
  if (!bucket || typeof bucket.get !== 'function' || typeof bucket.put !== 'function') {
    throw new Error('Storage not configured (expected env.R2 or env.R2_BUCKET with get/put)');
  }

  const clean = (k) => String(k || '').replace(/^\/+/, '').trim();
  const src = clean(fromKey);
  const dst = clean(toKey);

  if (!src) throw new Error('r2CopyOverwrite: fromKey is empty');
  if (!dst) throw new Error('r2CopyOverwrite: toKey is empty');

  const obj = await bucket.get(src).catch((e) => {
    throw new Error(`r2CopyOverwrite: failed to get source key="${src}": ${e?.message || String(e)}`);
  });

  if (!obj) {
    throw new Error(`r2CopyOverwrite: source not found key="${src}"`);
  }

  // Preserve metadata when available
  const putOpts = {};
  if (obj.httpMetadata) putOpts.httpMetadata = obj.httpMetadata;
  if (obj.customMetadata) putOpts.customMetadata = obj.customMetadata;

  // Overwrite destination with source body stream
  await bucket.put(dst, obj.body, putOpts).catch((e) => {
    throw new Error(`r2CopyOverwrite: failed to put dest key="${dst}": ${e?.message || String(e)}`);
  });

  return { ok: true, from: src, to: dst };
}

async function verifyTsq1(qrText, env) {
  try {
    const raw = String(qrText || '').trim();
    if (!raw) return { ok: false, reason: 'EMPTY' };

    const parts = raw.split('.');
    if (parts.length !== 3) return { ok: false, reason: 'MALFORMED' };

    const [prefix, payloadB64url, sigB64url] = parts;
    if (prefix !== 'TSQ1') return { ok: false, reason: 'BAD_PREFIX' };
    if (!payloadB64url || !sigB64url) return { ok: false, reason: 'MALFORMED' };

    const secret = env.QR_SIGNING_SECRET || '';
    if (!secret) return { ok: false, reason: 'NO_SECRET' };

    // Verify signature over "TSQ1.<payload_b64url>"
    const keyData = textEncoder.encode(secret);
    const key = await crypto.subtle.importKey(
      'raw',
      keyData,
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['verify']
    );

    const signedData = textEncoder.encode(`TSQ1.${payloadB64url}`);
    const sigBytes = base64UrlToUint8(sigB64url);
    const sigOk = await crypto.subtle.verify('HMAC', key, sigBytes, signedData);
    if (!sigOk) return { ok: false, reason: 'BAD_SIG' };

    // Decode payload
    let jsonStr = '';
    try {
      jsonStr = new TextDecoder().decode(base64UrlToUint8(payloadB64url));
    } catch {
      return { ok: false, reason: 'BAD_PAYLOAD_B64' };
    }

    let payload = null;
    try {
      payload = JSON.parse(jsonStr);
    } catch {
      return { ok: false, reason: 'BAD_PAYLOAD_JSON' };
    }

    if (!payload || typeof payload !== 'object') return { ok: false, reason: 'BAD_PAYLOAD' };

    // Minimal required fields
    if (!payload.tsid) return { ok: false, reason: 'MISSING_TSID' };

    // REQUIRE token for all TSQ1 (no backward compat)
    if (!payload.tok || typeof payload.tok !== 'string' || !payload.tok.trim()) {
      return { ok: false, reason: 'MISSING_TOK' };
    }

    return { ok: true, payload };
  } catch (e) {
    return { ok: false, reason: e?.message || 'ERROR' };
  }
}

async function handleBankingIdRunDraftStart(env, req, user) {
  try {
    let body = null;
    try { body = await parseJSONBody(req); } catch { body = null; }

    // Body is optional for this route. Accept empty body; if provided, must be an object.
    if (body === null) body = {};
    if (!body || typeof body !== 'object' || Array.isArray(body)) {
      return withCORS(env, req, badRequest('Invalid JSON'));
    }

    const noteRaw = (body.note === null || body.note === undefined) ? null : String(body.note).trim();
    const note = noteRaw ? noteRaw : null;

    const rpcRes = await sbRpc(env, 'id_consolidation_run_draft_start', {
      p_actor_user_id: user.id,
      p_note: note
    });

    let payload = rpcRes;
    try {
      if (Array.isArray(rpcRes) && rpcRes.length === 1 && rpcRes[0] && typeof rpcRes[0] === 'object') {
        payload = rpcRes[0];
      }
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'id_consolidation_run_draft_start')) {
        payload = payload.id_consolidation_run_draft_start;
      }
    } catch {}

    const draft_run = (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};

    return withCORS(env, req, ok({
      ok: true,
      draft_run
    }));
  } catch (e) {
    return withCORS(env, req, serverError(String(e?.message || e)));
  }
}
async function handleBankingIdRunDraftCommit(env, req, user, idRef) {
  const id_ref = String(idRef || '').trim();
  if (!id_ref) return withCORS(env, req, badRequest('id_ref is required'));
  if (!/^[0-9]{6}$/.test(id_ref)) return withCORS(env, req, badRequest('id_ref must be 6 digits'));

  let body = null;
  try { body = await parseJSONBody(req); } catch { body = null; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return withCORS(env, req, badRequest('Invalid JSON'));

  const bankUploadCode = String(body.bank_upload_code || '').trim();
  if (!bankUploadCode) return withCORS(env, req, badRequest('bank_upload_code is required'));

  try {
    const rpcRes = await sbRpc(env, 'id_consolidation_run_draft_commit', {
      p_id_ref: id_ref,
      p_bank_upload_code: bankUploadCode,
      p_actor_user_id: user.id
    });

    let payload = rpcRes;
    try {
      if (Array.isArray(rpcRes) && rpcRes.length === 1 && rpcRes[0] && typeof rpcRes[0] === 'object') {
        payload = rpcRes[0];
      }
      if (payload && typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'id_consolidation_run_draft_commit')) {
        payload = payload.id_consolidation_run_draft_commit;
      }
    } catch {}

    const p = (payload && typeof payload === 'object' && !Array.isArray(payload)) ? payload : {};

    const run = {
      id_ref: (p.id_ref !== undefined && p.id_ref !== null) ? p.id_ref : id_ref,
      bank_upload_code: (p.bank_upload_code !== undefined && p.bank_upload_code !== null) ? p.bank_upload_code : bankUploadCode,
      bank_uploaded_at_utc: (p.bank_uploaded_at_utc !== undefined) ? p.bank_uploaded_at_utc : null,
      totals: (p.totals && typeof p.totals === 'object') ? p.totals : {},
      line_count: Number.isFinite(Number(p.line_count)) ? Math.trunc(Number(p.line_count)) : 0,
      state: (p.state !== undefined && p.state !== null) ? p.state : 'COMMITTED'
    };

    return withCORS(env, req, ok({
      ok: true,
      run
    }));
  } catch (e) {
    const msg = String(e?.json?.message || e?.message || e || '');
    if (msg === 'ID_RUN_NOT_FOUND') return withCORS(env, req, notFound('ID_RUN_NOT_FOUND'));
    if (msg === 'BANK_UPLOAD_CODE_REQUIRED') return withCORS(env, req, badRequest('BANK_UPLOAD_CODE_REQUIRED'));
    if (msg === 'CANNOT_CANCEL_COMMITTED_RUN') return withCORS(env, req, conflict('CANNOT_CANCEL_COMMITTED_RUN'));
    if (msg === 'ID_RUN_ALREADY_COMMITTED_DIFFERENT_CODE' || msg === 'RUN_ALREADY_COMMITTED_DIFFERENT_CODE') {
      return withCORS(env, req, conflict('RUN_ALREADY_COMMITTED_DIFFERENT_CODE'));
    }
    return withCORS(env, req, serverError(String(e?.message || e)));
  }
}

